-- GENERATED by `wfj generate` from data/quest/quest-0001.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [1000] = { "新たなる辺境", "Cenarion CircleによるKalimdor辺境地域探索の呼びかけについて、Thunder BluffのElder RiseにいるArch Druid Hamuul Runetotemと話して下さい。", "英雄たちに告ぐ!\n\nCenarion Circleは、Kalimdorの広大な辺境の探索を手助けできる強健な者を探している!　TanarisとGadgetzanの遙か西には想像を絶する危険に満ちた禁断の荒野があり、Cenarion Circleは彼らの代わりに行動する、意欲的な素晴らしい代理人を求めている。\n\n興味のある者はCenarion Circleにお目通りを求めよ。詳細については、Elder's RiseのArch Druid Hamuul Runetotemから聞くように!", nil, "ごきげんよう、{class}。\n\nそなたのような者が自然の営みに関心を持ってくれるとは、喜ばしい。ここへ来るよりも先に偉業が伝わっているのでな、ここでは大歓迎だ。こうしてそなたを見ると、Cenarion Circleにまさしく必要な援助が得られるのだという確信がもてる。\n\nMoongladeのCenarion Circleと我らの繋がりは、種族や政治的な断絶を超越したものなのだ。Cenarion Circleの代わりに取り組んでいる時には、そのことを忘れないでほしい。そうすれば、うまくいくだろう。", 0x980efd04, 0xbd7b7191, 0xa1c5be40, nil, 0x5b237095, "...m." },
  [1001] = { "Buzzbox 411", "Buzzbox 411の近くの深い海にいるDarkshore ThresherからThresher Eyeを3個集める。", "機械の奥深くから、小さな声がパチパチと聞こえてくる。\n\n「Wizbangだよ！ 次のBuzzboxはAuberdineの北、浜辺にあるんだ\n\nで、そのBuzzboxは411番で、修理にはThresher Eyesが3つ要るんだよ。すぐ沖にいるからさ！ darkshore thresherの……*ヒック*……ごめんごめん……\n\n前と同じで、Buzzboxに品物を渡したら、報酬が出てくるからね。*ヒック*……え？ いやいや、大丈夫だって！」", "機械のハッチが開いており、3個のThresher Eyesが入れられるのを今か今かと待っているようだ。", "Thresher Eyesを中に入れるとすぐに、Buzzboxがうなりを上げて動き出す。一瞬雑音が流れた後、聞き覚えのある小さな声が呼びかけてくる。\n\n「Crawlerワインが一番だぜ……」*ひっく*\n\n「なに？ おお、もう直してくれたのか？ すげえ、はえぇやちゅだなぁ。しょれで、もう一ちゅ直してみにゃいか？」\n\n液体がカップに注がれる音と、それに続いてごくごくと大きく飲み下す音が聞こえた気がする。", 0xed386236, 0xe7f4d482, 0x03c10b82, 0x32d3a2c9, 0x37ad4bdf, "....." },
  [1002] = { "Buzzbox 323", "Moonstalker Fangを6本集め、Buzzbox 323に入れる。", "Buzzboxから雑音がどっと噴き出し、Wizbangが話し始めるのが聞こえる。\n\n「次のBuzzboxは323番ら。Auberdineの北にあるんらけど……エールはどこら？ んあ？ ああ、道沿いにあるから、橋の近くですぐ見つかるはずらよ」\n\nWizbangが何か訳の分からないことをつぶやき、それから大きくゴクゴクと飲む音が聞こえる。\n\n「こいつにはMoonstalker Fangsが要るんら……6本な」", "まだ6本のMoonstalker Fangsを中に入れていないのに、中から雑音と支離滅裂なノームのぶつぶつ言う声が聞こえてくる気がする。誰かがもう機械を直してしまったのだろうか?", "Buzzboxが突然動き出し、中から歯が粉々にすりつぶされるはっきりとした音が聞こえてくる。\n\n「しょれ、やり遂げたにゃ！ しょいつはしゅばらしいにゅーしゅだぁ……しょれで……先へ進んだらどうだい？ おっと！ もう一ちゅ仕事がほしいにゃら別だけどにゃ！」", 0xed381fb2, 0x81dea735, 0xb07e5e5e, 0x32946a73, 0xcd12f60d, "....." },
  [1003] = { "Buzzbox 525", "Auberdineの南にいるGrizzled Thistle BearからGrizzled Scalpを4枚集め、Buzzbox 525に入れる。", "機械から聞こえる沸き立つ音や滴る音に混じって、Wizbangの震える声が響いてくる。\n\n「つぎのはじゅーっと南、道沿いら。見つけるのは難しくないはず……ちょっと脇に外れたところ……柵の近くら。たしか茂みに隠したんら……しげみにぃ。へへへ……しょうそう、Buzzbox 525にはあのgrizzled thistle bearから取れるgrizzled scalpsが要るんら。いやあ、舌がもつれるねえ。グリジュルド……へへへ……」\n\n機械が途切れる間際に、またゴクゴクと飲む音が聞こえる。そして突然、再び息を吹き返す。\n\n「4！」", "Buzzbox 525から歌声が聞こえてくる。\n\n「crawlerのワインはうみゃいし、thresherのエールも上等、moonstalkerの密造酒もしゅばらしい。でもthistle bearのビールほど愛しいものはにゃい、もうしゅぐ手に入るのしゃ!」\n\nハッチは開いていて4枚のgrizzled scalpsを待っており、歌が何度も何度も繰り返されるのが聞こえる。", "「しょれでscalpは入れてくれたにゃ？ しょいつはしゅげぇ……なんだって？ まあ、しょうだにゃ、材料を機械に入れなくてもオレがお前と話せるってことに気づいちまったんだろうにゃ。でも壊れてるって言ったのはほんとのことだったんだじぇ！\n\nいいか、Buzzboxはちゅうしんどうぐであるだけじゃにゃく、上等な酒を醸造して蒸留もするんだ。だましちまってしゅまにゃいが、ナイトエルフどもは自分たちの町でのオレの酒商売を快く思っちゃくれにゃいのしゃ。お前の働きに感謝して、この箱にとくべちゅなもんを入れといたじぇ。楽しんでくれ！」", 0xed38a5c6, 0x456f18b8, 0x7c095433, 0x36f0523a, 0x8072af47, "....." },
  [1004] = { "新たなる辺境", "Cenarion CircleによるKalimdor辺境地域探索の呼びかけについて、Thunder BluffのElder RiseにいるArch Druid Hamuul Runetotemと話して下さい。", "英雄たちに告ぐ!\n\nCenarion Circleは、Kalimdorの広大な辺境の探索を手助けできる強健な者を探している!　TanarisとGadgetzanの遙か西には想像を絶する危険に満ちた禁断の荒野があり、Cenarion Circleは彼らの代わりに行動する、意欲的な素晴らしい代理人を求めている。\n\n興味のある者はCenarion Circleにお目通りを求めよ。詳細については、Elder's RiseのArch Druid Hamuul Runetotemから聞くように!", nil, "ごきげんよう、{class}。\n\nそなたのような者が自然の営みに関心を持ってくれるとは、喜ばしい。ここへ来るよりも先に偉業が伝わっているのでな、ここでは大歓迎だ。こうしてそなたを見ると、Cenarion Circleにまさしく必要な援助が得られるのだという確信がもてる。\n\nMoongladeのCenarion Circleと我らの繋がりは、種族や政治的な断絶を超越したものなのだ。Cenarion Circleの代わりに取り組んでいる時には、そのことを忘れないでほしい。そうすれば、うまくいくだろう。", 0x980efd04, 0xbd7b7191, 0xa1c5be40, nil, 0x5b237095, "...m." },
  [1007] = { "Ancient Statuette", "Ancient StatuetteをZoram Strandの近くの野営地にいるTalenのところへ持って行く。", "あなたに一つ仕事を頼みたいのです、{name}。\n\n私が小さな舟に乗って、水没したZoramの遺跡の上をすべるように進んでいた時、nagaが水から躍り出て、爪で私に襲いかかってきたのです！ 私は持てるだけの物資を抱えて逃げ出し、このささやかな野営地を作りました。\n\nでも岸にたどり着いて走った時……私の大切な宝物をなくしてしまったのです。\n\nどうか、{name}、北の海岸沿いにある私が襲われた場所を見つけて、ancient statuetteを探してください。それこそ、私がZoram Strandの危険を冒した理由なのです。", "statuetteは見つかりましたか、{name}?", "見つけてくれたのね！ ありがとう、{name}！\n\n古都Zoramには多くの秘密が眠っているわ。このstatuetteはその多くを解く鍵になるかもしれない。", 0x4f6fc8bc, 0x8d5ca3e4, 0xc4983d64, 0x4a9921c4, 0xad8649d6, "....." },
  [1008] = { "Zoram Strand", "Wrathtail Headを20個、AstranaarのShindrell Swiftfireのところへ持って行く。", "我らの北西の海岸、Zoram Strandとして知られる地に悪が潜んでいる。\n\nそこは、Sunderingの際に滅ぼされて海の底に沈んだ、呪われた都Zoramが眠る場所だ。ナイトエルフにとっては遠い昔に失われた地。失われ、ほとんど忘れ去られていた。\n\n今、nagaが戻ってきた。その理由は分からない。だが理由などどうでもよい。この悪鬼どもを倒し、深みへと叩き返さねばならない！\n\n任務を終えたら私のもとへ戻ってきてくれ。", "nagaに我らの海岸を侵させるわけにはいかない、{name}。Zoram Strandへ行き、任務を果たすことが肝要だ。", "実に見事だ、{name}。Zoram Strandでnagaに対して示したそなたの働きは称賛に値する。\n\nそなたの偉業がたやすく成し遂げられたものでないことは分かっておる。nagaの力と狡猾さはナイトエルフによく知られておるからな。我らがそれを知っているのは、彼らと歴史を共にしているからだ。\n\n二度と繰り返したくはない歴史だがな。", 0x9cbacfd8, 0x9d25563d, 0x187db273, 0x72b741c0, 0xd6ba7f97, "....." },
  [1009] = { "Ruuzel", "Ring of ZoramをZoram Strand近くのTalenのところへ持って行って下さい。", "古い像の秘密は、その古い錠の鍵を見つけない限り、永遠に隠されたままになるのではないかと心配です。\n\nその鍵とは指輪、Ring of Zoramです。Sunderingの波がこの都市を沈める前に、この都市を治めていた者たちのものでした。\n\n何年もの間その指輪は失われていましたが、最近nagaが見つけたのです。\n\n彼らの首領Ruuzelは、Zoramの北端にある島に棲んでいます。お願いです、{name}、指輪を取り戻してください！", "Ring of Zoramは、その都市のあらゆる錠を開ける鍵だと言われています。持っていますか、{name}?", "ringを見つけてくれたのですね！ ありがとう、{name}。どうかこれを報酬として受け取ってください。そして、今日のあなたの行いは私の記憶に永遠に残るということを知っておいてください。", 0xa5f22a9f, 0x9ce8fe4c, 0x90dfae10, 0xfa173a78, 0x281d1a0e, "....." },
  [1010] = { "Bathran's Hair", "Bathran's Hairを5束、AshenvaleのOrendil Broadleafのところへ持って行く。", "北にあるBathran's Hauntの古い遺跡に、かつて生えていた植物があります。その植物はBathran's Hairと呼ばれ、魂の病を癒すことで知られていました。\n\n村に病気の子供がいるのですが、ただの体の病ではないと私は考えています。Bathran's Hauntへ行って、Bathran's Hairを探してきてくださいませんか？ その子をきちんと治療するのに必要になるかもしれないのです。\n\nBathran's HauntはMaestra's Postの北、Darkshoreとの境のすぐ南にあります。", "Bathran's Hairは集めてくれましたか、{name}? あの子の体は刻一刻と弱っているのです……", "ああ、hairを持ってきてくれたのですね！ これであの子のための薬を調合します。私の調合がうまくいくよう祈りながら。\n\nそれに……ForsakenがBathran's Hauntにいるのですか？ それはとても気がかりな話ですね。本当に気がかりです……", 0x74a86ba6, 0xd56778b9, 0xaa6b3524, 0x340001ab, 0xbadaf9b1, "....." },
  [1011] = { "Forsakenの病", "Bottle of DiseaseをForest SongのKayneth Stillwindのところへ持って行って下さい。", "Hordeのアンデッドの一派であるForsakenが、Ashenvaleに忍び込み、我らの遺跡や墓所に潜んでいる。奴らの狙いは、ナイトエルフの地に病を広めることだと我々は考えている。それを確かめねばならない！\n\nForsakenはここから南、Dor'Danil Barrow Denの近くに野営地を構え、毒や病を作っては瓶に詰めている。その野営地に斬り込み、bottle of diseaseを一つ盗み出してくれ。その瓶を持ち帰るのだ。私が調べて、その目的を突き止めよう。", "野営地は見つかったか、{name}? bottle of diseaseは手に入れたか?", "とても良いですよ、{name}。さて……このbottleの中身を調べれば、Forsakenの目的が明らかになるはずです！", 0x56f1d203, 0x2dc3785e, 0xb7d7e188, 0x4bef8879, 0x706dafea, "....." },
  [1012] = { "狂えるドルイド", "ドルイドたち、Taneel Darkwood、Uthil Mooncall、Mavoris Cloudsbreakを倒し、Forest SongのKayneth Stillwindのところへ戻って下さい。", "Forsakenの毒に苦しんでいたとき、私は幻を見た。Dor'danil Barrow Denのドルイドたちが毒を盛られ……アンデッドに殺される幻を！ 彼らは今や彷徨える亡霊となり、肉体から切り離され、狂気に駆られている。\n\nドルイドたちの魂がいつの日か安らぎを得られるよう、Dor'danil Barrow Denに入り、かつての偉大な指導者たち、Taneel Darkwood、Uthil Mooncall、Mavoris Cloudsbreakを滅ぼさねばならない。\n\nそれを成し遂げたら、私のもとへ戻ってくれ。", "Dor'danilのドルイドたちの苦悶が、今も私の夢に取り憑いている、{name}。奴らの指導者を倒さねばならない!", "Dor'danil Barrowsの苦悶が和らぐのを感じ、あなたが務めを果たしたことを知りました。\n\nつらい仕事でしたね、{name}。あなたが滅ぼした霊たちは、Forsakenの悪行の犠牲者にすぎなかったのですから。けれども、彼らが滅びたことで、狂わされたほかの霊たちが安らぎを見出せるよう願いましょう。", 0x64537763, 0xe520e963, 0x73bdfd08, 0x1fc933f7, 0x6109c515, "....." },
  [1013] = { "The Book of Ur", "UndercityのApothecariumにいるKeeper Bel'dugurにBook of Urを渡して下さい。", "{name}、Shadowfang Keepには一冊の本、Book of Urがある。私のコレクションとして大いに珍重されるであろう品だ。UrはScourgeが現れる前のDalaranの偉大なメイジで、彼の異界の研究は……Forsakenの中のある方々にとって大いに価値があるのだ。\n\nShadowfang Keepへ入り、その本を見つけろ。私のもとへ持ってくれば、君の働きを我らがDark Ladyに報告しよう……", "本は見つかったかい、{name}?", "よろしい。この本は、Urの業績についての私の蒐集に見事に加わるだろう。彼の知識は偉大だったが、その良心が真の力を掴むことを妨げた。だからScourgeが来て彼の力が試されたとき、それは潰えたのだ。\n\n我々Forsakenは、生き延びようというのなら、そのような弱さを抱える余裕はない……\n\n……征服しようというのなら、なおさらだ。", 0x550d5dac, 0xa4439184, 0x27fdd02a, 0xfe172e90, 0x675a81e7, "....." },
  [1014] = { "Arugal死すべし", "Arugalを殺し、首をSepulcherのDalar Dawnweaverに渡して下さい。", "ArugalはいまだShadowfang Keepに潜んでいる。Arugalを倒さぬ限り、我々はSilverpineをDark Ladyのための戦略拠点とすることはできん。\n\n奴の魔法を根絶やしにするのは私が引き受けよう、{name}。だが、Arugalに当然の報いとしての死を与えるのは、君の手に委ねる。\n\nShadowfang Keepへ向かい、Arugalの忌まわしい呪文に今度こそ終止符を打て。あの卑劣な魔法使いの首を私のもとへ持ってくるのだ!", "Arugalが死ねば、LordaeronにおけるDark Ladyの支配をさらに強められる。", "ついにSilverpine Forestは悪党Arugalの悪行から解放された。{name}、お前はDark Ladyのために大きな貢献をしたのだ。その忍耐強さは報われるだろうよ。", 0xa62d9f82, 0x2b1851cd, 0x5186e893, 0xbfc38023, 0xd0cbb456, "....." },
  [1015] = { "新たなる辺境", "DarnassusのCenarion EnclaveにいるArch Druid Fandral Staghelmと、Kalimdorの辺境を探索するようにというCenarion Circleの呼びかけについて話して下さい。", "英雄たちへ告ぐ！\n\nCenarion Circleは、Kalimdorの広大な新天地の探索を手伝ってくれる健やかな者を求めている！ TanarisとGadgetzanのはるか西には、想像を絶する危険に満ちた禁断の荒野が広がっており、Circleは彼らに代わって行動してくれる意欲ある高潔な代理人を必要としている。\n\n関心のある者は皆、Cenarion Circleに謁見を求めること。詳しくは、Darnassusの大ドルイド、Fandral Staghelmと話すこと！", nil, "私がお前のような者にわずらわされたいと、なぜ思うのだ、{class}？ 待て――毎日こなしている重要な務めを中断して、お前がどこかの小道具を探すのを手伝ってやろうじゃないか。もちろんだとも、Darnassusの――いや、Teldrassil全体の――安寧など、お前の収集品のための安物を手に入れることの次で構わんのだからな。\n\nMoongladeの愚か者どもは助けを求めてきて私の時間を無駄にするし、今度はこれに耐えねばならんというのか？", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1016] = { "Elemental Bracers", "Intact Elemental Bracerを5個集め、それにDivining Scrollを使う。その後、Divined ScrollをSilverwind RefugeのSentinel Velene Starstrikeのところへ持って行く。", "このdivining scrollを持っていけ――これで、あのelementalどもを作り出した者を突き止められる。だが巻物の魔力を集中させる触媒として、奴らから何か取ってくる必要がある――奴らのbracersがちょうどいいだろう。\n\nあの生き物から取ったintact bracersがいくつかあれば十分だ。それ以外のbracersは我々の目的には役に立たないが、売りたいなら商人がいくらか値をつけてくれるかもしれん。intact bracersが手に入ったら、巻物を使ってみてくれ。結果を持って戻ってくれば、そこから先へ進もう。", "elementalを倒すにはbracersを破壊しなければならないから、divining scrollが必要とする情報を含んだものを見つけるのは難しいだろう。必要なbracersを手に入れるために他の者と交換してもいいし、あるいはもうdivined paperを持っているのかな?", "よくやった、{name}。これで犯人を突き止めるのに必要な情報が得られるはずだ。我々の水たまりを穢れた精霊で満たしているメイジを始末してみる気はないか？ Ashenvaleとその先の地の穢れは、それだけでも胃がむかむかする――それをさらに滅ぼそうと積極的に企む魔法使いがいるなど、どうにも我慢ならん。奴には報いを受けさせてやる。", 0xb698effb, 0xdea3d96f, 0x737c6b17, 0x90279ef1, 0x7f18db5a, "....." },
  [1017] = { "メイジの召喚士", "Sarilus Foulborneを倒し、その首をSilverwind RefugeのSentinel Velene Starstrikeのところへ持って行って下さい。", "Barrensでこれほど多くの水のエレメンタルを穢せるアンデッドのメイジは一人しかいない。そんなことを試みるほど愚かなのも奴だけだ。Sarilus Foulborneは、おそらくDreadmist Peakの頂上に座って私を笑っているのだろう。\n\n{name}、敵地へ乗り込み、この悪党を始末してくれ。奴の愚行にはもううんざりだ。Sentinelsを怒らせた者がどうなるか、思い知らせてやらねばならない。\n\n奴を倒し、首を持ってくるのだ。だが用心しろ、Hordeが君を見張っているかもしれない。", "終わったのか? Sarilus Foulborneは死んだのか?", "これであの忌まわしい笑みが奴の顔から永遠に消え去るのを見届けられる。実によくやってくれた、{name}。これを受け取るがいい。Light of Eluneだ。すべてが失われたように思え、死が迫った時に飲むといい。女神の思し召しがあれば、お前の命を救ってくれるだろう。", 0xd88bf407, 0x0a5ea9a8, 0xb383c3fe, 0xd734a9d3, 0x762bf18f, "....." },
  [1018] = { "新たなる辺境", "Cenarion CircleによるKalimdor辺境地域探索の呼びかけについて、Thunder BluffのElder RiseにいるArch Druid Hamuul Runetotemと話して下さい。", "英雄たちに告ぐ!\n\nCenarion Circleは、Kalimdorの広大な辺境の探索を手助けできる強健な者を探している!　TanarisとGadgetzanの遙か西には想像を絶する危険に満ちた禁断の荒野があり、Cenarion Circleは彼らの代わりに行動する、意欲的な素晴らしい代理人を求めている。\n\n興味のある者はCenarion Circleにお目通りを求めよ。詳細については、Elder's RiseのArch Druid Hamuul Runetotemから聞くように!", nil, "ごきげんよう、{class}。\n\nそなたのような者が自然の営みに関心を持ってくれるとは、喜ばしい。ここへ来るよりも先に偉業が伝わっているのでな、ここでは大歓迎だ。こうしてそなたを見ると、Cenarion Circleにまさしく必要な援助が得られるのだという確信がもてる。\n\nMoongladeのCenarion Circleと我らの繋がりは、種族や政治的な断絶を超越したものなのだ。Cenarion Circleの代わりに取り組んでいる時には、そのことを忘れないでほしい。そうすれば、うまくいくだろう。", 0x980efd04, 0xbd7b7191, 0xa1c5be40, nil, 0x5b237095, "...m." },
  [1019] = { "新たなる辺境", "DarnassusのCenarion EnclaveにいるArch Druid Fandral Staghelmと、Kalimdorの辺境を探索するようにというCenarion Circleの呼びかけについて話して下さい。", "英雄たちへ告ぐ！\n\nCenarion Circleは、Kalimdorの広大な新天地の探索を手伝ってくれる健やかな者を求めている！ TanarisとGadgetzanのはるか西には、想像を絶する危険に満ちた禁断の荒野が広がっており、Circleは彼らに代わって行動してくれる意欲ある高潔な代理人を必要としている。\n\n関心のある者は皆、Cenarion Circleに謁見を求めること。詳しくは、Darnassusの大ドルイド、Fandral Staghelmと話すこと！", nil, "私がお前のような者にわずらわされたいと、なぜ思うのだ、{class}？ 待て――毎日こなしている重要な務めを中断して、お前がどこかの小道具を探すのを手伝ってやろうじゃないか。もちろんだとも、Darnassusの――いや、Teldrassil全体の――安寧など、お前の収集品のための安物を手に入れることの次で構わんのだからな。\n\nMoongladeの愚か者どもは助けを求めてきて私の時間を無駄にするし、今度はこれに耐えねばならんというのか？", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1020] = { "Orendil's Cure", "Orendil's CureをAstranaarのPelturas Whitemoonのところへ持って行って下さい。", "{name}、苦しんでいる子供を救えると思う治療薬を作りました。これをAstranaarへ持って行き、子供の親であるPelturas Whitemoonに渡してください。\n\nAstranaarへ行くには、道を南へ、それから東へ進んでください。", "申し訳ありませんが、話している暇がないのです。私の子、Relaraが重い病にかかっていて!", "これはOrendilからなのですか？\n\n彼の薬草と治療の腕は素晴らしいものです。以前はほとんど希望がありませんでしたが、このcureが私に希望を与えてくれます……", 0xb9c0e606, 0xb594b387, 0x15801dd7, 0xb4a8bb23, 0x6dfa2147, "....." },
  [1021] = { "邪悪なSatyr！Dryadsが危ない！", "XavianでAniliaを見つけて下さい。", "ねえ、あなたが誰かは知らないけど、助けてほしいの。私の姉妹たちが、satyrからBranch of Cenariusを取り戻しに行ったの。すぐ戻るって言ってたのに、もう丸二日も経ってるのよ！\n\n{name}、あの子たちを見つけて！ 北東のXavianにあるナイトエルフの神殿の遺跡を探していたの。どう考えたらいいか分からない。Aniliaを探して。彼女が捜索を率いていたの。", nil, "脇腹に口を開けた傷から判断すると、Aniliaは死の淵にある。", 0xd88516a4, 0x901c0e74, 0x32056a49, nil, 0xe36895ac, "...m." },
  [1022] = { "遠吠えの谷", "Howling Valeへ行ってTome of Mel'Thandrisを調べ、Shrine of AessinaにいるSentinel Melyria Frostshadowのところへ戻って下さい。", "北のFelwoodから残る悪魔どもを追い払うため、多くの資源と労力を注いできましたが、成果はわずかです。それでも、悪魔の勢力の大半をAshenvaleから遠ざけておくことはできています。\n\n北のFelwoodとの境の近くでは、Mel'Thandrisの荒れ果てた祠が謎の狼男たちに占拠されています。その身も凍るような遠吠えから、あの一帯はHowling Valeと呼ばれるようになりました。祠に保管されていたTome of Mel'Thandrisが、狼男たちがなぜ現れたのかを解き明かしてくれるかもしれません。", "祠の書は不思議な品です。一般的な意味での本ではありません。その書の頁はMel'Thandris自身によって祝福されており、重要な出来事をその頁に記しているのです。\n\n説明するのは難しいですね。祠へ行けば分かるでしょう。", "Tome of Mel'Thandrisは不可思議な働きをする。それが記す出来事、それが見せる出来事……なぜそのようなことをするのか、真に理解している者はいない。\n\nとはいえ、Priestess Starsongが受け取ったもの――このScythe of Elune――が、さらなる調査に値することは明らかだ。", 0x4a2cd655, 0xda6b6938, 0x9b613692, 0x9ace9f35, 0xa2144a21, "....." },
  [1023] = { "Raeneの浄化", "Glowing Gemを見つけ、Teronis' Journalを持ってAstranaarのRaene Wolfrunnerのところへ戻る。", "Teronisの持ち物をあさると、まだ状態の良い日誌が見つかった。\n\nあなたは日誌を手に取り、Teronisの亡骸はそのままにしておく。\n\n残るは、Teronisが探していた宝石を見つけることだけだ。Raeneは、それがこの辺りにあると言っていた。もしかしたらmurlocが持っているのかもしれない……", "ああ、おかえり、{name}。", "なんということだ、{name}。Teronisが死んだだと？！\n\n悼む時はいずれ来るが、今は力を集中させねばならない。できるだけ早くSentinelsを何人か送って、Teronisの遺体を回収させよう。\n\nお前はTeronisのjournalと、彼が探していたgemを持っている。彼の務めを完遂できると思うか？ 彼の死が無駄ではなかったと分かれば、私はずっと安心して休めるのだが。", 0x30e3be54, 0x7f853c3d, 0xba0a18d8, 0x6c186150, 0x213bef75, "....." },
  [1024] = { "Raeneの浄化", "北東の月の泉にいるShael'drynを見つける。", "調べるのはあなた自身でやってもらわねばなりませんが、Teronisが残したメモからすると、次にすべきことはDartolが作った杖の他の部品を見つけることのようです。まずはIris Lakeの東にある月の泉へ向かうとよいでしょう。準備ができたら道を進み、左手に小さな休憩所が見えたら北へ曲がってください。\n\nそこにShael'drynというドライアドがいます。あなたを導くには彼女のほうがふさわしいでしょう。彼女を訪ねてください。\n\n宝石は持っておいてください――杖を作り直す手伝いをするには、Shael'drynにそれが必要になるはずです。", "こんにちは。お元気ですか?", "まあ、Raeneに言われて来たの？ 本当に深刻な事態なのね。何を手伝えばいいかしら？", 0x30e3be54, 0x870564ea, 0x74ecbe19, 0x8c397c59, 0xf0f35728, "....." },
  [1025] = { "攻撃的な防御", "Foulweald族のDen Watcherを1体、Ursaを2体、Totemicを10体、Warriorを12体倒し、AstranaarのRaene Wolfrunnerのところへ戻る。", "月の泉へ向かう前に、腕を試してみたいのなら、Ashenvaleの人々の助けになる別の仕事があります。\n\nFalfarren Riverの手前で東へ向かう道沿いで、furbolgが旅人を襲っているのです。苦しみに歪んだ心は恐怖を糧とし、その渇きは罪なき者の血で満たされています。\n\nあの怪物どもが私たちの同胞に示したのと同じ慈悲を示してやり、この地を守るSentinelsに力を貸してください。\n\n奴らの野営地は道の南にあるはずです……気をつけてください。", "furbolgは昔から敵だったわけではありません、{name}。ですが時は移ろい、この暗い森はもはや平和な時代ではないのです。", "よくやってくれた、{name}。ありがとう。", 0xac8970c1, 0x61ad4540, 0xb29beaa2, 0xa6e6b187, 0x53926f7d, "....." },
  [1026] = { "Raeneの浄化", "Wooden KeyとDartol's Rodの欠片を見つけてから、月の泉のShael'drynのところへ戻る。", "もっと良い知らせだったらよかったのですが。\n\nRaeneの言う通りです。私はDartolの作ったものと、この辺りのtreantのことを知っています――少なくとも、かつては知っていました。今では彼らは堕落し、その本性はねじ曲げられてしまいました。\n\nあなたの目的が杖の次の部品を見つけることなら、それが入っている箱を開ける鍵を見つけなければなりません。\n\nwooden keyは、ここから北東、Felwoodの近くにいるtreantの一体が持っています。手に入れたら、Felwoodとの境の近く、道の西にある小さな空き地を探してください……箱はその辺りに隠されているはずです。", "treantが穢れてしまったことが本当に悲しいのです。もっと彼らの力になれたらいいのに。", "戻ってきてくれて嬉しいよ、{name}。", 0x30e3be54, 0x8ec36891, 0xbb4dd335, 0x2a083fa2, 0xee5a6576, "....." },
  [1027] = { "Raeneの浄化", "Dartol's Rodの最後の欠片を見つけ、ムーンウェルのShael'drynのところへ戻って下さい。", "杖の最後の部品は、保管のためDor'danilのドルイドたちに託された。彼らがどこに隠したかは分からない。これ以上力になれなくてすまない。\n\n言えるのは、Barrensへ続く道を辿れということだけだ。ドルイドたちはその道の東に身を寄せていたが、彼らは大して助けにならないだろう。最近殺されてしまったのだ……あまり考えたくないことだ。\n\n最後の部品を見つけたら、私のところへ持ってきてくれ。杖の復元を手伝おう。", "杖の最後のかけらは見つかったか、{name}?", "最後の一つを見つけたのかい？ 君にとっても……Raeneにとっても素晴らしいことだ。\n\nさて、修理のことを考えないといけないね？", 0x30e3be54, 0x717478b4, 0x52aaaf37, 0xe95940f0, 0x5810af11, "....." },
  [1028] = { "Raeneの浄化", "隠された祠を見つけ、Dartol's Rodに再び魔力を込めて下さい。", "はい、完成した杖だよ、{name}。組み立て直すのは簡単だった……難しいのは、これを再充填する力を持つ祠を見つけることさ。\n\n多少集中して頑張れば、もうたくさんのことを成し遂げてきた君みたいな人なら、そんなに難しくはないはずだよ。\n\nここから南東へ向かって――道はほとんどないから気をつけてね――北に目を凝らしておくこと。祠はこの空き地を囲む山々の中に隠されているんだ。\n\n着いたら、祠の中に杖を置いて……あとは魔法さ。へへ。", "祠と周囲の木々の中に、微かでありながら強大な力を感じる。\n\n杖を祠の中に置き始めると、祠が輝き始め、あたりから柔らかな低い響きが発せられる……", "輝きが消えると、祠の水盤の中に再び魔力を宿した杖が見える。", 0x30e3be54, 0xb46bc4dc, 0xba1c18cf, 0xbf739d88, 0x772d23ad, "....." },
  [1029] = { "Raeneの浄化", "AstranaarのRaene Wolfrunnerのところへ戻って下さい。", "Raeneを見つけて、杖が完成したことを知らせてやってくれ。次に何をすべきか、彼女なら分かっているはずだ。\n\n幸運を祈る、{name}。", nil, "Teronisが探しに出た杖を作り直したのですか？ それは素晴らしい知らせです。\n\n悲しい死を迎えた後もなお自分の探求が続いているのを見れば、Teronisもきっと誇りに思うでしょう。", 0x30e3be54, 0x03b8caf8, 0x075c1399, nil, 0x6da04e68, "...m." },
  [1030] = { "Raeneの浄化", "堕落していないfurbolgを見つけ、Dartol's Rod of Transformationの力を使って彼と話して下さい。", "残念ながら、彼が次に何を考えていたのか、私にもはっきりとは分からないのです。\n\n杖の力について彼の言ったことが本当なら、それを使えばまったく別の姿になれるはずです。どんな姿なのかは分かりません。\n\nおそらく彼は、その力を使って穢れたfurbolgsに近づこうとしたのでしょう。ですが、穢れていない者たちでさえ、彼が用心していなければ彼を殺していたでしょう。杖で姿を変えたDartolは、Fel Mossの影響を受けていないfurbolgと話さなければならなかったはずです。\n\nまずはMystral Lakeの南東から探してみるといいでしょう。", nil, "そうだ、そうだ……お前は我が同族だが、まだ無傷だ。まだ穢れていない。\n\nナイトエルフが我らの民にもたらした残虐をお前がどうやって逃れたのかは分からぬが、もはや独りではないと知って嬉しく思う。\n\n今や穢れが我らの同胞の血管を流れている、若き者よ。傲慢なナイトエルフどもが我らにもたらした穢れだ。我らの民にこんなことをしたのは奴らだ……我が部族から追放されたのも奴らのせいだ。\n\n夜になると、今でも闇の中で燃える焚き火が見える。", 0x30e3be54, 0x9860f324, 0x7bc02b85, nil, 0xcb923d4d, "...m." },
  [1031] = { "Branch of Cenarius", "Geltharisを倒し、Branch of CenariusをShrine of AessinaのIlliyanaのところへ持ち帰って下さい。", "Aniliaはあなたの肩に両手を置き、あなたを引き寄せる。あえぎながら、彼女は北のアーチを指さす。そして目を閉じ、最後のかすれた息がその身体から抜けていく。「あいつが奪っていった……Geltharis……」 Aniliaの末期の願いは、Branch of Cenariusがdryadの手に戻ることだと、あなたは心の底から理解する。", "見つけたのですか? Aniliaは何と言っていました? 彼女はどこに?", "Aniliaが死んだの？ いや……そんなはずないわ！ つい昨日、一緒に森を駆け回って遊んでいたのに。\n\nそんな日々はもう終わってしまったのね……", 0x06ca6f6f, 0x9a671e71, 0x0638efcd, 0xb34326a3, 0x2df30514, "....." },
  [1032] = { "Satyr退治！", "Satyr Hornsを$N1個、Shrine of AessinaのIlliyanaのところへ持って行って下さい。", "Aniliaがいなくなったなんて信じられない……私たち、いつも森で一緒に遊んでいたのに。なんだか……悲しい気持ち。\n\n気が晴れるかもしれないことを知ってるの。お願い、私からAniliaを奪ったsatyrsを倒して！ その証として彼らの角を持ってきてくれたら、ずっと感謝するわ。", "お願いです、Aniliaの死の復讐に力を貸してください。", "ありがとう、心優しき{race}よ。あなたの尽力に、姉の魂も喜んでいます。", 0x23fc501b, 0x2ed3fe3c, 0x190a00e6, 0x713f462d, 0xd7c8e1b7, "....." },
  [1033] = { "Elune's Tear", "Elune's TearをAstranaarのPelturasのところへ持って行って下さい。", "Orendilの治療薬がRelaraを救ってくれると願っていましたが、私の子を蝕む病の進行を遅らせただけのようです。もっと強い薬を見つけなければ！ ありがたいことに、最初の治療が効かなかったときに試すべき別の治療法を、Orendilが教えてくれていました。\n\nElune's Tearは、ただ一か所にしかない石です。Astranaarの東、Iris Lakeの島です。Orendilによれば、その石は穢れを洗い流すそうです……お願いです、{name}、Elune's Tearを持ってきてください。そして、それが私の子の病を終わらせるよう祈ってください！", "{name}、Iris Lakeは見つかりましたか? Tearは持っていますか?", "まあ、見つけてくれたのね！ このtearをシチューに入れて、あの子が治るように祈るわ。\n\nありがとう！ ありがとう、{name}！", 0xae0d2497, 0xc2de57c8, 0x0451f462, 0xfd413dac, 0x3c6ec55f, "....." },
  [1034] = { "Stardustの遺跡", "Handfuls of Stardustを$N1個、AstranaarのPelturasのところへ持って行って下さい。", "Elune's Tearは娘の病をいくらか洗い流してくれました。悪夢は和らぎ、女神の祝福に感謝しています。ですが……熱はまだあの子の中で荒れ狂っています。\n\nOrendilから、Ruins of Stardustで見つかる霜の粉のことを聞きました。それならRelaraの熱を鎮められるかもしれません。その粉を集めて、どうか私のもとへ戻ってきてください。\n\nRuins of Stardustは南にあります、{name}。Eluneがあなたの旅路を速めてくださいますように。", "Stardustはもう手に入れましたか、{name}?", "塵を集めてくれたのね！ これで湿布を作るわ――Relaraの熱を下げてくれるはずよ。\n\n本当にありがとう、{name}。あなたの助けがなければ、私の子はきっと死んでしまっていたわ。", 0xfba883e2, 0x28f9030f, 0x14b3b904, 0x2c3445f3, 0x8980ab64, "....." },
  [1035] = { "Fallen Sky Lake", "Shadethicket OracleからFallen Moonstoneを取り戻し、AstranaarのPelturasのところへ持って行って下さい。", "Relaraの熱は引きましたが、あの子はまだひどく弱っています。時間だけで失われた力が戻るとは思えません。月長石の力が必要だと思うのです。\n\n私たちはかつて、南東のFallen Sky Lakeで月長石を集めていました……Shadethicketsが来るまでは。\n\n彼らの首領であるShadethicket Oracleが、落ちた月長石をすべて集めて貯め込んでいます。今こそ、Oracleから月長石を一つ取り戻してもらわねばなりません。\n\nそのためには……彼を殺さねばならないでしょう。", "Shadethicket Oracleと対峙しましたか、{name}? それなら、fallen moonstoneを渡してください。Relaraにはもう、あと数回息をするほどの力しか残っていないのです!", "ああ、{name}、あなたは私の娘を救ってくれたわ！ moonstoneの力が娘に元気を取り戻させてくれるって分かっているの！\n\nあなたがくれた助けに十分に報いることは決してできないけれど……どうか、これを受け取って。Relaraを除けば、私の一番大切な持ち物なの。", 0x2fb85293, 0xa905bcf0, 0xa253d48e, 0xc1063bd4, 0x077c83f2, "....." },
  [1036] = { "気をつけ、悪党", "Stranglethorn Vale の海岸外れに停泊している Crimson Vale 号に乗り、Fleet Master Firallon と話して下さい。", "{name} ……ああ、あんたのことは聞いてる。Booty Bay の支持者じゃないんだってな――俺たち Bloodsail Buccaneers みたいに。Fleet Master Firallon は特別な任務のためにあんたみたいな威勢の良い奴を探してんだ。\n\n興味があるなら、Crimson Veil 号に乗って、船倉にいる船団長と話しな。Crimson Veil 号は Wild Coast に停泊してるよ。Riptide 号と Damsel's Luck 号の隣だ。", nil, "気をつけ、ゴロツキ。おめえはちょっとした悪党なんだってな。まあ、Booty Bay の仲間じゃないんなら、Bloodsail Buccaneers で特別な地位につけるかもな。\n\nアーーーーー……", 0xa46e802b, 0xf94ce6e9, 0x79a4f159, nil, 0x930af57d, "...m.", nil, nil, 0x6d3b55ce, nil, nil },
  [1037] = { "Velinde Starsong", "DarnassusのWarrior's TerraceにいるThyn'tel Bladeweaverと話して下さい。", "Velinde Starsongは、ここAshenvale Forestでの私の前任者です。初めのうちは、VelindeはFelwoodの事態を掌握しているように見えましたが、その努力は少しずつ揺らいでいきました。そしてある日、Velindeはふっと姿を消してしまったのです。\n\n私はVelindeの仕事を引き継ぐためにここへ送られてきました。ですが残念ながら、あのプリーストのことは何も知りません。Sentinelsの指揮官の一人であるThyn'tel Bladeweaverなら、私の知らないVelindeの失踪の詳しい事情を知っているかもしれません。\n\nそのような情報の重要さを、Thyn'telならきっと分かってくれるでしょう。", nil, "Velinde Starsong? その司祭はしばらく前に姿を消したというのはほぼ周知の事実です。彼女の離脱にまつわる出来事の詳細について明かすには……正当な理由が必要です。", 0xf7ead98e, 0x98606e25, 0x016b231b, nil, 0xe9e791ce, "...m." },
  [1038] = { "Velindeの私物", "Velindeの物入れから日誌を探し、DarnassusのThyn'tel Bladeweaverに鍵と一緒に渡して下さい。", "Tome of Mel'Thandrisがあなたにそれを示したのですか?それなら、彼女の持ち物を調べてもらっても大した害はないでしょう。この鍵で、Sentinelsの宿舎に彼女の持ち物をしまってある箱を開けられます。彼女は任務の記録を日誌につけていました。何か分かることがあるとすれば、それからでしょう。\n\nお伝えしておきますが、Sentinelsは彼女が自分なりの理由で去ったのだと考えていて、いつ戻ってきてもおかしくないと思っています。あのプリーストはこれまで、私たちの信頼を得るに足ることを数多くしてきたのです。", "何が分かった?", "Velindeの失踪は、当初思われていたよりも厄介なもののようだ。それでも、彼女が悪しき最期を迎えたとは信じられない。おそらく彼女と連絡を取ることは、我々にとって有益だろう。\n\n{name}、あなたはこの件に強い関心を示してくれた。ぜひその力を借りたい。", 0x74dbac02, 0x09fb9185, 0x7dde5963, 0x7a7fed9c, 0x7a510565, "....." },
  [1039] = { "荒野の港", "BarrensのRatchetにいるWharfmaster Dizzywigと話して下さい。", "RatchetはBarrensで唯一の港です。Velindeはおそらく、RatchetでAzerothのBlackwater Coveへ向かう交易船を見つけたのでしょう。港を仕切るゴブリンとの取引はわずかしかありませんが、港湾長なら船客の出入りについて情報を持っているはずです。\n\nAshenvaleを抜けて南東へ道をたどれば、Barrensに着きます。足元に気をつけてください、{name}。Hordeのウォリアーたちがこの地を巡回しています。ですが、港にいれば安全です。", nil, "{race}か? 正直、この辺りではお前さんの同族はあまり見かけない。誰かを探しているのか? 少し待ってくれ、帳簿のどこかに書き留めてあるはずだ。\n\nとはいえ、ここを通る者は多いからな。もう少し待ってくれ。", 0xbce71855, 0x368d5e90, 0x984e6dd9, nil, 0xa9762f9c, "...m." },
  [1040] = { "Booty Bayへの旅路", "Booty Bay行きの船に乗り、Caravaneer Ruzzgotと話して下さい。", "ああ、そうだ、やっと見つけた。そんなに前にここを通ったんなら、先にそう言ってくれりゃいいのに。どれどれ。\n\nVelinde。Black OspreyでBooty Bayまでの船旅を予約してる。ほかに何も書いてないから、無事に港に着いたんだろうな。\n\nこれ以上はあまり力になれんが、あの人は世界の向こう側での陸路の旅について聞いてきたんで、Booty Bayを拠点にしてるキャラバンの御者のRuzzgotの話をしてやったよ。そのVelindeってのはRuzzgotと一緒に旅したのかもな。\n\nさあ、もう行ってくれ。あんたに一日中付き合ってる暇はないんだ。", nil, "何だい? さて、あんたは発送が必要な荷物を持ってるような手合いには見えないね。となると、俺のキャラバンでの仕事を探してるか――今は仕事なんてないけどね――でなきゃ、たぶん話しかけるゴブリンを間違えてるかのどっちかだ。\n\nで、どっちなんだい?", 0x23568846, 0x924d775e, 0x42b15a26, nil, 0x7012c387, "...m." },
  [1041] = { "隊商の道", "DarkshireのClerk Daltryと話して下さい。", "どうやらあんたのことを見誤ってたらしい。そんなことはめったにないんだがな。\n\nちょうどいいことに、あんたが探してるそのVelindeのことは覚えてるよ。ナイトエルフのプリーストが、うちみたいな汚くて古ぼけた――でも運送にはうってつけの!――キャラバンと一緒に旅したがるなんて、そうそうあることじゃないからな。\n\n北へ向かう途中で別れたんだ。あの人はDarkshireを目指してた。あそこの書記はありとあらゆる記録をつけてる。何か役に立つことを知ってるかもしれん。\n\nジャングルでは気をつけな。一番ましな時でさえ、命取りになる場所だからな。", nil, "ここ数年の奇妙な出来事と一緒に、できる限り旅人についてもしっかり記録をつけていますよ。いつ役に立つかは分かりませんが……役に立つ時はまあ大体喜ばしいことじゃないですね。あなたがお探しのVelindeさんについて言ってるわけじゃありませんよ。", 0xdd9cc4a0, 0x03b1164f, 0x16629094, nil, 0xba9aab3a, "...m." },
  [1042] = { "Carevin家", "DarkshireのJonathan Carevinと話して下さい。", "いや、Velinde StarsongがDarkshireに泊まったという記録はないな……とはいえ、言わせてもらえば、ナイトエルフのプリーストが宿屋に部屋を取るなんて、とても想像できないね。言いたいこと、分かるだろう?\n\nだが、あんたが言ってた狼男たちのことなら聞いたことがある。ついこの間、Calorが奴らの首を数珠つなぎにして町へ来たんだ。CalorはCarevin家と一緒に働いている。悪魔やアンデッドや、その他の化け物を狩るハンターの一家だ。Jonathanと話してみるといい。あの家の当主だ。", nil, "暗い時代だ。ざわめく枝という枝から不吉な報せがささやかれ、どの岩の下にも悪が潜んでいる。\n\nそんな時代に、見知らぬ余所者が我が家に入ってきてworgenのことを尋ねる……疑ったことを詫びはせん。欲しいのは答えだけだ。\n\nそして答えは、必ず聞かせてもらう。", 0x5b4165bb, 0x260919bb, 0x60b610fd, nil, 0xa9084ff2, "...m." },
  [1043] = { "Eluneの鎌", "Scythe of Eluneに関する手掛かりを探して、DarkshireのJonathan Carevinのところへ戻って下さい。", "その話は本当のようだな……君の動機を完全に理解したわけではないが、君のDuskwoodでの用事が、この森からworgenを一匹でも多く排除することなら、理解よりも結果を取ろう。\n\n南に、worgenに乗っ取られた鉱山がある……奴らはどこからともなく現れたが、我々の知る限り、奴らが最初に見つかったのはそこだ。\n\n君の用事を済ませるといい。ただ、何か重要なものを見つけたら、私にも知らせてほしい。悪との戦いにおいて、我々はどんな助けでも受け入れる。", "備えのない者にとって、森は危険だ。武器は手元に、知恵はさらに身近に置いておくことだ。さもなければ、次にこの呪われた森へ足を踏み入れた時が最後になるかもしれん。", "興味深い話だ、{name}。Carevin家の影響力は、この厄介事の根を見つけ出して永久に始末できるほど大きくはないが、Duskwoodのworgenどもの数を抑えるためにできることはやろう。\n\nすでにCalorには、これを最優先とするよう指示してある。", 0x0767908c, 0x803b9a4e, 0x6cd0e968, 0x9f8262d0, 0x837fbc53, "....." },
  [1044] = { "解き明かされた疑問", "DarnassusのThyn'tel Bladeweaverのところへ戻って下さい。", "worgenの問題は我々が抑え込む。その心配は無用だ。君の友がこの森に招き入れたこの悪は封じ込めよう。あの者の行いについて、私は恨みを抱いてはいない。この時代には奇妙なことが起きているのだ、{name}。そして闇に休息はない。\n\nこれ以上引き止めはすまい。君がDuskwoodの鉱山で見つけたことを聞くべき者は、ほかにもいると思うからな。", nil, "これがVelindeの最期だというのか? 高位女司祭がこれを聞けば落胆されるだろう。失踪の前は、二人は良き友であったのだ。それに、Scythe of Eluneは我らが女神からの恵みとして彼女に授けられたものに違いない。それが彼女の従者たちの手から失われたことは、私には落ち着かぬことだ。\n\nだが、それはまた別の機会の話だ。あなたが成し遂げたことには、少なからぬ感謝を負っている。", 0x44407ecd, 0xb8c245b0, 0x8d9eb68f, nil, 0x9bb2d02d, "...m." },
  [1045] = { "Raeneの浄化", "Lake Mystralの近くにいるKrolgのために、Bloodtooth Guardを4体倒し、Ran Bloodtooth's Skullを取り戻す。", "ナイトエルフは時と同じくらい古い。だが奴らの傲慢さは、自らの世界そのものを滅ぼしている。そして今、我らの暮らしまでも滅ぼしている。だが、それはもはや抑えられない……\n\n多くのことでエルフを責めはするが、我らの行いの責任は我ら自身にある。穢れを別にしても、我らは大きな悪をなしうるのだ。\n\nRan Bloodtoothはそうした悪の一つだ。力に飢え、欲望に満ち……穢れは奴をさらに強くしただけだった。エルフへの憎しみは燃えているが、奴らの子供たちの不幸を望みはしない。だから我らは、自分たちの身内を取り締まらねばならないのだ。", "Ranはもう倒したか、友よ?\n\nナイトエルフでさえ、本当に奴の怒りを受けるべきではない。奴の憎しみは私自身のものよりもさらに激しく燃えているが、奴の心はもはや奴自身のものではない。奴はこの森のすべての自然の生き物にとって脅威なのだ。", "よくやってくれた、友よ。\n\n森はまだ穢れているが、少なくとも我らはかつての栄光を取り戻すためにささやかな役目を果たしたと分かっている。また我のもとへ戻りたいと思うなら、同族との語らいを喜んで迎えよう。\n\n達者でな。いつか、もっと穏やかな時代に、我らの部族が再び出会えるかもしれぬ。", 0x30e3be54, 0x6e8f41fa, 0x326975a1, 0x15e560ac, 0x765c3955, "....." },
  [1046] = { "Raeneの浄化", "Ran Bloodtooth's SkullとDartol's Rod of TransformationをAstranaarのRaene Wolfrunnerのところへ持って行って下さい。", "自分の部族のもとへ戻り、ここでの勝利を知らせるがいい。\n\n戦利品を見せ、栄光に浸るのだ……", "SentinelsはここAshenvaleでできる限りのことをしているが、我々がこれだけの地歩を得られたのは、あなたのような{race}たちのおかげだ。", "では、これがAshenvaleで最も凶暴なfurbolgの脅威の頭蓋骨というわけか？\n\nお前の力には大いに満足しているぞ、{name}。Sentinelsはいくら感謝してもしきれない。今後も我らの民を助けるため、お前を頼りにできることを願う。\n\nこのskullとDartol's Rodは、ほかの者たちが目にできるよう、敬意を払うべき場所に置くとしよう。\n\nTeronisも誇りに思うだろう。改めて感謝する。", 0x30e3be54, 0x331416f0, 0xe5eec590, 0x96cede1d, 0xdaa0c8c3, "....." },
  [1047] = { "新たなる辺境", "DarnassusのCenarion EnclaveにいるArch Druid Fandral Staghelmと、Kalimdorの辺境を探索するようにというCenarion Circleの呼びかけについて話して下さい。", "英雄たちへ告ぐ！\n\nCenarion Circleは、Kalimdorの広大な新天地の探索を手伝ってくれる健やかな者を求めている！ TanarisとGadgetzanのはるか西には、想像を絶する危険に満ちた禁断の荒野が広がっており、Circleは彼らに代わって行動してくれる意欲ある高潔な代理人を必要としている。\n\n関心のある者は皆、Cenarion Circleに謁見を求めること。詳しくは、Darnassusの大ドルイド、Fandral Staghelmと話すこと！", nil, "私がお前のような者にわずらわされたいと、なぜ思うのだ、{class}？ 待て――毎日こなしている重要な務めを中断して、お前がどこかの小道具を探すのを手伝ってやろうじゃないか。もちろんだとも、Darnassusの――いや、Teldrassil全体の――安寧など、お前の収集品のための安物を手に入れることの次で構わんのだからな。\n\nMoongladeの愚か者どもは助けを求めてきて私の時間を無駄にするし、今度はこれに耐えねばならんというのか？", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1048] = { "Scarlet Monasteryへ", "High Inquisitor Whitemane、Scarlet Commander Mograine、Herod, the Scarlet Champion、Houndmaster Lokseyを倒し、UndercityのVarimathrasに報告して下さい。", "Dark Ladyが北のLich Kingの侵攻という差し迫った問題に当たっておられる間、私はより身近な問題が然るべく片付けられるよう取り計らっている。\n\n間違いなく、Scarlet Crusadeを名乗る人間の害虫どもは、国内において我らにとって最も鋭い棘となっている。Tirisfal Gladesは、文字通りあの小さな赤蟻どもで溢れかえっているのだ。\n\nMonasteryへ赴け、{class}。そしてHigh Inquisitor Whitemaneとその側近の副官どもを葬り去れ。", "命令が明確ではなかったようだな、{class}。High Inquisitor Whitemaneを完全に葬り去ってほしいのだ。ついでに奴の幹部どもも始末してこい。\n\nあの狂信者、Scarlet Commander Mograineを殺せ。Scarlet ChampionであるHerodを叩き潰せ。そしてHoundmaster Lokseyとその汚らわしい犬どもも皆殺しにしろ。\n\nさあ、行け!", "お前はDark Ladyによく仕えた、{class}。私が頼んだのは決して小さな務めではなかった。\n\nForsakenへのお前の忠誠は記録された。そして戦いでのお前の粘り強さは忘れられることはないだろう。", 0x36a5202e, 0x13fd9f20, 0xbcc177e7, 0xcffed030, 0x58289948, "....." },
  [1049] = { "Compendium of the Fallen", "Tirisfal GladesのMonasteryからCompendium of the Fallenを回収し、Thunder BluffのSage Truthseekerのところへ戻って下さい。", "Earthen Ringは、疫病に苦しむ同胞に対して純粋な意図を持っていた。だが、Elder Councilの耳に囁いている者たちの動機を、誰が知りえようか？\n\n我らが手を結んだForsakenには、欺瞞に満ちた過去がある。我らの盟約はあまりに性急だった。Orgrimmarからの警告に耳を傾けていれば、Cairneは賢明だったのかもしれぬ。\n\nScarlet Monasteryの奥深くに、Compendium of the Fallenが眠っている。狂った人間の狂信者どもが守っている。奴らのやり方は狂気から生まれたものだが、その研究は役に立つかもしれぬ。", "Cairneは勇敢で高潔な指導者です。私は自分の命さえ彼に預けられます。けれど、この政情の中で私が信用できないのは、他の者たちなのです。\n\n手に入る限りの知識を集める機会が得られれば、族長に的確な助言を差し上げられるでしょう。\n\nTirisfal Gladesへは行ってみましたか? Scarlet Monasteryへは? Compendium of the Fallenは、この複雑なパズルのひとかけらにすぎないのです……", "Compendium of the Fallenだ！ その本が本当に存在するのかと疑い始めていたところだ！\n\nThunder Bluffのトーレンによく尽くしてくれたな、{name}。お前の献身は忘れられぬぞ。", 0x9fedee71, 0xe62f1495, 0x3f852df9, 0x73e5ad0d, 0x706a516d, "....." },
  [1050] = { "Mythology of the Titans", "MonasteryからMythology of the Titansを回収し、IronforgeのLibrarian Mae Paledustのところへ持って行って下さい。", "未来は避けられない！ 我々は、Great Seaに落ちる雨粒のように、未来へと身を投じているのだ。\n\nだが、過去を学べば、何が起こるかを知り、未知のものにより良く備えられるかもしれない。\n\nLordaeronに恐ろしい災厄が降りかかる前、Tirisfal Gladesには知識の砦がひっそりと存在していた。古いMonasteryの書庫には、Mythology of the Titansという本が収められていたと噂されている。\n\nそれを持ってきてくれ。そうすれば、共に過去の秘密を解き明かせるかもしれない！", "Monasteryはかつて、修行中のパラディンのための神学校だった。光の砦だったそこは、Scarlet Crusadeの狂った狂信者どもの手に落ちてしまった。\n\nCrusadeは自分たちの目的を高潔なものだと信じていた。この地をアンデッドの疫病から浄化するという目的をな。だが狂気がその志を穢し、今や奴らはすべての者の敵となっている。\n\nMythology of the Titansを持ってきてくれ。研究して、ここIronforgeに保管したいのだ。\n\nMonasteryの腐った広間は、そんな歴史的な宝にふさわしい場所ではない。", "聖なる書を救い出してくれたのか！\n\n長い旅だっただろうし、あの本を手に入れるのは決して容易な務めではなかったに違いない。だがお前の成功で、Ironforgeのドワーフたちは恩恵を受けるだろう。\n\nExplorers' Leagueを代表して礼を言うぞ、{name}。", 0xd3cfccd9, 0x6a8c1f98, 0x8de6b786, 0xfbf31aac, 0x64c6bcaa, "....." },
  [1051] = { "Vorrelの復讐", "Vorrel Sengutzの結婚指輪をTarren MillのMonika Sengutzに返して下さい。", "意志は自由になったが、私はもうDark Ladyに仕えることはできない。Azerothでの私の時は終わりを迎えたように感じる。私の生命力は砕け散ってしまった。\n\nInterrogator Vishasが私をこんな目に遭わせたのだ！ 何週間も拷問され！ 結婚指輪を奪われ、奴の妻に贈られた。あの外道め！\n\n復讐を……復讐を果たしたい！\n\nあの傲慢な愚か者は、Lake Lordamereのほとりに住む大切な妻、Nancyのことを自慢していた。その女を突き止め、殺し、私の結婚指輪をTarren Millにいる私の妻、Monikaに返してくれ。\n\n私の最後の願いを聞き届けてくれ……", "何の用だ、よそ者?", "Vorrelはなんと苦難に満ちた生を送ったことか。それに、なんと良き伴侶だったことか……\n\nあの汚らわしい人間どもめ！\n\nVorrelは逝ってしまった。もう二度とアンデッドとしての生を楽しむことはない。せめて、お前が彼の名のもとに果たした復讐を慰めにできる。そのことには感謝する。\n\nさあ、悼むために独りにしてくれ……", 0xdc1da838, 0xb0195a96, 0x4965c07b, 0x1e59f0ac, 0x03add0ca, "....." },
  [1052] = { "Scarletの道を下って", "Brother Anton's Letter of CommendationをSouthshoreのRaleigh the Devoutのところへ持って行って下さい。", "我らScarlet Crusadeは、HearthglenからTirisfal Gladesに至るまでの砦を領有している。Lordaeron中にある我らの浄化の拠点を、我々は大いに誇りにしている。\n\n君はDesolaceでアンデッドを相手に力を示した。だが、疫病の真の脅威はLordaeronにある。\n\nEastern KingdomsにあるSouthshoreの町へ向かえ。Raleigh the Devoutという名の十字軍士を探すのだ。私の印章を押したこの推薦状を渡せば、彼が我らのScarlet Monasteryの名誉ある場所へ君を案内してくれるだろう。", "誰だ? 私に何の用だ?", "Brother AntonがまだScarlet Crusadeの教えを広めているのですか？ なんということでしょう……", 0xaeca3093, 0x57a21639, 0xacd22c21, 0x1efda351, 0xc98191de, "....." },
  [1053] = { "光の名において", "High Inquisitor Whitemane、Scarlet Commander Mograine、Herod, the Scarlet Champion、Houndmaster Lokseyを倒し、SouthshoreのRaleigh the Devoutに報告して下さい。", "私はかつて、名誉と忠誠と誇りをもってScarlet Crusadeに仕えていた。彼らの大義は高潔なものだと信じていた。Azerothからアンデッドを一掃するという大義だ。\n\nだがTirisfal GladesのMonasteryで過ごすうちに、彼らが現実を見失いつつあることに気づいた。今や彼らは、Crusadeの陣羽織を着ていない者は皆、疫病に冒されていると考えている。罪のない男女が、疫病に冒されているとされて拷問されたのだ。\n\nScarlet Crusadeは光の名のもとに打ち砕かれねばならない。{name}、君があの狂った体制を滅ぼすのだ。", "Monasteryの腐敗は、最高位の幹部たちが排除されるまで終わらない。\n\n光の名において、High Inquisitor Whitemane、Scarlet Commander Mograine、Scarlet ChampionであるHerod、そしてHoundmaster Lokseyを討て。彼らが倒れれば、真の大義が再び燃え上がるかもしれない。それまでは、Crusadeの道を横切る者は皆、危険にさらされる。\n\nSouthshoreから出発し、それを成し遂げるのだ!", "光に仕える者は決して命が失われることを喜びはしませんが、時には王国と世界のより大きな善のために、そのような犠牲が必要になることを受け入れなければなりません。\n\nMonasteryでのあなたの行いによって、多くの罪なき命が救われました、{name}。あなたの粘り強さに敬意を表します。", 0x90a29d76, 0x55b9e680, 0xa8cc842d, 0xb5e3d9d7, 0xefc4c627, "....." },
  [1054] = { "脅威の間引き", "Dal Bloodclaw's SkullをAstranaarのRaene Wolfrunnerのところへ持って行く。", "Astranaarの真北にはThistlefur furbolgがいます。私の斥候の報告では、この数か月で彼らの数が大きく増えたそうです。あまりに増えすぎれば、Astranaarを直接襲う勇気を得てしまうかもしれません。\n\nできる限り多くの彼らの仲間を倒してください。そして彼らの企みが挫かれた証として、族長の頭蓋骨を持ってきてください……ひとまずは、ですが。\n\n私はここAstranaarに留まり、あなたからの知らせを待っています。Eluneがあなたと共にありますように。", "furbolgの穢れによって、Ashenvaleはかつての栄光のほんの一部にすぎない姿になってしまった。", "よくやった、{name}。\n\n我々は常にfurbolgの脅威にさらされている。これで奴らをもうしばらく寄せつけずにいられるといいのだが。", 0xc9327026, 0x0cf5cd78, 0xbc890332, 0xc10729bc, 0x94c3bc40, "....." },
  [1055] = { "Raeneの浄化", "ムーンウェルのShael'drynのところへ戻って下さい。", "今や完成した杖が、あなたの手の中にある。Shael'drynはあなたの成功を聞きたがるだろう。", nil, "やり遂げたね、{name}！ よくやった！", 0x30e3be54, 0xa7333bfb, 0x652f01d5, nil, 0x9327f633, "...m." },
  [1056] = { "Stonetalon Peakへの旅", "Stonetalon PeakのKeeper Albagormのところへ行く。", "森の精霊たちが、あなたは勇敢で旅もいとわない者だと教えてくれました。\n\n南の、Mystral Lakeからそう遠くないところに、Talondeep Pathという名のトンネルがあります。このトンネルを抜けると、Stonetalon MountainsのWindshear Cragと呼ばれる地に出ます。そこに着いたら南西へ進んでCragpool Lakeを越え、それから北へ、険しい坂を登ってStonetalon Peakまで行ってください。\n\nそこでKeeper Albagormが待っています。彼の頼みに耳を傾けてください、{race}。\n\n旅は危険なものになるでしょう。", nil, "ようやく来たか。Faldreasは森の精霊の声に耳を傾けたようだな……", 0xb967664b, 0xecb8a211, 0xb0111aba, nil, 0x3ad69b06, "...m." },
  [1057] = { "Charred Valeの奪還", "Bloodfury Harpiesを6体、Bloodfury Ambusherを6体、Bloodfury Slayerを6体、Bloodfury Roguefeatherを6体倒してほしいと、Stonetalon PeakのKeeper Albagormは言っています。", "森の精霊の守り手であるそなたなら、我がなぜ憂えているのか察しがつくであろう。\n\nそなたはこの頂にたどり着くまでに、この山々を越えてきた。この地に降りかかった惨状をきっと目にしたはずだ。強欲がこの神聖な丘の破壊を招いたのだ。\n\n南のCharred Valeは、実業家どもの強欲な機械の軍勢によって火を放たれた。さらに悪いことに、この地に入り込んだBloodfuriesが、再生を始めるための我らの通行を拒んでおる。\n\nあの卑しいharpiesを追い払うのだ、{name}！", "Charred Valeをかつての豊かな森に戻すまでには、なすべき仕事が山ほどある。\n\nあの忌まわしい脅威どもをこの地から一掃するのだ、{name}! そうして初めて、自然のものを取り戻し始めることができる。", "Bloodfuriesがこれほど大きな損失を被った今、ようやく大地を癒す本当の仕事を始められるかもしれません……", 0x3dc3d0c0, 0xe2dfdbfc, 0x38e3847a, 0x64c961c6, 0x08e244c5, "....." },
  [1058] = { "Jin'Zilの森の魔術", "Malaka'jinのWitch Doctor Jin'Zilは、Stonetalon Sap 5つ・Twilight Whisker 5つ・Courser Eye 30個・Fey Dragon Scale 一つを求めています。", "ワクワクするのだよ!\n\n3人の小さなエルフのための、3つの小さな檻!でも、あの愛しい木を抱きしめるお友達を、どうしてやろうかな?そうだ、味わわせてやろう……何と言ったかな……森の魔法を!\n\nStonetalon sapがたっぷり要る。あの忌まわしい猫どもからは、twilight whiskersを持ってきておくれ。これにはcourser eyesもたっぷり要るね、もちろん――目はいくらあっても足りないのさ。ああ、忘れちゃいけない、fey dragonの貴重な鱗も一枚な。\n\n急いでStonetalon Peakへ行くのだ、{name}。森の魔法を煎じられるようにな!", "かわいそうなエルフのお友達を見てごらんよ。みんな檻に入れられて、はしゃぎ回る森もないなんて!\n\nそれで、sapは見つけてくれた? twilight runnerのwhiskersはどう? fey dragon scaleなんて持ってないよね?\n\nそれとeyes! eyesがたーくさん要るんだ! eyesをたっぷり入れなきゃ、強烈な森の魔法の薬なんて混ぜられないんだから!", "ああ、この愛らしい森の乙女はなんて幸せなんだろう! この特製調合薬で、ちょうど家にいるような安らぎを感じさせられるだろうよ!", 0xd3c89429, 0x92c3cbae, 0xe1ca5db1, 0x7327810a, 0x33e6fef9, "....." },
  [1059] = { "Charred Valeの奪還", "Thousand NeedlesとFeralasの境にいるFalfindel Waywarderのところへ行って下さい。", "Bloodfuriesは鎮圧されました。ですが、手を打たなければ、彼らはすぐにまた態勢を立て直すでしょう。\n\nBarrensのはるか南に、Thousand Needlesという地があります。Thousand Needlesを西へ進み、Feralasの緑豊かな森の外れに着いたら、Falfindel Waywarderという名のドルイドに会えるでしょう。\n\nこの偉大で賢明なドルイドは、Charred Valeの再生を助ける偉大な森の精霊を呼び出すことができます。\n\n私たちの窮状を伝えてください！ すぐに彼を探し出してください！", nil, "Keeper Albagormがそなたをこれほど急いで寄こしたのは賢明であった。\n\n手遅れになる前に、大いなる森から助けを呼び出し、Charred Valeへ向かわせられぬか試してみようぞ。", 0x3dc3d0c0, 0x9d2cf9a3, 0xc8c5b4c2, nil, 0x1237db66, "...m." },
  [1060] = { "Letter to Jin'Zil", "StonetalonのMalaka'Jinの洞窟にいるJin'Zilに、Darsok's letterを届けて下さい。", "よくやってくれたな、{name}。君はまさに幸運のウサギの足だ。見てもらいたいものがある。\n\nharpiesはもともとBarrensの者ではない。ここからずっと北西にあるStonetalonという場所から来ている。君にとってはおそらく危険な場所だろうが、この手紙をそこに住む古い友人に届けてほしいんだ。Jin'Zilという名の呪術医だ。\n\nSerena Bloodfeatherが死んだと知れば彼は喜ぶだろう。それに、Stonetalonは君にとって面白い場所になると思うよ。", "怪しい奴だな。私に見せたいものでもあるのか?", "あああ、Darsokからの手紙か。何年かあいつからは便りがなかったな。\n\nそれで、Bloodfeatherの最後の生き残りは死んだんだって? そいつはいい知らせだ。Serena Bloodfeatherの姉を殺すのに、我が友Rokhanがすんごいmok'nathal族と共に行ったのを思い出すね。ああ、あんたみたいにまた若くなりたいもんだ。", 0x0a260107, 0xab583fdb, 0x4a63eb6f, 0x2660ed01, 0x0dff3a9f, "....." },
  [1061] = { "The Spirits of Stonetalon", "Stonetalon MountainsにいるSeereth Stonebreakと話してください。", "Stonetalon Mountainsの精霊は、ゴブリンとその召使いが土地を略奪し傷つけている事を怒っています。そう、土地が悲鳴を上げ、それを感じられる者たちは・・・聞きました。\n\nHordeの優秀なシャーマンSeereth StonebreakがStonetalonに派遣されました。彼女はゴブリンによる大規模な森林破壊を報告し、援助を求めています。\n\nStonetalonで彼女に会ってください。Barrens' Crossroadsを西に。彼女はGreatwood Valeの近くで野営しています。", nil, "ああ、{class}。よかったわ。略奪者に対処するにはあなたの技能が必要となるでしょう！", 0x5fee63cf, 0x8e781950, 0xb39a0a24, nil, 0x1a8942fd, "...m." },
  [1062] = { "ゴブリンの侵入者", "１５体のVenture Co. Loggersを殺し、StonetalonとBarrens境にいるSeereth Stonebreakのもとへ戻ってください。", "ゴブリンが運営するVenture Companyが木を切り倒し、広大な森を燃やしながらStonetalon Mountainsへ移動してきました。この地の精霊は痛みと怒りで何も見えなくなっています。この企業を止めなくてはなりません！\n\n北西に向かい、 Greatwood Valeを超えて Windshear Cragに入ってください。ゴブリンとその使用人が働いているのがみえるでしょう・・・彼らにHordeがStonetalonの搾取を許さないことを示してください。彼らがもっともよく理解する言葉・・・    暴力で。", "Greatwood Valeは北西にある、{name}。行け。この地を略奪しようとする者どもに恐怖を叩き込んでやるのだ!", "見事にやってのけたな、{name}。\n\nStonetalonの精霊たちを鎮めるには、最終的にはトーレンの長老たちの知恵が必要になるかもしれんが……\n\nVenture Companyの手下どもを排除したのは、奴らに対する良い第一歩だ。", 0x644d74b8, 0x3cf1a755, 0x1fcadd3c, 0xc7a094ee, 0x3bf2b616, "....." },
  [1063] = { "The Elder Crone", "Thunder BluffのMagathaと話してください。", "本当にStonetalonの精霊の世話をするつもりなら、taurenの年長者に相談しなければなりません。\n\n私は彼らのリーダーの名前を多くはしりませんが、その1人、Magathaという名を知っています。彼女はとても高齢で、たくさんのことを知っているといいます。もし、taurenから精霊の世話について聞くとしたら、彼女です。\n\nMagathaはtaurenの首都Thunder Bluffに住んでいます、 Elder Rise ・・・町の北東の絶壁の上です。Magathaと話をして、Stonetalon Mountainsの危機について伝えてください。", nil, "ごきげんよう。助言を求めているのかしら？", 0x0ddadd80, 0x5862420f, 0xdb16a13c, nil, 0x64075e6d, "...m." },
  [1064] = { "Forsakenの援助", "Thunder BluffのPools of VisionにいるApothecary Zamahと話してください。", "Taurenはこの地と堅い絆で結ばれています。それ故に、Stonetalonの窮状を聞くと心が痛むのです。大地を癒すためには、まず始めに病を取り除かねばならないのではないかと思っています。\n\nそして、Forsakenが私たちと同盟を組んでいるのは幸いでした。 彼らは病について多くを知っています。私は彼らが助けてくれると信じていますし、またそのことによって、互いの信頼をより強くしてくれることでしょう。\n\nApothecary Zamahと話してください。彼女はForsakenの使者で、学者でもあります。Spirit Riseの下にあるPools of Visionに彼女はいるでしょう。", nil, "あなたが来ることはMagathaが教えてくれました、{name}。私の心臓はもはや動いていないけれど、それでも、Stonetalonの精霊を思って悲しみを感じています。\n\n我らForsakenは、出来得る限りの援助をしたいと心から思っています。", 0x17b128b1, 0x5e69b8a1, 0x592f2fc1, nil, 0x577f8df2, "...m." },
  [1065] = { "Tarren Millへの旅", "Zamah's NoteをTarren MillのApothecary Lydonに渡して下さい。", "StonetalonからVenture Companyを駆逐するには、我々は過激な手段をとらねばなりません。過激に、しかし流血事態無しに。\n\n私の仲間なら、必要なものを持っているでしょう。名前はLydon。遠い地LordaeronのHillsbrad FoothillsのTarren Millの町に住んでいます。\n\nHillsbradへ行くには、我らの首都Undercityへ飛行船に乗って行きなさい。それから北へ向かいTirisfal Gladesへ出て、南西へ向かいSilverpine、南へ行けばHillsbradに出ます。\n\nLydonを探しだし、彼にこの手紙を渡して下さい。我々に必要なものを、この手紙に詳しく書いてあります。", "ああ、新しい実験体を連れてきてくれたのか?", "Zamahからの手紙だと?　そんなに遠くから手紙を寄越してきたのなら、重大なのに違いない。彼女がなんと言ってるか見てみよう……\n\nや、素晴らしい!　まさしく俺の分野だ!", 0x2c58c31f, 0x813d4940, 0x672cefbb, 0x377d5a13, 0x60e2ce21, "....." },
  [1066] = { "Blood of Innocents", "Tarren MillのApothecary LydonにVial of Innocent Bloodを5本渡してください。", "毒を作ろうと思ってるんだ。Venture Companyの奴らから暴力の血を抜いて、弱っちく、おとなしくさせてやる。StonetalonのHordeが抱えてる問題もこれで解決だろ?\n\nだが、毒を作るには罪のない奴らの血が必要なんだ。この材料を調達するのは難しい。\n\n運のいいことに、Syndicateっていう人間の盗賊集団がここいらにいる。あいつらはshadow mageを雇ってて……でだな、その魔法使いどもは自分たちで使うためにinnocent bloodを集めてるんだ。ま、良からぬ目的でな。\n\n南東にあるDurnholde Keepに行けば、Syndicate shadow mageがいるぜ。", "Syndicate Shadow Magesは見つけたか? 奴らから血を集めてきたか?", "こりゃすごい! Syndicateは面倒じゃなかったか?\n\n前にも言ったが、blood of innocentを手に入れるのは楽じゃないんだ。Syndicate shadow mageの奴らが俺たちのために難しい仕事をやってくれて、ラッキーだぜ。\n\n調合するまで、ちょっと待っててくれ……", 0x99926917, 0x85aef9f0, 0x6a790f80, 0x2f61455a, 0x43a8a3bb, "....." },
  [1067] = { "Thunder Bluffへの帰還", "Lydon's ToxinをThunder BluffのApothecary Zamahに渡して下さい。", "さあ、これが毒だ。Venture Companyの連中に使えば、これは素晴らしい結果を生むはずだぞ。恐らく、次から次に伝染していくぜ。\n\nまったく、俺の研究成果が実際使われるのを見られるなんて、実に愉快だ!\n\nだが、これを使う前にZamahのところへ持って行け。毒の効果を最大限に発揮できるように、彼女には配達方法を考えてもらわなきゃならんからな。", "戻ったか、{name}。Apothecary Lydonからの助けを持ってきたのか?", "Lydonの毒? 素晴らしいわ。あのLydonなら、この毒はVenture Companyに対して非常に効果があるはずです……", 0xb5d4ecc4, 0x34181589, 0x0f57607d, 0xac7d03bb, 0x301885a4, "....." },
  [1068] = { "切り刻み機械", "shredders XT:4とXT:9を倒し、Stonetalon MountainsとBarrensとの境界にいるSeereth Stonebreakのところへ戻ってください。", "シャーマンの精神魔法とドルイドの自然魔法には関係があります。それで私たちシャーマンにStonetalonの精霊の声が聞こえるのです。彼らのささやきの多くは私から去りましたが、１つのメッセージ、１つのビジョンが明確です・・・。\n\n私は、Greatwood Valeの北西、Windshear Cragにおいて、ありえない速度で木を切り倒す人型の機械のビジョンを見ました。あの金属の獣をとめなくては！\n\nビジョンの中で、機械には変わった記号がつけられていました：    XT：４そして、XT：９。", "木々の精霊たちが同胞を失って嘆き叫んでいる、{name}。shredderのXT:4とXT:9を破壊するのだ。さもなくば、Stonetalonは二度と癒えぬのではないかと恐れている。", "XT:4とXT:9という機械が破壊されたことで、Stonetalonの多くの精霊が慰められました、{name}。それらを失ったことで、Venture Companyがこの山々から立ち去ってくれることを願いましょう。\n\nもしそうならなければ、この地がこれまで受けてきた残虐も、これから待ち受けるものに比べれば色あせてしまうのではないかと恐れています。", 0x2ad62d6a, 0xa1ab4fd0, 0xd582b30c, 0xf176340a, 0x8d125b87, "....." },
  [1069] = { "Deepmoss Spiderの卵", "Deepmoss Egg15個をRatchetにいるMebok Mizzyrixに渡して下さい。", "スパイダーエッグオムレツがBooty Bayで新しくブームになってるんだ! 問題なのは……Booty Bayにゃ卵がないことだね。\n\nそこで俺はチャンスを嗅ぎつけたのよ!\n\n北西のStonetalon MountainsにあるWindshear CragとSishir Canyonには、deepmoss spiderが生息してるんだ。そいつの卵を持ってきてくれたら、大金を払ってやるよ!\n\nWindshear Cragだと、卵は木の残骸の下にびっちりあるはずだ。\n\nSishir Canyonは……えっと、もし胃が弱いようだったら、Windshear Cragで卵を集めるべきだと思う……", "eggsは手に入れたかい、{name}? もうWharfmaster Dizzywigと輸送の取引をしちゃったんだよ!", "持ってきてくれたのか! ありがとう!\n\n波止場管理人のDizzywigに渡して、Booty Bayに出荷するんだ。もう儲けた気分が味わえるよ!\n\nこれはあんたの取り分だ、{name}。あんたなしじゃ、この取引は出来なかったよ。", 0x14d2d688, 0xf245c60e, 0x270b2709, 0x883bef30, 0x74f54230, "....." },
  [1070] = { "Stonetalonの警備", "Stonetalon MountainsのWindshear Cragへ入る谷を見下ろしているKaela Shadowspearを見つける。", "こんにちは、{name}。\n\n見たところ、旅への憧れでいっぱいのようですね。Stonetalon Mountainsには行ったことがありますか？ Venture Co.やナイトエルフの他の敵たちに苦しめられている地です。\n\n最近、Sentinel Wolfrunnerが、あの地で起きていることを調べるために私の友人Kaela Shadowspearを送り出したのですが、まだ彼女からの便りがないのです。Allianceがノームのメイジを同行させたので、なおさら心配しています……きっと何か厄介事の兆しに違いありません。\n\n彼女を見つけて、私に報告してもらえませんか？", nil, "ああ、Taraの頼みでAshenvaleから来たのですね。彼女が、そして故郷と友が、どれほど恋しいことか。他の任務のために冒険者を引き抜いているくらいですから、Sentinelsでうまくやっているのでしょう。彼女を誇りに思います。\n\nお会いできて嬉しいです、{name}。", 0xf1b5310d, 0x9ed94a98, 0xee657ad7, nil, 0x44b73423, "...m." },
  [1071] = { "ノームの休息", "Venture Co. Loggersを$N1体とVenture Co. Deforestersを$N2体倒し、StonetalonのGaxim Rustfizzleのところへ戻って下さい。", "いいかい、{name}、僕はEnlightened Assembly of Arcanology, Alchemy and Engineering Sciencesの一員で、僕の目標は……いや、僕の「義務」はだね！ 魔法と調合と機械の融合が彼らの森を救えるってことを、ナイトエルフたちに示すことなんだ。\n\nでもこれは厳しい戦いでね、ゴブリンはどうやらウサギみたいに増えるらしい。最新の発明品を作る時間さえないんだよ！\n\n計画を立てて準備する時間が必要なんだ。でもそのためには、東のWindshear Cragでゴブリンを食い止めるのを手伝ってほしいんだよ……", "そちらの戦いの様子はどうだ、{name}?", "手伝ってくれて本当にありがとう、{name}。実はちょうどいいところに戻ってきてくれたよ。\n\n完璧な計画を思いついたと思うんだ……爆薬さ。いや、それが計画ってわけじゃないけど、計画の一部なんだ。\n\nほら、ゴブリンどもを少し追い払うのに強力な爆薬を使ってきたんだよ――心配しないで、みんなが思ってるほど危なくはないから。山の縁沿いで要所をいくつか爆破すれば、奴らをけっこううまく追い立てられるんだけど、ここ数日は補給が足りなくてね……", 0x81885f31, 0x000ad726, 0x4f827ebf, 0x8ed33a78, 0x1460c1f4, "....." },
  [1072] = { "昔の同僚", "IronforgeのLomac Gearstripと話す。", "俺が考えてる装置は、これまでで一番進んだ型なんだ。だが動かすには特別な薬が要る。この任務がお前の最後になるかもしれないんだから、どうせなら上物を用意したほうがいいと思ってな。\n\nそのためには、強力な爆薬が必要になる。Nitromirglyceroniumだ。\n\nNG-5を作れるのは、俺の古い友人のLomac Gearstripだけだ。Tinker Townで探してみな。\n\nお前があいつを説き伏せてNG-5を作らせてくれたら、俺は装置の設置に取りかかる。", nil, "ほほう……Gaximに言われて来たって？ お前が嘘をついてないって、どうして分かるんだ？！ ん？ んん……？", 0xad49e719, 0xa710c50b, 0x2f2357b3, nil, 0xcaefb60e, "...m." },
  [1073] = { "無能 + 薬品 = 楽しい", "Minor Mana Potionsを$N1個とElixirs of Minor Fortitudeを$N2個、IronforgeのLomac Gearstripのところへ持って行って下さい。", "ハハハ……森を壊すゴブリンを止めるのにNitromirglyceroniumが要るだって？！\n\n君がGaximを知ってようが知るまいがどうでもいい……君か奴らがこっぱみじんに吹っ飛ぶのを見たいってだけで、ブツをくれてやるよ。\n\nただ問題があってね。在庫が切れてるんだ。\n\nでもこうしよう。正しい薬を持ってきてくれたら、すぐに作ってやるよ。\n\n僕の最高傑作のサンプルをただでやる前に、せめて錬金術師としての腕があるってことくらい証明してもらわないとね。", "potionsがなけりゃNitromirglyceroniumは作れないよ……作るのに欠かせないんだ。", "これなら十分だ。\n\n知らなかったら、よそ者よ、お前は錬金術に通じてるって言うところだぜ。いいね、いいね……世の中、剣と魔法だけじゃないってことさ、だろ？", 0x5ce18882, 0xfad1f6dd, 0x0bf71576, 0x36a2a5fb, 0x7db747d1, "....." },
  [1074] = { "無能 + 薬品 = 楽しい", "NitromirglyceroniumをStonetalonのGaxim Rustfizzleのところへ持ち帰って下さい。", "ほらよ、よそ者。でも気をつけて扱えよ……不安定な代物だからな。\n\n本当にGaximの友達なら、よろしく言っといてくれ。そうじゃないなら、せいぜい自分を吹っ飛ばして楽しむんだな。", "おお、やったやった、戻ってきたね。", "あなたの仕事は完璧に果たされた、{name}。\n\nNG-5は、ダイナマイトの荷車に点火するための調合に欠かせない成分なのだ。\n\n何だと？ そう、ダイナマイトだ……荷車何台分もの。完璧な陽動になる、本当だとも……まあ見ているがいい。", 0x5ce18882, 0xced1e491, 0xa98e7a8f, 0x3742a9e2, 0x1ee3952b, "....." },
  [1075] = { "Maurenからの巻物", "StormwindのCollin Maurenを見つける。", "よし、じゃあ次は俺の計画の遠隔起爆の部分だ……おっと、まだ説明してなかったか？\n\nよし、手短に言うとこうだ。ちょっとした魔法を使えば、お前がそばにいない時に爆薬を爆発させられるようにできる。今、ボタンを一つ押すだけで、好きな時にNG-5を爆発させられる装置を組み立てているところなんだ。\n\nだがそのためには、Stormwindにいる友人の呪文が要る――Collin Maurenって名前だ。あそこのメイジ地区にいる。人間だから、見つけるのに苦労はしないはずだ。", nil, "さて、あなたが必要としているこの呪文だが。離れた場所から爆薬を起爆できるようにするもの……ふうむ。", 0x58c40a09, 0x1b3699f4, 0xf43ca5a0, nil, 0x723899cb, "...m." },
  [1076] = { "Westfallの悪魔たち", "Dust Devil DebrisをStormwindのCollin Maurenのところへ持って行って下さい。", "ああ、分かった気がします。伝言の呪文……それが彼の求めている効果でしょう。\n\nその呪文を刻み込んだ巻物を作らなければなりません。そのためには、dust devilの残骸が必要です。\n\n私が残りの材料を集めている間に、Westfallへ行ってその邪悪な生き物を一体見つけてきてはどうでしょう？ 危険ですが、Gaximの実験に付き合う覚悟があるなら、あなたの手に負えないことはないでしょう。\n\n戻るまでここで待っています。", "こんにちは、{name}。私が必要としている素材は見つかりましたか?", "少しだけ時間をくれ。すぐに巻物を用意しよう。", 0xf0e28ebb, 0x2aa2e96c, 0x3e02eba9, 0x7f60f7de, 0x19cadc30, "....." },
  [1077] = { "Gaximへの特別配達", "Scroll of MessagingをStonetalonのGaxim Rustfizzleのところへ持って行って下さい。", "どうぞ、{name}。これで十分でしょう。\n\n次にGaximに会ったら、よろしくお伝えください。この冒険が完了したら、その話を聞くのを楽しみにしています。\n\nごきげんよう。", "ハハ! 戻ってきたな! 持ってきたか? 呪文は手に入れたか?", "これは完璧だ、{name}！ よくやった。\n\nこの呪文をNG-5と混ぜ合わせれば、完璧な遠隔爆弾ができる。\n\n完璧な陽動を起こしてやるから、その隙に忍び込んで、Venture Co.の手紙と工学設計図を盗み出してくれ。\n\nそうすれば、奴らの森林伐採もきっと遅らせられるだろう。", 0xd1462095, 0x51ae1c5d, 0x1b8d59b2, 0xdd1faf10, 0xbe0ac519, "....." },
  [1078] = { "Maurenのための回収", "Crystalized Scalesを8個、StormwindのCollin Maurenのところへ持って行く。", "旅人たちがしょっちゅうStonetalon Mountainsのことを聞いてくるの。冒険の人気の場所みたいね――wyvernを探していようと、elementalを探していようと、Venture Co.に用があろうと関係ないのよ。\n\nStonetalonの奥深く、Charred Valeの中には、かつてbasiliskの一種がいたの。その鱗を粉になるまで挽くと、私が作ったいくつかの呪文のための素晴らしい触媒になるのよ。\n\nそのbasiliskがまだ生きているなら、鱗をいくつか手に入れたいわ。\n\n急がなくていいから、ゆっくりどうぞ。でも、お代ははずむわよ。", "また会ったね、{name}。\n\nStonetalonのValeから、もうscalesを持って帰ってきたのかい?", "これは完璧です、{name}。本当にありがとうございます。\n\nいつの日か、あなたが私を助けてくれたように、私もあなたを助けられるといいのですが。", 0xf7d838e2, 0x2360a1f8, 0xc942697b, 0x291f5038, 0xdba69ed3, "....." },
  [1079] = { "秘密作戦 - アルファ", "Windshear Cragの製材所からVenture Co.'s Engineering Plansを回収して下さい。", "いよいよだよ、{name}。よく聞いてね。装置は完成して、いつでも使える状態だ。\n\nこのページを持って行って――起爆装置と爆薬について、それとどこに仕掛けるべきかを詳しく説明してあるから。\n\n忘れないで、任務の成功はどれだけ破壊を起こすかで決まるわけじゃない。Plan Alphaの成功は、Cragpool Lakeの南にある製材所の中から、Venture Co.の設計図を持ち帰れるかどうかにかかってるんだ。", "設計図は手に入れたか、{name}?", "本当にすごい！ これはVenture Co.にとって大打撃だ。\n\n奴らの機械の弱点を見つけられるし、その設計を俺たちの発明に取り入れることもできる。まったく、素晴らしい日だよ。", 0x67625d6d, 0xdbfd5680, 0x4c8cfe7c, 0x7e92c08b, 0xf3532bc5, "....." },
  [1080] = { "秘密作戦 - ベータ", "Windshear Cragの東端にあるWindshear MineからVenture Co. Lettersを回収して下さい。", "Plan BetaはPlan Alphaとまったく同じだよ、{name}。\n\n陽動を起こして、それから奴らの大事な手紙を盗み出すんだ。\n\n肝心なのは奴らの手紙を手に入れること……それを忘れないで。\n\n爆薬を仕掛ける場所は、もう渡したページに書いてある。とにかく生きて、その手紙を持ってここへ戻ってきてね……", "首尾はどうだった、{name}?", "信じられない、{name}！ KaelaもSentinelsもきっと大喜びだ。君の腕と僕の発明があれば、僕たちは無敵だよ。", 0x435bdad7, 0xaaab2588, 0xd5c09f15, 0x30cd8aea, 0xea15a34a, "....." },
  [1081] = { "Tyrandeの歓迎", "DarnassusでTyrande Whisperwindを見つけて下さい。", "{name}、Tyrande Whisperwindご本人も、この任務に加わってくれたあなたに感謝したいと思っておられるに違いありません。\n\n表面上はそう見えないかもしれませんが、あなたが始める手助けをしたことは、Stonetalon Mountainsにおける私たちの足場を大いに強めるかもしれないのです。\n\nこうした暴虐に対抗する私たちの味方だと思ってくださるなら、DarnassusのTemple of the MoonにいるTyrandeに会いに行ってください。", nil, "こんにちは、{name}。あなたの名前は確かに以前から聞いています。まだ若さにあふれてはいますが、あなたが自ら選んだ道を見て嬉しく思います。\n\n感謝のしるしとしてこれを受け取っていただければ、とても光栄です。", 0x2ecc6a2b, 0xbb227158, 0x02acff07, nil, 0x42a56151, "...m." },
  [1082] = { "Sentinel Thenysilへの近況報告", "AshenvaleのSentinel Thenysilのところへ戻って下さい。", "{name}、ここで手を貸してくれたことは、実に立派な行いでした。\n\nGaximと私が生きていると伝えれば、Sentinels of Ashenvaleがあなたに十分な報酬をくれるでしょう。私たちがVenture Co.を止め、大地を癒す道を順調に進んでいると伝えてください。\n\nAstranaarのTara Thenysilを訪ねてください。あなたが良い知らせを持って戻ったことを、彼女は喜ぶでしょう。", nil, "ありがとう、{name}。あなたはSentinelsに貢献してくれました。\n\nKaelaが……それにGaximまでもが元気にやっていると知って嬉しいです。\n\nあなたは私たちの感謝に値します。", 0x8cbe9e1c, 0xa02009ab, 0x0efa59cf, nil, 0xb214a8e6, "...m." },
  [1083] = { "怒れる霊", "Charred Valeにいる炎のエレメンタルからSmoldering Embersを$N1個手に入れ、StonetalonのKaela Shadowspearのところへ持って行って下さい。", "Venture Co.がValeに何をしたのかは分かりませんが、そこの生き物たちに圧倒されたのは明らかです。\n\n彼らは森に火を放ち、破壊の発明品を使ってValeをできる限り壊滅させました。\n\nですが、その無知ゆえに、彼らは別のものまで解き放ってしまったのです。燃え盛る精霊たち――炎と石と怒りのエレメンタルです。\n\nこうした生き物が野放しになっている限り、この地がEluneの微笑みを見ることはないでしょう。\n\n数を減らした証として、彼らのsmoldering embersを持ってきてください。", "初めてCharred Valeを見たとき、私は泣きそうになったよ、{name}。", "我らの敵の残骸か……そなたの力は我らの役に立っておる、{name}。感謝するぞ。", 0x541e782d, 0xfbe7515f, 0x91e83ed1, 0x4ab60f8c, 0x584d2d40, "....." },
  [1084] = { "傷ついた古代樹", "Corroded Shrapnelの破片を一つ、StonetalonのKaela Shadowspearのところへ持って行って下さい。", "Valeの守り手であるtreantsが、Venture Co.を撃退したことに何か関わっていたのは明らかだと思います。残念ながら、かつて偉大な守護者だった彼らでさえ、今では穢れてしまいました。\n\nGaximは、彼らの穢れが、ゴブリンが撤退中に使った武器と何らかの形で結びついていると考えています。\n\nそれが本当かどうか確かめるため、傷ついたtreantからサンプルを集めてGaximに調べさせると、私は彼に約束しました。\n\nその破片をいくらか持ってきてください。そうすれば、あのノームがもっと詳しく教えてくれるでしょう……", "Venture Co.がこれまでどう使ってきたかに関係なく、Gaximならshrapnelの使い道を見つけるだろうという気がする。", "ありがとう、{name}。\n\nこれだけあれば、treantがどうやって穢されたのかをGaximが突き止めるには十分すぎるはずです。すぐに彼に届けましょう。", 0x00a0d96c, 0x41c21b98, 0x08fc2949, 0x1516aa6d, 0x95a6d4f4, "....." },
  [1085] = { "Stonetalonの警備", "Gaximと話して下さい。", "ナイトエルフとノームが手を組むほど、ここStonetalonの状況は明らかに深刻なのです。\n\nVenture Co.はこの地を荒廃させ、私はその破壊を止めることに時間の大半を費やしてきました。\n\nGaximを早まって判断しないでください。彼は私たちが協力する必要性を理解しています。\n\n私たちを助けたいのなら、まずGaximと話してください。\n\nまだ良い知らせを持たせてあなたをTaraのもとへ帰せないのが残念です。おそらく、じきに。", nil, "油断ならない……油断ならなくて危険、それがこの土地さ。\n\nでも僕がここにいるのは、昔ながらの工学とちょっぴりの魔法の助けがあれば、ここも少しは安全になるってことをナイトエルフに示すためなんだ。\n\nいいかい、魔法を完全に断ったってナイトエルフのためにはならない――彼らには魔法が必要なんだ。世界にも必要さ。それに工学と錬金術も加えれば、間違いなしだよ。可能性は無限大さ。", 0xf1b5310d, 0x404858ae, 0xf9b6af40, nil, 0x80f212a2, "...m." },
  [1086] = { "飛行機の発着場", "Venture Co.の飛行機発着場にToxic Foggerを運び、Apothecary Zamahのところへ戻って下さい。", "毒の準備が出来ました。あとはこれを運ぶだけです。{name}、あなたがこれを運ばねばなりませんよ。\n\nVenture Company本部とStonetalonの現場との間で、軽い積荷やメッセージをやりとりするための手段が必ずあるはずです。たとえば小さな発着場のような……飛行船が使うような大きなものでなく、恐らく飛行機のためのものです。StonetalonのVenture Company支配下にある地域を探索し、今お話した発着場を見つけねばなりません。もし存在しているのならば、ですが。もし見つけたら、この毒を置いてくるのですよ。\n\nこれを設置し、そして走るのです。", "Venture Companyの飛行場が本当にあるのなら、それを見つけ出さねばならない、{name}。", "発着場を見つけたのですか? よくやりましたね、{name}!　ゴブリンたちはあなたの配達にさぞ驚いたことでしょう!　あの毒が本部まで届いていることを祈りましょう。\n\nあなたは一族によく尽くしました。それと忠告しておきますが、Venture Companyの者を毒殺することにあなたが罪悪感を抱く必要などありません。彼らはもっとひどい仕打ちを受けて然るべきですから。\n\nForsakenから同盟者へ、ちょっとした知恵を授けましょう。\n\n「暗黒の道から退くことなかれ、それが勝利への道であるならば」と。", 0x081eaf2b, 0x0f1268ec, 0xf51ce998, 0x3c03c943, 0x4e325c2a, "....." },
  [1087] = { "Cenariusの遺産", "Sun Rock Retreat付近のBraelyn Firehandのために、Son of Cenarius・Daughter of Cenarius・Cenarion Botanistをそれぞれ4人ずつ殺して下さい。", "この忌まわしい地へのわが憎しみは、そなたには想像もつくまい。Cenariusの眷属どもと、頂にいるkaldoreiのドルイドどもが、その哀れな力で魔力の流れを押しとどめているのだ。奴らの哀れな領地……奴らの愛する森から、これほど南に離れた地でさえな。\n\nできることならJaedenarへ戻り、魔力の流れに酔いしれたいものだが、わが主は務めを果たすまで戻ることを許さぬ。\n\nそなたも我と同じく、ナイトエルフとその仲間を好いてはおらぬはずだ。我に手を貸せ。さすれば我らの目的はどちらも果たされよう。", "ここで魔力を導くのは、穴だらけのバケツで井戸から水を汲むようなものだ。", "もう感じる……そうだ……甘美なる力……押し寄せる奔流。kaldoreiどもは愚かだ。この世界の贈り物を退け、お前の血脈を歌いながら流れる魔法のうねりを拒むとはな。\n\nその燃えるような抱擁なくしては、生など色褪せた紛い物にすぎぬ!", 0xed1982a5, 0xbcbb0b9b, 0x1af6bead, 0x47aaba26, 0x59ff2e1e, "....." },
  [1088] = { "Ordanus", "Sun Rock Retreat付近のBraelyn FirehandにOrdanus' headを渡して下さい。", "奴らは魔力の流れを止められると思っていた。とんだ思い違いだ。奴らはOrdanusを隠せると思っていたが、奴の首は我がいただく!\n\n魔力は我に真の視力を授ける。そう……そこにいる。十字路……Ashenvale Forestの大樹の頂に。名は……Raynewood。森の神の最も年長の息子たちの一人だ。我が見つける前に、奴らは頂からあの者を連れ去ったが、あの者の時は尽きかけている。\n\nそれを我のもとへ持ってこい。さすれば強大な贈り物を分け与えてやろう。", "我が主にStonetalonの頂へ赴くよう命じられたとき、我に必要なのは、我らが古きAzsharaの神殿の聖なる遺跡を這い回り、その手で神聖さを汚すナイトエルフどもを滅ぼすことだけだと思っていた……だがOrdanusは我の手をすり抜けたのだ。", "かつて、遠い昔にOrdanusを知っていた。奴は同族らしい傲慢さを持ち、Highborneにさえ己を上と構えていた。\n\n今ではその頭も、そう高くは掲げられまい? なあ、{name}。\n\n報酬を約束したな。それは受け取ってもらう。こちらへ来い。", 0xac86867a, 0xf081772c, 0x3c3cbd54, 0x28ec0d86, 0x664423d0, "....." },
  [1089] = { "隠れ家", "Stonetalon PeakのDenへ向かって下さい。Gatekeeper's Keyを使い、ドルイドの隠し持つ鍵を奪取して下さい。鍵はTalon Den Hoardを開けるために使います。", "ドルイドどもはStonetalon PeakにTalon Denを築き、そこに強力な品々を数多く保管している。\n\n奴らは、それが悪しき者の手に渡らぬよう、込み入った仕掛けを考え出した。\n\n幸い、我は奴らの一人から……いくつか詳しいことを引き出すことができた。\n\nDenの入り口にある小さなランタンの中に、Gatekeeper's Keyが隠されている――それがあれば、Denの各所にある隠し箱を開けられる。その隠し箱の品々を使えば、中央の一角にある奴らの宝の山を開けられるであろう。", "石には3つの鍵穴が彫り込まれている。", "三つの鍵がそれぞれに符合する鍵穴へと滑り込むと、輝かしい光の中にたくさんの秘宝が姿を現した。", 0x69a60aaa, 0x32a26601, 0x5799a343, 0x17c59583, 0x5dc68227, "....." },
  [1090] = { "Gerenzoの命令", "Piznikが採掘を終えたら、不思議な鉱石を受け取ってください。", "実はさ、俺はかつてこの現場で二番目に偉い人間だったんだ。それもGerenzoが乗っ取るまでの話さ。俺のボスのZiz Fizziksをクビにして、俺を鉱山送りにしやがった。でも、Zizには、ここに残って情報を集めろって言われてる。Gerenzoの企みを突き止められたら、Zizの新しいボスがたんまり払ってくれるんだ。\n\nとにかく、俺に分かってるのは、Gerenzoがこの金緑色の鉱石を大量に掘らせてるってことだ。Zizに持っていくサンプルを手に入れてやれるけど、俺が取ってくる間、見張りの巡回に気をつけててくれよ。", nil, "ありがとう、{name}。一瞬かなり危なかったし、たぶん目立ちすぎてしまった。\n\nだが大事なのは鉱石の見本が手に入ったことだ。できるだけ早くZizのところへ届けよう。", 0xce6824bd, 0x17fb1d28, 0x30d3cff4, nil, 0x96af83cc, "...m." },
  [1091] = { "Kaelaの近況報告", "Venture Co. LettersをKaela Shadowspearのところへ持って行って下さい。", "{name}、この手紙をKaelaのところへ持って行って。きっと彼女も知りたがるはずだよ。少なくともSentinelsはね。\n\n僕たちがどれだけうまくやったか、それにちょっとした魔法がなければ成し遂げられなかったってことも、ちゃんと伝えてね。", "どうした、{name}? 何か用か?", "これは実に興味深い。\n\nあなたとGaximは本当によくやってくれました、{name}。ありがとう。", 0x2303e574, 0x88de288b, 0xcc598924, 0x1573cda6, 0xcb79207d, "....." },
  [1092] = { "Gerenzoの命令", "Stonetalon MountainsのZiz FizziksにUnidentified Oreを届けて下さい。", "俺もそろそろ、ここから逃げ出すことを考えたほうがよさそうだ。ここで起きたことが上の連中に伝わるのに時間はかからないし、あいつらが俺との再会を喜ぶとは到底思えないからな。\n\nこっそり抜け出してZizと落ち合うよ。新しい仕事を見つけてくれるといいんだけどな!\n\nこの散らかりようを少し片付けてみるけど、あんたはすぐに鉱石のサンプルをZizのところへ持っていってくれ。Windshear Cragの西側のどこかに野営地を張るって言ってた。幸運を祈るよ。", "何かお手伝いできることはあるかな?", "ああ、Piznikを残していったのは正解だったな。Undermineの技術者連中は、きっとこいつに大いに興味を示すはずだ……\n\nもちろん、ちょっとばかり自分の取り分は取っておくがね。知らなけりゃ痛くもないだろう?", 0xce6824bd, 0x5ff378be, 0xe65a92f9, 0xdf112bb5, 0x1883fb16, "....." },
  [1093] = { "Super Reaper 6000", "Stonetalon MountainsのZiz Fizziksのために、Super Reaper 6000 Blueprintsを手に入れる。", "Venture Companyがここでやったことはひどいもんだろ？何を考えてたんだか。ゴブリンの会社がノームを雇うなんて！\n\n運よく、Sputtervalveは天才を見る目があってね。俺が追い出されたすぐ後に雇ってくれたのさ！\n\n聞いた話じゃ、あいつらはどでかい伐採機械を造ったらしくて、Sput'はその設計図を盗んでほしいんだとさ。ところがGerenzo――忌々しいノームめ――は俺を見つけ次第殺す気でいる……代わりに設計図を盗んできてくれないか？操縦士の誰かが持ってるはずだ。", "設計図は見つかったか? 新しいボスにいいところを見せたくてたまらないんだ。俺の忠誠心を納得してもらえたら――まあ、納得させられる限りでだけどな……ゴブリンの名誉にかけて、ってやつさ――俺のかなりすごい才能を安心して使ってくれるようになるといいんだが。", "おい、それってもしかして俺が思ってるやつか？ やったぜ！\n\nさて、どれどれ。うえっ……こんなのどうやって理解しろってんだ……ノームの考え方はさっぱり分からん。言っとくが、あいつらが車輪を作れたってだけでも驚きだよ。あいつらが大好きな空飛ぶ機械なんてなおさらだ。", 0xfe7b3d9f, 0xfe2d59bd, 0xad532ea7, 0x7a6f86e7, 0x7531d6d0, "....." },
  [1094] = { "さらなる指示", "BarrensのSputtervalveにthe Sealed Envelopeを届けてください。", "この封筒には、彼らが私を放り出したときにつかむ事のできた情報のすべてがはいっています・・・Venture Companyの内部資料、いくつかのマニュアル、専門的なもの・・・おお、もちろんSuper Reaper 6000の青写真も。\n\nSputtervalveはBarrensのRatchetに住んでいます。見つけるのは難しくないでしょう、彼は小さくて緑の同胞です。", "やあ! 何かご用かな?", "Fizziksか、ええ？ あいつは信用できんが、この情報は十分使えそうだ。Venture Companyを厄介払いできるなら、何だってくれてやるんだがな。\n\nとはいえ、奴らは良い機械を考え出すのも確かだ……奴らの考案した改良を使って、俺たちも得をしてきたことは否定できん。", 0xd12c0eee, 0xc9ab2557, 0xb0912f98, 0x73864487, 0xd6844379, "....." },
  [1095] = { "さらなる指示", "あたらしい指令をStonetalon MountainsのZiz Fizziksに持って行ってください。", "Venture Companyに雇われたこのノームの問題は、Undermineにちょっとした混乱をもたらしました。trade princesはRazdunkがこのGerenzoと付き合うことを承認していません。\n\nRiddlevoxは私に問題を解決するように頼みました、1人ないしはそれ以上のtrade princesからの指示であることは間違いないでしょう。もちろん、部長はそれを言いませんでした。私の勘ですよ。\n\nどちらにしても、Gerenzoは排除されなければなりません、そして、それはFizziksに丁度いいテストになるでしょう。", nil, "Gerenzoを始末する？それなら何の異存もない話だ。\n\nノームというだけでも厄介だが、Gerenzoについて知ったことでなおさらだ。どうやら奴はGnomereganの主任技師の一人で、そこで秘密の計画に携わっていたらしい――我々はDun Moroghに十分に潜入できず、詳しいことは突き止められなかった。計画は失敗に終わった。報告によれば、それが何であれ、文字通り奴らの目の前で爆発したそうだ。", 0xd12c0eee, 0x4cd21a54, 0x5de65c53, nil, 0x539bf0fe, "...m." },
  [1096] = { "Gerenzo Wrenchwhistle", "Gerenzo Wrenchwhistle's Mechanical ArmをStonetalon MountainsのZiz Fizziksのところに持って行ってください。", "Gerenzoには一度会ったことがあるが、言っておく、見られた顔じゃない。肉は腐り落ちかけているようだし、体には金属や歯車を継ぎ足して、手足のいくつかは機械のものに取り替えている。\n\nここから北東、Cragpool Lakeのはるか上、水車の近くから、Gerenzoは現場全体を見張っている。俺じゃあそこまで戦って登るなんて無理だ。Gerenzoの相手をするなんてなおさらだ……でも、あんたならたどり着けそうに見える。\n\nあいつを殺してくれたら、それに見合う礼はするぜ！", "SputtervalveはGerenzoが死んだという証拠を欲しがるだろう。奴の機械の腕なら十分だと思う。", "見てみろよ、こいつを……こんなものを思いつくのはノームぐらいだぜ。腕を切り落としてこんなものに付け替える理由がさっぱり分からん。両腕はそのままにして、もう一本足せばいいだけじゃないか！\n\nまったく、ノームってやつは……\n\nとにかく、これでGerenzoは使い物にならなくなった。これで証拠として十分だといいんだがな。そうすりゃSputtervalveが俺をGadgetzanの、いやひょっとしたらUndermineのTinkers' Unionの工房のどれかに配属してくれるだろう。", 0x896fbf9b, 0xf0c79254, 0x2e6098b0, 0xe15dc320, 0xfc121249, "....." },
  [1097] = { "Elmoreからの依頼", "Grimand Elmoreと話す。", "StormwindにはGrimand Elmoreというドワーフの鍛冶師がいてな。どうやら配達業務をやってくれる人を探しているみたいなんだ。北の故郷まで荷物を届ける仕事だと思うぜ。\n\nあんたは丈夫そうだねえ！もし興味があるなら、Grimandから話を聞いてみるといい。本当はここでやってもらいたいことがあるんだが、ドワーフ達とは深い絆で繋がっているから、ま、困った時はお互い様ってやつかな。\n\nやつはStormwindのDwarven Districtにある武器屋にいるぜ。町の北東エリアがそうだ。", nil, "オマエが配達してくれるってか？助かるぜ！", 0x30749260, 0x6ac05387, 0xf12b5a6f, nil, 0x7d006a0a, "...m." },
  [1098] = { "ShadowfangのDeathstalker", "Deathstalker AdamantとDeathstalker Vincentを見つけて下さい。", "Shadowfangへの攻撃に備え、情報を集めるために2人のdeathstalkersがあの城へ送り込まれた。もう何日も経つが、奴らは戻ってこない。だが、攻撃を成功させる望みを少しでも持つなら、奴らの報告を受け取らねばならん!\n\nそこで君の任務だ、{name}。南のShadowfang Keepへ行き、Deathstalkers AdamantとVincentを見つけろ。見つけ出し、助けが必要なら手を貸してやれ。\n\nこの任務は重大であると同時に危険なものだ、{name}。しくじるなよ。", nil, "Vincentの亡骸が、砕けたまま静かに横たわっている。\n\nDeathstalker AdamantがHadrecへ報告を送るだろうが……Vincentが得たそれ以上の詳細は、彼とともに失われたままだ。\n\nだがその手には、小さな装身具が握られている……", 0xf489f723, 0x203b0fd7, 0x8e3dd6ce, nil, 0x7257ca64, "...m." },
  [1099] = { "ゴブリンの勝利！", nil, nil, nil, nil, 0x5cd506d5, nil, nil, nil, nil, ".mmmm" },
  [1100] = { "Lonebrow's Journal", "Henrig Lonebrowの日誌を読んで下さい。", "あなたはHenrig Lonebrowの風化した日誌をゆっくりと開いた……", "その心配そうな顔を見ると、何かおかしなことがあったようですね……", "死んだドワーフから日誌を見つけたと言いますか? 熟読する時間を少し下さい……", 0x017f62c3, 0x0bed5682, 0xcc37a881, 0x8fe5acd8, 0x155e6539, "....." },
  [1101] = { "Kraulの老婆", "Razorflank's MedallionをThalanaarのFalfindel Waywarderに渡して下さい。", "哀れなHeralath! それに、このドワーフ……Lonebrowも。なんと勇ましい魂だったのだろう。\n\n彼らの勇敢さを無駄にしてはいけない。この老婆……Charlga Razorflank……止めねばならぬ。\n\n確かに、Kraulへ攻め入るのは危険だろう。Darnassusへ知らせている時間はない。{name}、老婆を殺すパーティを集めるんだ。\n\n葬った証として、Razorflank's Medallionを持ってきてくれ。", "Charlga RazorflankがRazorfen Kraulで兵を集めている限り、この地は大きな危険にさらされている。", "あの老婆は葬られたか。最高の知らせだ、{name}。\n\n危機的状況の中で、君と同じ勇敢な者を見るのは清々しいだろう。\n\nRazorflankの手先を片付けることで、この地域での研究を続けられる。Agamagganの眠る場所を腐敗させた正確な出来事について、さらなる知識を得ることができよう。\n\nしかし、その疑問に対する答えは、むしろ裏切りにあるのではないかと思うのだ……", 0xa74f8d30, 0x22dec81e, 0x5bd9e9cd, 0x680b6418, 0xfdde12e2, "....." },
  [1102] = { "復讐の運命", "Razorflank's HeartをThunder BluffのAuld Stonespireのところへ持って行って下さい。", "Cairneは、ここThunder Bluffで我らの民を一つにまとめた高潔な指導者だ。\n\nだが私は、他の者たちのように、我らを先祖の地から追い出した者たちを簡単には許せない。我らの民は何十年もBarrensの南部に住んでいた。あの地は我らにとって聖なる地だった。だが我らは数多の敵に追い払われたのだ。\n\nRazorfen Kraulの中から邪悪な軍勢を集めている老婆、Charlga Razorflankには、報いの運命が待っている。\n\nRazorflankの心臓を持ってきてくれれば、私は安らかに死ねるのだ、{name}。", "Razorfen Kraulの穢れた獣どもがその穢れた巣から追い払われたと分かれば、復讐が果たされたと知って、私は安らかに眠ることができるだろう。\n\nKraulからquilboarを追い払ってくれたか? Razorflank's heartという形で良い知らせを持ってきてくれたのか?", "Razorfen Kraulの忌まわしい部族も、今や我が同胞の痛みを知ったようだ。汚らわしい獣どもには当然の報いだ。\n\n聖なる地から者を追い出すことは、最も厳しい復讐に値する罪だ。\n\nありがとう、{name}。我が苦境に力を貸してくれて。", 0x7cb6ec12, 0x603cb78d, 0xc5e9f80f, 0x51a8f39e, 0x5aebdfcb, "....." },
  [1103] = { "水の呼び声", "Minor Manifestation of Waterに話しかけるのに失敗したら、Silverpine ForestのTiev MorduneにWater Saptaを渡して下さい。", "よう、同胞よ！あんたもここの水を清めて、Islenに理解を示しに来たのかい？\n\nおれはちょうど堕落した水の精霊を自分で倒したところでな、これから腕当てと残りの水の滴を火鉢に載せるとこなんだ。\n\nなんだって？ああ。何かがうまくいかねえときの気持ちは、Tievにはよーく分かるさ。まあ、清らかな水の精霊にもう一度会う必要があるなら、Tievがたっぷり助けてやれるぜ。\n\n準備ができてる証として、Islenからwater saptaをもらって持ってきな。そしたらおれは、自分の品を納めるのを待っててやるよ。", "saptaは持ってるか、同胞よ?\n\n前にも、穢れた水の精霊を倒した後で困ったことになった奴がいてな――待ちすぎたみたいで、思ったより早く霊界から出てきちまったらしい。他の奴にそんなことが起きるのは見たくねえから、しばらくここで待って、他に俺の助けが要る奴がいねえか確かめるとするよ。", "ああ、準備ができたようだな……\n\nわしの品を火鉢に入れよう。そうすればお前さんも精霊と話ができる。\n\nそれと、saptaで精霊の世界を覗くことなど何も心配いらん……このTievじいさんは、saptaの魔法の仕組みについて一つ二つ心得がある。\n\nさあ、わしと一緒に祠へ下りて、共に精霊たちと語ろうではないか、仲間よ。", 0x1f0e11aa, 0x672cce87, 0x1e351ce9, 0xec055306, 0x2814faec, ".....", nil, nil, 0x58f5d2d9, 0xff56d459, 0x7c436da4 },
  [1104] = { "塩原の毒", "Salty Scorpid Venom6個をShimmering FlatsのFizzle Brassboltsに渡して下さい。", "ロケットカーに使うたくさんの設計をしてきたんだ! そりゃもうたくさんのな! そのすべてを試さなきゃならんのだ!!\n\n俺は新型燃料に取り組んでいるところさ。燃えたら超超超熱いぜ!! 完璧に合成してはいないんだが、必要な物は分かってるんだ……\n\nShimmering Flatsをうろついてるscorpidどもには、めちゃくちゃたくさん塩の入ってる毒がある。すごく変わってるだろ! そして、それこそ俺が必要としてる物なんだ!\n\n毒を持ってきてくれ。そして、信じてくれ……俺たちの車は飛べるって!!", "やあやあやあ! あのvenom、手に入れた??", "やったあ! この毒はよく効くよ! ありがとよ、{name}!\n\nあとは煮詰めるだけだ、skipper-otomerに塗って、nega-catalystを加えて、それから……ちくしょう! 俺のメモはどこだ!?", 0x79971380, 0x01790f68, 0x8cc37d86, 0x9c48d083, 0x08780fd1, "....." },
  [1105] = { "硬くなった甲羅", "Hardened Tortoise Shellを9個、the Shimmering FlatsのWizzle Brassboltsに渡して下さい。", "オレの兄弟はロケットカーの新しい燃料を研究してるんだ。あいつは頭がいいよ、本当に。頭が良すぎて……あいつが作った新しい燃料は車のシャシーを浸食するほど強力じゃないかと思うんだ!\n\nそうなる前に、燃料タンクを補強したい。\n\nこの平原にいる亀はとても硬い甲羅を持ってる。その甲羅をロケットカーの新しいタンクに使いたいんだよね。新しい燃料に耐えられるタンクだ。\n\n君なら充分できそうだな。甲羅をとってきてくれないか?", "兄弟が新しい燃料の設計を進めていて、それが心配なんだ。できるだけ早く亀の甲羅を使った燃料タンクに取りかからないと!\n\n{name}、shellsはもう手に入れたかい?", "持ってきてくれたのか! ありがとう、{name}!\n\nうわあ、思ったより硬い甲羅だ! ヘへ、こいつを使う時は、箱の道具が全部曲がっちゃいそうだなあ!", 0x63fa007a, 0x1e243142, 0x73ecbecf, 0x5543b2ae, 0x8597a885, "....." },
  [1106] = { "Martek the Exiled", "BadlandsのMartek the ExiledにFizzle's Letterを渡して下さい。", "車をより速く走らせる新しいエンジンを開発しているんだ! 飛んでしまうほど速いんだ! もんのすごく大きな圧力に耐えられるピストンを作りたい。充分な強度のピストンが作れなくて、試みは全部失敗しちまった!\n\nでも、どうすればいいか知ってるに違いない奴がいる。\n\n名前はMartek the Exiled。偉大な鍛冶職人で、金属のことは誰よりもよく知ってる。この手紙を渡してくれ、彼なら助けてくれると思う!\n\nだけど、遠い遠い彼方……Azeroth大陸のBadlandsにいるんだ。そこのキャンプに、ゴブリンと一緒にね!\n\n彼を見つけてくれ!", "ほう、俺を見つけたか。大したもんだ。\n\nGath'Ilzoggのために作ったあの斧のことで来たのか? それともDuchess Pamayの名誉を取り戻しに来たのか?\n\n実のところ、どっちでも構わん。戦いに来たのなら、さっさと済ませようじゃないか……", "Fizzleの紹介だって？そういうことなら話は別だ！もちろん手を貸すよ。Fizzleとその兄弟は、俺の死を望まない数少ない連中のうちの2人なんだ！\n\nで、Fizzleはピストンを作りたいって？あいつが考えてるどんな負荷にも耐えられるほど頑丈なピストンをな。Fizzleのことだ、今度の新しい車は車輪のついた火山みたいなもんだろうよ！", 0x8475249c, 0xc310416f, 0x61d51e0e, 0xc7dfe421, 0xa6a733b4, "....." },
  [1107] = { "皮で覆われた尾びれ", "Encrusted Tail Fin10個をthe Shimmering FlatsのWizzle Brassboltsに渡して下さい。", "俺たちのロケットカーは塩原で一番速いんだぜ! 速すぎて……摩擦でバラバラになっちまうんじゃないか心配だよ!\n\nそれを防ぐには、駆動部品をコートする合成物質を作らなきゃならない。頑丈じゃなきゃいけないし、壊れにくく、そして塩の腐食に耐えなきゃならない。でなきゃ、Shimmering Flatsにいる間に浸食されちまう。\n\n{name}、Vile Reefって聞いたことあるかい? Stranglethorn Valeの海岸の外れにある。そこにはSaltscale murlocが住んでて、奴らの尾びれは合成物質の重要な素材なんだ。", "tail finsは持ってきた? 車をそれ自身の速さから守れないなら、このレースじゃ長くはもたないよ。", "ありがとう、{name}! これを磨り潰した後は他の素材と一緒に溶かして、合成物質のできあがりだ。その後、この車をスピードから安全に保護できるはずだ。\n\n安全か。何かにぶつからない限りはね……", 0x521760a7, 0xa2243a5b, 0xbcd5e84c, 0x06d9ca4a, 0x9b78a1b3, "....." },
  [1108] = { "Indurium", "Indurium Flakeを10個、BadlandsのMartek the Exiledに渡して下さい。", "私は一族から離れるためだけにここへ来たんじゃない。Badlandsには価値のある金属があるんだ、{name}。もし手に入れる気があるならね。\n\nその金属はinduriumと呼ばれていて、運の良いことに、熱と圧力に対する高い抵抗力を持ってると言われている。きっとFizzleの車に役立つに違いない。\n\nだが確認させてくれ。induriumのサンプルで性質を実験したいんだ。\n\n本当のindurium鉱石はUldamanの奥深くにある。でも、BadlandsのStonevault troggたちは時々induriumの破片を持ってるんだ。\n\nその破片を持ってきてくれ。", "indurium flakesは見つかったかい、{name}? 炉を熱して、試す準備はできてるんだ。", "ああいいね、これなら上手くいくだろう。じゃあ、熱してみて、どうなるか見てみよう……", 0x08fb481b, 0x23fd1dab, 0x1896b9a9, 0x41471857, 0xb691a1fc, "....." },
  [1109] = { "行くぞ、行くぞ、Guano！", "Kraul Guanoを$N1山、UndercityのMaster Apothecary Faranellのところへ持って行って下さい。", "見ての通り、{name}、我々Royal Apothecary Societyでは、実に……興味深い実験を進めている。\n\nここの師匠として、我々の錬金術の試みの中でも最も野心的なものを監督するのが私の仕事だ。やるべきことは山ほどあるのに、時間はあまりに少ない！\n\n{class}にしてはずいぶん旅慣れているようだな。私を手伝ってもらえるかもしれない。\n\n珍しい物質が必要なのだ。汚らわしい代物でね。Razorfen Kraulと呼ばれるあの汚泥の穴にしかいない、珍しい種類のコウモリから採れる。Kraul Batsの糞を持ってきてくれ。そうすれば我々の研究を始められる……", "ああ、戻ってきたのですね。Kraul Guanoは手に入りましたか?", "素晴らしい！まさに我々に必要だった第一歩だ、{name}。", 0x13509179, 0x3a5d0734, 0xfacef853, 0x8ee6341f, 0xbe8d8c5f, "....." },
  [1110] = { "Rocket Car Parts", "Rocket Car Parts30個をShimmering FlatsのKravel Koalbeardに渡して下さい。", "へへへ、ここで行われてるすべてのレースで、道沿いにいくつか不幸な出来事が起きるのは驚くことじゃないぞ。Shimmering Flatsを見て回ったら、過去に起きたクラッシュの証拠を見られるだろうよ……ロケットカーの残骸がそこら中に散らばってるからな!\n\nそのパーツはノームとゴブリンにとって、カネに値するんだ。あいつらは車にくっつける仕掛けをいつも探してるからな。\n\nだから、行ってパーツを取ってきてくれ。山盛りとってきたら、たんまりはずむよ。", "{name}、Flatsへは行ってきたかい? 頼んでおいたpartsの山は持ってきてくれた?", "うおっ、こりゃすごい量だ！このガラクタの山にはいい物が混じってるぞ。きっといい値で売り払えるな。\n\nそれに……あの2枚の金属板の間に挟まって潰れてるのは、耳か？？痛っ！へへ、あのパイロットにだけはなりたくないね！\n\nありがとよ、{name}。ほら、報酬だ。それとタダで助言をひとつやろう……\n\nよく目を凝らせば、他人の悲劇の中にはいつだって儲けが見つかるもんさ。", 0x5a9bdbad, 0x535db2a5, 0x658f82aa, 0x875cee91, 0x26d7ef6d, "....." },
  [1111] = { "Wharfmaster Dizzywig", "RatchetのWharfmaster DizzywigにKravel's Parts Orderを渡して下さい。", "俺は人々が必要としてくれるようなことを自分の職とすることにしててね、あそこにいるノームたちは目一杯の部品注文が要るんだ。部品は一週間前にRatchetへ運ばれたんだが、俺は取りに行けない。\n\nそんなわけで、運び屋をする準備はいいかい? Ratchetへ行って、この注文書をWharfmaster Dizzywigに渡してやってくれ。彼は恐らく港にいるだろう。\n\nこれをやってくれたら、別の仕事も頼むつもりだよ。\n\n仕事ってのはな、我が友よ、マジで儲かる見込みがあってな……", "はっきり言いな! で、預けに来たのか、受け取りに来たのか?", "ああ、はい。Kravelへの部品ね。君が来てくれてよかった。これ何日も放置されててさ、錆び付くんじゃないかって心配してたんだよ!", 0x68543425, 0xdf36f17f, 0x20992db4, 0x0757cb25, 0xed60a7b4, "....." },
  [1112] = { "Kravelへの部品", "Kravel's Partsをthe Shimmering FlatsのKravel Koalbeardに渡して下さい。", "これがKravelの荷包みだよ、{name}。それから、これを届けた時に伝えておいてくれ……もっと特別な注文がしたかったら、ツケを払えってな!", "Ratchetまで行って、partsを手に入れてきたかい?", "素晴らしい、持ってきてくれたのか! じゃあ、これはノームのところへ持って行かなきゃな。でも最初に……\n\n小さな部品を一つ抜いておこう……", 0xa7b09232, 0x2dab0b5b, 0xbb280b93, 0xe5299e30, 0x2a306b0a, "....." },
  [1113] = { "Hearts of Zeal", "UndercityのMaster Apothecary Faranellは、Hearts of Zealを$N1個欲しがっています。", "なぜ珍しい種類の糞が必要なのか、と思うかもしれないな。この実験では、正反対の性質を持つ二つの化学物質が互いにどんな影響を及ぼすか見てみたいのだ。とりわけ、両方を常に毒性を持つ薬剤と組み合わせ、最も……おぞましい結果を確実にしたときにな。\n\nTirisfal Gladesの北東の峰々に、Scarlet Monasteryがある。そこにはScarlet Crusadeの狂った信奉者どもが集まっている。奴らを殺し、その熱狂的な心臓を持ってこい。\n\n我々の調合物は、この上なく邪悪なものになるだろう！", "Scarlet Monasteryから戻ったのか? この愉快な実験には心臓がたくさん必要なのだ!\n\n間違いなく、VarimathrasとDark LadyもScarlet Scumがいなくなって喜ぶだろう……", "おやまあ、これほどたっぷりの血肉を持ってきてくれるとは、{name}！実に見事な働きぶりだ！", 0xbfae077b, 0x5f08eecf, 0x800f2482, 0x44f3de68, 0xa76176c8, "....." },
  [1114] = { "ノームたちへの配達", "Delicate Car PartsをShimmering FlatsのFizzle Brassboltsに渡して下さい。", "必要な物が揃ったから、この部品をFizzle Brassboltsに渡してくれ。彼はこれを長いこと待っていたんだ。……注文品から俺が取り除いたこの小さな部品、彼は気付かないだろうね……\n\nだけど、わざわざそのことを彼に言うつもりはないよ。これは小さいし、ガラクタだから。\n\n信じてくれよ。", "何か持ってきてくれたの? いいね! 見せて!", "部品が来た! 俺のハイドロラチェット装置とリピーターボルト! とっても良く動くだろうね。ありがとう!", 0x1ad08f86, 0x9a3333a0, 0xf8802ac2, 0xdbabd704, 0xed11b7d6, "....." },
  [1115] = { "噂を広める者", "Booty BayのKrazekに話しかけて下さい。", "ノームたちの仕事は終わったから、ゴブリンの頼み事をする時間だ!\n\nゴブリンのレースパイロット、Nazz Steamboilはいつもその名前を使っていないのだと聞いた。彼が何故名前を変えるのか不思議でな。もしこれが秘密だったら……彼はその秘密を大事にしているのだろうかと。\n\nこの真相を知る者がいるとすれば、それはStranglethornの南端にあるBooty BayのKrazekだ。Krazekと話して、我らがゴブリンパイロットについて聞いてみてくれ。\n\nもし有益な情報が聞き出せたら、そこから利益が得られるかもしれないぞ。", nil, "お前さんNazz Steamboilについて知りたいのかい? Shimmering Flatsのレースパイロットじゃないか?\n\nああ、俺なら彼について何か見つけることもできるかもな……だが、簡単にも速くも安くも出来ないだろうね。", 0x6518f606, 0x774d6a49, 0xf050b56f, nil, 0xfa425368, "...m." },
  [1116] = { "沼地のDream Dust", "Speck of Dream Dust10個をBooty BayのKrazekに渡して下さい。Dream Dustはthe Swamp of Sorrowsにいるdragon whelpから集められます。", "Nazzに関する情報を得るのは大変だよ、{name}。ああ、かなりね。だがお前さんはその情報を得るため、はるばるShimmering Flatsからやって来た……別のところへ行く気はあるかい?\n\n俺が情報源と接触している間、お前さんは俺のために何か集めてきたらどうだい?\n\nうーん……何がいいだろう。dream dustはどうかな、Swamp of Sorrowsの子ドラゴンから集めてくるんだ。うん、匂い袋に入れるdream dustが欲しいな!\n\n取ってきてくれたら、{name}、お前さんが探してる情報を渡してあげよう。", "もう戻ったのか? dream dustは持ってきたか?", "さて、見てみようか。dream dustを見つけてきたね!\n\nで、沼はどうだったね、{name}? あそこで温かい飯を手に入れるのは簡単じゃなかったろ?", 0xf9743ed7, 0x05c45b2c, 0x48f50dee, 0xf88411b7, 0xc5a1b8ee, "....." },
  [1117] = { "噂をKravelへ", "Goblin Rumorsをthe Shimmering FlatsのKravel Koalbeardに知らせて下さい。", "何人か味方を使わなきゃならなかったからエルフワインの貴重なボトルをあげたけど、重要な推測は俺自身でやってやったよ!　でも、お前さんが求めてる情報は見つけてきた。\n\nさあ、我らが友Nazz Steamboilに関するちょっとした興味深いことを手紙にしたためた。お前さんの好きなようにこれを使いな。……これは、俺には危険すぎる。\n\nどこからこれを入手したか、誰にも言うなよ!", "Nazz Steamboilについて何か掴めた? 奴が秘密にしておきたがりそうなことは何か??", "いいよいいよ! これは面白い……とても面白いぞ。ははあ、次にゴブリンパイロットに会った時は、俺はひざまずいて頭を下げなきゃなるまいな。\n\nこれは充分価値のあるものだよ、{name}。Nazzはかなりの大金を支払うはずだ。彼の秘密を……秘密のままにしておくためにはね。", 0xcdd0f57d, 0x75808d45, 0x2bbb0a0a, 0x73bd4bf1, 0x6cceedee, "....." },
  [1118] = { "再びBooty Bayへ", "Booty BayのCrank FizzlebubにKravel's Schemeを渡して下さい。", "{name}、あんたはこの仕事を成し遂げ、なおかつ遂行中は口外しないという両方において、信頼できる{class}だ。\n\n新しい計画を立てたんだ。これは危険性が高いが、成し遂げれば俺たち二人とも大金を手に出来るんだ! それで、あんたはまさにやり通してくれる奴だと思ってるのさ。\n\n始めるには、Booty Bayへ戻ってもらわなきゃならない。済まんな、{name}。俺が頼んだ最近の仕事であそこへ行ったのは分かってる。だが今回は、Crank Fizzlebubと話してきてくれ。\n\nこの手紙を渡してやってくれ。もし手助けを必要としてたら、出来るだけ助けてやってほしい。努力に見合う価値はあるだろうよ。", "やあやあ。それで、{race}のような高貴なお方がBooty Bayまで何のご用で?", "分かった。Kravelは大きな計画を立てたんだなあ。あいつは腹黒い。ま、そんなところが好きなんだけどね。\n\nだから、あんたも正気を失わせる何かが要るってわけだな? 何か力強い物がね……\n\nZanzilがゾンビに与えてる混ぜ物を使えないかと思ってるんだけどさ……", 0x9cba550e, 0x5566a7e5, 0x670bdb89, 0xf163c276, 0x0610f3c8, "....." },
  [1119] = { "Zanzil's MixtureとFool's Stout", "Fool's Stoutを持ち帰って、Shimmering FlatsのKravelに渡して下さい。", "黒ビールを強力な酒にするためには、どうZanzilの混ぜ物を使えばいいか分かったぞ。Fool's Stout。これこそがKravelに必要な物になるだろうと思ってるんだが、試してからどう効くのか教えてほしいな。\n\nそれと{name}、この酒はずっと使わないでおいといちゃだめだぞ。Zanzilの混ぜ物は黒ビールのイースト菌に変な効果があって、フル回転で発酵を進めてしまうんだよ。だから、ずっと新鮮なままにしておけないからね。", "やあ、{name}。Fizzlebubは力になってくれたかい?", "素晴らしい! Fizzlebubがやってくれたか! 次に会うときまで覚えておこう。\n\nそれと{name}、ありがとう。君はすごくいい仕事をしてくれた。おかげで俺たち二人とも、大金を手に入れられるよ……", 0xce92d3f1, 0xf149b5d7, 0x402ded4a, 0x0307b06c, 0x499b8790, "....." },
  [1120] = { "ノームを酔っぱらわせろ", "Fool's StoutをGnome Pit Bossに渡して下さい。", "Fool's Stoutをピットクルーの一人に試したいんだ。あんたもノームにこいつを試してみたいなら、ここにある。こいつを持ってって、ノームの監督に渡してくれ。\n\nそれと、あまり遅くなっちゃだめだぞ。この黒ビール、しまいには腐っちゃうからね。", "やあ! 何か持ってきてくれたの?", "黒ビール? なんて気が利くんだ! ありがとよ!\n\nレースが近づいたら酒を飲むべきじゃないんだが……ピットクルーたちもちょっとは必要だろ。ところでよ、この酒そんなに強くないよね?", 0x24e5f87c, 0x3c180f29, 0x8fb51da1, 0x38862010, 0xb574d1ab, "....." },
  [1121] = { "ゴブリンを酔っぱらわせろ", "Fool's StoutをGoblin Pit Bossに渡して下さい。", "Fool's Stoutをピットクルーの一人に試したいんだ。あんたもゴブリンにこいつを試してみたいなら、ここにある。こいつを持ってって、ゴブリンの監督に渡してくれ。\n\nそれと、あまり遅くなっちゃだめだぞ。この黒ビール、しまいには腐っちゃうからね。", "何見てんだよ?", "ここにあるのは何だ? 酒だって?\n\nよし、ほんのちょっとだけならいいよね……", 0xc88eb9be, 0xbba58fbf, 0x79d74462, 0x95698fab, 0xc0f3aec4, "....." },
  [1122] = { "Fizzlebubへの折り返し報告", "Fool's Stout reportをBooty BayのCrank Fizzlebubに渡して下さい。", "Fool's Stoutはよく効くなあ! 俺ぁ次のレースに賭けたんだ……あんたが酔わせたクルーの車が負けますように!\n\nただ、もうひとつ頼みたいことがある……この手紙をBooty BayのCrank Fizzlebubに渡してくれ。テストが成功したことを知りたいだろうからな。\n\nそれと、これからのレースのために、この黒ビールがもっと手に入るといいんだけどなあ!", "やあ、{name}。あのstoutの効き目はどうだった? 強烈だろう?", "fool's stoutは成功したと書いてあるね。こいつはいい知らせだ!\n\nこの酒がもっと欲しいなら言ってくれ。そしたら、Zanzil's Mixtureをもっと持ってきてもらうからな。", 0xb72e948c, 0xb37ce04b, 0xbe9ce7a5, 0x3934cc96, 0xf0e76c71, "....." },
  [1123] = { "Rabine Saturna", "Moongladeのvillage of NighthavenにいるRabine Saturnaと話して下さい。MoongladeはFelwoodとWinterspringのあいだに位置しており、Timbermaw Holdを通り抜けると行きやすいでしょう。", "MoongladeにいるKeeper Remulosの宮宰Rabine Saturnaは、TanarisとUn'Goroの遙か西にある広大な荒れ地を探検するのに援助を求めている。彼はMoongladeの大集落Nighthavenにいる。\n\nそなたが如何に重要な存在であるか、そなたに伝えたい。DarnassusのナイトエルフたちとMoongladeのCenarion Circleとの間に、緊張が高まっているのだ。{name}、種族の壁を越えた先に目を向け、Cenarion Circleとのやりとりの中で、そなたの祖先の知恵をうまく使うのだ。うまくやってくれ。", nil, "私はRabine Saturna。Keeper Remulosと、この神聖な森の住人全てに代わってあなたを歓迎する。\n\nあなたが関心をもってCenarion Circleを助けて下さることを、大変有り難く思っている。トーレンはCenariusの信条に対して驚くべき傾向を示してくれ、彼らの代理人によって、Hordeはこの森では安全に迎えられる。Azerothの保護は、我々Cenarion Circleとトーレンの共通の目標なのだ。\n\nあなたは友だ、{name}。", 0x53da4216, 0x2d1faec5, 0xe985db77, nil, 0x0f210d32, "...m." },
  [1124] = { "荒野", "SilithusのValor's Rest graveyard近くにいるLayo Starstrikeと話し、Rabine's Letterを見せて下さい。", "Un'Goro Craterの西、北西の尾根を伝って行くとそこは過酷な荒野、Silithusだ。かつてそこでナイトエルフと悪の異界勢力との間に古代戦争が行われたことを知る者は少ない。邪悪は封印されたが、我々は感じているのだ……言い表しようのない恐怖の存在を呼び起こそうとする力が働いているのを。\n\nSilithusにいる我々の仲間の一人、Layo Starstrikeを捜し出すのだ。荒野で死んだ者たちが眠る最後の安息の地、Valor's Restにいる彼を捜せ。この手紙を渡せば、相応に信頼するはずだ。", "そんなに気楽にしていられる土地ではないぞ、{class}。Silithusの荒野に何の用だ?", "Rabineが君を寄越したのかい?　まあ、歓迎されてると思ってくれ……荒れ果て、打ち棄てられたこの地が人を歓迎してくれるならという話だがね。\n\nここで大いなる苦難が起きた時代には生きていなかったが、この砂漠地帯は忘れ去られた遠い昔の不気味な光景と似たようなものだろうな。君の助けがあれば、Cenarion Circleが終止符を打てるかもしれん。何世代も前に死ぬべきだった、あの脅威に。", 0xf22898d5, 0x87046503, 0xaeb0ca1a, 0x82dd9796, 0xc25500fb, "....." },
  [1125] = { "Southwindの魂", "Southwind VillageにいるTortured Druid・Tortured Sentinelの魂をそれぞれ8人ずつ解放して下さい。その後、SilithusのValor's Rest graveyardにいるLayo Starstrikeのところへ戻って下さい。", "南西に悲劇の地、Southwind Villageの廃墟がある。まず始めに着手せねばならん場所だ、{name}。\n\n言い伝えによると、村はかつてSilithusにおけるナイトエルフの活動拠点だったそうだ。この荒れ地にはびこるsilithidの群れに侵略されたのは随分前だ。私には、村が最初に引き裂かれた恐怖を想像することしか出来ないがな……。\n\n死んだドルイドや歩哨の浮かばれぬ魂は、あてもなく廃墟をさまよい歩いている。あそこを探索して、哀れな者たちの求めに応じて魂を解放してやってくれ。", "AllianceだろうとHordeだろうと関係ない――苦しむ霊としてこの世界に囚われていい者などいない。これらの魂を解き放てば、正しい姿に戻るだろう、{name}。", "恐らく、村を消滅させたのは廃墟の近くで渦巻いている巨大な群れだと思う。巣との接近は、今後の活動すべてに脅威をもたらすぞ。君の働きでそれが正しいと証明されたんじゃないかな。\n\n死んだ者たちの魂を解放してくれた君の慈悲に感謝するよ。こういうことは決して簡単ではないからな、本当に。だが、準備ができたら、もう一度手を貸して欲しいことがあるんだ……", 0xe6842d04, 0x0e07dad7, 0xceeadba8, 0x88499085, 0x7f284670, "....." },
  [1126] = { "塔の中の巣", "Southwind Villageの塔に登り、silithidの巣を活発にする手段を見つけて下さい。その時に見つけた何か珍しい物を、SilithusのValor's Rest graveyardにいるLayo Starstrikeのところへ持ち帰って下さい。", "Southwind Villageの巣をなんとかしなければならないが、奴らに手を出す方法に心当たりがある。私の経験では、silithidの巣は周囲の環境にとても敏感だ。霊たちの死の叫びを聞くと奴らが襲ってくるのはそのためだ。\n\nsilithidは塔の中で最も強い。スズメバチの群れが周りを飛び回っている塔だ。塔をよじ登り、巣を揺さぶって活動させてみてくれ。わかったことを報告してほしいが、気をつけろ！役に立ちそうなものを見つけたら、私のところへ持ってきてくれ。", "で、うまくいった? 無事みたいだし、それは良い知らせだね。何か見つかった?", "何……なんだこれは?\n\nこの形は……箱、か?　何か気持ち悪いものに覆われてるな。待てよ、ここに見える何かの一部……このぬめぬめの下にあるのは本か?\n\nこれはかなりの掘り出し物に出くわしたな、{name}……いや、せめてそうであればいいんだが。恐らくこれは古代の日誌か記録だろうな。この殻に守られていたんだ。\n\nこれが一体何なのか調べる方法があるぞ。", 0x6ab47955, 0x1a975905, 0x486a2827, 0x4dc90908, 0xc8b19174, "....." },
  [1130] = { "Melor Sends Word", "Thunder BluffのMelor Stonehoofと話してください。", "{name}、Melor Stonehoofは君のことを聞いて、道を開いてくれたよ。\n\nもし君がその道を行きたいのなら、Thunder Bluffへ行ってMelorと話してくるんだ。\n\n彼はHunter's Riseにいるよ。", nil, "{name}、やって来たね。さて、遠い地への旅支度は出来たかい?\n\n支度が出来たなら、若い{class}よ、聞くがいい……", 0x5e008bcd, 0x6a65c556, 0x4231584c, nil, 0x6a852b38, "...m." },
  [1131] = { "Steelsnap", "Steelsnap's Ribを、Thunder BluffのMelor Stonehoofに届けて欲しい。", "時に我らは食物のために狩りを行い、時に名誉のために狩りを行い、そして時には大地の教えを得るために狩りを行う。\n\nしかしお前に頼む狩りはそのどれでもない。この狩りは、母なる大地の祝福から外れたものを殺すためのものだ。\n\nそのhyena、SteelsnapはBarrensの南、Thousand Needlesを徘徊している。奴は他のhyenaを引き連れ、平和な動物たちの間に、恐怖と流血を巻き起こす暴君だ。\n\nSteelsnapを見つけ、殺すのだ、{name}。", "あの穢れたSteelsnapを倒したか、{name}?", "Steelsnapは敗れた。お前は穢れたThousand Needlesを浄化したのだ。\n\nそして{name}よ、それが今日のお前への教えだ。", 0x308aefca, 0x9044f45f, 0x9c4857f9, 0x2b305955, 0xb98ec3d8, "....." },
  [1132] = { "Fiora Longears", "TheramoreのFiora Longearsと話して下さい。", "ああ、もう一度海に出たいものだ！ 風の口づけを感じ、波に揺られたい。遠い昔、私の優しい母が揺らしてくれたように！\n\nああ、あなたの運が羨ましい、良き{class}よ。あなたの未来には海が見えるのだから！\n\n陸の熱心な者たちに、Kalimdorの地、機会の地について語るのが私の仕事だ！ 海の向こうで運を試す気があるなら、ここから船に乗って美しい港町Theramoreへ行くといい。そこで私の相棒、エルフのFiora Longearsと話してくれ。\n\n彼女があなたのKalimdorでの冒険を始めさせてくれるだろう！", nil, "こんにちは！Menethil HarborのMr. Flintに言われて来たのかい？Mr. Flintは人を見る目が確かだからね。彼が寄こしたなら、君がこのKalimdorにふさわしいのは間違いないよ！", 0x30729feb, 0x79d16431, 0x1e6af9aa, nil, 0xf87f590d, "...m." },
  [1133] = { "Astranaarへの旅", "AstranaarのShindrell Swiftfireと話す。", "Menethilからの船を降りたばかりなら、まずやるべきことは……Astranaarへ行くことだ。お前のような熱心なAllianceの一員なら、きっとあそこで大いに役に立てるだろう。Shindrell Swiftfireと話して、力を貸すと申し出てくれ。\n\nただ、誰に言われて来たかは言わなくていい。Shindrellは私のことを知らないからな……", nil, "Allianceに力を貸すために来てくれたのですか、{name}？助けは歓迎します。美しさは今も残っていますが……Ashenvale Forestはかつてのような平和な場所ではないのです。", 0x78f25323, 0x8608dbb8, 0x35dfad68, nil, 0x975151ed, "...m." },
  [1134] = { "StonetalonのPridewings", "Pridewing Venom Sacを12個、AstranaarのShindrell Swiftfireのところへ持って行く。", "私たちはHordeと公然と戦争をしているわけではありませんが、その平和はもろいものです。彼らの手先が私たちに対して動いているのをよく見かけますが、彼らはそれを密かに行っているのです。\n\nそうした動きの一つが、Theramoreの秘密の情報源から明らかになりました。それによれば、オークは南のStonetalon MountainsのMirkfallon Lakeの近くでpridewingから毒を集めているそうです。そしてオークの暗殺者たちが、Allianceに対する秘密の暗殺襲撃でその毒を使っているのです！\n\nこれが本当なら、彼らを止めなければなりません、{name}。彼らから毒の供給源を奪わなければならないのです。", "pridewing venom sacsは持っているか、{name}? オークどもにあの獣の毒を我々に使わせるわけにはいかない!", "ありがとう、{name}。我らの敵に進んで手を貸しているとは限らない生き物の殺戮を命じるのは心が痛む。だが、それが私の務めなのだ。\n\n友よ、君が倒したpridewingのために君の心は涙するかもしれない。だが、仲間たちがpridewingの毒から守られていると知って、その心を奮い立たせてほしい。", 0xa7c7d697, 0x11cffadd, 0xf879268d, 0x5e83f83e, 0xcd6cbd25, "....." },
  [1135] = { "Highperchの毒", "Highperch Venom Sacsを$N1個、TheramoreのFiora Longearsのところへ持って行って下さい。", "知ってるかもしれないが、wyvernsはよくオークに手なずけられて乗り物に使われる。だがあまり知られていないのは、wyvernの毒が、ある筋ではその獣そのものより価値があるってことだ。だから、ちょっとしたwyvern狩りを恐れないなら……仕事があるんだがね。\n\nここから西のThousand Needlesの地に、Highperchって場所がある。Highperchのwyvernsは強力な毒を持ってるんだ。強力で、しかも価値がある。", "Highperchは見つかったか、{name}? そこのwyvernsはどうだった?", "ああ、そのほとんどが毒ではちきれんばかりだね、{name}。こういうのは普通、若いwyvernか繁殖できる雌からしか採れないんだ。Highperchではさぞかし大殺戮だったろう！", 0x943fcf56, 0xd345c3ee, 0xcf4ffefe, 0xc18d63cc, 0xc81ed9b7, "....." },
  [1136] = { "Frostmaw", "Frostmaw's ManeをThunder BluffのMelor Stonehoofに渡して下さい。", "{name}、はるか彼方の土地へ旅立つときがきた。君なら行ける。\n\nAlterac MountainsのFrostmawというイエティをもう狩れるだろう。山の生息地では、Frostmawの白い毛皮は雪にとけこんで見つけにくい。めったに姿を見せない獣だ。\n\nだが、そういう生き物をどうやっておびき出すか教えてやろう。さあ、この巻物を持って。Frostmawの引き寄せ方をこれに書いてある。\n\nさあ行け、{name}。旅は長く、多くの試練が待ち受けていよう。Frostmaw's maneを持ち帰ったその時こそ、君の仕事は達成される。", "Alterac Mountainsへは行ってきたか、{name}? あの捕らえどころのないFrostmawと対峙したか?", "Frostmawを見つけ出して倒すには、力と狡猾さが必要だ、{name}。君はそれを持ち合わせている。\n\nThousand Needlesの谷、Alteracの高い山々へと君は導かれてきた。いつの日か、Earthmotherの地すべてへと導かれるだろう。それが狩人の道というものだからな。", 0x214afb8d, 0xf3ad062a, 0xf00fc895, 0x4d27bf62, 0x1c1f8c71, "....." },
  [1137] = { "Fizzleへのニュース", "Shimmering FlatsのFizzle Brassboltsと話して下さい。", "Induriumは信じられないほどの熱耐性を持ってるぞ! Fizzleのピストンに役立つはずだ。だが、こんな欠片じゃなく、本物のindurium鉱石を必要としているだろう。\n\n鉱石を手に入れるには、Badlandsの北の境界にあるUldamanの奥から掘ってこなきゃならない。あそこはinduriumの真の源だ。\n\nFizzle Brassboltsによろしく。それと、君に言ったことも伝えておいてくれ。\n\n安全な旅をな、{name}。君にまた会ったとしても驚かない。……いったんFizzleがinduriumのことを知ったら、恐らく鉱石を得るためにUldamanへ君を寄越すだろうからな!", nil, "{name}、戻ってきたな! Martekを見つけたかい? 彼とは話した? なんて言ってた? 手伝ってくれた??\n\n教えて、教えて、教えて!!", 0x5408617d, 0xf7bb6567, 0xf7580227, nil, 0x3db91e33, "...m." },
  [1138] = { "海の果物", "Fine Crab Chunksを6個集め、AuberdineのGubber Blumpに届けてください。", "オラ、カニが好きでな。カニっつうのは海の果物だべな！　焼いてよし、丸焼きにしてよし、煮てよし、炙ってよし。ソテーしてよし、揚げてよし、炒めてよし。カニサラダ、カニスープ、カニシチュー、胡椒和え、レモン和え、whipper root和え、Ironforge surprise crab。とにかく…とにかくそういうことなんだべ。\n\nオラいま釣りしてッから、crab chunksを取りに行けねェだ。reef crawlerだのencrusted tide crawlerだのから取れるんだがな。ぎょうさん作れるべよ。焼いてよし、丸焼きにしてよし、煮てよし…。", "……lemon crab、whipper root crab、それにIronforge surprise crab。まあそんなところだな。\n\nおや、こんにちは、{name}。前に話したfine crab chunksは持ってきてくれたかい?", "おおぅ、これはオラが欲しかったfine crab chunksでねェべか。ありがてえ、{name}！　前に、釣りしてっ時に見っけたことがあんだがな、どうにもならねェモンだったんでな。お前ならなんとかすっべがな。ありゃあどうしたって美味ェもんにはなんねェべ。\n\nカニ料理のことは話しただかな、え？", 0xcf90f28d, 0x836c5e9a, 0x029859ec, 0x81c4ae4d, 0x4d6e1f4b, "....." },
  [1139] = { "失われしTablets of Will", "Tablet of Willを見つけ、IronforgeのAdvisor Belgrumに渡して下さい。", "Blackrock Spireから切り離したことで、Shadowforge氏族の動きは鈍った。だが、Hammertoeの探求はまだ果たされていない。彼の死を無駄にしてはならん。彼はTablet of Willを見つけることを夢見ていた。titans自らが魔法を刻み込んだ石の欠片で、titansの創造物に命を吹き込むためのものだ――創造物に自らの意志を持たせるのだと、伝説では言われている。\n\nShadowforge氏族に見つけられる前に、なんとしてもTabletを取り戻さねばならん。\n\nUldamanへ戻り、石板を見つけ、すぐにここへ戻ってこい。", "Hammertoeのクエストは成し遂げられねばならん、{name}。わしは彼にそれくらいの借りがある。\n\nお前がUldamanへ戻ることは、その目的のためだけでなく、すべてのドワーフの民の安全のためにも欠かせんのだ。tabletがDark Ironsの手にあっては、奴らのgolemsの軍勢がどれほど強大になるか分からん。", "<あなたが石の破片を手渡すと、Advisor Belgrumは信じられないというように首を振った。>\n\n{name}、これは驚くべきものだ。できるだけ早く王のメイジたちのもとへ届けさせよう。彼らは伝説が真実かどうかを確かめるために、これを研究したがるだろう。だがそれはまた別の機会の話だ。君は私が想像していた以上に我らの民を助けてくれた――礼を言う。", 0x468b846c, 0x0bea6162, 0x33b754db, 0x93583870, 0x69c1cc8b, "....." },
  [1140] = { "Tower of Althalaxx", "Night RunとSatyrnaarに囚われたHighborneの魂を解放し、Maestra's PostのDelgren the Purifierのところへ戻る。", "オークの文字は子供の落書きと大差ありません。私が彼らの言葉を学ぶと決めた時、私の教団の多くの者が嘲笑しましたが、敵をさらに深く理解するのに役立つと分かったのです。\n\nIlkrudの走り書きによれば、Athrikusはまだ2つのソウルジェムを持っていて、それはAshenvale北東部のsatyrが支配する地、Night RunとSatyrnaarに保管されているようです。\n\n向こうでは気をつけてください、{name}。satyrの血に染まった神殿は、あなたのような熟練の{class}にとっても不気味な場所でしょうから。", "かつて、satyrsの歴史はどういうわけかナイトエルフの歴史と関わりがあるという噂を耳にしたのですが、私をもてなしてくださる敬愛する方々は、その件について語りたがらないのです。", "satyrがこの森に居座るのを、あまりにも長く許しすぎたのかもしれません。次にAuberdineへ行ったときに、Elissaとそのことを話しましょう。\n\nいずれにせよ、魂の宝石が破壊されたことで、Athrikusの力は大きく弱まるでしょう。この機を捉えて、彼とその教団を排除しなければなりません。", 0x6dbe45ec, 0x43c733b7, 0xc9035df4, 0x57e3d2c0, 0x557eef7f, "....." },
  [1141] = { "ある一族と釣竿の物語", "Darkshore Grouperを6尾捕まえ、AuberdineのGubber Blumpに届けてください。", "オラ、釣りが好きでな。Blump一族は釣りで名高けェんだ。オラも釣り師なんだべ。\n\nこの辺で釣れる魚で好きなのァDarkshore grouperっつうやつだべ。前はよく船を出してgrouperを釣ったもんだが、あのmurlocがこの辺に来てからッつうもの、漁船もすっかり出なくなっちまっただよ。奴らgrouperも食い尽くしちまうに違いねェ。\n\nなあ、Darkshore grouperを捕まえてくれねェだか？　そしたらオラ、正真正銘ホンモノのBlump Family Fishing Poleをお前にやるだよ。　魚を釣るにはもってこいの釣竿だべ。", "Darkshore groupersを使ったうまい料理はたくさんあるんだ。食べてもうまいけど、釣るほうがもっと楽しいと思うね。\n\nDarkshore groupersはもう釣れたかい?", "こりゃァええgrouperだべ、{name}！　おかげで助かっただ！\n\nお前はオラのいとこのGraun Blumpと同じぐれェ腕のいい漁師だべ。あいつァ女のくせに髭を生やしててな、変わったにおいもすんだが、そんなのァ釣りの腕とは関係ねえ。お前にゃあBlump Family Fishing Poleを使う素質があるとオラは思うべよ。", 0x51cfab45, 0xde03fdb7, 0x220d149f, 0x9b959209, 0x5b8f085a, "....." },
  [1142] = { "衰えゆく命", "Treshala's Pendantを見つけ、DarnassusのTreshala Fallowbrookに返して下さい。", "私はもう長くない……とても……とても……弱って……\n\n……勇敢なドワーフ、Lonebrowが、Falfindelに知……知らせるため遣わされた……\n\nだが私が……し、死ぬ前に……\n\n……私の妻、Treshala……私との絆のペンダントが……奪われた……け、汚らわしい襲撃者の一人に……\n\nどうか、さ、探して……そしてDarnassusのTreshalaに返してくれ……\n\n……私の孤独な……死の知らせと共に。", "私の家に何の用だ、{race}?", "いや！\n\nこんなのあんまりです。ああ、なんと残酷で耐えがたい世界！\n\n私はこの悲しみの重荷を背負い、Heralathの仕事を彼と共に絶やさぬようにしなければなりません。\n\nあれほど危険な場所から旅してくるとは、勇敢でしたね、{name}。でも、どうか今は一人にしてください。\n\n独りで喪に服します。", 0x2566ff32, 0xee06bc91, 0x7bd38ff5, 0x01d3203d, 0xd4c26cfb, "....." },
  [1143] = { "Althalaxxの塔", "Athrikus Narassinを倒し、その首をTower of Althalaxx近くのBalthule Shadowstrikeのところへ持って行って下さい。", "なるほど。あなたの言うことが本当なら、今こそ攻め時です。Athrikusは塔の最上階にいると思います。ですが気をつけてください。彼の周りには強力なウォーロックが大勢いて、以前あなたが戦った者たちよりもはるかに危険です。", "Athrikus Narassinは古く強大なウォーロックだ。Delgrenの助けを待つべきかもしれないが、君一人を送り出したということは、彼は君を大いに信頼しているのだろう。", "Athrikusが死んだことで、この地域の悪魔の勢力が押し返されることを願っています。彼らが再び集結して戻ってくるのは間違いないでしょうが、そのときには我々もその脅威に立ち向かう備えがさらに整っているはずです。", 0x6dbe45ec, 0x0df455be, 0xb1924267, 0x1854f1fa, 0x2672806c, "....." },
  [1144] = { "Willix the Importer", "Willix the ImporterをRazorfen Kraulの外まで護衛する。", "やっと助けが来た！\n\nどれだけ長くここに囚われていたか、あんたには分かるまい。この場所の外を最後に見たのがいつだったかも思い出せないんだ。\n\nいいかい、俺は起業家なんだ。いつも銅貨一枚でも稼ごうとしてる、ってやつさ。Mebok Mizzyrixが、この豚小屋のRedleaf Tuberに高い金を払ってるって噂を耳にしてね。さっと入ってさっと出るだけの簡単な仕事だと思ったんだ。見ての通り、ちょいと読みが外れたがね！\n\nとにかく、ここから出るのを手伝ってくれたら、損はさせないよ。", nil, "改めてありがとう、友よ！骨折り損にはさせないって言っただろう。", 0xc56a0766, 0xd41eb22d, 0x19bfdb10, nil, 0x7fb3ae2d, "...m." },
  [1145] = { "昆虫の群れの増大", "Korran's Sealed NoteをOrgrimmarのBelgrom Rockmaulへ届けて下さい。", "Crossroadsを通り過ぎていくたくさんの旅人が、Field of Giantsから卵を集めるのを手伝ってくれるんだ。彼らの多くは、あそこの生物がいかに危険かという話をする。あの昆虫たちは、我が主が最初に考えていたよりももっと大きな脅威になるに違いない。\n\nOrgrimmarへ行ってBelgrom Rockmaulに会ってくれる急使が要る。これは簡単な問題じゃない。だから、真剣に取り組んでくれる人が行くべきだ。\n\nBelgromはいつもwarriors' guild houseの外にいるよ。", "羨ましいぞ、{class}。お前はしばらくOrgrimmarの城壁の外にいた者の顔をしている。\n\nThrallがこの街で私の技を必要としていなければ、私自身も大族長の名のもとに旅に出るところだ。だが彼は我々をよく導いているし、私はその判断を信じている。彼が私を必要とする限り、私はここに残る。", "ああ、Korranからの手紙だな。彼はもうだいぶ長い間、忠実な従者をしてくれている。Crossroadsでの責務はうまくいっているだろうか。", 0x0ead3856, 0x43c67366, 0x31ea7af9, 0x6c1f9723, 0xcb7b9016, "....." },
  [1146] = { "昆虫の群れの増大", "Belgrom's Sealed NoteをThousand NeedlesのMoktar Krinへ届けて下さい。", "それで、Korranはあの昆虫について同じ結論に達したのだね。我々が推測していたよりさらに大きな脅威となるだろう、と。\n\n何日か前、瀕死の狩人がThousand Needlesから戻ってきた。彼はShimmering Flatsからドワーフ発掘隊を追い出すために、襲撃隊とともに派遣されたんだ。攻撃の間にたくさんの昆虫が採掘場の穴から湧き出てきて、彼らの部隊はほとんどが殺されたそうだ。\n\n彼らはMoktar Krinに率いられて、Shimmering Flatsの境目まで避難したんだ。この手紙をMoktarに渡してくれ。", "戦のために、俺と仲間たちはShimmering Flatsに来た、{class}。お前は何をしにここへ?", "山肌に響く雷鳴みたいな音は気にしないでくれ。ゴブリンとノームがFlatsで互いにレース……彼らが科学と呼ぶ残虐行為をしてるんだよ。ここにはもっと大きな脅威がある。そのひとつが、我が部隊を半分以上殺したんだ。\n\nだが、OrgrimmarのBelgromからの連絡があるまでは、我々はここに残る。それまではここを守り、用心深くとどまるんだ。", 0x0ead3856, 0x666eb4f6, 0x317eae19, 0x42802096, 0x0278863a, "....." },
  [1147] = { "昆虫の群れの増大", "Silithid Searcher・Silithid Hive Drone・Silithid Invaderをそれぞれ5匹殺し、Thousand NeedlesのMoktar Krinのところへ戻って下さい。", "ふむ。Belgromはあの化け物どもを脅威だと思っているらしい。奴らが這い出してきた深みへ押し戻せとのことだ。\n\nExplorers' Leagueが送り込んだドワーフどもを殺しただけでは足りなかったらしい――今度は半死半生の戦闘部隊を、また別の戦いに送り出さねばならん。今のこの有様では、我々だけではやれん。発掘現場はここから南だ。もうドワーフの相手をする必要はないはずだ。剣か杖を振るって、我々に手を貸す気はあるか？", "あのレースのためにFlatsへ向かう旅人がこれだけいれば、あの虫どもを押し返す手伝いをしてくれる冒険好きを十分に説得できるはずだ。それが済むまで、俺の一行はここを離れられない。", "うわ! 君がかぶってるその液体は実に素敵だな、{name}! おまけに君を臭くしてるがね。そのkodoには近寄らないでくれ。暴走するか、興奮させる原因になるよ。\n\n仲間も同意すると思うよ。その臭いだけでも、あの昆虫どもに立ち向かって我々を助ける役割を果たしてくれた証拠だと。ありがとう、{name}。", 0x0ead3856, 0x100944ac, 0xa527158f, 0xbaf1eca2, 0x2db35fca, "....." },
  [1148] = { "昆虫の体の一部", "Silithid Heart1つ、Silithid Talon5つ、Intact Silithid Carapace3つをCrossroadsのKorranに渡して下さい。", "あなたは注意深く甲虫の殻を探った。手の上で裏返すと、キチン質のメッキが組み合わさったことで、殻を信じられないほど強固にしていることに気が付いた。今まで見た物のどれにも似ていなかった。あなたは死骸の残りをさらに調べ、この生物がとても強く、高度な進化を遂げたことに気が付いた。\n\n再び殻を見下ろし、Korranならばもっとこの生物を調査するのを楽しむだろうとあなたは思った。この殻は、この生物が何者でどこからやって来たのかを明らかにする助けとなるだろう。", "ああ、久しぶりに会いに来てくれたな、{name}。今日は何の用だ? 最近戦いの顔を見てきたような様子だな。いい……Hordeにとっても、お前にとってもいいことだ。戦いを見れば見るほど、お前は役に立つようになる。強くもなる。", "ああ、最近Moktarと会ったのかい? 彼はいつも私の世話をしてくれるんだよ。彼が実戦に臨む代わりに、小部隊を見守ることに時間を費やしていると聞いて残念に思ったけど、Explorers' Leagueの連中を殺すのを、彼は大いに楽しんでいるはずだよ。\n\n{name}、見本を持ってきてくれるなんて君は賢いなあ。Field of Giantsで見つけた卵も合わせると、この昆虫たちが何者で、何を望んでいるのかを解明するのに良い滑り出しになるよ。", 0xb7152462, 0xbd3c65cd, 0x9e8b55a6, 0xaf7531b9, 0xab137677, "....." },
  [1149] = { "信じる心の試し", "もし信じる心があるなら、Thousand Needlesを見下ろす板から跳んで下さい。", "そう、君は俺を捜し出した。それでなければ、宿命が君をここへ連れてきたんじゃなかろうか。まあいい。君は今ここにいる。そうして、旅が新たに始まるだろう。\n\n人というものは様々な面が作り上げているんだ。精神、肉体、心。これらは文化の伝統によって測られる。\n\nあとは、自分自身の中に存在しているのを願うことしかできない。君が同意するなら、君の中にある様々な面を試してあげよう。\n\n乗り越えたら、君は必ずもっと強くなれる。失敗したなら、地獄の広大さを悟るだろうね。\n\nまず最初に、信じる心の試しだ。", "信仰。それは一部の者が思うよりもずっと大切なものです。\n\n時には、何を信じるかは問題ではありません。何かを信じること、それ自体が大切なのです。", "予期せぬ逆境に出くわすまで、我々は精神力がどれほど強いか理解しようとしない。生き残るだろうという保証もないのに、君は信じて跳ぶ道を選んだ。君の心は開け放たれていて、そして精神はこれからやってくる物に対する心構えができている。\n\nもし君が望むなら、次の試しはもう準備できているよ。", 0xc6309c50, 0x327a01d5, 0xcf6b2811, 0xa135d3da, 0x4948c899, "....." },
  [1150] = { "我慢の試し", "Thousand NeedlesのDorn PlainstalkerにGrenka's Clawを渡して下さい。", "既に成し遂げたことから考えて、君の勇気が不動のものだと分かって嬉しいよ。信じる心はまったく損なわれていないから、肉体の試しを行う時がきた。\n\n最初は我慢の試しだ。仲間と共にFreewind Postの西にあるRoguefeather Denへ行け。ねぐらの奥深くへと進んでいき、食糧を使えなくしてほしい。その頃には、奴らの怒りをかっているはずだ。長く生き残ることができれば、Grenka Bloodscreech自身がやってくるはずだ。試しを終えるには、奴を殺し、その鉤爪を持ってきてくれ。", "この先に待ち受ける試練に向けて、そなたは霊的にも、肉体的にも、精神的にも備えておかねばならぬ。\n\n我らは準備が整う前に先を急ぎすぎることがあまりに多い。どの部族の者であろうと、若者たちが故郷という聖域を離れた後に直面するであろう危険に備えさせることが、若者に対する我の務めだと考えている。", "{race}の標準からみても、Grenkaは強力だ。君はこの日の成果を誇って然るべきだよ。\n\n信じる心の試しの中で君は精神の強さを示し、そして今、Roguefeather harpiesとの戦いにおいて我慢強さを見せてくれた。だが、新たな試しの時がきた。", 0x12df1701, 0x72831da6, 0x073abcf2, 0xc0c9c65e, 0x06612afd, "....." },
  [1151] = { "力の試し", "Thousand NeedlesのDorn PlainstalkerにFragments of Rok'Alimを渡して下さい。", "古き神々の時代、精霊たちはこの世界にたくさん住んでいたんだ。彼らは古き神々を崇拝し、神々はその力を通じて世界に精霊を結びつけていた。神々が消えた時、精霊たちもこの世界から消えていき、今では力ある魔法使いの命令に従って戻ってくるだけになった。\n\nただ例外もある。一部の精霊は自分自身で留まれるほどの力を持っている。そんな精霊のうちの一人がRok'Alimなんだ。\n\n力の試しのためにThousand NeedlesでRok'Alimを見つけ、倒すんだ。", "Rok'Alimは、Thousand Needlesのcentaurの部族からPounderとも呼ばれている。行く手に立ちはだかる勇敢な、あるいは愚かな生き物を叩きのめすとき、その拳が雷のような轟音を立てるからだ。", "力の試しは終わった。君は力と勇敢さを示してくれた。儀式を終える前に、最後の試しの準備ができたようだね。", 0xace06693, 0xf94cffe9, 0x1118dcbc, 0x474061dc, 0x6f3ea674, "....." },
  [1152] = { "知恵の試し", "Stonetalon MountainsのTalondeep Path入り口付近にいるBraug Dimspiritを見つけて下さい。", "共にいる時間もおおむね終わりだ。俺は物知りではあるが、知恵の試しを課すのは俺じゃない。学ぶべき課題と訪れるべき場所がある。そこには知恵は自分の分野だと主張する別の者がいるんだよ。\n\n用意ができたら、Braug Dimspiritを見つけ出せ。偉大な英知を持つ呪術師だ。君をより深く試してくれることだろうから、彼の言葉に耳を傾けるんだぞ、{name}。\n\n支度でき次第、AshenvaleとStonetalon Mountainsをつなぐトンネルを見つけるんだ。Braugはその近くに住んでいる。{name}、気をつけてな。ナイトエルフが試しの邪魔をしようとするかもしれん。", nil, "ゴブリンが大地を蹂躙し、ナイトエルフが若い種族を非難するにつれ、世界中で昼も夜も寒さを増している。KalimdorとLordaeron中に見られる苦難の責めを負うべきは、Forsakenやオークだけではない。知性ある種族の多くが、世界の痛みの一因となってきたのだ。Dornはそれを知っている。そしてお前もそれを悟るのに必要な資質を示したからこそ、彼はお前を私のもとへ寄越したのだ。\n\n今、お前はBraugの前に立っている。", 0xdf27dbbd, 0xbc1c7dd5, 0xf66e37cc, nil, 0xbf8f016c, "...m." },
  [1153] = { "新しい鉱石のサンプル", "Gravelsnout DiggerかGravelsnout Surveyorの死体からUnrefined Ore Sampleを見つけ、BarrensのCamp TaurajoにいるTatternack Steelforgeのところへ持って行って下さい。", "{class}さんよ、前によくしてくれたよな。今までwarchiefは俺の仕上げたものに満足してて、決意も新たに続けるよう求めてる。俺の中にある名誉ってヤツがこう決めたんだ、あんたのしてくれたこと全てをwarchiefにちゃんと知ってもらうって。でも、まず最初にまた頼み事があるんだ。\n\n最近、旅人が南のThousand Needlesってところからやってくる。彼らはあそこで珍しい鉱石を持ってるkoboldを倒しているんだが、鉱石を売ってくれないんだよ。分析するのにサンプルがほしいんだ。", "またあの旅人どもを見かけた。鉱石の見本を俺に売ろうとしなかった連中だ。大族長に力を貸さぬあいつらに唾を吐きかけてやった。\n\nあいつらが戦いの中で、ウォリアーらしくではなく臆病者のように死ねばいい。ウォリアーらしく死ぬのは、Hordeと手を結ぶ者すべての権利であるべきなのだがな。", "いいサンプルだ、{name}。実にいい。\n\n君が持ってきてくれたから、あの旅人ども、もう見つけた鉱石で威張れなくなったな。\n\nすぐ分析にとりかかるよ。充分頑丈だと分かったら、この素材で作った武器をwarchiefのところへ送って、俺たちの成果を見てもらおう。\n\n君の助けは忘れないよ、{class}。", 0x3d65e9bc, 0xeedf12cb, 0x8c10fc6a, 0x8d95d80a, 0xb5b523b0, "....." },
  [1154] = { "知恵の試し", "Legacy of the Aspectsを見つけ、Stonetalon MountainsのTalondeep Path入り口付近にいるBraug Dimspiritのところへ戻って下さい。", "そなたはDornの試験に合格し、今や次の試練に挑もうとしている。大変よろしい。だが、これまでの課題は子供だましであった。肉体を試すのはたやすい――精神となると、まったく別の話だ。\n\n簡単に説明しよう。私が名を挙げる本を見つけ、それを学び、その内容についての私の問いに答えるのだ。\n\nどの本か、と訊きたいところであろう。Legacy of the Aspectsだ。それは南AshenvaleのDor'danilの最深部にあり、死せるドルイドたちとその殺害者たちに守られている。", "読み終えたら、その本を持ってきてくれ。本を渡してもらうまで、君に問いを出すつもりはない。", "指定の本だ。それなら、私の問いに正しく答えられる望みはある……ただし学んだ内容を忘れていなければね。\n\n準備ができたら、また話しかけてくれ。君への問いを出そう。", 0xdf27dbbd, 0x39bbcae9, 0x72aec8c5, 0xef15ae23, 0x8b098b5b, "....." },
  [1159] = { "知恵の試し", "UndercityのParqual Fintallasを見つけて下さい。", "よくやったぞ{name}。知恵の試しの始めの一部に通ったけれど、まだ答えなくてはならない別の問いがある。だが、その問いを出すのは私ではない。\n\nLordaeron CityのParqual Fintallasを探し出すんだ。病に襲われる前の彼は、ヒューマンの偉大な歴史家だった。今も彼は啓蒙を求め続けている。異質な物としてね。\n\n何か問う前に彼は別の物を必要とするかもしれないが、君は今まで見事にこなしてきた……だから、彼の壁も乗り越えるに違いない。", nil, "Braugがお前を寄越したのか? ありえん。\n\n<Parqualはあなたをじろじろと見た。>\n\nDor'Danilも物ともせず、信じて賭けに出て、強力な精霊と戦って征服しただと? ふん! 茶番だろう。冒険者どもが酒場で話しているのが聞こえたようなお話だな。それで今、試しに通るために必要な物が自分にあると思っているだろう。それならこれをやってみろ……{class}。", 0xdf27dbbd, 0x476bd838, 0xbc70b167, nil, 0x47c906c9, "...m." },
  [1160] = { "知恵の試し", "'The Beginnings of the Undead Threat'を見つけ、UndercityのParqual Fintallasに返して下さい。", "探さねばならぬ物を教えよう。問いも出すつもりだが、お前が力量を証明したいと望んだからじゃない。\n\n知識とは力よりも遙かに大切な物だ。能力で他の者がお前を追い越していくように見えても、この世界の知識はもっと価値あるものとなろう。\n\nTirisfal Gladesの北にある修道院へ行け。そこの図書室に「Beginnings of the Undead Threat」と呼ばれる本がある。そこは今や堕落したパラディンどもに使われている。我ら不死の者と戦うべく訓練するためにな。\n\nその本を私のところへ持ってくるんだ。", "本を盗む前に、Scarlet Crusadeに少しは苦しみを味わわせてやっただろうな。\n\n奴らへの私の見方は不当なものではない。Crusadeもかつては光の信奉者だったのかもしれんが、今では自分たちの宗教に与しない生き物をことごとく滅ぼそうとしている。奴らは、Forsakenであろうとなかろうと、すべてのアンデッドは浄化されねばならず、奴らの土地を旅する者は正気を失っているか、アンデッドの強力な魔法に操られているに違いないと信じている。愚か者どもめ。愚か者と馬鹿者の集まりだ、一人残らずな。", "お前に探すように遣わした本だな。\n\n<Parqualは本を見下ろしながら、表紙をゆっくり撫でた。>\n\n体と精神と同じく心も力に溢れていると証明すべく、問いを望んでいるのだな。この本をじっくりと読みこなしたならば、問いを出そう。そして、お前は試しを終えることができるのだ!", 0xdf27dbbd, 0x554be03e, 0x23bddc58, 0x23dd4b70, 0x67b7a387, "....." },
  [1164] = { "盗賊からの窃盗", "Kenata Dabyrie・Fardel Dabyrie・Marcel Dabyrieの首をUndercityのGenavie Callowに渡して下さい。", "あの売女め!あの豚め!Kenataはまだ生きている。こっちが苦しんでいるというのに、あいつの家族は元気で栄えているんだ。Forsakenとはよく言ったものだ!\n\n俺の家族は疫病に奪われていなくなった。屋敷も失った。戦争の最中に略奪され、焼かれたんだ。それなのに、あの女とろくでもない子供たちは、厚かましくも俺に残されたたった一つの大切な持ち物を盗んでいきやがった。\n\n盗まれた物なんてもうどうでもいい。今欲しいのはあいつらの首だ!\n\n俺の代わりにあいつらを殺してくれ!ArathiのRefuge Pointの北東にあるDabyrie Farmsteadへ行け。", "皆殺しにして、奴らの首を持ってこい!", "お前は復讐の化身として私の前に立っている。私は感謝してその前に頭を垂れよう。\n\nあの牛が死に、その種がもはやAzerothの地に広がることはないと分かった今、私はもっと実入りのいいことに力を注げる。始末したあとで、奴らの農場も漁っておいてくれたことを願うよ。", 0x081f6bb7, 0xad2cc7b0, 0xa3be99fb, 0x5c443fe9, 0x4bc6c4c4, "....." },
  [1166] = { "Overlord Mok'Morokkの懸念", "Brackenwall VillageのOverlord Mok'Morokkは、Dustwallow Swampで彼のグロッグ酒、嗅ぎタバコ、金庫を取り戻してほしいと言っています。", "Overlord Mok'Morokkの前にひれ伏せ！\n\nRexxarがオレをStonemaul Clanの偉い親分にした！\n\nオレ、いい親分。オレ、一族守る。\n\nでっかいドラゴン来て、古い家を燃やした。オレ、賢いogre。ここに一族の新しい家見つけた。\n\n古い家から急いで出たから、オレ、物忘れた。ちっこい{race}、オレの物取ってこい。南へ行って、オレのうまいグロッグと、嗅ぎタバコと、金庫見つけろ。そしたらオレ、お前気に入る。Den of FlameとStonemaul Ruins探せ……そこにある、オレ、確かだ！", "オレ、酒飲みたい。嗅ぎタバコも恋しい。宝箱どこだ? お前、Overlord Mok'Morokkのために取ってこい。\n\n南の古い家で探せ。オレ、ogres率いるので忙しい、取りに行けない。", "お前、いい{race}。オレ、なくしたもの、とても困ってた。オレ、今お前好き。", 0x5a81c0dd, 0x3cb66304, 0x32b1f20e, 0xbe0d76f0, 0x97e50b4d, "....." },
  [1167] = { "Althalaxxの塔", "Tower of Althalaxx近くのBalthule Shadowstrikeと話して下さい。", "Athrikusと対決する前に、Balthuleに相談しておくのが賢明だろう。彼がTowerの見張りを怠らずに続けてきたのは間違いない。最近の動きについて情報を持っているかもしれない。", nil, "やあ、また会えて嬉しいよ、{name}！このあたりで実に奇妙なことが起きていてね、君が来てくれて良かった！\n\n本当に奇妙だったんだ、{name}。すべて普通に見えていた――まあ、ここで言う普通程度にはね――そうしたら突然、塔の上の部屋からまばゆい光がほとばしったんだ。それから悲鳴が聞こえた。叫び声が空気を切り裂き、ときおり稲妻が地面を打った。一体何が起きているんだ？", 0x6dbe45ec, 0x8c848775, 0xac045326, nil, 0xce65d2b7, "...m." },
  [1168] = { "黒い竜の大群", "Brackenwall VillageのThargはFiremane Scoutsを$N1体、Firemane Ash Tailsを$N2体、Firemane Guardsを$N3体倒してほしいと言っています。", "Mok'Morokk は Rexxar に大王にしてもらっただ。あいつはogreのことより権力のこと気にしてる。\n\n黒い竜がogreたくさん殺した。Tharg のかみさんも殺した。Mok'Morokk がおらたちに走れ言った。おらたちはここへ来させられた。\n\nogre戦うべき。ogre走るの苦手。Mok'Morokk は Mok'Morokk のことしか考えてない。\n\nおら Stonemaul Ruins を家って呼んでる。おら南の家好き。ここ家違う。\n\n黒い竜の大群と戦うの手伝え。おら復讐する。家に帰りたい。", "Mok'Morokk、ogres全員にここ残って守れと言う。オレ思う、ogresはblack dragonの軍勢を殺して古い家を取り戻すべき。\n\nお前、ogresが家を取り戻すの手伝え。ogresの復讐手伝え。", "おまえ、黒竜の軍をたくさん殺した。おまえ、勇敢な{race}。\n\nTharg、うれしい。", 0x4d563d56, 0x14890393, 0x4e3ed1c7, 0xa2146fb9, 0x1a50d66b, "....." },
  [1169] = { "眷属の特定", "Brackenwall VillageのDraz'Zilbは、Searing Tonguesを$N1個とSearing Heartsを$N2個持ってきてほしいと言っています。", "あの臆病な愚か者Mok'Morokkが権力に溺れ、Thargが悲しみと復讐の悪魔と格闘しながら一族の主導権を争っているというのに、我らの古き住処への攻撃の源を突き止めようと気にかけているのは、どうやら私だけのようだ。\n\nなぜそんな怪訝な顔をする、{name}？ 私がogreだからといって、粗野なならず者のような話し方をすると思っていたのかね？\n\nさて本題に戻ろう。幼竜と孵化したての竜から、心臓と舌を持ってきてくれたまえ。私がこの悪の根源を突き止めよう……", "black dragonの軍勢の焼け焦げた子らのheartsとtonguesがあれば、どの忌まわしい獣が我らの家に子を放ったのか解き明かせる。侵略者についてもっと知ることができれば、奴らをきっぱりと滅ぼし、Stonemaul Villageを荒廃から取り戻せるかもしれん。\n\nもちろん、Mok'Morokkにあのものぐさで太った図体をこの泥穴から動かさせること自体が、壮大なクエストになるだろうがな……", "これだけのheartsとtonguesを集めるのは、間違いなく危険な仕事であったろう。我は秘術の深淵を探り、かつての我らが故郷に降りかかった黒き脅威の源を突き止めよう。", 0xe19f76ee, 0x206278cb, 0x4b1a3865, 0x1c82c56b, 0xfbf91be7, "....." },
  [1170] = { "Onyxiaの眷属", "Brackenwall VillageのOverlord Mok'Morokkと話して下さい。", "Stonemaul VillageはOnyxiaの眷属に侵略された。だが、なぜ黒きドラゴンロード、Deathwingの娘が、我らの地に降り立ったのか？\n\n実に気がかりだ。Onyxiaがここへ来たのは、ogreの小さな一団を攻め立てる以上の目的があったに違いない。\n\nすぐにMok'Morokkに知らせてくれ！ 手を打たねばならない。", nil, "なんでオレにdragonのこと言う？オレ、dragon嫌い。オレ、ここ好き。ここ、dragonいない。", 0x65f8bb52, 0x834a6679, 0x06296b60, nil, 0xdcff519e, "...m." },
  [1171] = { "Onyxiaの眷属", "Brackenwall VillageのDraz'Zilbと話して下さい。", "お前、オレにかまうな。Draz'Zilbに言え、オレたちここにいる。黒いドラゴン、ここにいない。", nil, "あの怠け者の臆病者め！\n\nMok'Morokkは、Rexxarが我らの長だった頃は強さを示していた。だがRexxarが去ってまもなく、Mok'Morokkは権力の誘惑に屈した。導く代わりに、要求するようになった。奴は民に仕えるのではなく、我らが奴に仕えることを求めているのだ。\n\n何とかしなければならん。", 0x65f8bb52, 0x5a13b3f0, 0xc6b5dbcd, nil, 0x3c7f64b4, "...m." },
  [1172] = { "Onyxiaの眷属", "Brackenwall VillageのDraz'Zilbは、Eggs of Onyxiaを$N1個破壊してほしいと言っています。", "Onyxiaの眷属はDragonmurk中に散らばっている。これ以上幼竜を孵化させてはならない。\n\n急いでDustwallow Marshの南にあるWyrmbogへ向かってくれ。彼女はきっとそこに巣を構えている。あの邪悪なドラゴンの卵を探し出し、破壊するのだ。\n\n周辺がこのまま繁殖地であり続ければ、我らがStonemaul Villageを取り戻すことは決してできない。\n\nMok'Morokkについては……あの間抜けには別の考えがある。", "急いでDragonmurkへ向かえ、{name}。Wyrmbogのそこら中にOnyxiaの卵がある以上、すぐに手を打たねば圧倒的な数を相手にすることになる。\n\n奴の卵を破壊しろ! black dragonの災いを我らの故郷に広げさせるな!", "素晴らしい！Onyxiaが次の卵を産めるようになるまで、しばらくかかるだろう。\n\n我が民を代表して礼を言う、{name}。\n\nこれまで多くを頼んできたが、Stonemaul Clanのためにもう一つだけ力を貸してくれないか。\n\nMok'Morokkは我らを率いるにふさわしくない。Thargなら優れた長になるだろうが、傷と年齢がそれを阻んでいる。力ずくでMok'Morokkをここから追い出してくれ。そうして初めて、我らを南の本来の故郷へ戻してくれる新たな長を立てられるのだ。", 0x65f8bb52, 0x5769434b, 0x7bb5ebbf, 0xe5274aa2, 0x125a2e9d, "....." },
  [1173] = { "Overlord Mok'Morokkへの挑戦", "Mok'Morokkを倒し、その知らせをBrackenwall VillageのDraz'Zilbに報告して下さい。", "お前、Overlord Mok'Morokkに挑むか？\n\nガハッ！\n\nオレ、ちっこい{race}潰す！\n\n痛い目見る用意できたら、言え。", "Mok'Morokkを村から追い出そうとしているものと思っていたが。代わりに私のところへおしゃべりしに来たのか?", "あの臆病な肉の塊Mok'Morokkは、怯えた子供のように逃げ出した。大いに役立ってくれたな、{name}。\n\nこれで我が民は新たな長を立てられる。我らの古き故郷をきっぱりと取り戻す助けとなる長をな。", 0x89fa2f8a, 0xa9d8b07f, 0xa5cf520d, 0x33951340, 0xbd3b2fa6, "....." },
  [1174] = { "ノームの勝利！", nil, nil, nil, nil, 0x5a91d422, nil, nil, nil, nil, ".mmmm" },
  [1175] = { "道で衝突", "the Shimmering FlatsのTrackmaster Zherinのために、Saltstone Basilisk・Saltstone Crystalhideそれぞれ10頭、Saltstone Gazer6羽を殺して下さい。", "\"goblins' Red Thunder\"のレーサーとbasiliskの大クラッシュの後、Kronkriderがコース整備のためにオレを雇ったんだよ。この塩原にいる動物たちが何を食べてこんなに大きく育ってるのか知らない。けど、レース開催中にコースへ出てこないように、数を減らさなくちゃならないんだ。\n\nこれはどうだろう。ちょっとした儲けが欲しいなら、出かけてってこの地域からbasiliskたちを消してくれないかな。", "レースカーの残骸を片付けるだけでも大変なのに、焼け焦げた動物の部位の中から拾い出さなきゃならないなんてね。", "道の上でbasiliskとかを殺してないだろうね! 太陽で死骸が朽ちていくのには時間がかかる。掃除するのにシャベルを持ち出すはめになりたくないんだよ。", 0x4aad9ddd, 0x75fec0c8, 0xfde98f20, 0x6d42b9b8, 0x20504194, "....." },
  [1176] = { "積載量の軽量化", "the Shimmering FlatsのPozzikのために、Hollow Vulture Boneを10個手に入れて下さい。", "レースってのは、ほんのわずかな差が大事なんだ！出力をちょっと調整するにしろ、テンションコイルを少し緩めるにしろ、フレームを軽くするにしろ、あらゆることを考えに入れなきゃならない。\n\nうちのレーサーの細かい構造調整には、ハゲワシの骨をよく使うんだ。強度と重さのバランスが完璧だからな。しかも手に入れるのも簡単さ。塩原にはハゲワシがうじゃうじゃいるからね。\n\nいくつか持ってきてくれたら、いい値で買い取るよ。", "bonesは持ってきてくれた? ちょうどステアリング機構の軽量化に取りかかろうとしてたんだけど、必要な部品が全部揃うまでは中を開けたくないんだ。", "すごいね! 今すぐクルーに仕事してもらえるよ。ありがとう、{name}!", 0x8045452d, 0x9cca10c7, 0xe02de3be, 0xb41bd113, 0x8ecc8ad5, "....." },
  [1177] = { "腹ぺこ！", "Dustwallow北部のMudcrush Durtfeetは、Mirefin Headsを$N1個欲しがっています。", "Mud、でっかいogre。\n\nMud、腹へった。\n\n魚ども、ぶん殴ってこい。Mudに食い物持ってこい。\n\nお前Mudに食わせる。さもないとMud、お前食う。", "食い物よこせ、さもないとお前食う。", "オレ、魚の頭好き！\n\nオレ、今お前食べない。", 0x5e888439, 0x59abcba6, 0xe3fe3013, 0xb79a4571, 0x39ff20ed, "....." },
  [1178] = { "ゴブリンのスポンサー", "RatchetのGazloweと話して下さい。", "オレたちのレーシングチームはゴブリンすべての誇りなんだ。チームにいろんなやり方で貢献してくれる人たちを知ったら、君は驚くに違いない。\n\nGazloweを知ってる? 彼はオレたちのために、世界中から部品を見つけ出してくれる。一度、オレたちのマシンの作業をしに来てくれたこともあるんだ!\n\n何週間か前、燃料調節装置の試作品を送ったと言ってたんだけど、まだ届いてないんだ。彼は普段すごく正確なんだけどな……。\n\nもしよかったらRatchetへ行って、彼に装置のことを聞いてきてもらえないかな? 無理強いはしないつもりだけど、ノームが追いついてきてるんだよ!", nil, "Pozzikが君を寄越したんだろ? 知っての通り、Pozzikはレーサーたちの元で働き始める前、Undermineの職人たちからすごく尊敬されてたんだ。\n\n彼がチームに入ってから最初にしたことは、2エンジン型レース車の開発だ。彼がTinkers' Unionと働かなくなって、商売は不都合を被るかもしれない、でも知ったこっちゃない、そうだろ? あんなレースはどこにもないんだからな!", 0x3e5e1f8e, 0xae7dcd1f, 0xe33f3552, nil, 0x5d6c9c9b, "...m." },
  [1179] = { "Brassbolts兄弟", "Shimmering FlatsのWizzle Brassboltsにcrate of crash helmetsを渡して下さい。", "Shimmering Flatsについて聞いたことはあるか? 遙か遠くのKalimdor大陸にある塩の平原の広がりだ。Thousand Needles渓谷のちょうど南だ。レースをするには絶好の場所なんだ。なぜなら、そう、真っ平らだからな!\n\n俺の友人のノーム兄弟がそこにいて、新しいロケットカーを試している。聞くところによると、それは速いそうだ! へへ、あまりに速すぎるんでパイロットはクラッシュし続けてるんだ。自分自身で脳震盪を起こしてるんだな。\n\nそれで彼らがシージエンジンヘルメットを頼んできたんだが、俺はここでやらなきゃならないことがある。旅に出られないんだよ!\n\n頼んでいいか?", "足元に気をつけろ! 気をつけろ、気をつけろ、気をつけろ!! ここにあるのは繊細なものばかりなんだ、勝つためには全部が完璧に動かなきゃならないんだよ!", "ああ! Longbeardが大量のヘルメットを送ってくれたよ! やったぁ!\n\nこれで俺たちの車を運転してくれるようパイロットを説得できるだろ……", 0x089469a7, 0x61c0dbae, 0x6042b639, 0xbe73198d, 0x3d6efd11, "....." },
  [1180] = { "ゴブリンのスポンサー", "Booty BayのWharfmaster Lozgilと話して下さい。", "なんで君がここへ戻ってきたか。分かってる、新しい燃料調整装置を届けるってPozzikと約束したんだ。だけど、まだ受け取っていないんだよ。Booty BayのRevilgazが出荷させると言ってたんだが、どうも見過ごされてるみたいだ。\n\nそれが本当なら、これ以上は何もできない。Booty Bayから発送されたか調べるくらいしかできないな。\n\nあそこへ行ってWharfmaster Lozgilに連絡してくれ。彼なら貨物の記録を調べられるはずだ。", nil, "Ratchetへの積荷? どれ、記録文書を調べてみよう……\n\nいや、最近積荷がRatchetへ出された記録は、Drizzlikのブーツだな。建築資材や道具の他にはないよ。間違いなく、レースに使う部品はないね。", 0x3e5e1f8e, 0x38005cbf, 0x3e7ecd8a, nil, 0x4f208c0b, "...m." },
  [1181] = { "ゴブリンのスポンサー", "Booty BayのBaron Revilgazと話して下さい。", "{name}、残念だけどこれ以上力にはなれそうにないよ。もっと追跡したいのなら、Revilgaz自身に聞いてみることをお勧めするよ。Revilgazの仕事を知ってる者がいるとしたら、Revilgaz自身だからね。\n\n彼は港の向かい、最上階にある酒場にいるだろう。", nil, "おお、君が言ってることはもちろん分かるさ。いや、もう手伝ってあげられないんだ。野郎どもがその燃料調整装置の設計図を見つけ出してくるはずだったんだが、手ぶらで戻ってきちゃってね。", 0x3e5e1f8e, 0x92e6dd47, 0x1a2020d4, nil, 0x2e25ddf5, "...m." },
  [1182] = { "ゴブリンのスポンサー", "Fuel Regulator BlueprintsをBooty BayのBaron Revilgazに渡して下さい。", "見ろ、北StranglethornのLake NazferitiにあるVenture Companyのシュレッダー、新型の燃料装置を装備してるだろ。Pozzikならあれを利用できると思ってたよ。装置の詳細を知ることができればね。\n\n残念なことに、あそこにいる現場監督のCozzleは、オレが思っているよりずっと頭が切れるみたいだ。\n\nだけど、君なら設計図を見つけ出すだけの運があるように見える。設計図は彼の家に保管されてるんだ、でも間違いなく鍵をかけてるだろうね。", "認めるのはしゃくだが、あそこにいるノームのチームはなかなかのもんだ。うちの連中にはあらゆる強みが必要なんだよ。", "さて、記録用に設計図の写しをとらせてもらうよ。そしたら、すぐPozzikのところへ持って行けるから。スポンサーのひとりがPozzikを見捨てただなんて思わせたくないだろ。", 0x3e5e1f8e, 0x453f4e10, 0x834be830, 0x2002c528, 0x39f830a2, "....." },
  [1183] = { "ゴブリンのスポンサー", "Fuel Regulator Blueprintsをthe Shimmering FlatsのPozzikに届けて下さい。", "これで準備は万端のはずだ。Pozzikによろしく伝えてくれ。それから、何か必要なものがあれば遠慮なく言ってくれ、ともな。あいつがコース記録を破ったって知らせがすぐ届くのを待ってるよ！", "{name}! fuel regulatorは突き止められたかい?", "もう組み立てられてると思ってたんだがなあ。でも、ゼロからデザインを改良する滅多にない機会をくれたよ。ありがとう、{name}。改良した回路図を描きあげて組み立てて、本当にすぐ導入できると思うよ。", 0x3e5e1f8e, 0xf8ea40fb, 0x542895c5, 0x37624653, 0x39475990, "....." },
  [1184] = { "昆虫の体のパーツ", "OrgrimmarのBelgrom Rockmaulのところへ戻って下さい。", "OrgrimmarのBelgromのところへ向かって、我が主に伝えてほしい。MoktarはThousand Needlesでの仕事をすっかりやり終えたと。それと、私の研究も進んでおり、早くもっと学んでいきたいと言っていたと伝えてくれ。主はすごく喜ぶと思う。", nil, "君の取り組みに感謝しているよ、{class}。責務をこなす君がいかに粘り強いかを聞いたら、warchiefは楽しかろう。\n\nああ、もちろんwarchiefには君の名を申し上げておこう。私とはよく話すし、私の意見も高く評価して下さるんだ。\n\nさあ行ってくれ。やることがたくさんあるんだ。Korranとすぐ話して、彼があの生物についての情報を持っていたら、私のところへ戻ってきてくれ。私は、あの昆虫たちが深刻な脅威となるに違いないと思っているんだ。", 0xb7152462, 0x87c8d78c, 0xc452cee3, nil, 0xf6cc8c10, "...m." },
  [1185] = { "殻の下には……", nil, nil, nil, "やあ、また君だ! いや、つまり君――{name}である君のことだよ! そう――その君!\n\nいや、最初からやり直させて!\n\n君がSilithusで見つけたあの物――あれは実は本だったんだ。今でいうDarnassianの言葉の、とても古い方言で書かれた日誌だった。時間はかかるけど、じっくり読み込むつもりだよ。君が見つけたものはCircleにとって非常に価値のあるものだった、それを知っておいてほしくてね。\n\n巣の母さんもすっかり大喜びさ!", 0xa4f443d7, nil, nil, nil, 0x3784d4d5, ".mmm." },
  [1186] = { "十八人目のパイロット", "the Shimmering FlatsのRazzericと話して下さい。", "私はこの新しい燃料調整器をうちのレーサーの設計に組み込む作業で忙しくなるが、チームをもっと手伝いたいならRazzericに話してくれ。あいつはうちのパイロットだ――まあ、正確に言えば十八人目のパイロットだけどな――それで、レーサーに自分なりのちょっとした改造を加えるのが好きなんだ。\n\nただ、あいつはちょっと頭のネジが外れてるから、あまり驚いた顔をしないようにな。", nil, "あんた、Pozzikを手伝ってくれた{race}だな。そうだろ? オレもあんたみたいに、メカニックがさせる仕事を手伝って、ピットを走り回ってたもんさ。\n\nだがオレを見ろよ! ゴブリンレーシングチームの天才パイロットだぜ!", 0xf4451d0a, 0xbc5e51c2, 0xdaab6bf2, nil, 0x555bc85d, "...m." },
  [1187] = { "Razzericの調整", "the Shimmering FlatsのRazzericのためにSeaforium Boosterを入手して下さい。", "Pozzikが腕のいい整備士なのは分かってる。だけど、あいつは火力をどんどん積んで、しがみついて乗り切るってのを怖がってるんだ。でも俺は違う。\n\nPozzikがレーサーを仕上げたあと、俺はちょっと時間をかけて自分なりの改造を加えるんだ――ほら、操縦を緩くしたり、フレームの一部を外したり、パワーを足したりな！\n\nGadgetzanのGizmoriumにいるShreevにseaforium boosterを注文したんだが、どうやらそれを運んでた飛行船がDustwallow Marshで墜落しちまったらしい！どうしてもあれが要るんだ、{name}！", "ちょっとした後押しがなきゃ、どの面下げてトラックに顔を出せっていうんだ? ひどい話だよ、まったく。", "この美しさ、ちょっと見てみろよ! 15ポンドのseaforiumの力! いったんこれを車の横にくくりつけたら、周回が速すぎてノームを二度も負かしちゃうだろうな!", 0x5f1c77f9, 0x8bc42dc6, 0xa43547e3, 0x69ca8aa1, 0xae15182c, "....." },
  [1188] = { "安全第一", "Seaforium BoosterをGadgetzanのShreevに渡して下さい。", "でも待てよ、何だこれ? Shreevの奴、安全装置をつけっぱなしだ。ブースターから引き出せる力が限られちまう。外しておいてくれって言っといたのに! こりゃいかん。\n\nTanaris DesertのGadgetzanにあるGizmoriumへ持って行って、Shreevに取り外させてくれ。", "ご存じのとおり、Gizmoriumならどんな機械いじりの要望にもお応えできるよ! 何をお手伝いしようか?", "これを見て、安全装置の類をつけただろうなんて言うのはRazzericだけだ。このブースターはほとんどseaforium爆薬みたいなものだよ。ブースターの燃焼部分がちゃんと役目を果たすよう既に改造してあるけど、Razzericは限界を超えなきゃ満足しやしない!", 0xb32586c0, 0x6f1f839c, 0x382adabb, 0x323f1c58, 0x45db1af4, "....." },
  [1189] = { "安全第一", "the Shimmering FlatsのRazzericにModified Seaforium Boosterを返して下さい。", "よし、Razzericの望みどおりにしてやったぞ。これに点火するときは気をつけろって伝えてくれ。ほんのちょっとでもしくじったら、前に進むどころか、コースの上の焦げ跡になっちまうだけだ。\n\nそんなことになったら残念だしな。十九人目のドライバーが使い物になるかなんて、誰にも分からないし。", "Pozzikがレースカーに砂のバケツを載せたなんて信じられる? 座席の下に砂のバケツがあって、どうやって最高速度を出せっていうのさ?", "そっちの方がいいよ! こいつを動かして見せたら、ノームの目が釘付けになるのが見られるだろうよ。\n\n新記録を打ち立てるので忙しすぎるのが残念だけどな!", 0xb32586c0, 0xe7e4338c, 0x3395609b, 0x91d34415, 0x50350a5a, "....." },
  [1190] = { "ペースを保って", "Zamekに陽動作戦を行わせ、Shimmering FlatsのPozzikのためにRizzleの計画書を盗んで下さい。", "Brassbolts兄弟は新しい建築素材を見つけたんだ。筋が通る説明はそれしかない。奴らの車は前より速く走ってるのに、設計も、奴らの走行から集めたほかのデータも全部同じなんだ。\n\n分かってるのは、Rizzle Brassboltsがこの新発見の設計図にほとんど付きっきりだってことだ。\n\nZamekが陽動を仕掛けてくれるから、その間に奴らから設計図を盗み出せるはずだ。", nil, "急いだ筆跡で書かれた、ある原料の精錬に関する注意と設計の巻物だ。", 0xe566e0e0, 0xff2f3a85, 0xf5d0ad11, nil, 0xb2a3fc14, "...m." },
  [1194] = { "Rizzleの概略図", "Shimmering FlatsのPozzikにSample of Indurium Oreを渡して下さい。", "Rizzleの概略図にindurium鉱石の製錬工程が書かれている。その走り書きによると、indurium鉱石はBadlandsにあるドワーフの採掘場Uldamanから産出すると書かれている。\n\n他には、熱耐性に関してのメモがある。\n\n計画書のペーパーウエイトとして使われていたのは、精錬前のindurium鉱石の塊のようだ。", nil, "Indurium? 面白い……。君が言うような加熱耐性能力があるなら、最近ノームが見せている性能の向上に説明がつく。\n\n君が持ってきてくれたこのサンプルにも、とてつもない価値があるだろうね。鉱石にもいくつか実験ができそうだ。でも、これが実際役に立つには、鉱石がもっと必要になるだろうね。", 0x88c336fd, 0x1d1e5712, 0x7f1c4de3, nil, 0x3212b263, "...m." },
  [1195] = { "神聖な炎", "Thunder BluffのZangen StonehoofにFilled Etched Phialを返して下さい。", "Thousand NeedlesにいるGalak centaurは、彼らcentaurが創られた時から遺物を守り続けている。\n\n我々はそれを手に入れたいのだが、ナイトエルフのmoonwellのうちのひとつから水を汲んだ小瓶が必要なのだ。\n\n水を汲むためには、まずAshenvale Forestの中心にあるRaynewood Retreatで、dryadたちが持ち運んでいる小瓶を入手しなくてはならない。moonwellはFalfarren Riverの西岸近く、街道の南にある。そこで瓶を満たせるだろう。", "filled phialが手に入ったら、Thousand Needlesにいる私の仲間、Rauに送ることができる。phialの水を頼んできたのは彼だから、どう役立てればいいかは彼のほうがよく分かるだろう。", "とても素晴らしい。これは問題なくRauの要求を満たしているだろう。これをRauのもとへ運んでくれないだろうか。Thousand Needlesで楽しく時を過ごせるかもしれないぞ。", 0x0eec15af, 0xbef453f2, 0x39ee05d9, 0x1e88abdc, 0x6bcc8f92, "....." },
  [1196] = { "神聖な炎", "Freewind PostのRau CliffrunnerにFilled Etched Phialを届けて下さい。", "Thousand Needles南東のFreewind PostにいるRau Cliffrunnerにこの瓶を持って行きなさい。Barrens南端のGreat Liftに乗れば、Thousand Needlesに行ける。\n\n間違いなく、君なら我々をもっと助けられるよ。", "もしかして、Zangenに送られてきたんじゃないだろうね?", "うーん、そうですね。この瓶なら完全に目的に適うでしょう。dryadとcentaurは共通の祖先を持っているので、moonwellの水はcentaurの遺物を取り囲む永遠の炎の守りを破るのを可能にしてくれると思います。", 0x0eec15af, 0xedccb470, 0xcc1fbf00, 0xa64fa397, 0x98a80600, "....." },
  [1197] = { "神聖な炎", "Cloven Hoofを入手し、Freewind PostのRau Cliffrunnerに渡して下さい。", "あなたが持ってきて下さった水を使えば、centaurの遺物を保つ炎を一時的に消すことができるでしょう。しかし、長くはもちませんから、素早く行わなくてはなりません。\n\nここの北にSplithoof Cragというcentaurの砦があります。厳重に守られた岩山、Splithoof Holdの中で炎は守られています。\n\n充分気をつけて下さい。ここのGalak centaurはとても数が多いですし、奴らにとっても、大切な物を明け渡すのはとても嫌でしょうしね。", "Cloven Hoofを手にするのが待ちきれない。もう手に入れたか?", "この蹄から奇妙な力が出ているのを感じます……これを研究することで、間違いなくcentaurに関する驚異的な新発見ができるでしょう。\n\n感謝します、{name}。あなたがもたらした謎について、これから解読を始めなくては。", 0x0eec15af, 0x29892850, 0xe37c2230, 0x248ac646, 0x46ef0c77, "....." },
  [1198] = { "Thaelridを探し求めて", "Blackfathom DeepsでArgent Guard Thaelridを探し出して下さい。", "近ごろ、Ashenvaleの沿岸にあるBlackfathom DeepsでTwilight's Hammerとnagaが手を組んだという噂が数多く流れています。\n\nここArgent Dawnでの私の役目は、できる限り多くの情報を集め、いつどこで助けが必要なのかを把握することです。\n\nBlackfathom Deepsの動きを調べに斥候を送ってから、もう何週間にもなります。Argent Guard Thaelridからはまだ報告がありません。\n\nほかの斥候たちは差し迫った用事で手が離せないのです。\n\n私の代わりにThaelridを探し出し、力を貸してあげてください、{name}。", nil, "Dawnwatcher Shaedlassが君をここへ寄越してくれて良かった。この腐敗した場所で、ひどく邪悪な計画が密かに進んでいる。", 0x6711bba5, 0x899a2616, 0x5e4d6659, nil, 0xa5cf35d8, "...m." },
  [1199] = { "Twilightの崩壊", "DarnassusのArgent Guard ManadosにTwilight Pendant 10個を渡して下さい。", "混沌のOld Godsの古の儀式によって力を得たTwilight's Hammerの者どもは、闇の主たちを復活させ、世界中に死と恐怖をまき散らそうと励んでいる。\n\n我々は、Twilight's Hammerがnagaと手を組み、Ashenvaleの沿岸にあるBlackfathom Deepsに集結していると考えている。\n\nあの古い神殿の奥深くでどんな邪悪な企みが練られているにせよ、阻止せねばならん。\n\nHammerに戦いを挑み、その働きの証を持ち帰ってこい。君の働きにはたっぷりと報いよう。", "Blackfathom Deepsはかつて古代ナイトエルフの神殿でした。そこには、この上なく強力な月の泉があったのです。Twilight's Hammerの手によって、今そこでどんな悪がたくらまれているのか分かりません。\n\n彼らを一掃する成果はありましたか?", "君は紛うことなく勇敢で誇り高き家系だ、{name}。Argent Dawnは邪悪に対する君の取り組みを称賛する。", 0x89671cf6, 0x4e205a89, 0x1b3033fd, 0x81e6c9bf, 0x80ee0d52, "....." },
  [1200] = { "Blackfathomの悪事", "Twilight Lord Kelrisの首をDarnassusのDawnwatcher Selgormに渡して下さい。", "力が尽きてしまいました。あなたの助けが必要です!\n\n遠い昔、この場所はEluneの偉大な神殿でした。けれど、Old Godの穢れが大地の下から染み出して聖なるMoon Wellを汚したとき、不運がこの地を廃墟へと導いたのです。\n\nOld Godのしもべ、Aku'Maiが水の中から現れました。\n\nTwilight's Hammerの信者たちはnagaと手を組み、この地を占拠しています。Kelrisに率いられた信者たちは、力を得るために罪なき者をAku'Maiへの生贄にしているのです。\n\nどうかKelrisを倒し、その首をDarnassusのSelgormのもとへ届けてください、{name}。", "時間は貴重なものだ、{class}。\n\nこのDarnassusでの私の役目は、Argent Dawnを繁栄させ、Kalimdorに迫る邪悪な勢力を阻むことだ。\n\n用件を手短に言うか、立ち去るがいい。", "Kelrisはずいぶん長い間、我々の手を逃れてきた。\n\nこの地で悪がその姿を現すときには、決まってKelrisが一枚噛んでいたようだ。しばらくの間、我々は奴を死んだか行方知れずだと考えていた。\n\nだがこれで完全に筋が通る。奴の支配を終わらせたことで、君は多くの罪なき人々の命を救ったのだ。\n\n光にかけて! 己の私利のために、Old Godの僕へ誰かを生贄に捧げるなど、非難の言葉すら足りぬ!\n\n君は偉大な行いを成した、{name}。Argent Dawnを代表して敬意を表する。", 0x43ec82c9, 0x563f3e88, 0x7cceb3eb, 0xcf6bba07, 0xa9fa6819, "....." },
  [1201] = { "Theramoreのスパイ", "Theramore Infiltratorを９人倒して、Brackenwall VillageのNazeer Bloodpikeのもとへ戻ってください。", "HordeとAllianceは休戦状態にあるが、辺境でのこぜりあいと隠密行動が敵対勢力によってなされている。そしてHordeこそが最高であることを証明するのは我らの義務である！\n\n今こそその絶好の機会である。\n\nAllianceのInfiltratorどもがBrackenwall Villageの東にいる。奴らはこの村の動向を調査し、Theramoreに報告しているようだ。断じて許しがたい！\n\nInfiltratorどもを見つけだし、始末するのだ。やつらにスパイの存在を我らが容認しないという断固たるメッセージを送りつけてやるのだ！", "潜入者たちは見つかったか、{name}?", "よくやった！やつらのInfiltratorどもは手練だが、Hordeの警戒網から逃れることは容易ではあるまい！", 0xf43a1add, 0x3b0e1591, 0x5ac2dc14, 0xe24f4bcb, 0xe38465d3, "....." },
  [1202] = { "Theramore 桟橋", "Brackenwall Village の Nazeer Bloodpike に Captain's Documents を渡す。", "{name}、我々の密偵2人が、Theramoreの波止場に停泊する船から書類を盗み出すために送り込まれた。書類は手に入れたが見つかってしまい、書類を海へ投げ捨てるしかなかった。\n\n密偵の1人は後に逃げ延びたが、獲物を取り戻すことはできなかった。彼は私に失敗を報告した。そこで今、この任務を君に任せる。\n\n書類はTheramoreの波止場の下、水中のどこかにある収納箱の中だ。その書類を見つけ出し、私のもとへ持ってこい、{name}。", "documentsは見つかったか、{name}? あれにはAllianceの安定に欠かせない情報が記されている。つまり、Hordeの安全にも欠かせないということだ。", "よくやった、{name} 。これは簡単な任務ではなかった。お前が手に入れた文書は必ず上官に高く評価されるぞ。", 0xca5e3f3f, 0xd9e13fa6, 0x94510bbb, 0xfa923232, 0x9250cb73, "....." },
  [1203] = { "Jarlには剣が要る", "Moonsteel BroadswordをDustwallow MarshのJarlのところへ持って行って下さい。", "切らなきゃならないものがある。何を切るかは言えないが……刃が要るんだ。ある特別な刃が……\n\nmoonsteel broadswordと呼ぶ者もいる。俺はスイングブレードと呼んでる。\n\n手を貸してくれるか？ 町で見つかるかもしれないし、鍛冶屋と話せば特別に作ってくれるかもしれない。\n\nだがのんびりするなよ。俺が切るものは、いつまでも待っちゃくれないからな……", "俺の剣を持ってるのか??", "いい剣だ。振り心地がいい。よく振れる剣だ。ありがとう。ありがとう、ありがとう、ありがとう！！！さっそく試してみたい……\n\nあとで。あとで試そう。でも、さっき言いかけたように……ありがとう。", 0x83fbbd68, 0xb3fd6755, 0xb542ec67, 0x72ec59cb, 0x58fdfcb9, "....." },
  [1204] = { "蟹と Mudrock のスープ", "Theramore の Morgan Stern に Forked Mudrock Tongue を8つ渡す。", "今、「Mudrock Soup and Bugs」って料理に取り組んでるんだ。まだ肝心の材料がそろってなくて……それに、Dustwallow Marshをのそのそ歩き回ったら、私なんかすぐにやられちゃうと思うんだよね！\n\nだから{name}、狩りをしてきてくれない？まずはMudrock turtleの舌が必要なんだ。Mudrockは海岸沿い、主に湾のあたりにいるよ。\n\nでも、ただの舌じゃだめなんだ！Mudrockの中には舌が二股に分かれてるのがいるって聞いたんだよ……\n\n二股の舌には独特の風味があるらしくて、その風味を料理に入れたいんだ……", "forked tonguesは手に入れたか?", "これで十分です！ありがとう、{name}！\n\nさて、この舌でいろいろな調理法を試して、味を一番引き出せる方法を見つけますよ。\n\nいつかStormwindのBlue Recluseで出せるほどの料理を作ってみせます！", 0x7aeb5221, 0x078c2d47, 0x20cb64c6, 0x92cf0d6d, 0x831a37a0, "....." },
  [1205] = { "Deadmire", "Deadmire's Tooth を Thunder Bluff の Melor に渡す。", "DeadmireはDustwallow marshに棲む太古のcrocoliskだ。そして今、奴が死ぬ時が来た。\n\n沼を巨体で這い進むたびに古い骨がきしむ。今なお若き日の力と速さで動くものの、老いた体はその内に宿る偉大な魂を苛んでいる。その炎は決して揺らがぬ魂だ。\n\nだが今、奴は絶え間ない狂おしいほどの痛みの中で生きている。この気高い生き物の命を終わらせねばならない、{name}。Deadmireを安らぎへと導くのだ。", "Deadmireのtoothは持っているか、{name}? あの生き物の苦しみを終わらせてくれたか?", "よくやってくれました、{name}。\n\n狩りは容易ではなかったでしょうが、あの獣の苦しみがようやく終わったと知れて良かった。", 0x3bd9ecfc, 0xfa8d27c2, 0xad357187, 0x0f6b0ab3, 0xdf43794d, "....." },
  [1206] = { "Jarlは目玉が欲しい", "Unpopped Darkmist Eyesを$N1個、Swamplight Manorの\"Swamp Eye\" Jarlのところへ持って行って下さい。", "目玉の汁は飲むのにいい汁だ。残念なことに、たいていの生き物には目が二つしかない。\n\nだが蜘蛛には目がたくさんある。たくさん、たくさんな。それにDarkmistの目玉の汁はうまい。まろやかでしょっぱい！ 潰れていない蜘蛛の目玉……もう味がしてくるようだ。\n\nDarkmistの蜘蛛はここから西、Darkmist Cavernにいる。蜘蛛の名前が洞窟から来たと思うか……それとも逆か？", "あのeyesはどこだ?", "目玉を持ってきた！目玉を持ってきた！おいしい、おいしい蜘蛛の目玉！\n\n目玉の中には……じっと見つめると見つめ返してくるのがある。そういうのは最後に食べるんだ。一緒にいてくれるからね……この沼の中で。\n\nこんにちは、小さな蜘蛛の目玉ちゃん。こんにちは！お前はチキンの味がする。ねばねばで、しょっぱいチキン！\n\nんん～。", 0xb7299084, 0x7739e293, 0x284e05c2, 0xb359f7ef, 0xc906ff19, "....." },
  [1218] = { "Soothing Spices", "Soothing Spicesを$N1個、Dustwallow Marshの\"Swamp Eye\" Jarlのところへ持って行って下さい。", "料理が好きなんだ。うまい沼地料理さ。緑のカエルの足の揚げ物なんかをね。\n\n料理にはスパイスが要る。心安らぐスパイスがね。そしたらシチューを作って、ぐつぐつ煮込んで、すすって、あんたにも分けてやるよ。\n\nシチューは好きかい？", "スパイス。誰の人生にも少しスパイスが必要だ。そう思わないか?", "ああ、それがそのスパイスだ！さあ、沼地仕込みのうまいシチューだよ。", 0x2b1b6638, 0x3a1d39ae, 0xdb8fa4c7, 0x17a16907, 0x3316beb0, "....." },
  [1219] = { "オークの報告書", "Spy's ReportをTheramore Lieutenantのところへ持って行って下さい。", "柔らかい土をふるいにかけていると、切断されたオークの手が見つかる。その手には骨を彫った筒が握られている。そして筒の中には、泥で汚れた羊皮紙が入っている。\n\n羊皮紙はオーク語で書かれている……重要なものに見える。", "報告することはあるか?", "うーん……オークの文字はあまり読めないけど、これは報告書のようだ……オークのスパイが書いたものだ！", 0x651c8b2c, 0x1eca7823, 0x0c01ebc8, 0x58f40bcf, 0x2681dae1, "....." },
  [1220] = { "Captain Vimes", "Spy's ReportをCaptain Garran Vimesのところへ持って行って下さい。", "君が見つけたオークの報告書は、Captain Vimesに見せるべきだ、{name}。彼は誰よりもオーク語に通じている。それに、Theramoreの近くにHordeの密偵がいることも知らせねばならない！\n\n隊長はTheramore Isleの北東側にある兵舎にいる。", "何か私に渡すものがあるのか？", "オークのスパイの報告書だって！どうやってこれを見つけたんだ？まあいい――何と書いてあるか見てみよう……", 0x5cadbab4, 0x82091bb0, 0xf362d612, 0xa03be4c2, 0x434989ce, "....." },
  [1221] = { "Blueleaf Tubers", "Crate with Holesを手に入れる。\n\nSnufflenose Command Stickを手に入れる。\n\nSnufflenose Owner's Manualを手に入れて読む。\n\nRazorfen KraulでCrate with Holesを使ってSnufflenose Gopherを呼び出し、Command Stickをgopherに使ってTubersを探させる。\n\nBlueleaf Tuberを6個とSnufflenose Command Stick、Crate with HolesをRatchetのMebok Mizzyrixのところへ持って行く。", "Blueleaf tubersは世界中で珍味とされてるんだ！ でも珍しい、とても珍しいんだよ。見つかる場所はここBarrensの、地中深くにあるRazorfen Kraulだけさ。\n\nしかもそこでさえ、どこを探せばいいか正確に分かってなきゃ見つけられない！ だから、代わりに見つけてくれるようにこのsnufflenose gopherたちを訓練したのさ。こいつらは鼻がすごく利いて、50歩離れたところからでもtuberの匂いを嗅ぎつけるんだ。\n\n簡単じゃないだろうけど、tubersを持ってきてくれたら、たっぷり払うよ。", "tubersは持っているか、{name}?", "よし、手に入れてきたな！これなら取引相手にたんまり売れるぞ！\n\n配達ありがとう、{name}！君は最高の相棒だ。", 0x7ee65c2a, 0x7098b232, 0x604bd2e9, 0x6deb831e, 0xca3541f1, "....." },
  [1222] = { "Stinky の逃走", "\"Stinky\" Ignatz を護衛し、Theramore の Morgan Stern と話す。", "よかった、やっと私を食べようとしないのが来た！\n\nこのあたりの生き物をどうにかするのに手を貸してほしいんだけど、あんたならぴったりだよ、相棒。\n\n料理人のMorgan Sternが新しいレシピを研究していて、bogbeanの葉を集めてこいって私をここへ使いに出したんだ。美味いと思ってるんだろうね。\n\nとにかく、bogbeanの株を探しているうちに……囲まれちゃったんだ！ここから出るのを手伝って、bogbeanを探す間、背中を守ってくれない？", "Mr. Ignatzを見なかった? しばらく前に沼へ行かせたんだけど、戻ってこないんだ!", "ついさっきMr. Ignatzがbogbeanの葉を持って来て、あなたに大変な窮地から救ってもらったと話してくれました。\n\nありがとう、{name}。次にStormwindのBlue Recluseに来たときには、ごちそうを振る舞うよう叔父に頼んでおきますね。", 0xa7772055, 0x9665fa1b, 0x3e242cc2, 0x9fc16527, 0x1aa75038, ".....", nil, nil, 0x9f0044e4, nil, nil },
  [1238] = { "失われた報告書", "Spy's ReportをBrackenwall VillageのNazeer Bloodpikeのところへ持って行って下さい。", "柔らかい土をふるいにかけていると、切断されたオークの手が見つかる。その手には骨を彫った筒が握られている。そして筒の中には、泥で汚れた羊皮紙が入っている。\n\nその羊皮紙は、何週間もTheramoreの街を偵察していたオークが書いた報告書だ。\n\n羊皮紙に目を通すと、Brackenwall Villageにいるオークの密偵長に届けねばならないことは明らかだ。", "何か私に渡すものがあるのか？", "よくやった、{name}。我らの密偵Marg NighteyeはTheramoreの外に配置されていた。彼の任務はその街を探ることだった。\n\nこれは彼の最新の報告書で、そしておそらく最後のものだ――君の証言からすると、Margは沼地で最期を迎えたのではないかと思う……", 0xf5b5536a, 0xad5280a6, 0x2210ebf5, 0xa03be4c2, 0xf08dae6b, "....." },
  [1239] = { "切り落とされた首", "Defiant Orc HeadをBrackenwall VillageのNazeer Bloodpikeのところへ持って行って下さい。", "力を込めて掘り進めると、オスのオークの頭部が現れる。首のところで無残に切断されている。唇はうなり声を上げたまま凍りつき、暗い目が反抗的に宙を見つめている。", "また別の報告があるのか、{name}?", "これはMarg Nighteyeの首だ！恐れていた通り、彼は死んでいる。\n\n首の傷を見ろ！武器であんなぎざぎざの傷がつくだろうか、それとも何かの獣が我らの密偵を殺したのか？\n\nこれは解かねばならない謎だ、{name}。Margの死がAllianceの手によるものか突き止めねばならん！", 0xfa82fef6, 0x47eaae1f, 0x00307025, 0xd63435f2, 0x76e949da, "....." },
  [1240] = { "トロールの呪術医", "Defiant Orc HeadをStranglethorn ValeのGrom'gol Base CampにいるKin'weelayのところへ持って行って下さい。", "Margの死にまつわる出来事を知らねばならない！ そのための唯一の方法は、{name}、トロールの呪術だ。\n\nMargの頭をStranglethorn ValeのGrom'gol Base CampにいるKin'weelayへ持って行け。\n\nKin'weelayはDarkspearのトロールの中で最も強力な呪術医だ。Marg Nighteyeの魂と話せる者がいるとすれば、それは奴だ。", "お前の周りには怒れる魂がまとわりついているぞ、同胞よ。Kin'weelayに何の用だ?", "ああ、分かったぞ。このオークの魂は、果たされぬ務めへの怒りに煮えたぎり、この世に縛られているのだ。\n\nでは、この怒れるオークと言葉を交わすとしよう……", 0xc3ebe4b0, 0x47abb0de, 0xb5a267d6, 0x00ef9e2f, 0xc7c2af90, ".....", nil, nil, nil, 0x7e03cdf2, nil },
  [1241] = { "消えた外交官", "Stormwind CityでJorgenを見つけて下さい。", "最近、Jaina Proudmooreと会うため、ある外交官がTheramoreへ送られた。その外交官は到着しなかった。\n\nDefiasがこの陰謀に関わっていると私は考えているが、どう関わっているのかは分からない。外交官の失踪はまだ世間の注目を集めていないが、いつまでもそうはいかないだろう。\n\n王の密偵たちがすでに街中で手がかりを探し回っているが、私には私で関わらせたい伝手がある。\n\nValley of Heroesに、Jorgenという古い友人がいる。彼を見つけてこのメモを渡し、その指示に従ってくれ。", "ふん、男の釣りの邪魔をするからには、ちゃんとした理由があるんだろうな。行商人は好かん、物乞いなんぞもってのほかだ。", "ふむ……<Jorgenが目を細めてあなたを見上げる。>\n\nいいだろう。手を貸してやる。だが、そうしたいからじゃない、そうする義理があるからだ。\n\nそれと、一つはっきりさせておくぞ。あんたはそもそも知るべき以上のことを知りすぎている。これはここだけの秘密にしておいて、何か分かっても酒場でべらべらしゃべるんじゃないぞ。分かったか？", 0xbe525a75, 0x33b9abb0, 0x849a1ec8, 0x3360f67b, 0x7c260137, "....." },
  [1242] = { "消えた外交官", "Jorgen's Sealed NoteをStormwind CityのElling Triasに届けて下さい。", "このメモをElling Triasに持って行きな。他には何も言うんじゃねえぞ。礼儀正しくして、返事を待つんだ。心配するな、返事はくれるさ。\n\nもう一度だけ念を押しとくぜ、{name}。この件は真剣に扱え。それと、口は閉じとけ。\n\nTriasならTrade Districtにある奴のチーズ屋、Trias' Cheeseで会える。幸運を祈る。", "こんにちは、{name}。何かご用ですか? 特製のTrias cheddarはいかが? それともDarnassian bleuをひとかたまり?", "すまない、私に手紙だって？これは驚いた……仕事ばかりしていると、木箱や樽以外の配達なんてめったにないからな。何の用件か見てみよう。\n\n<Ellingが手紙を開けながらあなたを見上げる。>\n\n少し緊張しているようだが、大丈夫か、{name}？", 0xbe525a75, 0x5346c0c9, 0x39356874, 0x382f590a, 0x3fbb5bf2, "....." },
  [1243] = { "消えた外交官", "Sealed NoteをDuskwoodのWatcher Backusに渡して下さい。", "Jorgenのやつめ……そういうことかよ、え？\n\nまあいい、それなら対処できる。あいつがさっさとTwisting Netherに行っちまうことを願うよ！\n\nこれからの段取りを話すぞ、{name}。俺はここで自分の伝手を使い始める。だが、金を節約したいんで、足を使う仕事はほとんどお前にやってもらう。\n\nDuskwoodのDarkshireへ向かって、Watcher Backusを探せ。あいつはたいてい町のすぐ外の北の道を巡回してる。俺のためにDefiasの動きを調べてるって伝えれば、できる限りの情報をくれるはずだ。", "森の中をうろつくのはあまり安全じゃないぞ、{name}。気をつけて、何か怪しいものや危ないものを見かけたら、すぐにWatchersに知らせるんだ。自分で片付けようとするなよ。お前の身に何か恐ろしいことが起きても、こっちは責任を持てないからな。\n\nでもまあ、お前はどうせ俺の言うことなんか無視して、暗闇から出てくるものと片っ端から戦うんだろう? ハハ、そうさ、冒険者って連中は……みんな同じだ。", "おや、Triasに言われて来たのか？それなら話は少し違うな。\n\n暗闇から襲ってくる化け物どもとは好きに戦ってくれ。あいつと付き合うような手合いなら、きっと楽に片付けられるだろう。\n\nで、こんな陰気な日に、我が友は私に何の用だ？", 0xbe525a75, 0x46fcf9c1, 0x7257660b, 0x9545778d, 0x820d06c6, "....." },
  [1244] = { "消えた外交官", "Defias Docketを見つけ、DuskwoodのWatcher Backusのところへ持ち帰って下さい。", "Defiasの動き？ まあ、動きならいつだってあるさ。奴らが大人しくしていようと、俺たちは脅威とみなしている。\n\nだが考えてみると、最近ちょっと妙な目撃情報があったな。二、三週間前のことだったはずだが、奴らの手先が何人かAddle's Steadの周りに集まっていたんだ。報告からすると、何か大きなことが起きたんだろうと思った。\n\nまずそこを調べて、見つけたものを何でも持ってきてくれないか？\n\nその農場は、Duskwoodに入ってすぐ、Westfallから来る道の南にある。", "外では気をつけてくれ、{name}。お前をここへ寄越したのがTriasなのは分かっているが、だからといって森に厄介なものが潜んでいないとは限らない……特に、Defiasを調べているとなればな。", "無事に戻ってきたな。それ以上望むことはないだろう？\n\nさて、何を持ってきたか見てみよう。これまで見てきたDefiasの文書と比べても、かなり正式なもののようだ。だが、君が探しているものから目をそらさせるための偽物という可能性もある。", 0xbe525a75, 0x48feff50, 0xea67aecc, 0xcea0ed63, 0x67804e8a, "....." },
  [1245] = { "消えた外交官", "Defias DocketをStormwindのElling Triasのところへ持って行って下さい。", "おっと、これはただ君を惑わすためのものにしては複雑すぎるな。俺はこんなものを見るべきですらない。Triasのところへ持って行け。あいつなら意味が分かるはずだ。それから、絶対に誰にも邪魔させるんじゃないぞ。これは俺の手に余る。あいつの手にも余るかもしれないが、まあ様子を見よう。\n\nそれと頼みがある、{name}。俺が手を貸したことは誰にも言わないでくれ。こんなことを知っていながら黙っていたと上の連中にばれたら、たぶん俺は吊るされちまう。", "戻ってきたか、それも無事で。お互い分かっているだろうが、チーズを買いに来たわけじゃないんだろう。挨拶は抜きにしよう。Backusは役に立ったか、それともまだDuskwoodへ出発すらしていないのか?", "ああ……これは興味深い内容だ。JorgenとDeLaveyが私を巻き込んだのは賢明だったな。\n\nDefiasはこの計画を成し遂げようと、かなり躍起になっていたようだ。ふむ……これは何だ？「Fist」？聞き覚えのある名前だな。", 0xbe525a75, 0xa98e158b, 0xfafe092f, 0x24e86e52, 0x8bf38d0b, "....." },
  [1246] = { "消えた外交官", "StormwindのDashel Stonefistと話して下さい。", "ああ、今考えてみると……Dashel……Dashel何とか……名前は何だったか？ FIST！ Dashel Stonefistだ。ある筋じゃFistと呼ばれてる。たぶん喧嘩好きだからだろうな。\n\nたいていはOld Townにいる。ど真ん中にな。行って話してこい。必要なら、剣か何か重くて鈍いもので口を割らせろ。それと、ためらうな。この書類が示すほど深く関わってるなら、自分から情報を渡す気はないだろうからな。", nil, "何だと？！\n\n俺の路地に入り込んできて、俺の個人的な商売について聞き回るだと？お前には明らかに関係のない商売だろうが。", 0xbe525a75, 0x89ab0b6a, 0x9bede811, nil, 0xc7bc3a6e, "...m." },
  [1247] = { "消えた外交官", "StormwindのElling Triasと話して下さい。", "で、まあ……その……Addle's Steadでの集まりについて、ちょいと知ってるかもしれねえ。二、三週間前だったと思う。俺はほとんど関わってねえんだ。A計画がしくじった時点で俺の役目は終わりだった……くそったれの冒険者どもめ。\n\nB計画のために送り込んだ内通者はMenethilから来た奴だ。Slimって呼ばれてる。奴らの予備の計画について知ってるのはそれだけだ。", nil, "まだ生きていたようで何よりだ、{name}。それで、Dashelとはうまくいったんだな？\n\n奴らのこの計画についてさらに読み込んでいたんだが、狙っていた外交官の名前は書かれていないものの、最初の誘拐に失敗した後に実行したプランBについては書かれている。\n\nDashelが言っていたこのSlimについては、ほかの名前は何も書かれていないが、Menethilにいると言うなら、それが手がかりになる。", 0xbe525a75, 0x3f1c2d43, 0x27062c88, nil, 0x4d29634d, "...m." },
  [1248] = { "消えた外交官", "WetlandsのMikhailと話して下さい。", "私の知り合いが、Wetlandsの港町Menethilで引退生活を送っている。私の下で動いていると伝えれば、君の言葉だけで手を貸してくれるはずだ。名前はMikhail。数年前にStormwindを離れる前、バーテンダーになると言っていた。\n\n彼と話し、そのSlimを見つけ、さらわれた外交官について他に知っておくべきことがないか探ってくれ。奴らが彼をどこへ連れて行ったのか、せめて彼が誰なのかを突き止めねばならない。書類には、彼を捕らえた後の奴らの計画については何も書かれていない。", nil, "ようこそ、ようこそ、ようこそ、{name}。よく来てくれたね。今日はエールでもどうだい？それとも羊肉かな？\n\n望みを言ってくれれば、ちゃんともてなすよ。私の名はMikhail、お役に立てるのを楽しみにしているよ。\n\nん？何だって？Trias？声を落としてくれ、友よ。これは酒場中に聞かせる話じゃない。", 0xbe525a75, 0xc1ff9a9a, 0xe0299135, nil, 0x98173898, "...m." },
  [1249] = { "消えた外交官", "Tapoke Jahnが逃げる前に取り押さえ、MenethilのMikhailのところへ戻って下さい。", "Ellingがあなたをここへ寄越したと？ それなら、先ほどのもてなしは十倍にしましょう。必要なものがあれば、何でも言ってください。できる限りお力になります。\n\nふむ、Slimですか？ 聞き覚えのある名前かどうかは分かりませんが、気をつけておきましょう。\n\n今は見ないでください、{name}。ですが、出口のそばにいる紳士がこちらを見ています。どうも私たちの会話に聞き耳を立てすぎている、と言えばお分かりでしょう？ 私があなたなら、彼が扉へ逃げ出す前に取り押さえるよう、できることをしますね。", "逃げられたのか？私たちを見ていたあの様子、少し怪しかったからな。", "捕まえたのか? よくやったな。あれがSlimだったとは驚きだ。\n\n正直に言うと、裏社会のもっと悪どい仕事のスリルを恋しく思う日が来るとは思ってもみなかった。昔の癖はなかなか抜けないものだな。Ellingにはこのことを言わないでくれ――私がそういう刺激を恋しがっていると聞いたら、きっとStormwindへ戻ってこいと言い出すだろうからな。\n\nMenethilにいる間、少しでも君の役に立ててよかった。他に何か必要なら、遠慮なく言ってくれ。", 0xbe525a75, 0x3bd029b1, 0xf0ae8653, 0x7fb968d6, 0xe9181389, "....." },
  [1250] = { "消えた外交官", "WetlandsのMikhailと話して下さい。", "Defiasの払いは、奴らの大義のために死ねるほど良くはなかった。奴らは王をさらったんだ。そう、Stormwindの王だ。そこらの外交官なんかじゃない。王はJaina Proudmoreと会うためTheramoreへ向かう途中だった。どうやら大ごとで、しかも極秘だったらしい。だが関わってるのはDefiasだけじゃない。奴らは誰かと手を組んでる。奴らも、これが自分たちの手に余ることだと分かってたんだと思う。\n\n俺の役目は、王の船が港にいる間に、奴らの手の者を乗り込ませることだけだった。そいつの名前はHendel。知ってるのはそれだけだ。本当だ！", nil, "王だと？！いや……王？本物の王か？冗談だろう？王をさらった連中を探しているなんて一言も言ってなかったじゃないか。王がいなくなったなんて話すら聞いていなかった――それなら王子が戴冠したのも少しは納得がいく。\n\nすぐにEllingに知らせを送ろう。君が手がかりを追っていると知りたがるはずだ。\n\nJahnがわずかな金のためにStormwindを売るとは思いもしなかった。ローグにだって、守るべき名誉というものはあるだろうに。\n\n今肝心なのは、このHendelを見つけることだ。それなら手伝えると思う。", 0xbe525a75, 0xc1ff9a9a, 0x1afb0f80, nil, 0x42686ebe, "...m." },
  [1251] = { "黒い盾", "Blackened Iron ShieldをBrackenwall VillageのKrogのところへ持って行って下さい。", "宿屋を焼き尽くした炎で黒焦げになった鉄の盾が、崩れかけた煙突に取り付けられている。その煙突は、かつてShady Rest Innを成していた建物のわずかに残った部分の一つだ。\n\n盾は煙突のレンガから取り外すことができる。", "{name}、そこに持っているのは何だ？Shady Rest Innの焼け跡から見つけた証拠か？", "人間が変わった飾りの趣味を持っているのは認めるが、暖炉を飾るのにただの鉄の盾を使うだろうか？この盾は、宿屋を焼いた者たちが置いていったのかもしれない。\n\n警告か？それとも脅しか？", 0xd8f479b5, 0x9cc24b45, 0xec300856, 0x2736d039, 0xb591fc54, "....." },
  [1252] = { "Lieutenant Paval Reethe", "Reethe's BadgeをTheramoreのCaptain Garran Vimesのところへ持って行って下さい。", "瓦礫の下で地面に光るものがあなたの目を引く。物体にこびりついた破片や灰を払いのけると、白地に金の錨の記章が表面にエナメルで描かれているのが現れる。Theramoreの紋章だ。\n\n錨の下には「Lieutenant Paval Reethe」という名前が浮き彫りにされている。", "Shady Rest Innで何か気になるものは見つかったか？", "衛兵のバッジが私のもとに持ち込まれるのは、決して良い知らせではない。\n\n戦いで倒れた男や女のこともあり、そのときは悲しむ家族に知らせを届けるのが私の役目だ。何があったのか結局分からないこともある。そして、それよりもっとひどい場合もある。", 0xf970a6d2, 0xde7dc586, 0x3bfb93d8, 0xad27b22f, 0x690ad0db, "....." },
  [1253] = { "黒い盾", "Blackened Iron ShieldをTheramoreのCaptain Garran Vimesのところへ持って行って下さい。", "宿屋を焼き尽くした炎で黒焦げになった鉄の盾が、崩れかけた煙突に取り付けられている。その煙突は、かつてShady Rest Innを成していた建物のわずかに残った部分の一つだ。\n\n盾は煙突のレンガから取り外すことができる。", "Shady Rest Innの跡地で証拠は見つかったか？", "ふむ、私は武器や防具の造りには詳しくない。使い方なら分かるが、作り方は分からない。\n\nこの盾は、宿屋を包んだ炎による損傷を除けば、ごく普通のもののようだ。", 0xd8f479b5, 0x9f8648e5, 0xec300856, 0x0edc101a, 0xaa7de7cb, "....." },
  [1258] = { "……そしてカニ", "TheramoreのMorgan SternにPristine Crawler Legを12本持ってくる。", "私の新しいレシピのもう一つの材料は、巨大な蟹の殻付きの脚だ。Dustwallowにいる蟹――Muckshellsと呼ばれているやつ――では、まったく駄目なんだ！ 残念ながら、ふさわしい蟹は遠く離れたSwamp of Sorrowsにしか棲んでいない。\n\n蟹の脚の殻は料理の見た目の要だから、傷ひとつない完璧な脚が必要なんだ。大人の蟹でも、そんな脚は一本か二本しかないかもしれない。料理の研究のためには、たくさん要るんだよ。\n\nそれで、{name}……遠出する気はあるかい？", "Mudrockの舌を使った私の研究は順調に進んでいる。君の蟹狩りもうまくいっているのだろうね？", "これはモノがイイな、{name}！この殻は完璧だよ、肉もピンクで柔らかいし。君はきっと料理人の血筋に違いないよ！", 0x08246e49, 0x169ea56c, 0x092dccb4, 0x710c2a6a, 0x5fea1325, "....." },
  [1259] = { "Lieutenant Paval Reethe", "TheramoreのAdjutant Tesoranから、Reetheについてさらに詳しく聞き出して下さい。", "Lieutenant Paval Reetheという名前に心当たりはない。Adjutant Tesoranに確認するのが一番だろう。彼は人員から装備に至るまで、Theramoreの衛兵隊の記録をすべて管理している。\n\n帳簿をざっと調べれば、このReetheが何者か分かるはずだ。", nil, "こんにちは、{name}。Theramoreの衛兵の特定の者について知りたいのですか？Reetheでしたね？\n\n正しい本を探しますので、少しお待ちください。", 0xf970a6d2, 0x9c3cc67d, 0x2df926b7, nil, 0x6f0ac7f0, "...m." },
  [1260] = { "Morgan Stern", "TheramoreのMorgan Sternと話して下さい。", "レストランの新しいメニューを考えているんだ。「バイユー」をテーマにした田舎料理でいっぱいのメニューになる。Blue Recluseの常連客もきっと気に入ってくれるはずだよ！\n\n甥のMorganを、Dustwallow Marshの端にある街、Theramoreへ送ったんだ。彼は今そこで地元の人々からレシピを集めている。これまでに何を見つけたのか、どうしても知りたくてね。\n\nTheramoreへの旅は長い。私には長すぎる。でも、君のような若い{class}なら、旅の機会に飛びつくだろう？", nil, "おや、おじさんに言われて来たのかい？\n\n実はレシピを研究していて、いくつか手がかりはあるんだけど、助けが必要なんだ。\n\n足を濡らすのをいとわない人の助けがね。", 0x9691be75, 0xccbf98b5, 0x542d5629, nil, 0x3b4fc026, "...m." },
  [1261] = { "Margは語る", "Jeweled PendantをBrackenwall VillageのNazeerのところへ持って行って下さい。", "忌々しいmuckshellめ！ Margを殺せるはずが……ああ、だが俺は死んでいる。ということは、奴に殺されたに違いない……\n\nだが俺の任務が！ 俺の任務が！ お前だ、{name}、お前がそれを果たさねばならん。\n\nTheramoreの近くで、浜辺に野営しているAllianceの兵士の一団を見つけた。そのうちの一人の兵士がペンダントを身につけていた……兵士ごときには到底手の届かないほどの宝石をちりばめたペンダントをな！\n\nその夜、俺は奴らの野営地に忍び込んでペンダントを盗んだが、基地へ戻る途中でmuckshellの蟹人間に殺されたのだ！\n\n{name}、そのmuckshellを見つけ出し、ペンダントを取り戻してくれ！", "{name}、Margがどうなったか分かったか？", "このペンダントはStormwindの兵士が身につけていたものだと？？\n\nありがとう、{name}。君はMargの死の秘密を明らかにしてくれた。だがこのペンダントは新たな謎だ。Allianceにも、そしてHordeにも、恐ろしい影響を及ぼしかねない謎だ。", 0x70433ca1, 0x5ad641f7, 0xb249811e, 0xfa0c8d04, 0xd436e6fe, "....." },
  [1262] = { "Zorへの報告", "Jeweled PendantをOrgrimmarのZor Lonetreeのところへ持って行って下さい。", "Margが盗んだペンダントが、普通の兵士の手にあったとは妙だ。持ち主が変装していたのか、あるいは兵士たち自身が盗んだのかもしれん！\n\nどちらが真実にせよ、これは貴族のペンダントだ。その謎を解き明かすには、本当の持ち主を突き止めねばならん。\n\nペンダントをOrgrimmarのZor Lonetreeへ持って行け。彼はAllianceの政治に通じている。このペンダントがStormwindの貴族たちの間で何か来歴を持つかどうか、分かるはずだ。", "DustwallowのBrackenwall Villageから来たのか？Nazeerは元気か、沼地での彼の奮闘はどうなっている？", "このペンダントは実に見事な技と精密さで作られている、{name}。オークならこんな宝石を欲しがりはしない……\n\nだが、人間の多くは欲しがるだろう。\n\nこのペンダントを調べさせよう。いずれその謎が明らかになることを願おう。", 0xd722ec73, 0xcecf9108, 0x62946d7f, 0x28d93ec7, 0xceb5e47e, "....." },
  [1264] = { "消えた外交官", "Dustwallow MarshでCommander Samaulを見つけて下さい。", "毎月の初めに、Kul Tiras Marinesは全員給料を受け取り、たいていTheramoreを離れてどこか別の場所へ行きます。その多くがここへ来て、女遊びをし、飲み騒ぎ、ただ楽しい時を過ごすのです。その中の一団はこの酒場の常連と言っていいほどで、そのHendelもその中にいると思います。\n\nHendelがまだTheramoreに駐留しているなら、TheramoreのCommander Samaulが見つける手助けをしてくれるでしょう。彼はProudmooreに完全に忠実ですが、Ellingの名前を出せば手を貸してくれるはずです……内密にね。", nil, "お会いできて光栄だ、{name}。私はCommander Samaul。ここTheramoreでMiss Proudmooreの軍を指揮している。\n\nかなり忙しい身だが、質問があれば遠慮なく言ってくれ。手短になるかもしれないが、君が助けを必要としているなら無礼を働く理由はない。\n\n街の外へ出るつもりなら、気をつけることを勧める。ogreやオーク、murlocだけでなく、沼地の南部にはblack dragonがうようよしている。", 0xbe525a75, 0x1fb00952, 0x67b3bd30, nil, 0xe1b11c72, "...m." },
  [1265] = { "消えた外交官", "Sentry PointでPrivate Hendelの手がかりを探す。", "Hendel？ ああ、その男なら知っている。だが、なぜ私の兵士の一人が必要なのだ？\n\nEllingが彼を探すよう君を寄越したと？ ふむ、気に入らんな。君の用件が厄介なものでなければ、Ellingがまず私のところへ君を来させることはないだろう。何の件か話せないのは分かるが、これだけは知っておいてもらおう。私にはこの地を守る義務がある。騒ぎを起こすつもりなら、話せることは何でも知らせてもらいたい。\n\nHendelは、Theramoreの外にある最初の塔に配置されていたはずだ。用心しろ。", "何かな、{name}？", "君が探している男、Hendelという者はここにはいない。ほかの情報源から、君がすでに知っているであろう情報がLady Proudmooreのもとに届いている。彼女は私に君を探し出し、君の企てに力を貸すよう命じた。許してもらえるなら、Private Hendelの居場所を教えよう。そうすれば彼を裁きにかけることができる。", 0xbe525a75, 0xb829492c, 0xb6dd2bf9, 0xabfc0333, 0xf5957b11, "....." },
  [1266] = { "消えた外交官", "Dustwallow MarshでPrivate Hendelを見つけて下さい。", "Private Hendelはここから西にいる。今は見張りの任務について、休息中のTheramoreの潜入兵たちを守っている。彼らはHordeの基地であるBrackenwallを見張り、我らの国境を脅かしそうなものが他にないか探っているのだ。\n\n彼を見つけるのに苦労はしないだろう。道沿いのテントを探せばいい。\n\n私には別に片付ける用事があるが、すぐに追いつこう。何か問題があれば、いつでもLady Proudmooreの塔で私に会える。", nil, "やあ、市民よ。ここはうろつくには危険な場所だ。命が惜しいなら、長居はしないほうがいい。\n\n質問を手短にしてくれるなら、力になれるか考えよう。ただ、あの汚らわしいogreどもには目を光らせておけ。噂では、沼地のどこかにHordeの基地があるらしい。潜入部隊が見つけ出そうと手を尽くしているが、なかなか進まず、ほとんど成果が上がっていない。", 0xbe525a75, 0x5678b4f5, 0xab7441b9, nil, 0x6713d66f, "...m." },
  [1267] = { "消えた外交官", "Dustwallow SwampのJaina Proudmoreと話して下さい。", nil, nil, "まず私から、あなたがしてくれたすべてのことに感謝させてください、{name}。あなたは我が民とStormwindの民にとって、計り知れない恵みとなってくれました。もっと良い状況でお知り合いになれなかったのが残念です。\n\nまた、あなたの尽力に表立って感謝することはできないことも理解してください。ですが改めて言います、心から感謝しています。\n\nこの先Theramoreを訪れることがあれば、私を訪ねてください。状況をお知らせできるよう努めます。\n\n改めてありがとう、{name}。", 0xbe525a75, 0x956fa3cc, nil, nil, 0xc294090a, "..mm." },
  [1268] = { "怪しい蹄の跡", "Shady Rest Innの怪しい足跡について、Brackenwall VillageのKrogに報告して下さい。", "まだくすぶっているShady Rest Innの骨組みから、ひづめの跡の列が延びている。はっきり見える跡が少なくともいくつかあり、沼地の柔らかい泥には、ほとんど見分けられないほどの跡の列がさらに続いている。", nil, "蹄の跡か……quilboarの仕業かもしれんな。あるいはcentaurかもしれん。Barrensでの奴らの勢力は小さくない。あのような真似をしてもおかしくはないだろう。\n\n話したか？宿屋が焼け落ちただけではないのだ……主人の女房と子供も殺された。ひどい話だ。\n\nいずれにせよ、Kagoroに足跡の行き先を探らせよう。", 0x5f364f94, 0x942687dd, 0xbff654c6, nil, 0x4d9c0cd1, "...m." },
  [1269] = { "Lieutenant Paval Reethe", "Reethe's BadgeをBrackenwall VillageのKrogのところへ持って行って下さい。", "瓦礫の下で地面に光るものがあなたの目を引く。物体にこびりついた破片や灰を払いのけると、白地に金の錨の記章が、表面にエナメルで描かれているのが現れる。Theramoreの紋章だ。\n\n錨の下には「Lieutenant Paval Reethe」という名前が浮き彫りにされている。", "Shady Rest Innで何が起きたのか、手がかりは見つかったか？", "この人間、Paval Reetheのことは知っている。人間の中でも情けない奴だ。仲間の兵士たちを見捨てて脱走し、今は森に隠れている。\n\nOgronに奴を追わせた。ほかの者たちの中には、奴が我々の物資を盗んでいると疑う者もいる。Ogronが南東へ向かうのを見た気がする。", 0xf970a6d2, 0x0f663e91, 0x7e146834, 0xf7245a62, 0xcd44cbef, "....." },
  [1270] = { "Stinky の逃走", "\"Stinky\" Ignatz を護衛し、Ratchet の Mebok Mizzyrix と話す。", "よかった、やっと私を食べようとしないのが来た！！\n\nこのあたりの生き物をどうにかするのに手を貸してほしいんだけど、あんたならぴったりだよ、相棒。\n\nRatchetのMebok Mizzyrixってゴブリンが、薬か何かにbogbeanの葉を欲しがってるんだ……正直、理由なんてどうでもいい――金払いはいいし、この沼には詳しいから、こうしてここにいるってわけ。\n\nでも、bogbeanを見つける前に囲まれちゃってさ、ついてないよ！ここから出るのを手伝って、Mebokの植物を探す間、背中を守ってくれない？", nil, "Stinkyが頼んでおいた薬草を持って来てね、あなたに窮地を救ってもらったって話してくれたよ。よくやった！Stinkyの友は私の友だ！\n\nあなたに会ったらこれを渡してくれって頼まれたんだ。そのすぐ後、あいつは南の沼地の方へ歩いて帰っていったよ。", 0xa7772055, 0x739949f0, 0x056d03ac, nil, 0xb97b301a, "...m.", nil, nil, 0x51b0d53e, nil, nil },
  [1271] = { "Blue Recluse でのもてなし", nil, nil, nil, "甥から聞いたよ、Dustwallowでの研究を手伝ってくれた上に、あいつの仲間を窮地から救ってくれたそうだね。我々Sterns一家は結束が固いし、友人をないがしろにはしないんだ！\n\nさあ手を洗っておいで、{name}。これから君のためにパーティーを開くからね！", 0x68de3fd4, nil, nil, nil, 0x54293c24, ".mmm." },
  [1273] = { "Reetheの尋問", "Ogronと一緒にReetheと話しに行き、Brackenwall VillageのKrogのところへ戻って下さい。", "長い時間かかった。でもReethe見つけた。人間にしては、うまく隠れてた。\n\nOgron心配。沼に長くいて、あいつ狂ってるかも。お前、オレと来い。あいつから答え聞き出しに行く。", "Reetheは見つかったか？", "ふん。Reetheがもう沼地をうろつかなくなったのは良いことだが、人間というのはあまりにも脆くできていて、ちょっとした矢傷からも回復できなかったとは残念だ。\n\nこの謎の糸口はどこにも行き着かなかったようだ。別のところを探らねばならん。", 0xe8973a7f, 0x8def88e1, 0x14fc9704, 0x085e8d22, 0x468b3eb6, "....." },
  [1274] = { "消えた外交官", "Stormwind KeepでBishop DeLaveyを見つけて下さい。", "失礼いたします、そちらのお方。Bishop DeLaveyから、微妙な問題で手助けしてくれそうな冒険者に声をかけるよう頼まれております。\n\nご都合のつき次第、そっとStormwind Keepへ赴き、彼とお話しいただければ、きっとお力添えに感謝なさることでしょう。重ねて申し上げますが、どうか内密に。それなりに重要な問題なのです。", nil, "こんにちは、{name}。私はBishop DeLaveyです。\n\nこの砦での私の務めについて尋ねているということは、きっと若きThomasがうまくあなたを我が王国の手助けに引き入れたのでしょう。彼は昔から私の頼みをこなすのが上手でしたから。\n\nあいにく詳しく説明している時間がないので、率直に言わせてください……そしてどうか、このことが知れ渡らないようにしてください。", 0xbe525a75, 0xad07fc69, 0xb4ae9854, nil, 0x1740d560, "...m.", nil, nil, 0xdcbfc145, nil, nil },
  [1275] = { "汚染調査", "AuberdineのGershala NightwhisperはCorrupt Brain stem 8個を求めています。", "愚かなblood elvesどもが悪魔の魔法に手を染めている。nagaやKalimdorのsatyrsに何が起きたのか、奴らは見てこなかったのか?\n\nblood elvesも同じような変わり果てた姿になるのではないかと、私は恐れている。Azerothに、また一つおぞましい怪物の種族を生み出す余裕などないのだ。\n\nsatyrとnagaの脳幹を研究し、エルフたちがどんな運命へ向かっているのかを導き出したい。Ashenvaleの沿岸にあるBlackfathom Deepsへ行けば、satyrもnagaも見つかるだろう。\n\n長い旅になるぞ、{name}。", "研究に十分なサンプルが揃えば、私の本当の仕事が始められます。Blackfathom Deepsのsatyrとnaga、両方の腐敗した脳幹があれば、その変異の間に相関関係を見出せるかもしれません。\n\nそこで得た知識があれば、blood elvesがこれ以上の奇形と悪へと堕ちていくのを防げるかもしれません。", "あなたは遠くまで旅をし、間違いなく大きな危険に立ち向かってきたのでしょう。\n\nあなたの行いは無私のものでした。私の研究を助けてくれるのは、Azeroth全体のためになることです。あなたがしてくれたすべてに感謝します、{name}。\n\nでは失礼、私にはやるべき仕事が山ほどありますので……", 0x80a39979, 0x1c3b6c70, 0x7deb66bd, 0x0e194d4e, 0x90492795, "....." },
  [1276] = { "黒い盾", "Blackened Iron ShieldをThunder BluffのMosarnに見せて下さい。", "ああ、思い出した！ MosarnはThunder Bluffで評判の高い鍛冶屋だ。どこかで名前を聞いたことがあると思っていた。\n\n感謝の印として、Earthen RingはMosarnが作った鎧一式を私に授けてくれた。実に良い出来だ。\n\n彼なら、自分が作った盾についてもっと教えてくれるかもしれない。\n\n大した手がかりではないが、Reetheから役に立つことを何も聞き出せなかった以上、頼れるのはこれだけだ。", "やあ、{class}。何か手伝えることはあるか？", "ええ、確かにその通りだ。これは私が作った盾だ。\n\nだが、それ以上話せることはあまりないんだ、{name}。いろいろな盾や鎧を山ほど作っているから、全部は覚えていられない。", 0xd8f479b5, 0x2b923ccb, 0x3480d362, 0x2ab9d79b, 0xd1a8e8de, "....." },
  [1282] = { "人呼んでSmiling Jim", "TheramoreのCaptain Garran Vimesと話して下さい。", "Jimの奴を気の毒に思わずにはいられないんだ。昔からああだったわけじゃない。しばらく沼地で宿屋をやってた。素晴らしい場所だったよ。\n\nなあ、その話はあまりしたくないんだ。どうしても知りたいなら、Captain Vimesに聞いてくれ。", nil, "本名はJames Hyalだ。Barrensの外れに宿屋を開いた。旅人が立ち寄れる良い場所を作りたかったんだ……\n\n夢が大きすぎたのかもしれないが、宿はしばらく繁盛していた。だがその後、我々は湿地の街道を掌握できなくなり、ogreどもに乗っ取られた。\n\nJamesは頑固で、我々の城壁の内側での安全のために夢を諦めようとはせず、Shady Rest Innは焼け落ちてしまった。調査はしているが、あまり成果はない。手伝ってくれるなら、瓦礫の中で何か見つからないか探してみてくれ。", 0x384dd290, 0x3c994baa, 0x82498178, nil, 0xd9d4e55f, "...m." },
  [1284] = { "怪しい蹄の跡", "Shady Rest Innの怪しい足跡について、TheramoreのCaptain Garran Vimesに報告して下さい。", "まだくすぶっているShady Rest Innの骨組みから、ひづめの跡の列が延びている。はっきり見える跡が少なくともいくつかあり、沼地の柔らかい泥には、ほとんど見分けられないほどの跡の列がさらに続いている。", nil, "蹄の跡だと？確かにDustwallow Marsh近くの土地では、centaurの動きが異常なほど活発だ。Barrensへ短い遠征をした際にも、あちこちに奴らの野営地や拠点が点在しているのを見つけた。\n\n追跡者の一人、Falgran Hastilを送って、足跡の行き先を探らせよう。", 0x5f364f94, 0x2dcbca6f, 0xbff654c6, nil, 0xa2feeb9c, "...m." },
  [1285] = { "Daelinの部下", "Reetheについての情報をTheramoreのCaptain Garran Vimesのところへ持ち帰って下さい。", "Reddon……Redpath……ああ、あった！ Lieutenant Paval Reethe。\n\nLady Proudmooreと共に海を渡ってきた新兵の大半と一緒に、Theramoreの衛兵隊に加わった。十六歳でKul Tirasの海兵隊に入隊。顕著な功績、昇進……\n\n行方不明として記載。", nil, "行方不明？それはTesoranなりの優しい言い方で、裏切り者ということだ。\n\n間違いなく、Admiral Daelinに盲目的に忠誠を誓うあまり裏切り者になった愚か者の一人だろう。なんとも痛快な皮肉じゃないか？脱走者どもが、我々がAllianceを裏切ったと非難しているのだから。", 0x746d0032, 0x75439ef7, 0xe4a2f9e1, nil, 0x354a9ec5, "...m." },
  [1286] = { "脱走兵", "Dustwallow MarshでBalos Jackenと脱走兵たちからReetheについての情報を手に入れて下さい。", "沼地で拠点を維持するのは苦労の連続だったが、我々の強い決意によって、この地域一帯にいくつもの防衛用の監視塔を維持することができている。\n\n私が受け取った最新の情報と偵察報告によると、脱走兵の一団が、宿屋の南東、Lost Pointにある我々の放棄した塔に居座っているらしい。\n\n脱走兵たちのリーダーはJackenという男だ。何か情報を聞き出せないか試してみてくれ。\n\n気をつけろ、{name}。手ごわい相手かもしれない。", nil, "Vimesに言われて来たのか？汚れ仕事を自分ではできなかったというわけか……", 0xbe79be90, 0xd00374f2, 0xe232deab, nil, 0xdd5a3926, "...m." },
  [1287] = { "脱走兵", "TheramoreのCaptain Garran VimesとReetheについて話して下さい。", "Reethe？ あの臆病者か？\n\nBrackenwall Villageのogresの物資を襲うと言って聞かなかったから、キャンプから追い出したんだ。俺たちはあの脳みそのない獣どもに立ち向かえるほどの数はいない。\n\nあいつは何度も一線を越えすぎた。だから放っておいて、自分で何とかさせたんだ。\n\nさあ、あんたを助けてやったんだ……だから、あんたも俺たちを助けて、ここで俺たちに出くわしたことは忘れてくれないか？", nil, "Lieutenant CaldwellをLost Pointの脱走者どもの始末に向かわせよう。加えて、Reetheを見つけるよう命じておく。湿地はそれほど広くも道なき場所でもない、彼が見つけられないはずはない。", 0xbe79be90, 0x6242ea9c, 0x2dd080ff, nil, 0xa854f41c, "...m." },
  [1288] = { "Vimes's Report", "Vimes's ReportをTheramoreのLady Jaina Proudmooreのところへ持って行って下さい。", "よくやってくれた、{name}。素人の中では今まで見た中で一番だ。\n\nLady Proudmooreから、この微妙な状況について逐一報告するよう頼まれているのだが、しばらく話せていない。\n\n後で報告書を届けるつもりだったが、君がその件を彼女に話すほうがふさわしいだろう。私より君のほうが、彼女の質問にうまく答えられるはずだ。", nil, nil, 0x65423931, 0x1638d8cd, 0x1f002d1d, nil, nil, "...mm" },
  [1289] = { "Vimes's Report", "TheramoreのCaptain Garran Vimesのところへ戻って下さい。", "さて、Captain Vimesの報告書からすると、あなたは彼の調査に大いに貢献してくれたようですね。そのことに感謝します。\n\nこれほど有能な人の手に委ねられていると知って、少し気が楽になりました。よろしければ、Captain Vimesのもとへ戻り、この謎の真相を突き止める手助けをしてあげてください。", nil, nil, 0x65423931, 0x2b73ae61, 0x188bd0a0, nil, nil, "...mm" },
  [1301] = { "James Hyal", "Menethil HarborのVincent Hyalと話して下さい。", "Blue Recluseで働く前、私は今までに会った中でも最高の料理人で宿屋の主人でもある人に鍛えられた。その人の名前はJames Hyal。私が持っているものも、人生で辿り着いた場所も、すべて彼のおかげだ。\n\n彼はどうしているだろう。彼は兄弟のVincentと一緒にMenethil Harborの酒場で働きに行ったんだが、最近は便りがないんだ。\n\nもしそちらの方へ行くことがあったら、私からよろしく伝えてもらえないかな？", nil, "James？ああ、彼ならだいぶ前に出ていったよ。\n\n愛国心が再び燃え上がったんだろうね。そうなるのも無理はない。Lordaeronがあれほど狂気に満ちていたから、Jaina Proudmooreが海を渡ったとき、多くの人が彼女についていったんだ。", 0x44b76fdd, 0xc1cf5639, 0x894d2527, nil, 0xb47d985d, "...m." },
  [1302] = { "James Hyal", "TheramoreのClerk Lendryと話して下さい。", "兄弟のJamesはLady Proudmooreと一緒に海を渡った。最後に聞いた話じゃ、向こうの戦いは落ち着いて、Jamesは大陸のどこかで宿屋を始めるところだった。どこにいようと、きっと商売繁盛してるさ。実に腕のいい料理人だったからな。\n\nしばらく便りがないんだ――宿屋が忙しすぎるんだろうよ――だが、Theramoreの書記なら居場所を教えてくれるかもしれないな。", nil, "James Hyal、James Hyal……どうしてその名前にこんなに聞き覚えがあるんだろう？\n\nそうだ！Shady Rest Innの事件だ。あそこで何が起きたのか情報があるなら、Captain Vimesに話してみるといい。彼が調査を担当している。", 0x44b76fdd, 0x1cc2fc0c, 0x228dd9c4, nil, 0x331f172f, "...m." },
  [1318] = { "Gordokとの未完の用件", "Gauntlet of Gordok Mightを見つけ、Dire MaulのCaptain Kromcrushのところへ持ち帰って下さい。\n\nKromcrushによれば、「昔々の話」では、王子を名乗る「気味の悪い」エルフ、TortheldrinがGordokの王の一人からそれを盗んだという。", "今はお前が王。だから、自分を王子って呼ぶ気味悪いエルフから、大事なGordokの宝を取り戻せるかも!お前の前の王は失敗した。気味悪いエルフのTortheldrinが昔のGordokの王から盗んでから、ほかの王たちもみんな失敗した!\n\n宝の名前はGauntlet of Gordok Might。昔話では、Gordokのただ一人の真の王だけが取り戻せるって言う。昔話では、気味悪いエルフはまだこのあたりにいるとも言う――お前が見つけたら、ずっとはめていられる強い篭手になる!ヤー、見せてやる!", nil, nil, 0xd84c3631, 0xbc347604, 0x302edb3f, nil, nil, "...mm" },
  [1319] = { "黒い盾", "Blackened Iron ShieldをTheramoreのCaz Twosprocketに見せて下さい。", "あまり力になれなくてすまない、{name}。だが、力になれる者を紹介しよう。うちの最高の鍛冶屋の一人、Caz Twosprocketが鍛冶場で炉を預かっている。\n\n盾を彼のところへ持って行って、何が分かるか聞いてみてくれ。", "何か見てほしいものがあるのか？", "ふむ……面白い鉄を持っているな。こちら側の海で私が知っている鍛冶屋の誰が作ったものでもないし、私の作品でないのも確かだ。", 0xd8f479b5, 0x212f7a6c, 0x2b6194b9, 0xc4679a79, 0x2c714d88, "....." },
  [1320] = { "黒い盾", "TheramoreのCaptain Garran Vimesと話して下さい。", "ああ、危うく見落とすところだった……裏の革紐は焼け落ちてしまったようだけど、大柄な者に合うように作られていたみたいだ。実のところ、トーレンだと思うね。\n\n分かるのはそのくらいだ。Captain Vimesに、もっと力になれなくてすまないと伝えてくれ。", nil, "手がかりとしては乏しいが、覚えておく必要があるな。この謎のほかの部分がうまくつながって、何が起きたのかもっと役に立つ全体像が見えてくるといいのだが。", 0xd8f479b5, 0x3c994baa, 0x68e746d7, nil, 0x95dae4a3, "...m." },
  [1321] = { "黒い盾", "Blackened Iron ShieldをBrackenwall VillageのDo'golに見せて下さい。", "ふむ……この盾には特に変わったところは見当たらないな。鍛冶屋のDo'golに見てもらって、何か分かるか確かめるべきだが、あまり期待はしないほうがいい……", "私に何か持ってきたのか、{class}？", "これ、いい盾。とても頑丈、重い、いい。でもDo'golはいらない。オレは盾を作る。買わない、{name}。\n\nそれくらい知ってるはず。", 0xd8f479b5, 0xd7744d0a, 0xce30d6ac, 0x78c26d65, 0x94630cc4, "....." },
  [1322] = { "黒い盾", "Brackenwall VillageのDo'golのために、Acidic Venom Sacsを$N1個手に入れて下さい。", "ふーむ、盾の縁のここに文字が書いてある。だが焦げたもののせいで読みにくい。\n\nきれいにするには酸がいる。沼地のDarkfangの蜘蛛の毒ならちょうどいい。奴らの毒袋を取ってこい。そうすれば、これをきれいにできる。", "蜘蛛からsacsを取ってきたかい？", "座って潰せないくらいでっかい蜘蛛は嫌いだ。\n\n取ってきてくれてありがとう、{name}。さて、こいつらを引き裂いて盾に注ぐとするか……", 0xd8f479b5, 0x79026b82, 0x28766611, 0x1eed4701, 0x7d2c3c18, "....." },
  [1323] = { "黒い盾", "Brackenwall VillageのKrogと話して下さい。", "おっと、盾に酸を垂らしすぎたかもしれない。ちょっとこすってみるか……\n\nふむ、読みにくいが、Mosarnという名前のようだ。聞いたことがない。Krogなら知ってるかもしれない。Krogは顔が広いからな。", nil, "Mosarn？聞き覚えがあるような……どうも思い出せない。あとで思い出すかもしれない。\n\nたぶん大したことじゃないだろう。盾なんてどこから来てもおかしくないし、何の意味もないかもしれない……", 0xd8f479b5, 0x24478181, 0x03bc3300, nil, 0x1fc78c73, "...m." },
  [1324] = { "消えた外交官", "Dustwallow MarshでPrivate Hendelを打ち負かす。", "何だと？！ 俺がDefiasと手を組んでると言いがかりをつけに来て、侮辱されても俺が黙って突っ立ってると思ってるのか？！ どうやらお前は、とっくの昔にこうなるべきだったようだな。", "また会ったな、{name}。手を貸したことは気にしないでくれ。Hendelに逃げられるわけにも、ましてや死なれるわけにもいかなかったのでな。", "確かに、我々は皆、今の事態にひどく動揺している。だが、尋問のために彼をTheramoreへ連れて帰らせてくれ。王を見つけ出す件も対処しよう。\n\n我が主君Proudmoreも、君の助力に礼を言いたいはずだ。時間があるときに彼女と話してくれ。", 0xbe525a75, 0xa55f3f2b, 0x75615882, 0x7d3659b6, 0x64e6efe8, "....." },
  [1338] = { "Stormpikeのオーダー", "StormwindでStormpike's RequestをFuren Longbeardに持って来てください。", "心から敬服しているドワーフの防具鍛冶がいる。名はFuren Longbeardといって、その腕は並ぶ者がない。新しい盾が要るんだが、どうしても奴の盾が欲しいんだ！\n\n問題は……Furenがはるか南、Stormwindのドワーフ地区にいることだ。人間の土地だぞ！Ironforgeからあんなに離れた所に、なぜ住んでいるのか見当もつかん。人間どもが大金を積んで引き留めているに違いない！\n\nというわけで、旅をして金を稼ぐのが嫌でなければ、Furenに盾の依頼を届けてくれんか？", "ドワーフの地からの手紙？はるか北からいったい誰が呼んでいるのだろう……\n\nどうか、その命令書を見せてくれ。", "おお、Stormpikes一族からの依頼か。誇り高い一族で、立派なドワーフばかりだ。金持ちでもある。\n\nありがとう、{name}。今日中にMountaineer Stormpikeの盾に取りかかるとしよう。", 0xecf988f4, 0x130880f5, 0x24e88b1f, 0xd07031a3, 0xae03cdbb, "....." },
  [1339] = { "Mountaineer Stormpikeの任務", "Mountaineer Stormpikeと話す。", "Mountaineer Stormpikeが伝令を探しているそうだ。彼のためにちょっとした旅をしてくれる者をな。どうだ？ お前がその役にぴったりの{race}か？\n\nそうなら、Stormpikeは北の見張り塔のてっぺんにいる。", nil, "その通り。見張りをしている間はできない仕事があるんだ。実際、Loch Modanから遠く離れた所まで行ってもらうことになる。\n\n冒険にはうってつけの機会だぞ！", 0x7fce6abd, 0x1e66698f, 0xb2c24d7c, nil, 0x86e71667, "...m." },
  [1358] = { "Helbrimへのサンプル", "BarrensにいるApothecary HelbrimにWolf Heart Sampleを届けてください。", "Kalimdorにいる同僚、Apothecary HelbrimはKalimdorの猛獣にLordaeronの毒がどんな効果をもたらすか調査しているわ。彼はRenferrelが送ってきたこの狼の心臓の標本にとても興味を持つでしょう。\n\nHelbrimはBarrensのCrossroadsという村にいるわ。彼のもとへ行くには、Zeppelinに乗ってオークの首都、Orgrimmarまで行くの。それからDurotarを道なりに南へ下っていき、西へ行くとBarrens。さらに行けばじきにCrossroadsへ着くわ。", "私宛ての荷物があるのか？", "おお、よしよし。もし最初の報告のとおりなら、この心臓の毒性は我らの毒の知識を更なる進歩に導くぞ。\n\n届けてくれてありがとう、{name}。謝礼ははずむぞ。", 0x1774ad9a, 0x34098eea, 0x43d57adf, 0x3bd8c94e, 0x48a9688d, "....." },
  [1359] = { "Zingeへの届け物", "UndercityのApothecary ZingeにWolf Heart Sampleを届けてください。", "君が持ってきた狼の心臓は見たことのない特質を持っている。それには狼の命にもかかわるであろう毒性が含まれているのだ！\n\nにわかには信じがたいことであるが、さらに調べなければならん。心臓の標本を少しとっておいた。これを私の同僚、Apothecary Zingeに届けてほしい。彼女はUndercityの我らの本部にいるだろう。", "何か私に渡すものがあるのか？", "ああ、どうも。それがRenferrelの言ってた心臓の標本ね。早く実験したいわね・・・。新しい毒を見つけるのはRoyal Apothecary Societyにとって重要なことだからね。", 0xc147e9c6, 0x64dad9f3, 0x8fc4a7ce, 0xa03be4c2, 0xb2b3ed16, "....." },
  [1360] = { "取り戻された宝物", "UldamanのNorth Common Hallにある収納箱からKrom Stoutarm秘蔵の宝を手に入れ、IronforgeにいるKrom Stoutarmに渡して下さい。", "BadlandsのUldaman発掘現場で、俺は掘り手として結構な仕事にありついてたんだ……あのいまいましいtroggsが現れるまではな。命からがら逃げ出したが、ほかには何も持ち出せなかった。どさくさで、一番大事な持ち物を置いてきちまったんだ。箱の中だからtroggsからは無事だろうが、奴らのど真ん中にあるんだよ。\n\nそいつを取ってきてくれたら、名誉にかけても、金の面でも恩に着るぜ!俺の名前が書いてある箱が、North Common Hallの突き当たりにある。開けてもらいたいのはそいつだ。", "さてと、あのtroggsどもを十分に叩きのめして、俺の箱を開けてお宝をかっさらってこられたか？", "ああ、これでまた満ち足りた気分だ――心から礼を言う。\n\n金属の輝きを宝とするドワーフもいれば、宝石のきらめきを宝とする者もいる……だが、大事なジョッキを手にしていないStoutarmなど、Stoutarmとは呼べんよ!", 0x029286ee, 0xee1fb633, 0x7cf7eb5d, 0x47f6cd8c, 0xacfc9710, "....." },
  [1361] = { "Regthar Deathgate", "Regthar Deathgateと話して下さい。", "Hordeのウォリアー、Regthar Deathgateが、Desolaceの地への任務に就く者を募っている。志願するなら彼と話せ。彼はBarrensの、Crossroadsの西にある一連の掩蔽壕に駐屯している。\n\nそれと、武器を研いでおけ。Desolaceは戦に引き裂かれた地だ。", nil, "そうだ、兵を募っている。この任務はDesolaceへ向かい、そこのcentaurと戦うものだ。すぐに始められるよう、手短に話そう。", 0x1e8becbf, 0x8136176a, 0xc8170079, nil, 0x79798034, "...m." },
  [1362] = { "DesolaceのKolkar", "DesolaceのGhost Walker PostにいるFelgur Twocutsと話して下さい。", "KolkarのcentaurはDesolaceに住んでおり、その軍勢はBarrensにまで広がっている。これは周知の事実で、ここではHordeの者たちが奴らに対処している。\n\nだが、Desolaceでcentaurが強大である限り、奴らは常に脅威となる。その脅威を取り除くときが来たのだ。\n\nDesolaceのGhost Walker PostにいるFelgur Twocutsと話せ。彼はcentaurについての情報を集めるために送られた。DesolaceのKolkarにどう対処するのが一番か、彼なら分かっているはずだ。", nil, "Regtharの命令で来たのか？ならばcentaurの相手をしに来たわけだな。よし。\n\n休息は取れているといいが。centaurとの戦いがどう決着するかは分からんが、長い戦いになることは分かっている。\n\n座って、聞いてくれ。", 0x5e8309c9, 0xf2537bcd, 0x14f8e488, nil, 0x4f7ee468, "...m." },
  [1363] = { "Mazenの命", "StormwindのAcolyte Dellisと話して下さい。", "ここ、Academy of Arcane Arts and Sciencesの書庫の管理人として、すべての魔法の書物や巻物を常に把握しておくのが私の責任だ。これらの魔法の書が悪しき者の手に渡れば、どんな愚行が繰り広げられるか分かったものではない。\n\nそれで思い出した……私の助手のDellisが、先週ひどい失敗をしでかしたのだ。彼は書庫では有能なのだが、Stormwindの門を出るとからきし駄目でね。英雄となって、Dellisの奴を助けてやってくれないか？", nil, "私のせいじゃない。本当に私のせいじゃないんだ。", 0x9b7f1af7, 0xa52657ac, 0xc73b33de, nil, 0x4198d05d, "...m." },
  [1364] = { "Mazenの命", "Khadgar's Essays on Dimensional Convergenceを回収し、Nethergarde KeepのWatcher Mahar Baに届けて下さい。", "Master Mazenの指示はとても明確でした。Nethergarde KeepのWatcher Mahar Baへ、とても重要な小論文を届けること。\n\nでも、私はそれまでBlasted Landsに行ったことがなかったんです！ 道中は恐ろしいものでした！\n\nSwamp of Sorrowsに着いたとき、道を間違えて、植物のような恐ろしい沼の生き物たちに囲まれてしまいました。襲いかかってくるようによろめいてきたので、私は逃げ出しました。でも慌てていたせいで、小論文を落としてしまったんです。きっとあの獣の一匹が持って行ったに違いありません。\n\nどうか取り戻して、Mahar Baに届けてもらえませんか？", "{race}よ、Nethergarde Keepに何の用だ？", "ああ、実に素晴らしい！\n\nKhadgar's Essays on Dimensional Convergenceを求めた私の依頼が、Academy of Arcane Arts and SciencesのMaster Mazenに見過ごされてしまったのではないかと、しばらく心配していたのです。\n\nこれだけ奇妙な出来事が続いているのですから、きっと依頼が山積みなのでしょう。\n\nさて、失礼して、すぐに研究を始めなければ。Khadgarほどの偉大な人物の洞察にようやく触れられると思うと、興奮が止まりません。", 0x9b7f1af7, 0x92af49f7, 0xcc4a9ccb, 0x650cdeab, 0x6fe2a3a5, "....." },
  [1365] = { "Khan Dez'hepah", "Khan Dez'hepah's HeadをDesolaceのFelgur Twocutsのところへ持って行って下さい。", "DesolaceのcentaurはKolkarだけではない。多くの氏族がこの乾いた平原をさまよい、互いに戦っては死んでいる。奴らが仲間同士で戦うのは好都合だ。奴らは強く、残忍だからな。centaurが団結して我々に立ち向かえば、手強い敵になるだろう。\n\n奴らが団結する前に対処せねばならない。\n\n最初の任務は、Kolkar氏族をかき乱すことだ。その首領、Khan Dez'hepahを殺してそれを成し遂げろ。\n\nKolkar Villageはここから北東にある。行け、幸運が共にあらんことを。", "{name}、Khan Dez'hepahを倒したか？", "よくやった。Kolkarに対するこの迅速な一撃は、力を示す効果的な手段だ。そして力こそ、centaurが最もよく理解するものだ。\n\nKolkarの長が死んだことで、あの氏族が混乱するだけでなく、ほかの氏族もためらうだろう。", 0x139e3513, 0xf3978a4d, 0x673b6255, 0x67ac3b0b, 0x39033be5, "....." },
  [1366] = { "Centaurの懸賞金", "Centaur Earsを$N1個、DesolaceのFelgur Twocutsのところへ持って行って下さい。", "centaurの氏族どもを怯えさせた今こそ、奴らの血を流させるときだ。Desolaceを旅する間は、centaurを狩れ。どの氏族を狩ろうと構わん。とにかく耳を集めろ。山ほどの耳をな。\n\n奴らの数を減らせば、その決意も弱まり、勢力拡大の考えなど根こそぎにできる。\n\n良い狩りを、{name}。", "earsの集まり具合はどうだ、{name}？たっぷりか？", "今頃centaurどもは君の名を知っているはずだ。きっと知っていて、敬い、恐れている。そして君を知っているのと同じように、君がどの旗の下で戦っているかも知っている。\n\nHordeの旗だ。", 0x06d4a2f6, 0x6b3a6445, 0xd6d135b3, 0x09d0e393, 0x2ce2ecef, "....." },
  [1367] = { "Magramとの同盟", "Magramとの評判をFriendlyまで上げ、Warugと話して下さい。", "centaurを打ち負かすには、奴らの憎しみを逆手に取らねばならない。氏族の一つと手を組み、奴らを通じて全氏族を倒す方法を学ぶのだ。\n\nMagramと手を組むことを選ぶなら、その敵であるGelkisを倒せ。そうすればMagramの間で敬意を得られる。十分に得たら、Desolace南東のMagram Village外れで、Magramの代弁者Warugと会え。", "去れ！Magramは弱い者とは話さない。弱い者は殺す！\n\n俺と話したいなら、強いと示せ。Gelkisをたくさん殺してから戻ってこい。", "Gelkisはお前の名を聞くと泣く、{name}。奴らはお前を恐れ、憎んでいる。Magramを憎むのと同じように、お前を憎んでいる！\n\nお前はMagramのように強いのかもしれない。いずれ分かる……", 0x41d2c471, 0x7eb0b368, 0xe277347c, 0x09979302, 0xf890305d, "....." },
  [1368] = { "Gelkisとの同盟", "Gelkisとの評判をFriendlyまで上げ、Uthek the Wiseと話して下さい。", "centaurを打ち負かすには、奴らの憎しみを逆手に取らねばならない。氏族の一つと手を組み、奴らを通じて全氏族を倒す方法を学ぶのだ。\n\nGelkisと手を組むことを選ぶなら、奴らが最も憎む宿敵、Magramを倒せ。Gelkisの敬意を得たら、Desolace南西のGelkis Village外れで、Gelkisのシャーマン、Uthek the Wiseと会え。", "お前の二本の足がGelkisの大地を踏んでいる。お前はここでは歓迎されない！\n\nGelkisと友になりたいと証明しろ。Magram centaurを殺せ。大地がMagramの血で濡れたら戻ってこい。", "大地が我に語りかける。お前が多くのMagramを殺したと。それは良いことだ。\n\nお前がGelkisの友ならば、聞け。お前に頼みたい仕事がまだある。", 0xbfb1f183, 0x51384a38, 0xfbde3377, 0xb291f366, 0x5423ea57, "....." },
  [1369] = { "Broken Tears", "Magramとの評判を保ったまま、Broken Tearsを$N1個、Magram VillageのWarugのところへ持って行って下さい。", "Gelkisは、我らcentaurの母Theradrasが我らを守っていると思っている。奴らは愚かだ。centaurを守る者などいない。Magramに守りなど要らない！ 我らが最強だ！\n\nGelkisに奴らが愚かだと思い知らせろ。奴らの村の洞窟へ行け。奴らはその洞窟に結晶を貯め込んでいる。Theradrasの涙だ。その涙を破壊し、砕けた欠片を持ってこい！", "我々の敵でないなら、俺の頼みを聞くはずだ！", "tearsを手に入れたな！これでGelkisは、Theradrasが奴らを助けないと思い知る。我らが奴らを踏み潰しても、彼女は泣かない！Magramが支配するのだ！\n\n我らに手を貸すとは賢いな、{name}。我らが最強だ。", 0xef98fac3, 0xf1669e0b, 0x67b6cf3a, 0x407b8c54, 0x72f06993, "....." },
  [1370] = { "物資の盗み出し", "Crudely Dried Meatを$N1袋、Gelkis VillageのUthek the Wiseのところへ持って行って下さい。", "戦のないとき、我らは肉を求めて狩りをする。肉は我らに力を与え、満ちた腹は空の腹より激しく戦う。\n\nMagramも同じだ。奴らは狩りの合間により長く戦えるよう、余分な肉を蓄えている。東にある奴らの村を襲い、蓄えた肉を奪えば、奴らの力は衰えるだろう。", "Gelkisにもっと価値を示してから戻ってこい！", "よし。遠く離れた村から、Magramどもの腹がぐうぐう鳴る音が聞こえるぞ！\n\nこの肉はGelkisに渡す。そして我らは何日も休まず戦う。\n\nお前のしたことはGelkisのためになる、{name}。", 0x73f9471d, 0x18931045, 0x2395d2b3, 0x8a2d6702, 0x83fe3f46, "....." },
  [1371] = { "Warugのための仕掛け", "Magramとの評判を保ったまま、Advanced Target DummyをDesolaceのMagram VillageにいるWarugのところへ持って行って下さい。", "ずっと昔、小さなノームがDesolaceにやって来た。馬と荷車を持っていて、荷車には変な物が積まれていた。面白い物。いろんな色に燃える物。生きていないのに動く物。オレは小さなノームを殺した。でもその前に……あいつはオレを笑わせた。\n\nあいつの荷車から一番気に入った物を取っておいた。木でできた人間で、オレが叩いて壊すまで、オレに手を振っていた。\n\n新しいのが欲しい。新しいのを持ってこい！", "我々の敵でないなら、俺の頼みを聞くはずだ！", "そう、これが私の持っていたものだ！また動くようにしてやる。これを見ると笑っちゃうんだ！", 0x4f769b60, 0x2f21bf99, 0x54814c85, 0x407b8c54, 0xb8ff3b0f, "....." },
  [1372] = { "本物以外の何者でもなく", "Beggar's HauntにいるApothecary Faustinと話して下さい。", "我らの遠征隊は、Varimathrasの命によりAzerothの南部を調査するため送り出された。\n\n偵察の最中、私はBeggar's Hauntを探っている人間のInfiltratorに気づいた。私が捕らえる前に、我らのオークの……同胞……の何人かがそいつを捕まえ、Swamp of Sorrowsにある奴らの砦、Stonardへ連れていった。\n\n我らのオークの同盟者たちを……助けて……やりたいのだ。奴らはここにある我らの野営地に気づかなかったが、それでも手を貸してやりたい。\n\nここにいるFaustinと協力して、Stonardにいる我らの友のために……自白剤を作ってくれ。", nil, "あなたが来る前、Zraedusがちょうどあの詮索好きな小者のInfiltratorについて話してくれたところだ。\n\nまったく厄介な話だ。Beggar's Hauntの周りを嗅ぎ回るお節介者など、最も要らぬものだからな。\n\nStonardのオークたちは、我らの友人が何を話すかを聞きたくてうずうずしているに違いない。彼らは我らの同盟者なのだから、コホン、その人間からできる限りの情報を引き出す手助けをしてやらねばな。\n\n私と組んでくれ、{name}。そうすればStonardへ自白剤を届けられる。\n\nHordeのために!\n\n……今の、合っていたかね?", 0xbc3bb2c0, 0x4d2ab9f0, 0x8a908581, nil, 0x3b954a9f, "...m." },
  [1373] = { "Ongeku", "Gelkisとの評判を保ったまま、Draenethyst ShardをDesolaceのGelkis VillageにいるUthek the Wiseのところへ持って行って下さい。", "そなたにはまだ証明すべきことがある。次の務めはそなたを遠くへ導くゆえ、今しばらくGelkisはそなた抜きでMagramと戦おう。\n\n大地は耳を傾ける者に多くの秘密を囁く。我が耳にする秘密の一つは、赤い結晶のことだ。それはdraenethystと呼ばれ、我らの大地にとって新しいものだ。山が空を飛び、悪魔が支配する場所から来たのだ。\n\ndraenethystの欠片を持ってくるがいい。それは我が魔法を強くしてくれよう！ その欠片はSwamp of Sorrowsと呼ばれる場所にあり、迷える者Ongekuが持っている。", "{name}、Gelkisの友であることを示せ。", "そうだ、これこそ大地がささやいていた欠片だ。強い魔力を感じる！この魔力をGelkisの敵に使ってやる。\n\nお前はまた一つ我らのために仕事をした、{name}。そのうち、お前を友と呼ぶかもしれない。", 0x369f906c, 0x75042547, 0x76e99d01, 0x16b10c28, 0xe31475d3, "....." },
  [1374] = { "Khan Jehn", "Khan Jehn's HeadをDesolaceのGelkis VillageにいるUthek the Wiseのところへ持って行って下さい。", "大地が語りかけてくる。Magramは弱っている、と。今こそ奴らのKhanを殺す時だ！\n\nMagramのKhan、Jehnの首を持ってこい！", "{name}、Gelkisの友であることを示せ。", "Khan Jehnは強かったが、愚かだった。自分の力が偉大だと思っていた。大地の魔法のほうが強いと分かっていなかった。長を失ったMagramのcentaurはこれから滅び、いつかGelkisが支配するのだ！", 0x67d27eda, 0xb931aa69, 0xb94a89cc, 0x16b10c28, 0xef98cf4e, "....." },
  [1375] = { "Khan Shaka", "Magramとの評判を保ったまま、Head of Khan ShakaをDesolaceのMagram VillageにいるWarugのところへ持って行って下さい。", "お前、Magramを助ける。だからお前、気に入った。さあ、GelkisのKhanを殺せ！ そいつはKhan Shakaだ。そいつの首が欲しい！ そいつの首をじっと眺めて、笑ってやりたい！", "Magramのために働け。そうすれば手を貸してやる。", "Khan Shakaが死んだ！奴の首を槍に刺して手元に置いておく。そうすればShakaにMagramの強さを見せつけられる！", 0xbf1765da, 0xce816957, 0xe53d1b02, 0x0dc2136d, 0x18c5bcaf, "....." },
  [1380] = { "Khan Hratha", "Gelkisとの評判を保ったまま、Maraudine Key FragmentをGelkis VillageのUthek the Wiseのところへ持って行って下さい。", "{name}、お前はMagramに力を貸してくれた。今度はMaraudineを倒すのを手伝え！ 奴らの氏族の長、Khan Hrathaを殺せ！\n\nそいつと対決するには、Maraudine War Hornを吹け。Valley of Spearsの高い崖の上にある。\n\nだが角笛を吹くには、角笛の吹き口を手に入れねばならん。吹き口は珍しく、信頼されたMaraudineのcentaurしか持っていない。\n\n角笛を吹けば、centaurどもがやってくる。Hrathaが現れるまで、そいつらを殺し続けろ。\n\nKhan Hrathaは……鍵のかけらを持っている。それを俺のところへ持ってこい……", "Khan Hrathaは死んだか？key fragmentは持っているか？", "奴は死んだ！Khan Hrathaは死んだ！これでMaraudineも滅びる！Gelkisがこの地を支配するとき、{name}、我らはお前を忘れない。そして大地の精霊たちが、永遠にお前の名を歌うだろう。", 0xa9d55f09, 0x9642f60f, 0x6c401142, 0x1502ec7f, 0x462f6777, "....." },
  [1381] = { "Khan Hratha", "Magramとの評判を保ったまま、Maraudine Key FragmentをDesolaceのMagram VillageにいるWarugのところへ持って行って下さい。", "Gelkis Khanは死んだ。次はMaraudineが倒れる番だ！ MaraudineのKhan、Hrathaを殺せ！\n\nそいつと対決するには、Valley of Spearsの高い崖の上にある角笛を吹け。だが角笛を吹くには吹き口がいる。吹き口を手に入れるには、Maraudineのcentaurを殺せ。吹き口が見つかるまで殺し続けろ。それから角笛を吹け。\n\nそうすればMaraudineのcentaurどもが塔にやってくる。Khan Hrathaが現れるまで、そいつらを殺せ。Hrathaは鍵のかけらを持っている。そのかけらを俺に渡せ……", "俺の頼みを果たせ。Magramの味方だと証明しろ！", "Khan Hrathaは死んだ！これでMagramがcentaurの中で最強だ！ほかの奴らを踏み潰し、Desolaceを支配してやる！\n\n我らはお前を忘れない、{name}。ほかの者が皆踏みにじられるときも、お前だけは我らの蹄から逃れられるだろう。", 0xa9d55f09, 0x8191fcdf, 0x7ba3ffdb, 0xadd5101a, 0xf5be96ca, "....." },
  [1382] = { "奇妙な同盟", "Gelkisとの評判をFriendlyまで上げ、Uthek the Wiseと話して下さい。", "centaurの氏族同士が争っているのは幸運なことだ。もし一つの軍勢にまとまったなら、奴らは止められなくなるだろう。そう、我々は幸運だ。この優位を押し広げるべきだ。\n\ncentaurの氏族の一つ、Gelkis氏族は、Magram氏族と激しい戦争をしている。我々がMagramを攻撃すれば、Gelkisと同盟を結べるかもしれん。\n\nDesolace南西部、Gelkisの野営地の外れにいるUthek the Wiseと話せ。彼女を通じて、Gelkisと同盟を結べるかもしれん。", "失せろ！Gelkisはお前をここに望まない。今すぐ去れ！！\n\nMagramをたくさん殺してから戻ってこい。そうしたら話してやる。", "お前の名はGelkisの間でささやかれている。お前の手には多くのMagramの血がついている。それは良いことだ。\n\n話をするのも良いことかもしれない。お前がGelkisのために何ができるか、そして我らがお前のために何ができるかを話そう。", 0xee376413, 0x51384a38, 0x26257222, 0x05c7cbde, 0x04b86867, "....." },
  [1383] = { "本物以外の何者でもなく", "Beggar's HauntのApothecary Faustinは、Shadow Panther Heart 5つ・Mire Lord Fungus・Deep Strider Tumorを求めています。", "ちょうどいい薬の心当たりがある。真実というものを、まさに扱われるべきやり方で扱ってくれる薬だ。\n\nこの調合には、Swampに棲むShadow Panther heartsがいくつか必要だ。それに、あそこに棲むMire Lordから魔力を帯びたキノコももらいたい。{name}、君ほど有能な者なら、きっと奴を説き伏せて少し分けてもらえるだろう。\n\nさて、厄介なのは、遠く離れたDesolaceでDeepstriderの腫瘍を見つけることだ。ごくまれに、あそこの巨人たちが病にかかり、腫瘍ができるのだ。\n\nさあ、行ってこい!", "StonardにいるあのInfiltratorも、私の特製の自白剤を飲めばきっと……口を割る……だろう。ハハ！\n\n必要な材料を手に入れるのは決して簡単ではない。Shadow PantherはSwampではよく見かけるが、目的を果たすのに十分なheartsを集めるのは骨が折れるだろう。それにMire Lordはなかなか気難しい獣だ。\n\nDeepstriderの腫瘍については、見つけるのが恐ろしく難しい。だが、それから引き出せる化学反応は他に比類がない。", "見事だ、{name}! しかも実にいい頃合いだ。Zraedusの話では、Infiltratorは傷から回復し、オークたちの尋問を受ける用意が整ったそうだ。\n\n少しだけ時間をくれ、毒――いや、自白剤を用意するのでな。", 0xbc3bb2c0, 0xb505a934, 0x5a646919, 0x68f0f3f1, 0x18219aec, "....." },
  [1384] = { "Kolkarへの襲撃", "Gelkisとの評判を保ったまま、Crude Charmsを$N1個、DesolaceのGelkis VillageにいるUthek the Wiseのところへ持って行って下さい。", "Kolkarのcentaurどもは、自分たちの魔法が強いと思っている。あいつら、魔法を知らない！ 魔法に噛みつかれたって、それが魔法だと分からない！\n\nお前が、あいつらの魔法は弱いと見せてやれ。北東のKolkarのところへ行って、あいつらを殺せ。あいつらのcharmsを奪え。charmsを持ってきたら、俺が火に投げ込んで笑ってやる！", "charmsを持ってきたか？Kolkarに奴らが弱いと思い知らせたか？", "お前はGelkisのために良いことをした。Kolkarは弱く、いずれ死ぬ。奴らの魔法は哀れで、奴らを救えはしない。お前がそれを見せつけた。恐怖で奴らはますます弱くなる！\n\nそして我らの地では、弱い者はすぐに死ぬ。", 0x0119bbcf, 0x5209f653, 0xa26a18c9, 0x0e2b206f, 0x817c7bc1, "....." },
  [1385] = { "非情な政治", "Magramとの評判をFriendlyまで上げ、Warugと話して下さい。", "Desolaceは戦の地だ。centaurどもは互いに戦をしている。そして奴らの中の勝者が溢れ出して、我々の拠点を脅かすだろうと我々は考えている。それを許すわけにはいかん\n\ncentaurを打ち負かす方法を知らねばならん。そのためには……氏族の一つと手を組まねばならんのだ。Magramのcentaurどもは、Gelkisと戦をしている。お前がGelkisと戦えば、Magramも同盟を考えるかもしれん。\n\nMagramたちの信頼を勝ち取ったら、Desolace南東部のMagramの村にいるWarugと話せ。", "今すぐ去れ、さもなくばMagramがお前を叩き潰す！我々の友になりたいなら、Gelkisを殺せ。", "多くのGelkisがお前に倒された。気に入った。お前なら、もっと気に入ることをしてくれるかもしれない。お前とMagramは友になれるかもしれない。", 0x172c2704, 0x7eb0b368, 0xeb8642ad, 0xeb771986, 0x3a57bd89, "....." },
  [1386] = { "Kolkarへの猛攻", "Magramとの評判を保つ。Kolkar Centaursを$N1体、Kolkar Scoutsを$N2体、Kolkar Maulersを$N3体倒し、DesolaceのMagram VillageにいるWarugのところへ戻って下さい。", "Kolkarは自分たちが強いと思ってる。でも俺たちはあいつらを笑う！ 笑って、殺す！ お前も殺せ。俺たちみたいにKolkarを殺せるって見せてみろ。北へ行って、あいつらを皆殺しにしろ！", "Kolkarが怖いのか？なぜ殺さない？殺し方を忘れたのか。奴らが死ぬ前に、急いでKolkarを殺せ！", "Kolkarどもは今やお前を恐れている！奴らを殺すとき、笑っていたならいいが。殺すときは笑うほうがいい。そうすれば敵は自分が弱いと分かる。", 0xbbc50e78, 0x294c764e, 0x89bc84c9, 0x37df1713, 0x749da75d, "....." },
  [1387] = { "Centaurの懸賞金", "Centaur Earsを$N1個、DesolaceのNijel's PointにいるCorporal Melkinsのところへ持って行って下さい。", "centaurという種族は多くの氏族から成っている。それぞれに長と思惑があるが、すべての氏族に共通していることが一つある。残虐さだ。\n\n我々が平和を手にするには、centaurを排除せねばならん。そこで、君にその任務を与える。\n\nDesolaceを巡りながらcentaurを狩り、earsを取ってこい。earsをたくさん、たくさん持ってくるのだ。\n\nAllianceのためにこれを成し遂げてくれ、{name}。そうすれば、我々は戦の終わりへ一歩近づくだろう。", "{name}、報告はあるか？", "ああ、earsか。よくやった。\n\nAllianceへの君の貢献は疑いようがない、{name}。君がDesolaceで流した血は、間違いなく数えきれない命を救うだろう。", 0x06d4a2f6, 0x1cee922a, 0x780fd268, 0xe6610dc1, 0xc3517793, "....." },
  [1388] = { "本物以外の何者でもなく", "Beggar's HauntにいるDeathstalker ZraedusにFaustin's Truth Serumを渡して下さい。", "すべては計画通りに進んでいる、{name}。この自白剤をDeathstalker Zraedusに渡してくれ。そうすれば、奴がこれの……正しい……飲ませ方を教えてくれるはずだ。\n\nハハハ!", "我らが親愛なる友、Apothecary Faustinの役に立ったのならよいが。", "老いぼれFaustinなら何かいいものを思いつくと思っていたぞ! お前の助けが絶大だったことは疑いない。\n\nさて、本題に入ろうか。", 0xbc3bb2c0, 0xe9d16511, 0x0f1fce69, 0x5e8d31de, 0xcf587ee1, "....." },
  [1389] = { "Draenethystの結晶", "Draenethystの結晶を$N1個、Swamp of SorrowsのThe HarborageにいるMagtoorのところへ持って行って下さい。", "Fallow Sanctuaryに住むlost onesは、我々と同じ姿をしていますが、怪物です……Azerothへの過酷な旅路で正気を失ってしまったのです。かつては我々の同胞でしたが、今は東のFallow Sanctuaryに住み、近くをさまよう者を誰であれ捕らえるか殺しています。\n\nそして彼らは、我々にとって神聖なもの――draenethystの結晶を盗んでいったのです。\n\n我々にはFallow Sanctuaryに踏み込み、彼らの小屋や焚き火の間から盗まれたdraenethystを取り戻すだけの力がありません。しかし、あの結晶がなければ……我々もまた道を見失ってしまうかもしれません。", "水晶は持っているか？", "ありがとう、{name}。我々は、君に恩がある。", 0xcad2adbf, 0x587c2825, 0x6821de7c, 0xe71a500d, 0x6fac1fcb, "....." },
  [1390] = { "Oops、また殺しちまった。", "テキストがありません", "テキストがありません", nil, "やってくれた仕事、ありがとう！", 0x571f5200, 0xfb6ac99d, 0xfb6ac99d, nil, 0x5d446519, "...m." },
  [1391] = { "本物以外の何者でもなく", "StonardにいるInfiltrator MarksenにZraedus's Brewを渡して下さい。", "ある程度は慎重に動く必要がある。何しろ、お前がのこのこ乗り込んでいって、あの愚か者にここにあるFaustinの調合薬を飲むよう説得するわけにもいかないだろう?\n\nだが、人間どもが一つだけ逆らえないものがあるとすれば、それは酒だ。Faustinの薬を受け取って、このエールに混ぜておこう。あの哀れな間抜けは、酒をがぶ飲みすることにためらいなど見せんと保証する。\n\n急いでSwamp of SorrowsのStonardへ向かえ、{name}。そして、我らのちょっとした任務は静かに内密に進めるんだぞ……", "どうか命だけはお助けを！私は陣営の垣根を越えた情報を持っているのです。Hordeに肩入れするつもりはありませんが、暴かれなければならない政治的な裏切りが進んでいるのです！", "酒をくれるのか? 親切だな。酒が飲めるようになって何日ぶりだろう。これを飲みきったら、俺の知ってることを教えてあげるよ……。", 0xbc3bb2c0, 0xe745ac9d, 0x8238c84b, 0x22c8c3a1, 0xd453fc1b, "....." },
  [1392] = { "Noboru the Cudgel", "Noboru's CudgelをSwamp of SorrowsのThe Harborageの指導者のところへ持って行って下さい。", "Noboruは何か月もの間HarborageのDraeneiを苦しめてきました。彼のcudgelは、Draeneiがlost onesの手で受けてきた残虐な仕打ちの象徴です。", "こんにちは。そして、Harborageへようこそ。", "恐るべきNoboruの武器を手に入れたのですか？では、彼は死んだのですね？\n\nHarborageにとって喜ばしい日です。Noboruとその一味は我々にとって恐怖でした。沼地をうろつき、行く手を横切ったDraeneiを誰彼構わず殺していたのです。彼は我々の存続を直接脅かす存在で、我々には彼に立ち向かう力がありませんでした。\n\nあなたという友を得られて、我々は幸運です、{name}。", 0x82434af7, 0x9ad7f0d0, 0xcf70779e, 0x6d6a1aa7, 0xb1d288e6, "....." },
  [1393] = { "Galen の脱出", "Galen を護衛し、Swamp of Sorrows で彼のキャンプを探して金庫を開ける。", "お願い、助けて！こいつらに食べられちゃう！\n\nここから出してくれたら、すごいお宝をあげるよ！Stonardの北の沼にある私の野営地にあるんだけど、私しか知らない仕掛けでしか開かない頑丈な箱に鍵がかけてあるんだ。\n\n逃げるのを手伝ってくれたら、そのやり方を教えてあげる。", "この金庫の鍵穴は黒い樹脂で埋められている。開けることはできない。", "この金庫の鍵穴は黒い樹脂で埋められている。開けることはできない。\n\nだがGalenは、箱の底に隠し留め金があると教えてくれた……\n\n……少し探すと留め金が見つかった。留め金を跳ね上げると、金庫が開いた……", 0xe34a3b56, 0x7fd40839, 0x675861c3, 0x923b8c0e, 0x6ae04157, "....." },
  [1394] = { "最後の道", "Thousand NeedlesのDorn Plainstalkerと話して下さい。", "お前はよくやったぞ、{name}。私の試しと、その前の試しに通ったのだ。Thousand NeedlesのDornの元へ戻るがいい。彼はお前の中の変化に気づくだろう。そして、努力に報いるべきだと信ずるに足るほど、お前の心・体・精神が強くなったことを理解するはずだ。\n\n試しを通じて示してきた調和に忠実であり続けよ、{name}。そうすれば、Dornはこの先もまたお前を試すことだろう。", nil, "ああ、{name}。最後に私の家へ来てから久しいな。進む道に配した第一歩を君が踏み出して以来、たくさんの月が空を横切っていったようだ。\n\nそして今、君はかつての君より強くなって戻ってきた……さらに見識を深めてな。とても嬉しいよ。私の試しを最後まで体験したのだから、君は正当に報いられるべきだ。", 0xddc17579, 0xfcbd234c, 0x6cdc6f6c, nil, 0x56c82398, "...m." },
  [1395] = { "Nethergarde砦への物資", "パワーストーンの期限が切れる前に、Quartermaster LungertzのところへCrate of Powerstonesを届けて下さい。", "このパワーストーンの箱をBlasted LandsのNethergarde Keepへ届けねばならない。力は長くはもたないから、次のキャラバンで送るわけにはいかないのだ。\n\n君が運ばねばならない。それも急いでな。\n\nNethergarde KeepのQuartermaster Lungertzに届けてくれ。砦にたどり着くには、東へ向かってDeadwind Passを抜け、さらに東へSwamp of Sorrowsを抜け、そこから南へBlasted Landsを抜けねばならない。\n\n用心しろ、{name}。危険な地を旅することになるが、失敗は許されない。", "やあ！この騒ぎは気にしないでくれ、Nethergarde Keepではいつものことさ。\n\n私に何か持ってきたのか？", "おお、力の石だ! メイジたちが見れば喜ぶだろう!\n\n本当にありがとう、{name}。Darkshireからの道のりが楽でなかったことは分かっている。", 0xa26e9783, 0x6e0883b5, 0x5e29a42b, 0x59251ed0, 0x8d183396, "....." },
  [1396] = { "迫り来る野生動物", "Young Sawtooth Crocolisksを$N1体、Sorrow Spinnersを$N2体、Swamp Jaguarsを$N3体倒し、Swamp of SorrowsのWatcher Biggsのところへ戻って下さい。", "私の隊商は東の海岸を目指していましたが、たどり着けませんでした。Lost Onesに襲われ、護衛は殺され、物資は打ち砕かれたのです。\n\n襲撃を生き延びたのは私一人です。残った物資を守ると誓いましたが、野生の獣がこそこそと近くをうろついています。どうか、獣たちから私の野営地を守るのを手伝ってください！", "沼地の生き物たちが迫ってきている、{name}。お願いだ、野営地を守ってくれ！", "動物たちの声が、今はかすかに、遠くなりました。ありがとう、{name}。あとは戻ってこないことを祈りましょう！", 0xfdec5bf1, 0x2c095fd7, 0xb440dcb7, 0x510cdc33, 0xf5a78b36, "....." },
  [1398] = { "流木", "Sundried Driftwoodを$N1本、Swamp of SorrowsのWatcher Biggsのところへ持って行って下さい。", "あなたには大きな恩があります、{name}。あなたの内には高潔な心が脈打っています。そして今、もう一つ、あなたの力をお借りしたい仕事があるのです。\n\nNethergardeにたどり着くには、この荷馬車を直さねばなりません。そのためには……木材が要ります。強くて乾いた木材です。沼の木のような、ぐずぐずに湿って絡まった木ではだめです。\n\n{name}、東の海岸へ行って、日に干されたdriftwoodを探してください。それを私のところへ持ってきてください。", "driftwoodは見つかったか、{name}？", "この木は軽いけれど丈夫だ。ありがとう、{name}。これならうまく使える。", 0xcaa58e59, 0xab76dfc2, 0x0a0e6bfa, 0x3b499b78, 0x4bb328b3, "....." },
  [1418] = { "Neeka Bloodscar", "Neeka Bloodscarと話して下さい。", "Badlandsは過酷な土地で、Allianceが押さえるLoch Modanの地に近い。そのため、StonardとBadlandsの前哨地Kargathとの連絡はしばしば途絶える。\n\n自分の力を示せ、{name}。Badlandsへ行き、Kargath前哨地の斥候長Neeka Bloodscarと話せ。彼女と話したら、その報告書を俺のところへ届けろ。", nil, "Helgrumが報告を欲しがっているだと？3日も経たぬ前に伝令をStonardへ送ったぞ。任務に失敗したのか？Stonardに私の報告が届いていないなら、失敗したようだな。\n\n次に送る伝令が、もっと腕が立つか、もっと運が良いことを願おう。", 0x4fdf2d12, 0x41769f96, 0x4439f268, nil, 0x4e8d5220, "...m." },
  [1419] = { "コヨーテの盗っ人", "Coyote Jawbonesを$N1個、KargathのNeeka Bloodscarのところへ持って行って下さい。", "Badlandsで何日も過ごしたことはあるか、{class}？ その暑さを肌で感じたことは？ 埃っぽい平原をうろつく獣どもと向き合ったことは？ そろそろそうすべき時だ。\n\ncrag coyotesは手強い連中だ。手強いうえに図太くて、Kargathに忍び込んでは我々の食料をかすめ取っていく。この盗人どもを前哨地から追い払うのを手伝え！\n\ncrag coyotesを狩れ、{name}。狩って、奴らのjawbonesを持ってこい。十分な数を持ってきたら、お前がBadlandsを知っていると言っても信じてやるかもしれんな。", "jawbonesは持ってきたか？", "見事なjawbonesの数だな、{name}。これでcoyoteどもが残飯を求めて物資を荒らすこともなくなるだろう。\n\nよくやった。Badlandsのcoyoteは簡単な獲物じゃない。君の働きを見るに、ここでも生き延びられるかもしれないな。", 0xe2df48c3, 0x59970e12, 0x6c41cee8, 0x5ef32081, 0x1b414f0a, "....." },
  [1420] = { "Helgrumへの報告", "Neeka's ReportをStonardのHelgrum the Swiftのところへ持って行って下さい。", "StonardのHelgrumに宛てて、新しい報告書を書いた。それを彼のところへ届けて。\n\nそれから、自分が伝令走者だと思っているなら、道に迷わないことね。敵に倒されることもね。", "戻ったか。reportはあるか？", "ありがとう、{name}。Neekaの報告から見ると、Allianceにもそれなりの問題があるようだ。そして、我々には共通の敵がいると分かるかもしれない。", 0x2b1d22b8, 0x9ee22fc8, 0xd4183ee5, 0x123be0a5, 0x20f6945b, "....." },
  [1421] = { "消えた隊商", "Fallow SanctuaryでCaravan Chestを見つけてWizards' Reagentsを手に入れ、Watcher Biggsのところへ持って行って下さい。", "Lost Onesの襲撃で気を失ってしまったのですが、目の前が真っ暗になる前に、我々の荷馬車の一台が、北にあるlost oneの村、Fallow Sanctuaryへ引きずられていくのを見たのです。\n\nその荷馬車には、貴重なreagentsの入った隊商の箱が積まれていました。Nethergarde Keepの魔法使いたちの研究に欠かせないreagentsです。その箱を見つけて、reagentsを取り戻してください、{name}。取り戻して、私のところへ持ってきてください。", "wizard's reagentsは持っているか、{name}？", "ああ、見つけてくれたか！これがあれば、Nethergardeの魔術師たちは仕事を続けられる。彼らが何をしているのかは知らないが、Blasted LandsのDark Portalに関わることで、Allianceの安全にとって極めて重要なのだ。", 0x587c39bf, 0x476b9cf1, 0x4ed5f669, 0xf4baed06, 0x09b4f393, "....." },
  [1422] = { "海からの脅威", "Swamp of SorrowsのKatarと話して下さい。", "お前の武器に取りかかっている間に、Katarと話してきたらどうだ？ 浜辺の巡回で手が要ると言っていたぞ。この野営地を一緒に使っている他のろくでなしどもと酔っ払っているより、お前には頭も武器もしゃんとさせておいてほしいんでな。", nil, "少し黙れ、{class}。鈍い海鳴りの中でも、あの魚人どもの汚らわしいゴボゴボという声がまだ聞こえるだろう。", 0xb86184e0, 0x36b1514a, 0xa8804f17, nil, 0x5a3f2317, "...m." },
  [1424] = { "Pool of Tears", "StonardのFel'zerulは、Atal'ai Artifact 10個を集めるよう求めています。", "大族長は、The Temple of Atal'Hakkarで起きている奇妙な出来事を調べるよう我々を送り出した。\n\nAtal'aiのトロールは闇の術者の部族で、禁じられた魔法を使うことで知られている。ここに着いて、神殿が沈んでいるのを知ったとき、我々がどれほど驚いたか想像がつくだろう。\n\n今はgreen dragonsがこの場所を守っていて、自分たちはAzerothの守護者だと言っている。\n\n何が起きたのか突き止めねばならない。Pool of Tearsのあたりを探索して、Atal'ai artifactsを集めてくれ。それを手がかりに、この謎を解き始められる。", "Temple of Atal'Hakkarの中でどんな闇の儀式が行われていたのか、誰も知らない。だが、偉大で強力な魔力が使われたことは分かっている。\n\nそのような魔法について、できる限り学ばねばならない。Atal'aiの呪文はHordeの役に立つかもしれん。\n\nPool of Tearsの周辺から十分なAtal'ai artifactsを集めてくれれば、トロールたちが何を成し遂げようとしていたのか、そして何がそれほど恐ろしく狂ってしまったのか、理解し始めることができる。", "Atal'ai artifactsを集めた君の努力は称賛に値するぞ、{class}。", 0x70eb27d9, 0x85f789e7, 0x69f14f41, 0xd5cd8f65, 0x4eda64ed, "....." },
  [1425] = { "積荷の配達", "Shipment to NethergardeをNethergarde KeepのQuartermaster Lungertzのところへ持って行って下さい。", "私がこの荷馬車を直している間に、{name}、最後の頼みがあります。\n\nogreの襲撃から守り抜いた、最も重要な物資を荷造りしました。これをNethergarde Keepへ運んでください。砦はBlasted Landsの北の丘陵に抱かれるように建ち、Dark Portalを見張っています。\n\nNethergardへ行くには、道を東へ進んでください。道が分かれたら南のBlasted Landsへ向かい、次の分かれ道で左に曲がってください。道なりに進んでくださいね、{name}。くれぐれも用心して。", "私に用か？", "何？Biggsのキャラバンからの荷物だと？荷物も彼も、失われたものと思っていた。\n\nありがとう、{name}。運が良ければ、この物資には待ち望んでいた試薬、Azoran Crystalsが入っているはずだ。我々の在庫は尽きかけているのでな……", 0xb3be378a, 0xc7a1c2dd, 0x2ca40def, 0x102a12fa, 0x3b45b55e, "....." },
  [1426] = { "海からの脅威", "Marsh Murlocsを$N1体、Marsh Inkspewerを$N2体、Marsh Flesheaterを$N3体倒し、Swamp of SorrowsのKatarのところへ戻って下さい。", "私は海を好まぬし、その深みから出てくるのを見たどんな生き物も好まぬ。海は力強いが盲目の女主人だ。冷酷で、残忍だ。私にその力があれば、魚人どもを何百と屠ってやりたいところだ。だが、Hordeの意志に従う者の手で奴らが死ぬのを眺めるだけでも、いくらかの満足は得られる。\n\nそこで君の出番だ、{class}。君はどれだけ屠れる？ 奴らの中でも最も強い種類の者に、自分の力を試してみるか？", "私は忍耐強い。Draenorの古いkankの石のように、忍耐強く、永遠だ。魚人どもに我らの境界を越えさせはせん――私がまだ立っている限りはな。自由に使える軍があれば、この世界からもあらゆる世界からも奴らを一掃してやるものを。奴らのことを話すだけで、憎しみが煮えたぎるのを感じる。", "海は広大で容赦ないように見える。だがお前は、海が生んだ者どもの血で海を汚したのだ。魚人どもは痛みを知った。愚かな奴らは、お前がもたらした壊滅から隊列を立て直さざるを得なくなる。それは良いことだ。\n\n奴らのゴボゴボという悲鳴を、夜更けまで海鳴りよりも大きく響かせてやれ。奴らが1匹黙らされる声を聞くたびに、私は笑みを浮かべるだろう。\n\nさらに魚人どもを殺したいなら、また私のところへ戻ってこい。喜んでまた報酬をやろう。", 0xb86184e0, 0x753ca7df, 0x45250944, 0xff4eb55e, 0x0ee4e19a, "....." },
  [1427] = { "海からの脅威", "Swamp of SorrowsのTok'Karと話して下さい。", "休む前に、もう一度Tok'Karと話すがいい。君が出かけている間に、彼が武器をいくつか仕上げたはずだ。ここでの働きの礼に、そのうちの一つを君に差し出すだろう。準備ができたら、その切れ味を魚人どもで試すといい……ただし、それはもっぱら私をさらに喜ばせるためにだ。", nil, "ああ、{name}、戻ったか。よし。murlocとの戦いに使う武器を追加で作り終えたところだ。新鮮なsawtoothの肉を持ってきてくれたこと、そしてKatarの顔に小さな笑みを取り戻してくれたことに対して、そのうちの1つをお前に贈ろう。", 0xb86184e0, 0x86724759, 0xd1393d8f, nil, 0x7d92da71, "...m." },
  [1428] = { "続く脅威", "Marsh Inkspewersを$N1体、Marsh Flesheatersを$N2体、Marsh Oraclesを$N3体倒し、Swamp of SorrowsのKatarのところへ戻って下さい。", "魚人どもへの君の憎しみが、私の憎しみとともに募っていくのを見るのは喜ばしい。\n\n浜辺に沿って奴らの仲間をもっと見つけ出せ。戦いを存分に味わったら、私のもとへ戻ってこい。その時に、君の精勤への報酬について話そう。", "海とその子らすべてが黙らされるまで、私の気は晴れん……とりわけ、あの忌まわしい魚人どもがな。", "よくやった、{class}。奴らの血をもっと求める。魚人どもを皆殺しにしろ。", 0xb056d70f, 0x75513e7c, 0x001e739a, 0x55c95e19, 0x7decfd78, "....." },
  [1429] = { "Atal'ai Exile", "Bundle of Atal'ai ArtifactsをHinterlandsのAtal'ai Exileに渡して下さい。", "君がPool of Tearsの危険に立ち向かっている間に、私の斥候の一人が、干からびた肉の上に血で書かれた巻物を持ち帰ってきた。どうやら、Atal'ai部族のプリーストに対する裁きの宣告のようだ。\n\nこのプリーストは、Atal'aiの間では死よりもつらい運命を言い渡された。\n\nはるか北のHinterlandsへ追放され、Witherbarkのトロールと共に暮らすことになったのだ。\n\nこの遺物は私がまとめておこう。君はその追放者を探し出し、遺物の本当の使い道を突き止めてくれ。旅を終えたら私のところへ戻ってこい。", "ここへ来るとは勇敢だな。勇敢か、あるいは愚かか……", "Atal'aiの召喚の遺物を持ってきたというのか?\n\nJammal'an the Prophetが、Chamber of Bloodの信徒たちを定められた運命へと導いているようだな。Hakkarは神殿に戻ったのだろうか? 彼らの運命はもう果たされたのか?", 0xd0a32a97, 0xfab578a3, 0x89f6c847, 0x14f217d4, 0x123cfa3c, "....." },
  [1430] = { "新鮮な肉", "Monstrous Crawler Legsを$N1本、Swamp of SorrowsのDarのところへ持って行って下さい。", "うちのお客さんの間じゃ、crawlerの肉のとろけるような味が大人気でね。特にmonstrous crawlersの肉が。\n\n海岸へ行くつもりなら、あいつらのlegsを持ち帰ってきてくれれば、ちゃんと割に合うようにしてあげるよ。Orgrimmarへ送るんだ。\n\n海岸はここから東だよ。浜辺や海の中をちょろちょろ走り回ってるあいつらは、すぐに見つかるはずさ。", "{name}、君の成功を祝うワインの樽を用意してあるよ。お客に送り返す前に品物を味見するのは、当然のことだからね。", "ああ、これは完璧だ。直火で完璧に調理したら、どんな味がするか待ちきれないよ。旅のお供に少し持っていくといい。本当に美味しいんだから。", 0x0c83d861, 0xde624c9d, 0xc9743254, 0xf7bcdd24, 0x5095d527, "....." },
  [1431] = { "Allianceとの関係", "Orgrimmar の Keldran に話しかけて下さい。", "そのままでいい、{class} 。同胞にとって大切なものを伝えたい。でも、目に見えるものじゃない。\n\n我々は誇り高い種族だ。ヒューマンとの戦争は Thrall の忍耐さえも試した。知っての通り、我らが大族長は聡明で用心深く、同胞のことを第一に考えていてくれる。突き詰めると大族長は外交家なのだ。ヒューマンと共にいた間に、大族長はヒューマンのやり方を詳しく学んだんだ。\n\n私の始めた話が興味をひいたなら、この都市の西門の近くにいる Keldran を見つけてくれ。彼の小屋があそこにある。", nil, "Putanni、高貴なる{class}よ。私はKeldran、魔法……そして他の神秘の術を学ぶ者だ。\n\nCravenが君をここへ寄こした用件は、君がこれまで必要としてきた以上の繊細さを少々要するものだ。だが、それでも君が我らの大義に力を貸せないということではない。\n\nどうか楽にしてくれ。なぜ大族長が私の助けを……そして君の助けを必要としているのかを話そう。\n\nすべては見た目から始まるのだ、{name}。Hordeが自らをどう見ているか。我らの同盟者が我らをどう見ているか。そして何より大切なのは、我らの敵が我らをどう見ているかだ。", 0x3dfe4bf4, 0xe4927aad, 0xb8b5b27d, nil, 0x232bbca9, "...m." },
  [1432] = { "Allianceとの関係", "Desolace の Takata Steelblade に話しかけて下さい", "AllianceがKalimdorの奥深くへと進むにつれ、HordeがBurning Legionと手を結んでいるという誤った結論が導かれかねない。大族長はそれを許すわけにはいかない。そして大族長の祝福のもと、私はその者たちを排除する監督の任を引き受けている。\n\nDesolaceの地、大きなKodo Graveyardの北にあるGhost Walker Postに、私の手の者がいる。Stonetalon MountainsのCharred Valeから南へ向かえば、そこへ行き着くだろう。着いたらTakata Steelbladeを訪ねるがいい。", nil, "ご機嫌よう、{class} 。Orgrimmar から知らせを持ってきてくれたのか。それはいい。\n\nこの地域全体に悪魔がはびこっている。centaurの糞の臭いよりもっとな。馬人間どもはこの土地を自分たちのものだと主張しているが、明らかに悪魔の影響はcentaurの手に負えなくなっている。影響を食い止めねば、centaurどもは壊滅させられるだろうな。\n\n間接的にcentaurを支援するのは俺にとって面白くないが、Horde にとっては良いことだ。だから、それが Horde にいるウォーロックを助けるということを意味していても、俺は大族長のために自分の任務をこなすんだ。", 0x3dfe4bf4, 0xfa6ed566, 0xe87c4f74, nil, 0x046395cd, "...m." },
  [1433] = { "Allianceとの関係", "Desolace の Maurin Bonesplitter に話しかける。", "Burning Bladeには企みがたくさんあるが、奴らの核をなすものは邪悪でその精神は堕落しており、奴らの目標を阻止するには壊滅するしかないと分かっている。\n\nKeldranは俺のところへMaurinを寄越した。Burning Bladeとwarlockどものやり口を熟知しているからな。\n\n俺がここで悪魔の脅威に対処している間に、彼はBurning Bladeに対する作戦を管理している。\n\n彼に話しかければ、策略に導いてくれるだろう。", nil, "ああ、うん。Warchiefへの忠義心からの支援は、いつでもありがたい。\n\n私の名はMaurin。Keldranと若きWarchief Thrallの強い要望があってここにいる。Thrallの支配を脅かす邪悪に立ち向かい、若き指導者を助けることは、私の望みだ。\n\n{class}おいで、もっと近く。腐敗した患部すなわちBurning Bladeを取り除く私の計画について、君に説明しよう。", 0x3dfe4bf4, 0xbcfd85d2, 0xcf30d5af, nil, 0x4a612c91, "...m." },
  [1434] = { "Satyrに汚された者", "Hatefury Rogue・Hatefury Felsworn・Hatefury Betrayer・Hatefury Hellcallerをそれぞれ7人討ち取り、DesolaceのTakata Steelbladeのところへ戻って下さい。", "悪魔の蔓延は他の影響無しに起こらない……邪悪な者が足がかりを得るのを、何かが許しているのだ。\n\nそれは弱き精神、力を求める不必要な欲望から起こるのかもしれない。恐らくそれは復讐の渇きか、最後の審判を求める望みだ。我々が痛みに苦しんでいるとき、邪悪な者が優位に立つ……satyrのような邪悪がな。\n\n奴らとBurning Bladeの間にはすでに結びつきが出来ているのだ。それでThrallは奴らを討伐させるのだろう。ここの北東に行って奴らを探し、追い返したら戻ってきてくれ。", "トーレンの仲間から、satyrは見た目どおりの存在ではないと警告された。奴らには何か裏があり、その邪悪さは本来の性質がねじ曲げられたものだと彼は考えている。だが、私はそんなものを見たことがない。\n\n私に見えるのは、弱き者への容赦ない殺戮と、闇の力を求める者たちの堕落だけだ。\n\n大族長から別の命が下るまで、奴らを殲滅する務めを続けるつもりだ。それまでは、奴らに情けはかけん。", "よくやってくれた、{class}。君は名誉と献身を示してくれたんだ。\n\nDesolaceでの作戦が終わったとき、君がここで我々の行動を助け、大族長の願いが実現するよう助けたことを、彼は知るだろう。\n\nどうもありがとう。", 0x52420039, 0x51e12b2c, 0x56476d12, 0xc5dd0ea9, 0x1cee0929, "....." },
  [1435] = { "魂の炎上", "Burning GemとInfused Burning Gem15個をDesolaceのMaurin Bonesplitterに返してください。", "利己的な理由で君主に背くような卑劣な奴らには、死こそ最も望ましい。だが、闇に染まった奴らを始末するには、死すら充分ではない。\n\nこの宝石を持って行け。Burning Bladeの者が瀕死の時、宝石の魔法を発動させるのだ。その呪文は犠牲者から堕落した魂を抜きだし、infused gemを後に残すだろう。\n\nその宝石は私のところへ持ってきてくれ。私ならきっちりと処分できるからな。\n\nさあ行け。死がお前さんを避けていきますように。", "魔法はできる限り単純にしておいた。傷ついた獲物の体からその魂を引き出すのは、子供の遊びも同然のはずだ。敵を完全に倒すのにgemの力を頼ってはならない。gemは相手が死に瀕したときにだけ発動させること。さもなくば役に立たん。", "ああ、うまくやってきたんだな。それはよかった。宝石を渡してくれ、どこか安全な場所へしまっておこう……。\n\nお前さんに頼んだ仕事は終わりだ、{class}。休んだら、Takataに話しかけてくれ。彼は別な仕事を頼むかもしれん。それでなくばOrgrimmarへ戻り、Desolaceでの進捗状況をKeldranに伝えるよう頼むだろう。", 0xbbb0e71b, 0x7215960a, 0xa0bf7d88, 0xb86937a9, 0x148c1e21, "....." },
  [1436] = { "Allianceとの関係", "Orgrimmar の Keldran に話しかけてください。", "戦いは上手くいったのだな、{name} 。恐らく Warchief も季節が変わる前に帰郷することをお許し下さるだろう。悪魔とその下僕との戦いにこのような躍進を続けていればな。\n\nKeldran のところへ戻って、我々が成し遂げたことを知らせてくれ。君の尽力に対して報いてくれるはずだ。動機は彼にとって大切なんだ。Warchief が彼の懸念していることを尊重していると知れば、誇りに思うだろう。", nil, "上手くやって Desolace から戻ってきたのだな、{name} 。ありがとう。\n\n私の願いを理解してくれたこと、時間を割いてくれたこと、尽力してくれたことに感謝する。Thrall は Horde と Allianceとの和平を理解し望んでいる。我々の出現が受け入れられるのを保証する策を講じることで、我々は不必要な暴力という脅威を引き起こすことはないだろう。\n\n恩に着るよ。", 0x3dfe4bf4, 0xe4927aad, 0xf8bf26de, nil, 0xc0a27dba, "...m." },
  [1437] = { "Vahlarrielの捜索", "DesolaceでTyranisとDalinda Malemの荷馬車を見つけ、調べて下さい。", "私はVahlarrielです、{name}。Darnassianの商家、House Malemの行方不明になった二人の貴族の居場所を突き止めるため、ここへ来ました。家の父君は最悪の事態を恐れており、私は行方不明のお子様方を見つけるためにできる限りのことをせねばなりません。TyranisとDalindaの捜索はまだ始めていませんが、ここに長居せずに済むことを願っています。\n\n最後の知らせでは、二人は数週間前にStonetalon Mountainsを通っていったそうです。\n\nもし二人の荷馬車を見つけたら、どうか、すぐに私のところへ来てください。", nil, "荷馬車の残骸を探ると、呪文と武器の両方で襲われたことが明らかになった。戦いは一方的で、すぐに終わったようだ。血は一滴も見当たらず、遺体も残っていない。\n\n荷馬車を襲った者が誰であれ、手際が良く迅速だった。", 0x7ca9c473, 0x2f1bef36, 0x1e29426b, nil, 0x3b1107b1, "...m." },
  [1438] = { "Vahlarrielの捜索", "DesolaceでDalinda Malemを見つけて下さい。", "できれば、DalindaとTyranisの両方を見つけて、分かったことを私に知らせに戻ってきてください。捜索はこの砦から始めてください。私はすぐにDarnassusの上官に連絡して、事情を伝えます。\n\n{name}、もう一つ、あなたにしっかり心に留めておいてほしいことがあります。上官たちは、Tyranisと、彼がここへ来た動機に、いくらか懸念を示しているのです。上官たちにとっては、Dalindaが見つかって無事に連れ戻されることの方が大事なのです。Tyranisは……家へ連れ帰る前に、見極めねばなりません。", nil, "Eluneに感謝を。ようやく助けが来てくれました。お願いです、{class}、あなたの助けが必要なんです。兄弟のTyranisと私はBurning Bladeに捕らえられ、ここへ連れてこられました。彼らは私を悪魔の主たちへの生贄にするつもりなのだと思います！\n\nDesolaceへ来るのは間違いだと分かっていました。でもTyranisは最近、秘術にまつわるあらゆる知識を渇望するようになっていたのです……私たちの民の意に反してまで。この地に悪魔がはびこっているという話を聞いてもなお、彼はこの旅に出ると決めてしまいました。\n\n彼の身に最悪のことが起きたのではと恐れています。", 0x7ca9c473, 0xe829ed7f, 0x2400811d, nil, 0x800a2c6a, "...m." },
  [1439] = { "Tyranisの捜索", "DesolaceでTyranis Malemを見つけて下さい。", "オークたちが私たちの護衛や召使いを皆殺しにした後、私たちはここへ連れてこられたの。ああ、彼らにしたあの恐ろしい仕打ちといったら！ きっとその場で私たちも殺されると思ったけれど、オークたちには別の企みがあるのだとはっきりしてきたわ。\n\nTyranisは彼らに話しかけようとしたの。秘術の知識で彼らを感心させたかったんだと思うけど……なぜだかは分からないわ。\n\nお願い、兄に何があったのか分かるまで、私はここを離れられないの。兄を見つけて、その運命が分かったら、私を迎えに戻ってきて。", "TyranisがBurning Bladeの秘密を学ぼうとし、許されるなら自分を奴らの仲間に数えるのではないかと心配だ――彼は昔から、魔法に魅入られた者にそれがもたらす力に憧れていたからな。\n\nTyranisの魂がそんな危険に手を出しているという知らせを持って家族のもとへ帰るなど、耐えられるかどうか分からない。我々の種族の間では、そういうものを追い求めるだけでも重い罪だ。だが、我々が身を守ろうとしているものそのものになってしまうとは……まったく、許しがたいことだ。", "なんてひどい！でも、仕方のないことだったのでしょう。あなたの手によるものでなければ、きっと私の民の手によるものだったはずです。お礼を言うべきなのでしょうね……心がこもっていないように聞こえたら許してください。悪気はないのです。\n\n兄弟の運命が分かった今、私が脱出する時が来たようです。もしまだその気があるなら、この恐ろしい場所から逃げ出すために、あなたの助けをお借りします。\n\n準備ができたら、安全な場所へ向かいましょう。", 0xbdd7dd05, 0xe08cffee, 0x4ef69f49, 0xe2f9a2df, 0xc8605933, "....." },
  [1440] = { "Vahlarrielのもとへ戻る", "Dalinda MalemをThunder Axe Fortressから護衛し、DesolaceのVahlarriel Demonslayerのところへ戻って下さい。", "では、今がその時なのですね？ あなたの尽力に感謝します。もし機会がないといけませんから、今のうちに、私と家族のためにしてくださったすべてのことにお礼を言わせてください。準備ができているなら、もうここに私の用はありません。あなたが頃合いだと思ったら、出発しましょう。", nil, "ありがとう、{name}。DalindaはこのNijel's Pointまで無事に戻ってきた。しかも、望める以上に良い状態でな。自分の力でここまでたどり着いたのは良い兆しだ。あなたも無事かね？\n\nTyranisとDalindaがそろって戻ってこられなかったのは心が痛むが、Tyranisの決断がもたらした恥は彼女が耐えねばならぬものだ。Darnassusへ戻ったとき、彼女が向き合わねばならないことだろう。", 0xbc22c5c2, 0x9d8532db, 0xf6f3ea86, nil, 0xdf942d1f, "...m." },
  [1442] = { "Kor Gemの捜索", "DarkshoreにいるThundris WindweaverにKor Gemを渡して下さい。", "ご機嫌よう、{name}。聖なる道を歩む君にしてあげられることはあるかい?ああ、そうとも。鍛冶屋のStilwellは……古くからの友人だ。よく覚えているけれども、しばらく名前を聞かないな。彼を無礼な奴だと思ったことはないから、Kor gemに対する情熱は高潔なものとしか思えない。あの宝石を本当に求めているのなら、Ashenvaleの北西へ行かねばならない。古代遺跡の中にBlackfathom Deepsがある。そのずっと奥に宝石を使っているnagaがいる。ひとりで行くんじゃないぞ、{class}。", "聖なる道を歩まぬ者がKor gemについて尋ねに来たのなら、もっと疑ってかかったでしょう。ですが、私はあなたの同胞を、私の身内の一部よりも信頼しています。あなたたちの一人が堕ちたからといって、あなたの教団全体を裁くことはしません。", "これは確かにStilwellが欲している宝石だ。だが、彼のもとへ持っていくことを許す前に、堕落を浄化しなければならない――nagaの女どもは宝石に力を吹き込む、それは確かだ。だが、奴ら自身の邪悪な類の力をな。\n\nStilwellに、その力は損なわれておらず、彼が加えたいどんな儀式にもきっと役立つだろうと伝えてくれ。\n\n自分が何をしているのか分かっているといいが、{class}。お前が持っているのは、決してありふれた品ではないぞ。", 0x5d353131, 0x049bb428, 0x8e41ca81, 0x45d628b2, 0x4ca4aaaa, "....." },
  [1444] = { "Fel'Zerulの元へ", "StonardのFel'Zerulのところへ戻って下さい。", "Jammal'an the Prophetは、私をThe Temple of Atal'Hakkarから追放した。かつて私は、あの大プリーストがふさわしい指導者だと思っていた。\n\nあいつの揺るぎない予言への信仰は、Atal'aiに破滅をもたらすだろう。まだそうなっていないならの話だが。\n\n私が懸念を口にすると、異端者の烙印を押され、神殿から追い出された。\n\nお前が持ってきた遺物は無害だ。だが、もしJammal'anが召喚の儀式にふさわしい呪物の魔法を見つけたのなら、世界は大きな危機にさらされている……", nil, "ずいぶん久しぶりだな、{class}。旅が実り多きものであったことを願う。\n\nHinterlandsの追放されたAtal'aiからは、どのような知識を得た?", 0xf284afc4, 0x1253981a, 0xe5febc62, nil, 0xa6dc8e06, "...m." },
  [1445] = { "Temple of Atal'Hakkar", "Fetishes of Hakkar 20個を集め、StonardのFel'Zerulに渡して下さい。", "では、あの者はJammal'anの予言について話したのだな?\n\nAtal'aiの精神的指導者は、HakkarがNetherからAzerothへ戻れば、その神がAtal'ai部族に不死を授けると信じている。\n\n私に言わせれば、終末の日を早めるだけの愚かなまやかしだ。\n\nだが、追放者が魔力を帯びた呪物について話したと言うのか?それはひどく気がかりだ。もしそれが本当に、この騒ぎを引き起こしたAtal'aiの儀式の鍵なら、その本来の力を理解せねばならない。\n\n神殿へ踏み込み、呪物を奪ってこい!", "Atal'aiの呪物にHakkarを召喚し、Jammal'anの予言を成就させる力があるのなら、奪わねばならん。そのような力はHordeが理解しておかねばならんのだ！", "勇敢なる{class}よ、お前はHordeの偉大な闘士であることを証明した。\n\nさあ、このHakkarの呪物の一群を、直ちに始末せねばならん!", 0xd35a3c3c, 0x4d302605, 0xdc768673, 0xde7a372b, 0xfd249f1e, "....." },
  [1446] = { "Jammal'an the Prophet", "HinterlandsのAtal'ai ExileはHead of Jammal'anを求めています。", "Witherbarkの仲間たちは、よそ者が住みかをうろつくのを快く思わない。\n\n私か?私にはもう住みかなどない。私は一族から追放されたのだ。Swamp of Sorrowsの偉大なAtal'ai部族からな。\n\n我らの精神的指導者Jammal'anは、自ら予言と呼ぶものを得た。あいつは、神Hakkarを召喚すればAtal'aiに不死がもたらされると信じている。\n\nだが私は慎重になるよう説いた。もしその予言が、ただの策略にすぎなかったとしたら?\n\n私は追放の復讐がしたい。Jammal'anの首を持ってこい。そうすれば、我が一族も解放されるかもしれん。", "Jammal'anさえ除かれれば、私にも同胞のもとへ戻る望みがある。\n\nJammal'anを精神的指導者に戴いている限り、Atal'aiを待つのは確実な破滅だ。", "Jammal'anが偽りの幻視を軽々しく信じたことが、我が民を永遠の破滅へと導いた。\n\n我が追放の仇を討ってくれたことに感謝する、{class}。我が民を悼む。私にはもう帰る故郷もない。", 0x3ec26544, 0xf5de6b03, 0xf4b43414, 0x7bc273d3, 0x903206c9, "....." },
  [1447] = { "消えた外交官", "StormwindのDashel Stonefistを打ち負かす。", "ああ、お前は明らかにStormwindに来た{class}の中で一番賢いってわけじゃねえな。だが、ここから出ていけなかった一番のまぬけの一人にはなろうとしてるぜ。\n\n俺のダチには会ったか？", "お前が間抜けな{class}だって言ったのは、別に悪気があったわけじゃないんだ。俺たち友達だろ？根に持ってないよな？", "それで、何か理由があって私のところへ来たんだろう。何が必要なんだ？", 0xbe525a75, 0xb5b86b0e, 0x06c089ad, 0x7b7af356, 0xb7bb28c3, "....." },
  [1448] = { "神殿を探し求めて", "StormwindのBrohann CaskbellyはTemple of Atal'Hakkarを探すよう求めています。", "わしにも、お前さんのように若くて活力に満ちていた頃があったんじゃよ、{class}。\n\nじゃが今はすっかり年を取って、かつてのように世界を探検することもできん。ああ、わしが見てきたものといったら!\n\nじゃが、ひとつだけ解けなかった謎があってな。わしの最後の探求として、Explorers' LeagueはわしをThe Temple of Atal'Hakkarの捜索に送り出した。Swamp of Sorrowsにあるという噂じゃった。\n\n体が弱っておったんで、gryphonに乗って空から探したんじゃが、結局見つからなんだ。\n\n年寄りのドワーフを助けてくれんか?お前さんなら、自分の足で探したほうがうまくいくかもしれん。", "私はAzerothのジャングルからKhaz Modanの雪深い峰まで、世界中を旅してきた。\n\nこれまでの冒険で助けを求めたことは一度もない。だが、この老いた骨はもう疲れてしまった。\n\nExplorers' Leagueのための最後のクエストをやり遂げたと知ることほど、満ち足りた気持ちになれるものはないだろう。\n\n{class}、もし親切にもTemple of Atal'Hakkarを探す手伝いをしてくれるなら、大いに感謝するよ。\n\nSwamp of Sorrowsをくまなく探し、見つけたことを報告してくれ！", "Temple of Atal'HakkarがPool of Tearsの下に沈められただと? しかも緑のドラゴン族に囲まれている?\n\n驚くべき発見だ、{class}。だが明らかに何かがひどく狂っている。", 0xf54b5fd9, 0x1d48ee51, 0x73052453, 0xde93f335, 0xe5b8eafa, "....." },
  [1449] = { "The Hinterlandsへ", "HinterlandsのAerie PeakにいるHigh Thane Falstad Wildhammerと話して下さい。", "さっきも言ったとおり、わしは自分で空から神殿を偵察しようとしたんじゃ。まあ、正確には一人ではなかったんじゃがな。\n\nわしはThe Hinterlandsにある、名高いAerie Peakのgryphon飼育場へ行った。そこで、選りすぐりの乗り手の一人に手を貸してもらったんじゃ。その乗り手は乗騎から落ちて、沼へ真っ逆さまじゃった……\n\n年のせいで、その気の毒な男の名前が思い出せん。飼育場の長ならきっと覚えておるじゃろう。\n\nそこへ行って、Falstad Wildhammerを探すんじゃ。\n\nあの乗り手に何があったのか、突き止めねばならん。", nil, "何の用だ、お前さん? こっちは片付けなきゃならん厄介事を抱えてるのが見えんのか? {race}のおしゃべり屋と突っ立って無駄口を叩いてる暇なんぞ、誰にある?\n\nそこら中からトロールが湧いて出てるんだ! さっさとしろ。", 0xd0cc34a2, 0xb97cf5c4, 0x7af0d9ca, nil, 0xeb2412a7, "...m.", nil, nil, nil, nil, 0x750ec02a },
  [1450] = { "Gryphon Master Talonaxe", "Aerie Peak AviaryのGryphon Master Talonaxeと話して下さい。", "で、お前はExplorers' Leagueのじいさんのための、ご大層な使い走りってわけか、ええ?\n\nいいか、よく聞け、{class}。お前の古なじみがAzerothで誰と飛び回ってたかなんて、俺は知らん。俺がGryphon Master Talonaxeに見えるか?見えるのか?\n\nそんなに飛行任務のことが気になるなら、gryphonの管理人に聞いたらどうだ?これ以上このあたりでぶらぶらしてるのを見つけたら、本物の仕事をやらせるからな。\n\nさあ、さっさと行け。", nil, "ああ、そうだ。もちろん覚えているとも。Brohann Caskbellyに手を貸すため、gryphonの乗り手を一人送ったことはな。\n\nExplorers' Leagueにはいつも心を寄せてきた。実のところ、私の父はUldamanを発見した最初の発掘隊に加わっていたのだ。\n\n当時、最高のgryphonの乗り手だと思っていた者をBrohannとともに送った。Rhapsody Shindiggerという名の男だった。\n\nそして実に見事な乗り手だったよ! まあ、あのことがあるまではな……", 0xf343f271, 0xda4d8e91, 0x87d768fb, nil, 0x6562d1f1, "...m.", nil, nil, 0xc10ce1d8, nil, nil },
  [1451] = { "Rhapsody Shindigger", "HinterlandsでRhapsody Shindiggerを探し出して下さい。", "Rhapsodyは酒にすっかり入れ込んじまってな。いや、勘違いしないでくれよ――ここの飼育場にいる俺たちドワーフはみんな、しかるべき時にはうまいエールが大好きさ。\n\nだが、Shindiggerのやつは、gryphonが空に舞い上がるみたいに酒に溺れていった。まったく残念なことだったよ。Rhapsodyほど飛べるやつはいなかったんだからな。\n\n最初に問題の兆しが見えたのは、お前さんの仲間のBrohannとの任務から、あいつがふらふら戻ってきたときだ。それからはあっという間に転げ落ちていった。辞めさせるしかなかったのさ。\n\n最後に聞いた話じゃ、ここの東で酒造りのキャンプを構えてるそうだ……", nil, "ヒック!\n\nお前さんをまっすぐ見てるのに、上がったり下がったりしやがる。目が回るぜ。ホホー!\n\nヒック!\n\nおっと! 今のを感じたか? 地面が揺れてるぞ、友よ。一杯やらにゃならん。\n\nヒック!", 0x18625738, 0xdc4c878f, 0x0d6b4b73, nil, 0x0f496b34, "...m." },
  [1452] = { "Rhapsody's Kalimdor Kocktail", "HinterlandsのRhapsody Shindiggerは、Roc Gizzard 3つ・Groddoc Liver 3つ・Ironfur Liver 3つを持ってくるよう求めています。", "ヒック!\n\nじゃあ、あのイカれたBrohannがお前さんをよこしたってのか?いやあ、あれはとんだ冒険だったぜ……ヒック!\n\n沼で何があったか話してほしけりゃ、何か強い酒がいるな。きれいな光景じゃなかったんだ、分かるだろ。ヒック!\n\nこうしようぜ……Kalimdor Kocktailをこしらえるのに要るもんを持ってきてくれりゃ、洗いざらい話してやるよ。\n\nTanarisのRoc gizzardsが要るな……それと、ええと……FeralasのGroddocとIronfurのliversもだ……\n\n強くてうまいKalimdor Kocktail……そいつがありゃ口も回るってもんさ!", "Rhapsody Maltは飲んだことあるか？俺の最高の酒の一つさ、自分で言うのもなんだがな。ヒック！\n\nだが、あの運命の飛行の……ヒック……沼地の上での恐怖を思い出すとなると、もうちょいと強いのが要るんだ。ヒック！\n\nまさか、俺のKalimdor Kocktailにガツンと効かせるのに要るgizzardsとliversを見つけてきてくれたりはしてないよな？\n\nヒック！", "必要なもんを持ってくるのに、まるで苦労しなかったようだな! 遠いKalimdorじゃ、さぞ大変な滞在だったろうよ。\n\nこの砂肝と肝臓から必要なもんを取り出すのに、大して時間はかからん。ヒック!\n\nそうしたら強烈な酒を蒸留して、ようやくお前さんの知りたいことを話してやれる。\n\nヒック!\n\nあの古い沼のことを考えるだけで身震いがするぜ。\n\nヒック!\n\nちょいと手早く一杯こしらえてくるよ。", 0xada58393, 0x5a78cf72, 0xae771620, 0x73d2b888, 0xd9dd039a, "....." },
  [1453] = { "Desolace での Reclaimers の商売", "Desolace にいる Kreldig Ungor に話しかけて下さい。", "Desolace にやらねばならん仕事があるのだ、{name} 。あそこはcentaurやその他の汚らわしいもので汚されたひどい場所だ。だが、正味一週間分ある仕事を探しておるんなら、あそこへ行って Kreldig Ungor に会ってわしに寄越されたと伝えろ。\n\nあいつは Nijel's Point にこもっとるはず―― Desolace 北部の山中に隠された居心地のいい小さなキャンプだよ。Stonetalon Mountains から入れば、東に向かうだけだ。見逃しやすいから、注意して探すのだぞ。", nil, "Reclaimers が仕事不足なわけでもなく、進んで手伝ってくれる冒険者がいないわけでもないと分かって良かった。\n\nわしは Kreldig だ、{name} 。Reclaimers に協力するとは賢いことだ。近頃、皆何かを必要としとる……失った家宝、魔法の道具、愛する者……。まあ色々だ。だが Reclaimers が活動しておれば、失ったものを適正価格で見つけることができる。", 0x8efbb2b8, 0x0e15ac26, 0x3c8dd6f7, nil, 0x7ba6dd47, "...m." },
  [1454] = { "Karnitol の難破", "Desolace で Karnitol's Chest を見つける。", "メイジ Karnitol ―― Stormwind の貴族だか何だかの仕事が最優先だ。Karnitol の船が Desolace 北西の沖でsea giantsに襲撃されたらしい。召使いと本人は貴重品の入った箱のうちひとつを岸へ運ぼうとしたんだが、sea giantsが集団で襲ってきたんで、箱を放棄して安全な場所へテレポートすることを選んだんだと。その箱と中身を見つけて、Stormwind へ持ち帰ってきて欲しいとの依頼だ。", nil, "箱は水による損傷をまったく受けていなかった。また、上蓋はこじ開けられており、保護のためにかけられていた魔法の罠がかなり前に発動していた――箱の縁周りにある焼け焦げた痕跡からもそれは明らかである。", 0x77004981, 0x054562b5, 0x7adbdbf2, nil, 0x4cc9f50a, "...m." },
  [1455] = { "Karnitol の難破", "Desolace にいる Kreldig Ungor のもとへ戻る。", "しばらく時間をかけて、何が箱をこじ開けたのかを調べると、箱の側面と上面に長く深い引っかき傷があることに気づいた。人や巨人ではない何かがこの箱に興味を持ったらしい。その痕は短剣や剣によるもののようには見えない。\n\n箱の中を探ってみたが、中身はまったくの空だった。\n\nほかに打つ手もなく、あなたは箱を閉じて立ち去る支度をする。Kreldigはがっかりするだろう。", nil, "Nijel's Pointへよく戻ったな、{name}。で、何を見つけたか聞かせてくれ。\n\n何だと！？何もない？空っぽの箱じゃ、俺たちに金は入らないんだがな。\n\nお前が見たというその跡について、もっと詳しく話してくれ……その切り傷についてな。", 0x77004981, 0x0438e587, 0x40c594a7, nil, 0xab30987a, "...m." },
  [1456] = { "Karnitol の難破", "Karnitol's Satchel を見つけ、Desolace にいる Kreldig Ungor に渡す。", "興味深い。\n\nまあ、まだ望みがないわけじゃなさそうだ。\n\n同じ海岸沿いだが、北のRanazjar Isleの近くの海の底に、ナイトエルフの遺跡がある。nagaの部族、Slitherbladeがそこをねぐらにしている。そこが一番見込みがありそうだ。\n\n偵察隊がそこまで南へ行ったのなら、かなりの手練れだったに違いない。Karnitolの持ち物を探すなら、まずは強いほうのnagaから当たるな。tidehunterかsea witchだ。", "Nijelが誰だか知らないが、悪く言うつもりはない。けど、このキャンプは俺が夜を過ごした中で一番快適な場所とは言えないな。分かるだろ、{name}。", "すごいぞ、{name}！Karnitolの持ち物を見つけてくれたんだな！\n\nあのいまいましいnagaどもめ、いつも面倒ばかり起こしやがる。あいつらを相手にするくらいなら、一生Hordeと戦っていた方がましだ。君はReclaimersに大きな貢献をしてくれたよ。", 0x77004981, 0x03a28634, 0x8eb022f8, 0xe6bee56f, 0x27c447b7, "....." },
  [1457] = { "Karnitolの難破船", "Karnitol's SatchelをIronforgeのRoetten Stonehammerのところへ持って行って下さい。", "Karnitolの荷物をIronforgeのRoettenのところへ持って帰れ。そうすりゃ、よくやったって報酬を払ってくれるよ。\n\nハハ、気をつけないと、あんたのことをすっかり気に入って、うちに正式に加われって言い出すぜ。\n\nもう一度言うが、よくやったな、{name}。\n\n帰り道は気をつけてな。それと、あまりのんびりするなよ。Karnitolは辛抱強い男とは言えないが、それでも気前はすごくいいんだ。", "商売は大繁盛だ、{name}。質問に付き合ってる暇はあまりない。Reclaimersに用があるなら聞こう。そうでないなら、俺の部下の誰かと話してもらうしかないな――ここらのことを片付けるには十分有能な連中だ。", "ああ、DesolaceのKarnitolの件か。素晴らしい！\n\nで、箱は壊れちまったが、品物は全部ここにあるってわけか？まあ、それは本人に判断してもらうさ。俺がここでやってる商売のいいところは、客が満足しなけりゃ「知ったことか！」って言ってやれることだ。連中は自分の物を見つけるのを俺たちに頼ってるんであって……戻ってきたときに全部きれいで状態がいいことまで保証してるわけじゃない。\n\nよくやった、{name}。報酬を払うとしよう。", 0x77004981, 0x5d5a35d4, 0x939e2e91, 0x52455200, 0x731ac734, "....." },
  [1458] = { "Reclaimers Inc.のための試薬", "Hatefury Clawsを$N1個とHatefury Hornsを$N2個、DesolaceのKreldig Ungorのところへ持って行って下さい。", "ここでの仕事の一つに、KharanosにいるノームのメイジのLeftwitchのために、reagentsを集めるってのがあってな。Roettenは、どうせこっちに来てるんだから楽に稼げる金だと思ってるらしい。今でさえ人手が足りてないってことは、あんまり気にしちゃいないのさ。\n\nあいつのリストの最初の何品かは簡単に手に入るはずだ。手伝ってくれる奴には、けっこうな額の金になるぜ。\n\nここから東にいるHatefuryのsatyrからhornsとclawsが要るんだ。そいつを持ってきてくれたら、リストの残りに取りかかろう。", "卑劣な生き物だよ、satyrってのは。話じゃ、奴らはどういうわけかナイトエルフと繋がりがあるらしいが、俺はそれを信じていいものかよく分からん。\n\nそんな話になったのは、数年前に奴らを戦争に引き込んだ、あるエルフのせいだと思う。それ以来、世界はすっかり変わっちまった。ずっと危険に、ずっと恐ろしくなった。", "いいぞいいぞ、{name}。質がいいかどうかは分からんが、Leftwitchが特定の種類を欲しかったんなら、そもそもReclaimersをここへ送り出す前にそう指定しておくべきだったんだ。\n\nリストの次の品に取りかかるってのはどうだ？", 0xe45ccdc7, 0x53a9f26d, 0x57a7170f, 0x099adac5, 0x85c4b847, "....." },
  [1459] = { "Reclaimers Inc.のための試薬", "Scorpashi Venomの小瓶を$N1本とAged Kodo Hidesを$N2枚、DesolaceのKreldig Ungorのところへ持って行って下さい。", "Leftwitchのリストの次は……どれどれ……ふむ。ああ、これだ。\n\n簡単なもんだが、指示はずいぶん細かい。scorpashiのvenomと、kodoのhideが要るそうだ。但し書きによると、どっちも決まった生き物から取れってさ。venomはscorpashiならどれでもいいが、hideはaged kodoからでなきゃだめだ。死にかけのや、年老いたのはだめだとよ。\n\nメイジってやつはさ、あいつらが欲しがるもんときたら……ほんと妙なんだよ。", "kodoやscorpashiの居場所を教えられなくてすまない。この辺りにはあまり詳しくないし、探索する時間もなかったんだ。", "お前さんの助けは本当にありがたいよ、{name}。おかげでDesolaceでの滞在が少なくとも半分に縮まってる。お前さんの助けがあれば、あっという間にIronforgeに戻って足を温めてられるさ。\n\nこのリストを片付けて俺が家に帰ったら、訪ねてきてくれ。必ずエールを一杯おごるよ。\n\nだがそれまでは、残りの試薬を集めるとしよう。", 0xe45ccdc7, 0x4938a153, 0x2e8f8320, 0xa6c85e6f, 0x29a4da1f, "....." },
  [1462] = { "Earth Sapta", "新たにEarth Saptaを受け取るには、Seer Ravenfeatherに話しかけて下さい。", nil, nil, "これを持っていけ。そして忘れるな、これは神聖なものだ。", 0x9c7e1740, 0xcbef76ba, nil, nil, 0x794bb81e, "..mm." },
  [1463] = { "Earth Sapta", "新たにEarth Saptaを受け取るには、Canaga Earthcallerに話しかけて下さい。", nil, nil, "信頼の証に1つやろう。お前はもう一度自分を証明しとる。だが、これからはもっと気をつけるべきだと俺は思うぞ。", 0x9c7e1740, 0xb10078b8, nil, nil, 0x8882c1af, "..mm." },
  [1464] = { "Fire Sapta", "Telf Joolamと話し、Fire Saptaをもう一つもらう。", nil, nil, "その心に炎が燃えさかるように、{name}。\n\n精霊たちがお前を待っている。", 0xe8738c8b, 0xdfafed76, nil, nil, 0xeab93f1f, "..mm." },
  [1465] = { "Vahlarrielの捜索", "Malem PendantをDesolaceのVahlarriel Demonslayerに返して下さい。", "荷馬車の捜索を続けると、pendantだけでなく、南へ続く足跡も見つかった。遠くには、大きな砦から煙が立ち上っているのが見える。その煙は建物が燃えているのではなく、手入れされた火から出ているものだ。Malem家の者たちがまだ生きているなら、あの方向へ連れていかれたのだと直感が告げる。\n\nNijel's PointのVahlarrielには、見つけたpendantを見せるだけでなく、南に人の気配があることも知らせるべきだろう。", nil, "腹立たしい！何もかもが大失敗だ！\n\nあの2人には、ここへ来るのがどれほど危険か警告してあった。それが今や、どちらも行方不明……あるいはもっと悪いことになっている。\n\n近くの砦へ向かう足跡を見たと言ったな？それが一番の望みかもしれん。\n\n地元の者たちの話では、その砦にはBurning Bladeの連中がはびこっているそうだ……悪魔の大義に身を捧げたオークどもだ。奴らはHordeの大多数の信条を代表しているわけではないかもしれんが、邪悪であり、偵察しているところを見つかれば即座に殺しにかかってくるだろう。", 0x7ca9c473, 0x2a425383, 0x27905566, nil, 0x24532a73, "...m." },
  [1466] = { "Reclaimers Inc.のための試薬", "Felhound Brainsを$N1個、Nether Wingsを$N2個、Doomwarder Bloodの小瓶を$N3本、DesolaceのKreldig Ungorのところへ持って行って下さい。", "これが最後の品だ。嘘は言わない、きれいな仕事じゃない。それに、他の品よりちょっと時間がかかると思う。\n\nさて、警告はこれくらいにして、始めようか。Leftwitchが言うには、必要なのは、mana eaters、mage hunters、ley huntersのどれかから取ったbrainsを十個。nether maiden、sister、sorceressから取ったnether wingsを十枚。それから……doomwarder captainかlordから取ったdoomwarder bloodを十瓶だ。\n\n簡単だろ？ はあ……こいつを断りたくなっても、無理もないと思うよ。", "Desolaceにこんな悪魔どもがいるなんて知りもしなかった。最後に読んだ話じゃ、何年も前にナイトエルフが引き払ってからは、centaurがこの土地をほとんど支配していたはずだ。\n\n奴らがなぜここに住みついたのか、それにどうやってなのか、気になるな。", "正直に言うと？そんなことができるとは思わなかったよ。君はすごいな、{name}。メイジの実験のために悪魔どもに立ち向かって、しかも無事に戻ってくるなんて。お見事！\n\nIronforgeに戻ったら、Roettenに君のことを直々に話しておくよ。", 0xe45ccdc7, 0x4c27382b, 0x3b351b55, 0xe2c29f34, 0x1036a532, "....." },
  [1467] = { "Reclaimers Inc.のための試薬", "Leftwitch's PackageをIronforgeのRoetten Stonehammerのところへ持ち帰って下さい。", "報酬をもらうには、Ironforgeに戻ってRoetten本人と話さなきゃならない。どのみち、あいつはLeftwitch's packageを片づけられて大喜びするだろうさ。これを渡せば、報酬をもらうには十分なはずだ。\n\nそれに心配するな。俺が戻ったら、ちゃんとあんたのことを口添えしといてやるよ。Desolaceにはもう長くいないはずだからな。", "よく来たな、{name}。商売は大繁盛、Ironforge中に金床を打つ音が響き渡り、ふいごは炉の火を熱く燃やし、女房は今夜の夕食の後のデザートにパイを焼いてくれている。これ以上素晴らしい人生があるかね？", "ああ、Desolaceから届いたLeftwitch宛てのpackageか。素晴らしい。仕事ぶりにも時間どおりに来てくれたことにも感謝するよ、{class}。このちょっとした仕事だけでも、仲間になってくれて嬉しいね。\n\n報酬はここにある。Reclaimers Inc.は一週間のきつい仕事にいつでもたっぷり払うってことを、みんなに知らせてやってくれ。", 0xe45ccdc7, 0xda6fadc1, 0xa74df9be, 0x305a2aa8, 0x0f265115, "....." },
  [1468] = { "Children's Week", "Children's Weekの期間中に面倒を見る子供と話すため、Human Orphan Whistleを使って下さい。", "この孤児院を手伝って下さるのですか? あなたに恵みあれ、友よ。Children's Weekの援助は、大変貴重なものとなりましょう。\n\nこの笛をお持ち下さい。これは短期間……通常はChildren's Weekの間だけしか使えません。笛を吹くと、面倒を見る承諾をした子供と話すことができるでしょう。もう一度吹くと、子供は帰ります。\n\nぜひ{name}、笛を吹いて子供とお会いになって下さい! その子はあなたにすごく会いたがっていると思いますよ。", nil, "うーん……やあ。僕の名前はRandis、あなたが僕の面倒をみてくれるんだよね? 冒険者なんだね、ママとパパみたいな。会えて嬉しいよ。\n\n一緒にいろんな楽しいことをしたいな。やりたいことがいくつかあるんだ。あと、寮母さんが言うには、期間中はきょうだいみたいになってくれって。すっごくそうしたいです、先生。", 0x70336621, 0x73f8ace3, 0x427476d3, nil, 0xba88d1b9, "...m.", nil, nil, nil, nil, 0x75b10d50 },
  [1469] = { "Rhapsodyの話", "Atal'ai Tablet FragmentをStormwindのBrohann Caskbellyに渡して下さい。", "飛ぶ前に、俺はスタウトを樽ごと一つ飲み干したんだ。ヒック!\n\nいやあ、大した飛行だったぜ。Brohannを後ろに従えてびゅんびゅん飛び回ってな。でも神殿は見えなかった。ヒック!\n\nいや、見えなかったんだよ、ちょいと酔いが回りすぎて乗騎から落ちるまではな。まっすぐ水に飛び込んで、底へ引きずり込まれた。気づいたら、気味の悪いトロールどもに囲まれてたんだ。もちろん大急ぎで泳いで逃げたさ!ついでにこのトロールの土産までちょろまかしてきた。ほら、これをBrohannに持っていって、奴の神殿は確かにあそこの下にあるって伝えてくれ。ヒック!", "ようやく戻ってきたか、{name}。最後に話してから随分と経ったな。私のクエストのことなど忘れてしまったのかと思っていたよ。\n\nあの抜け目のないグリフォン乗りは見つかったか？何か報告はあったか？", "Rhapsody Shindigger! そうだ……どうしてあんな名前を忘れられたものかな?\n\nでは奴は神殿が沈んだことを初めから知っていたのか? まったく、それが分かっていれば君の足労もずいぶん省けただろうに。\n\nだがこのAtal'aiの遺物! いやはや、大変な発見だぞ!", 0x446abea7, 0xc3da0aa6, 0x14b04ec9, 0xc9373946, 0xa73985d2, "....." },
  [1470] = { "ヴェールを貫いて", "Venya MarthandにRattlecage Skullを3個届けて下さい。", "こんにちは、幼き者よ。どうやらまだWarlockの道を進んで間もなく、その力が理解できていないようだね。しかし学ぼうという熱意は感じるよ。\n\nそしてお前さんは学ぶだろう。\n\n無知に力は無い。知識は私たちの最大の力だ。私たちはその応用によって混沌の魔法と空虚をコントロールすることが可能なのさ。意思によりそれらを捻じ曲げることによってね。\n\nお前さんに使い魔をお前さんの意思と結びつける方法を教えてやろう。だがその前に、廃墟となった鍛冶場付近にいるRattlecage Skeletonの頭蓋骨を3個持ってきておくれ。", "お前の力はまだ小さいが、すでにその可能性を感じ取っているのだろう。\n\nその力が我らの内を駆け巡れば、死者でさえ生を感じられるかもしれん。", "まだ試されておらず、学びも浅いが、お前はimpの召喚と束縛を習得するに足る力を持つことを証明した。impの小ささに惑わされるな。肉体の力には欠けるが、お前の役に立つ力と狡猾さを備えている。\n\nよく聞け、{name}。この教えは二度と繰り返さぬ。その習得はお前自身に委ねよう。", 0x8a25b592, 0xddd91cad, 0xb55098f9, 0x14b29f22, 0x89ff488a, "....." },
  [1471] = { "拘束", "Runes of Summoningを使い、voidwalkerを召喚して征服し、UndercityのMagic QuarterにいるCarendin HalgarにRunes of Summoningを返して下さい。", "下にある召喚の輪は、もう見ただろう?縛られていないvoidwalkerを呼び出せるのは、あそこだけだ。\n\nこのルーンを使えば、それを呼び出せる。そうしたら、武器と魔法の力でねじ伏せねばならない。\n\n屈服させれば、それはお前に仕えることになる。そうなったら私のところへ来い。召喚の呪文を解き明かしてやろう。そうすれば、お前の望むどんな目的にも仕えるようになる。", "お前の成功の知らせを待っているぞ、{name}。もっとも、失敗すれば、私の期待に応えられないことなど些細な悩みにすぎなくなるだろうがな。", "よくやった、{name}。では、voidwalkerを召喚するための呪文を授けよう。\n\nそれが君に向けて解き放った力は、今や君が操るものだ。賢く使え。", 0x5926988f, 0xb0c8ef2d, 0x89f8824d, 0x55fcbafc, 0xc8611eae, "....." },
  [1472] = { "魂を貪る者", "Temple of the DamnedのGodrick Farsanと話して下さい。", "sayaadは魂を貪る者であり、意志を支配する者であり、心を惑わす者だ。深い邪悪と、ただ一つの目的を持つ存在だ。\n\n正しき者も邪な者も、民話ではその通り名を使う。女はsuccubus、男はincubusとな。\n\nその悪魔は、刺激によって我らの世界へおびき寄せねばならない――清らかで愛にあふれた定命の者たちの心臓だ。sayaadはそれに抗えないだろう。そうしたら、お前はそれを支配し、己のものとできる。\n\n神殿の中にいる私の助手、Godrick Farsanと話せ。餌を見つける手助けをしてくれるだろう。", nil, "Carendinに遣わされたのか? では{name}だな。\n\n私の視力が失われているからといって、侮るな。今の私は、その奥にあるものを、かつて知らなかったほどの明晰さで見ている。かつて呪いと思っていたものは、今では恵みだ。", 0xc90e9da6, 0x8c9c2de8, 0xd89bee8d, nil, 0x4683a2b5, "...m." },
  [1473] = { "無の生物", "Egalin's Grimoireを取り戻し、Temple of the DamnedのCarendin Halgarに渡して下さい。", "皆の意見では、お前はvoidwalkerの召喚を学ぶ準備ができているようだ。\n\n彼方に広がる混沌から生まれた存在だ。召喚しても制御できなければ、お前は引き裂かれるだろう。\n\n最初のvoidwalkerはEgalinによって召喚された。そして、その手順は彼の魔導書に記されている。\n\nあいにく、それはScarlet Crusadeの手先に盗まれてしまった。そいつは西にある塔の拠点に、それを隠し持っている。それを私のところへ持ってくれば、その知識をお前に授けよう。", "Egalinは私を教えた師だった。ほとんど目を向けることもなく、彼は自ら召喚したvoidwalkerを従えることができた。\n\n私の番が来たとき、私は自信過剰だった。自分が振るう力を侮るな、{name}。その力は用心深い者でさえ呑み込むのだ。", "ああ、これは素晴らしい。おそらくPerrineは、我々から盗み出したあのかび臭い本の真の力を知らなかったのだろう。\n\n二度と我々の手から離れることはない。見ておけ、{name}。この呪文の構造と、お前の力を注ぎ込むべきやり方をな。", 0xb03c11f0, 0xb78fe20e, 0x67827b5f, 0x4c05983d, 0xa9462493, "....." },
  [1474] = { "拘束", "Pure Heartsを使い、succubusを召喚して征服し、UndercityのMagic QuarterにいるCarendin HalgarにPure Heartsを返して下さい。", "この心臓を使って召喚の輪で呪文を唱え、succubusがくぐってくる扉を開け。お前の力は以前より強くなっているが、succubusを倒すにはその力のすべてが必要になるだろう。\n\nその魅惑には気をつけろ、{name}。多くの強き心がその意のままに縛られてきたのだ。打ち負かせば、succubusは虚無へと送り返される。そうしたら、お前の命令一つでそれを呼び出す呪文を教えてやろう。", "虚無の彼方からの力のうち、succubusは最も危険なものの一つだ。弱い者ほどたやすくその手玉に取られるからな。\n\n今も、そしてこれからも、それを忘れるな。", "またしても見事だ、{name}。お前ほど素質のある若いウォーロックを見たのは、ずいぶん久しぶりだ。安心しろ、私はこれからもお前の成長を見守り、来るべき試練に備えさせ、力を貸してやろう。\n\n今は、新たに従えたsuccubusを召喚する呪文を見せてやろう。", 0x5926988f, 0xddee7319, 0x7ce3671d, 0xcfab2997, 0xf5810adb, "....." },
  [1475] = { "Temple of Atal'Hakkarの中へ", "Atal'ai Tablet 10個を集めてStormwindのBrohann Caskbellyに渡して下さい。", "伝説によれば、The Temple of Atal'Hakkarは古の神、Hakkar the Soulflayerに捧げられた聖なる社だ。Atal'aiという凶暴なトロールの部族が守っていて、難攻不落だと噂されている。\n\n今ではPool of Tearsの底に沈んでいるから、神殿から遺物を持ち出すのはなおさら難しい。だが、それこそお前さんにやってほしいことなんだ、{name}。\n\n無傷のAtal'ai Tabletsを集めて力を貸してくれ。それを持ってきてくれれば、わしは英雄としてExplorers' Guildに戻れる。栄光は二人で分かち合おうじゃないか。", "私の経歴にゆっくりと夕暮れが訪れようとしている今、{name}、Explorers' Leagueのための最後のクエストを手伝ってもらうべく、君を頼りたい。この老いた骨にSwamp of Sorrowsと沈んだ神殿に挑む力が残っていれば、君と肩を並べて戦っているところなのだが。\n\n誇りがあるゆえに、Atal'ai Tabletsの収集に君の助けを求めるのはつらい。だが、老いはそれを避けられぬものにしてしまう。\n\nどうか助けてくれ、{name}。Explorers' Leagueの最後の命を果たして引退したいのだ。", "Atal'ai Tabletだ! ありがとう、{name}!\n\nこれをExplorers' Leagueに届ければ、我々の名は共に歴史に刻まれる。老いぼれドワーフが人生最後の務めを果たすのを助けてくれたのだ。そのことには永遠に感謝する。", 0xa403bf55, 0x7f6d6719, 0x09e59f8e, 0xa14e8aae, 0x4584ecfd, "....." },
  [1476] = { "清らかな者の心臓", "Dalin ForgewrightとCorma Villardの心臓を、Temple of the DamnedにいるCarendin Halgarのところへ持って行って下さい。", "succubusをおびき寄せるには、清らかな者の心臓が要る。だが、悪徳を持たぬ定命の者などいるだろうか?\n\n漏れ聞いた話の断片から、うってつけの人間を2人見つけた。\n\n一人目はDalin Forgewright。Greymane Wallで同族に拒まれたLordaeronの避難民の世話に身を捧げている男だ。\n\nもう一人はCorma Villard。失った恋人に今も操を立て、その手がかりを求めてWetlandsをさまよっている女だ。\n\n二人の心臓をCarendinに届けろ。だがまずは、お前の獲物を見せてやろう。", "{name}、これまでのお前の進み具合の速さには嬉しい驚きだった。心臓を持ってくれば、再び私を感心させられるだろう。", "善良な男の心臓も、こうして見ればどれも大して変わらぬものだな、そう思わんか?\n\n我々はこの手のことについて……少々……違う見方を持っているのかもしれんが。ともあれ、これで十分だ。この純粋さなら、succubusも惹きつけられるに違いない。", 0xed4dadf4, 0x458b0130, 0x6fb0be4e, 0x8c61a82d, 0x50a945bb, "....." },
  [1477] = { "大切な物資", "Watchmaster Sorigalと話して下さい。", "我らのメイジたちはBlasted LandsのNethergarde Keepで研究を行っている。Dark Portalsを理解するうえで欠かせない研究だ。彼らにはほぼ絶え間なく物資が必要だが、Nethergardeへの補給線は心もとない。\n\n物資が確実にNethergardに届くよう、君が手を貸さねばならない。DarkshireのWatchmaster Sorigalのもとへ出頭し、彼の指示に従え。この任務では敵地へ踏み込むことになる、{name}。覚悟しておけ。", nil, "Andromathからの使いか? いいだろう。君に任せる重要な任務がある……。", 0x9d8ff76c, 0x71a7d15d, 0x3ad8891c, nil, 0x84281d45, "...m." },
  [1478] = { "Halgarの呼び出し", "UndercityのCarendin Halgarと話して下さい。", "ああ、{name}!ちょうどCarendin Halgarから知らせが届いたところだ。さらなる修行のために君に会いたいそうだ。\n\n誇りに思っていいぞ、{name}。Master Halgarが自ら若いウォーロックを指導しようと考えることなど、そうそうあることではないのだからな。\n\nUndercityのMagic Quarter、Temple of the Damnedの近くで彼に会えるだろう。", nil, "よろしい。Ageronがなんとかお前を見つけてくれたのだろうな、{name}。おしゃべりや挨拶に時間を無駄にせず、訓練に集中することにしよう。お前が学ばねばならぬことはまだたくさんある。", 0xe177dd44, 0xf7495b7c, 0x60a08a74, nil, 0xe35c74a7, "...m." },
  [1479] = { "Bough of the Eternals", "孤児をDarnassusの銀行へ連れて行って下さい。銀行はBough of the Eternalsとして知られる木をくりぬいたものです。", "ナイトエルフは銀行を木の中に置いてるって話を聞いたんだ――クマの形をした木だって!すっごくかっこいい!ナイトエルフって自然とかが好きなところがいいよね。でも、クマはもう最高にすごいんだ!\n\nDarnassusのクマの木を見に連れてってくれない?お願い!近くまで乗せてってくれる船があるし、そんなに時間もかからないはずだよ。お願い、お願い、お願い!", "まだ着かないの?", "わあ、想像してたよりずっとすごかった――Bough of the Eternalsだよ! あんなに大きいなんて思わなかったけど、本当に大きかった! てっぺんの鳥も見た?! どうやったら枝があんな形になるんだろう!\n\nDarnassusに連れていってくれてありがとう、{name}。最高だね!", 0xf3e0870f, 0xb7d47cf2, 0x68cd4a01, 0x63e6b64c, 0x4ca74036, "....." },
  [1480] = { "堕落させる者", "Flayed Demon SkinをDesolaceのMaurin Bonesplitterのところへ持って行って下さい。", "破れたskinは腐った臭いがする。乾いてもろそうに見えるのに、驚くほどしなやかだ。\n\n広げてみると、片面に何かの言語らしき赤い印がはっきりと見える。skinの下の方には、何かの署名だと思われる、とてもはっきりした記号がある。\n\nMaurinなら、これについてもっと詳しく教えてくれるかもしれない。", "Burning Bladeは、自分たちが本当はいかに弱いか気づき始めている。奴らの魔法は哀れなもので、力もか弱い。\n\n奴らの唯一の力は仕えている者たちから来るもので、真の力と知識への理解から来るものではない。", "ふむ、このルーン文字は確かに言語だ、{name}。古い言語だな。Eredunの言語にわずかに似ているようだが、違いは大きい。私の見立てが間違っていなければ、これは何らかの契約書だ……ここだ、そう、この印が悪魔の署名だ。Lord Azrethoc。", 0x8efbe8e1, 0x1590edd2, 0x0b712ed5, 0x2e3a1856, 0x5068ca0d, "....." },
  [1481] = { "堕落させる者", "Shadowstalker ScalpをDesolaceのMaurin Bonesplitterのところへ持って行って下さい。", "然るべきreagentsがあれば、この悪魔の王を見つけ出せると思う。\n\n奴が本当に私の睨んだとおりの力を持っているなら、危険な生き物から集めた品が必要になる。だが君は大族長の名のもとに動いているのだから、きっと私の任務を引き受けてくれるだろう。\n\nまず、奴が遠見に対して張っている守りを破らねばならん。そのためにはsatyrのscalpが必要だ。だが、どのsatyrでもいいわけではない。scalpはHatefury shadowstalkerのものでなければならん。\n\nDesolace北東部の古代の遺跡で、奴らを探せ。", "間違ったscalpを持ってくるなよ、{class}。誤った触媒を使えば、我々の死を招きかねん。悪魔の王は、自分を覗き見ようとする者を殺すための備えの呪文を身に帯びているかもしれんのだ。\n\n運命はすでに十分な苦痛を私に与えてきた。", "shadowstalkerどもはお前を殺せなかったか、{class}。見事だ……実に見事だ。\n\nこのscalpは私の呪文に申し分ない。お前がいない間に、呪文に必要な他の試薬もいくつか集めておいた。\n\n準備はほぼ整った。あとは呪文の焦点となるもの……悪魔の王の姿とその居場所を映し出すものが必要なだけだ。", 0x8efbe8e1, 0xf6e13fb9, 0x6a93925d, 0xf2335f98, 0x90fced86, "....." },
  [1482] = { "堕落させる者", "Oracle CrystalをDesolaceのMaurin Bonesplitterのところへ持って行って下さい。", "oracle crystalがあれば申し分ない。nagaが自分たちのoraclesに使わせるために作るものだ。\n\nここから北西の海岸沿いに、広大な珊瑚礁がある。nagaは岸の近くに来た時、そこを住処にしているのだ。oraclesはそこで見つかる。Slitherbladeは恐ろしい連中で、侵入者に容赦はしない。気をつけて、急いで行ってこい。\n\n君が戻ったら、この悪魔の王Azrethocを見つけ出す算段をしよう。", "oracle crystalを受け取る準備はできているぞ、{class}。このLord Azrethocを見つけ出して倒せば、我々二人とも大族長から大いに目をかけてもらえるだろう。手を組んで、しかも素早く事を運ぶのが得策だ。そうすれば我々自身の目的を進められるし、大族長の覚えもめでたくなる。", "貴重なoracle crystal……傷一つない……美しい。まさに。\n\nすぐに始めよう。この悪魔の王を見つけ出すことが我々の最優先事項であり、その討伐には全力を注がねばならぬ。\n\n一歩下がれ、{class}。この悪魔が何者で、どこにいるのか見てみよう。", 0x8efbe8e1, 0x51b70be4, 0x86752ef1, 0x57be0104, 0xf4d871bc, "....." },
  [1483] = { "Ziz Fizziks", "Windshear CragのZiz Fizziksと話して下さい。", "Venture Companyはゴブリンの頭脳をたくさん盗んでいっちまったが、時々、それを取り戻す機会があるんだ。\n\n以前、Stonetalon MountainsのVenture Company組織がGerenzo Wrenchwhistleを雇ったんだ……そいつノームだぜ! 別のエンジニアでZiz Fizziksってのがいて、そのせいでひどく驚いてたよ。ZizはTinkers' Unionで職を見つけてくれってオレに泣きついてきたんだ。いくつか仕事を回したけど、助けが要るに違いないよ。\n\nあいつをちょっと訪ねてくれるだろうか? Windshear Cragの西の端に駐在してるよ。", nil, "Venture Companyの上層部は奴隷使いだと思ってたけど、そいつら全員よりもっと残酷なSputtervalveに会っちまったよ!\n\nハン! それでも職を失うよりはマシ、だと思う……。下手すりゃ、Gerenzoと一緒に働かなきゃならねえ。あんたが手伝いに来てくれたんなら、頼みたい仕事がある。", 0x6cf0b999, 0xd85f0063, 0x5c119beb, nil, 0x4bc25ea8, "...m." },
  [1484] = { "堕落させる者", "DesolaceのTakata Steelbladeと話して下さい。", "この生き物は、私が予想していたよりはるかに危険だ。Takataはきっと、私にそのような生き物を相手にする力があるのかと疑っているだろう。今起きたことを知らされなければ、彼の名誉を傷つけることになる。\n\nあの剣士と話し、許しが得られるなら悪魔を倒すつもりだと伝えてくれ。だが、あまり強く押してはならん。彼が自分で思いついたと思わせた方がいい。", nil, "Maurinと悪魔の王との間で今起きたことを見ていた。あの化け物は、幻影の姿でさえ、私の仲間のウォーロックより強い力を持っているようだ。あいつにあの怪物を倒す務めが果たせるのだろうか？私自らが行くほうが大族長のためになるだろうが、ここでの責任がある以上、自分の名誉のためにこの悪と戦おうとここでの任務に背を向ければ、私は氏族の恥となるだろう。", 0x8efbe8e1, 0xfa6ed566, 0xa85d99cf, nil, 0x1eed7fd6, "...m." },
  [1485] = { "Vile Familiars", "RuzanにVile Familiar Head 6個を渡して下さい。", "我らより前にいたウォーロックたちはHordeの不信を買った。我らは許されてはいるが、好かれてはいない。\n\nだからといってウォーロック同士の結びつきが強まったわけではない。多くの者が人目を避けて暮らし、ひとりで魔術に手を染めることを選んでいる。お前をどちらかの道へ導こうとは思わない。ただ、お前の成長を助けるだけだ。\n\n召喚の術を教える前に、北東の洞窟にいるvile familiarsの首を6つ持ってこい。", "魔法で召喚する存在を制御できることが肝要だ。{class}の道を学ぼうとする者はただでさえ少ない。準備が整う前に何かを教えて、お前の命を無駄にさせるような危険は冒せん。", "{class}としての修行を通じて、お前はさまざまな種類の存在を呼び出すことを学ぶだろう。そうは見えぬものもいるが、どれも役に立つ道具だ。\n\nimpの小ささに騙されるな。お前も気づいたとおり、あれでも侮れぬ敵だ。", 0x8ce65439, 0x2ec68e02, 0xbf697324, 0x5b74965b, 0xa4f071a9, "....." },
  [1486] = { "Deviate Hides", "Wailing CavernsのNalpakは、Deviate Hide 20枚を求めています。", "Naralexが悪夢の奥深くへと沈んでいくにつれ、奇妙な獣の一群がBarrensの地下からWailing Cavernsへと現れました。\n\nこのdeviateの生き物たちは、奇妙で異界的な性質を持っています。本質は邪悪ですが、ここKalimdorに彼らがいることから、何か良いものが生まれることもあると私は考えています。彼らの皮は、革細工の技に特に役立つと思うのです。\n\nその任を引き受けてくれるなら、下の洞窟へ入って、deviate hidesを取ってきてください。", "この洞窟に巣食う変異した生き物のhidesを調べることに、とても興味があります。いくらか集められましたか、{class}？", "この皮を集めてくれた働きは、無駄にはならん、{name}。\n\n君の献身に感謝する。", 0x1bed65d5, 0x27d84e49, 0x3e2a3766, 0x0dcdb776, 0x715ed582, "....." },
  [1487] = { "Deviateの根絶", "Wailing CavernsのEbruは、Deviate Ravager・Deviate Viper・Deviate Shambler・Deviate Dreadfangをそれぞれ7匹ずつ殺すよう求めています。", "Naralexには気高い目標がありました。\n\n私たちの偉大な指導者は、Emerald Dreamに入り、この過酷な地をかつての緑豊かな森へと再び育て直す手助けをしようと志したのです。けれど、何かがひどくおかしくなってしまいました。\n\nNaralexの夢は悪夢に変わり、堕落した生き物たちが洞窟に棲みつき始めたのです。\n\nDisciples of Naralexの中には私たちの師を目覚めさせようとしている者もいますが、私の関心は、この洞窟から邪悪な獣たちを取り除くことにあります。\n\n洞窟に立ち向かってください、{name}。そしてdeviateの落とし子たちを根絶やしにしてください。", "{name}、私たちDisciples of Naralexにはあなたの助けが必要です。私たちの師匠が歪んだ悪夢に囚われ、仲間の数は減る一方です。今この洞窟に巣食う堕落した生き物たちに立ち向かうだけの力が、私たちにはありません。\n\nお願いです、洞窟に入り、変異した生き物たちと戦ってください！", "Disciple of Naralexの一人として、あなたの勇気を称えます、{name}。\n\n洞窟を浄化する助けとなったことは、Barrensの回復を見届けるという我らの長い苦闘の第一歩です。\n\nありがとう。あなたに繁栄がありますように。", 0x97d1256c, 0x65cf05d4, 0xc616bee2, 0x56e545f4, 0x09635dc9, "....." },
  [1488] = { "堕落させる者", "Lord AzrethocとJugkar Grim'rodを倒し、DesolaceのTakata Steelbladeのところへ戻って下さい。", "このLord Azrethocのことは何も知らんが、Maurinに同意する。奴は止めねばならん。特に、自らの目的を果たすためにBurning Bladeへの影響力を得ようとしているのならな。\n\n君はすでに大族長に力を貸したいという意志を示した。君になら、仲間を集めてこの悪魔の王とそのウォーロックの従者を倒すことを任せられる。\n\n準備ができたら、まっすぐ南へ向かえ。脅威を終わらせたら、私のもとへ戻ってこい。", "Hordeに栄光を、そして敵に死を、{name}!\n\nDesolaceの悪魔どもは、かつてないほどの脅威となっている。汚らわしい奴らが次から次へと現れるようで、大族長のもとへ戻れるという望みは薄れていくばかりだ。\n\n相手にするのがcentaurだけならよかったのに、と時々思う。", "我ら皆にとっての大いなる勝利だ、{name}。お前の成功を共に喜ぼう。我々のこの地での未来は、かつて思っていたほど暗くはないと今は信じている。\n\n悪魔どもは討たれ、Burning Bladeの企みは失敗に終わり、いつの日か我々は再び安心して故郷と呼べる場所を持てるだろう。", 0x8efbe8e1, 0x1dffc6b8, 0x5e0f3483, 0xa0eb60f9, 0xe22be9d2, "....." },
  [1489] = { "Hamuul Runetotem", "Hamuul Runetotemと話して下さい。", "君が持ってきてくれた甲羅は汚染されてる。こんなもの今まで見たことない。オアシスの水がこの原因だと思うんだ、この地に発生した「混乱」を感じるよ。まるで、大地は眠っていて、目覚めることができないみたいだ。\n\n汚染の原因はWailing Cavernsに違いない。でもその前に、ドルイドの長老Hamuul Runetotemと話してきてほしい。長老には、Barrensに起きている事を知らせておいた。長老は英知のある人だから、助言をくれるはずだ。\n\n長老はThunder BluffのElder Riseにいるよ。", nil, "ごきげんよう、{name}。歓迎しているぞ。そなたの持てる力をすべて集結させるよう、勧める。我々が今そなたに頼もうとしている仕事は……恐ろしく危険なものだからな。", 0x034c803e, 0x658f0ea3, 0x9a855028, nil, 0x4f036dc1, "...m." },
  [1490] = { "Nara Wildmane", "Nara Wildmaneと話して下さい。", "私は夢の地へ入り込み、Wailing Cavernsに住むドルイド狂信者を夢に見たのだ。彼らの目的はかつて崇高なものだったが、道を外れてしまったようだった。今や彼らはBarrensに滲み出る汚染の下僕なのだ。\n\n私は年老いて、力も衰えている。夢の地に長くいることは出来ず、汚染されたドルイドたちのこともわずかしか分からなかった。\n\nだが、Naraは若く、魂も猛々しい。私が夢から離れたあとも、彼女はその夢の中に残っていたのだ。\n\nNaraと話をしてくれ。天幕の中のあちらにおる。", nil, "ええ、それは本当ですよ。Wailing Cavernsにいるドルイドたちのことを知っています。ねじ曲がり、鱗に覆われた顔も見たことがあります。彼らの犯した罪、それに計画も知っています。\n\n彼らを止めなくてはなりません、{name}。", 0xa9a75b81, 0x236c53c8, 0xdac1c62f, nil, 0xcfbd0a8a, "...m." },
  [1491] = { "頭の良くなる飲み物", "Wailing Essence6つをRatchetのMebok Mizzyrixに渡して下さい。", "まあ、raptorの角はあまりうまくいかなかった。でも大丈夫――最初の一回で金持ちになったやつなんていないさ！それに、俺のスマートドリンクにもっと効きそうなものを見つけた気がするんだ！\n\nWailing Essenceっていう物質があってな、そいつがBarrensの奇妙な植物や動物の原因じゃないかと俺はにらんでる。そいつを手に入れてくれたら、俺のドリンクで試してみるよ！\n\n聞いた話じゃ、そのエッセンスは西のWailing Cavernsにいるエクトプラズムの生き物の中にたまるらしい。そいつらを狩って、エッセンスを集めてきてくれ。", "私のwailing essenceはどこだ？", "すごいや、取ってきたんだ! 試すのを待てないよ。そいつがオレを金持ちにしてくれるって、分かるんだ!\n\nありがとうよ、{name}。これ持っていきな。オレが金持ちになってから、もっと送ってやるよ。約束する!", 0x3bd3c186, 0x92e0631f, 0x440930e0, 0x1ed90584, 0x985f6f88, "....." },
  [1492] = { "Wharfmaster Dizzywig", "Secure CrateをRatchetのWharfmaster Dizzywigに届けましょう。", "Old Worldにいる仲間たちに、薬や試薬、その他の品を詰めた箱を送らねばならん。私にはそれをRatchetの波止場まで実際に届けるだけの時間がほとんどないし、最後の隊商はもう出てしまった。\n\nできれば、これをWharfmaster Dizzywigのところへ持って行ってほしい。彼が必ずBlackwater Cove行きの次の船に載せてくれるだろう。", "次の船に乗りたいのか、それとも船に積みたい品があるのか？", "小さな木箱。ええ、これを置く場所は、船にありますとも。船は次の潮流で出航します、もうすぐだと思いますよ。いいですね、では記帳させてください。\n\nあなたの旅が良いものでありますように、{class}。", 0x68543425, 0x17f5da95, 0xb65ac0a7, 0x189f5df8, 0xd447e508, "....." },
  [1498] = { "防御の道", "BarrensのFar Watch PostにいるUzzekに、Singed Scale 5枚を渡して下さい。", "ウォリアーとして、我々の最も重要な務めの一つは……守ることだ。我々はHordeの盾であり、弱い同胞を守っている。我らの仲間に加わりたいなら、その気骨を俺に示してみろ。\n\nDurotarのThunder Ridgeへ行け。lightning hidesとthunder lizardsが棲む場所だ。獣どもを狩れ!奴らよりお前のほうがタフだと見せてみろ!奴らの攻撃に耐え、その証としてsinged scalesを一山持ってこい。\n\nこれを成し遂げたら、教えてやろう。", "scalesは持っているか、{name}？thunder lizardsの攻撃に耐えられないようでは、私の教えは何の役にも立たん。", "ほう。thunder lizardどもを倒してきたようだな。これで君が強靭であることは証明された。では次は、強靭な皮と抜け目のない動きが合わさって、いかに鉄壁の守りとなるかを見せよう。\n\n教えをよく学べ、{name}。そして次の指南に備えておけ。", 0xd3cf9699, 0x7867009f, 0xda36a73f, 0x7db1e33a, 0x88e15585, "....." },
  [1499] = { "Vile Familiars", "Zureetha Fargazeと話して下さい。", "Zureethaは、お前のような新米を送り出して、お前がvile familiarsと戦った場所の近くの洞窟にいる生き物の数を減らす手伝いをさせている。\n\nZureethaを手伝って経験を積むのは、お前にとって良いことだと思う。impの問題を手伝ったと必ず伝えるんだ。きっと報酬をくれるだろう。", nil, "よくやった、{name}。\n\nあの邪悪な使い魔どもは、Burning Bladeの内にある暗き力の飼い犬にすぎなかったが、奴らを相手にした君の成功は、この先のより大きな功績を予感させる。", 0x8ce65439, 0x71f688ac, 0xd440d0c7, nil, 0x1dac4028, "...m." },
  [1501] = { "無の生物", "Tablet of Vergaを取り戻し、OrgrimmarのGan'rul Bloodeyeに渡して下さい。", "ウォーロックはもうほとんど残っていない……危険は大きいが、冒すだけの価値はある。Hordeと大族長の役に立ちたいなら、お前は急いで力を成熟させねばならない。\n\n新たな召喚の呪文を学ぶ時が来た。\n\nまずはTablet of Vergaを取り戻せ。Burning Bladeのウォーロックどもに盗まれ、今は街の東にあるSkull Rockの奴らのねぐらに保管されている。その石板があれば、voidwalkerの召喚に必要なルーンを見せてやろう。", "Tablet of Vergaは持っているか、{name}？持っていないなら、手に入れるまでお前と話すつもりはない。", "よろしい。これを取り戻しに行ったついでに、Burning Bladeに他の損害も与えてきたことを願う。\n\n奴らは大族長にとって大いなる悩みの種であり、ウォーロック全体にとっての災いでもある。", 0xb03c11f0, 0xba21a12c, 0x041f9a8c, 0xac90ab1b, 0xa45dabc8, "....." },
  [1502] = { "Thun'grim Firegaze", "BarrensのThun'grim Firegazeと話して下さい。", "ウォリアーの武器は質の良いものでなければならない。そして、質の良い武器を作れるオークがいるとすれば、そのオークとはThun'grim Firegazeだ。Crossroadsの東の丘の上に住む世捨て人だ。\n\n武器を求めるなら、ウォリアーよ、Thun'grimを訪ねるがいい。会いに行くには、まず西のCrossroadsへ向かい、そこから東の丘へ進め。奴の野営地は丘の頂の高いところにある。", nil, "炉の炎を見つめすぎて、この目はとうに乾ききってしまったが、まだ見えるものもある。お前が何かを欲しているのは分かる。\n\nそしてここまでたどり着いたのなら、お前の望みも見当がつく。", 0xc4560ed6, 0xb0a44244, 0xdaa37c45, nil, 0x8b035e5e, "...m." },
  [1503] = { "Forged Steel", "BarrensのThun'grim FiregazeにForged Steel Barsを渡して下さい。", "武器はくれてやろう、{name}。だが、まずは俺に手を貸せ。数晩前、北西のRazormanesが俺の野営地にやってきた。奴らは俺と正面から戦おうとはしなかったが、俺の目が悪いことは知っている――何匹かが鼻を鳴らして俺の気を引いている間に、ほかの奴らが盗みを働いたのだ!臆病者どもめ!\n\n奴らは鉄の箱を奪っていった。その中にはforged steel barsが入っていた。それを取り戻せたら、お前の求める武器をくれてやろう。\n\nquilboarの野営地で鉄の箱を探し、forged steel barsを持って戻ってこい。", "私のsteel barsは持ってきたか？", "見つけてくれたか! しかもbarsは全部揃っている。まあ驚きはせんがな。Razormaneどもに、これほど上質な鋼の使い道が分かるとは思えんかったからな。\n\nありがとう、{name}。これが君への報酬だ。役に立つことを願う。", 0xf63daa21, 0x537f8286, 0xe1ba1ae1, 0x59a53ecc, 0x748375a3, "....." },
  [1504] = { "拘束", "Glyphs of Summoningを使い、voidwalkerを召喚して征服し、Glyphs of SummoningをOrgrimmarのGan'rul Bloodeyeに返して下さい。", "さあ、Tablet of Vergaをよく見るがいい。召喚に必要な紋章が記されている。それを洞窟の反対側にあるNeeru Firebladeのテントの輪へ持っていけ。そこでvoidwalkerを呼び出せる。\n\nお前の手の内にある物理的、魔法的なあらゆる手段を使って、それを倒さねばならない。それが済んだら、glyphs of summoningを持って私のところへ戻ってこい。その生き物をお前の意志に縛りつける方法を見せてやろう。", "voidwalkerは強大な存在だ。私がお前と同じ立場にいた頃のことを覚えている、{name}。年月を経て、私のvoidwalkerも私に逆らうことが少なくなった。もっとも、それは私が油断するのを待っているだけだろうがな。\n\nそれを忘れるな、{name}。", "よくやった、{name}。今しがた君が倒したものに似たvoidwalkerを召喚する方法を教えよう。\n\n我々は君に大きな期待を寄せている。そして君は今のところ、それに応えてきた。\n\nだが思い上がるな。この先に待つ務めに比べれば、これなど朝に目覚めるのと同じくらい簡単なことに思えるだろうからな。", 0x5926988f, 0x127c523e, 0x0b393cbb, 0xbd139f64, 0x6a8e44d2, "....." },
  [1505] = { "Veteran Uzzek", "BarrensのFar Watch PostにいるUzzekと話して下さい。", "Hordeがウォリアーを称えるのは、その力が疑いようのないものだからだ。だが、真に偉大なウォリアーは、偉大な学び手でもある。\n\nUzzekを訪ねろ。多くの戦いをくぐり抜けた古強者で、今は若いウォリアーたちに戦いの術を教えている。Far Watch Postの南で会えるだろう。BarrensとDurotarの境、東にあるオークの駐屯地だ。", nil, "こんにちは、お若いの。ちょっと指導を受けにきたのかね?", 0x365c7a94, 0x93d0830e, 0x5f80517e, nil, 0xf9b5711a, "...m." },
  [1506] = { "Gan'rulの呼び出し", "OrgrimmarのGan'rul Bloodeyeと話して下さい。", "そこのお前。{name}だな?\n\n予定が詰まっていないといいんだが。Gan'rulがすぐに会いたいそうだ。Cleft of Shadowで上級ウォーロックたちと一緒にいるはずだ。\n\nこれまでのGan'rulとの付き合いからすると、お前が呼び出されたのは、とても良いことか、とても悪いことかのどちらかだな。", nil, "よろしい。Ophekが君のもとへたどり着けないのではないかと案じていた。\n\n君のウォーロックとしての修行を進める時が来た。今抱えている用事は後回しにしてもらう。\n\nそれで問題はないな?", 0x45c24282, 0x52eba0f6, 0xea7dba0a, nil, 0xe1bee51f, "...m." },
  [1507] = { "魂を貪る者", "Cleft of ShadowのCazulと話して下さい。", "お前が召喚の魔術をさらに学ぶ時が来た。sayaadの召喚を学ぶのだ。驚くべき精神の力を持つ存在だ。心の弱い者を眠らせるように手なずけ、しもべにしてしまう――だが、恐れることはない!お前ならきっとその試練に耐えられるだろう。\n\nsayaadは、深い献身と愛を表す品を餌にしなければ召喚できない。そのような品を見つけるのはお前に任せよう。\n\n助言か?Cazulと話してみろ……あの老練なウォーロックに知らぬことなど、ほとんどないようだからな。", nil, "ふむ……{name}。お前はまだその道に入ったばかりだが、偉大になる可能性を感じる。\n\nお前は才を持って生まれた、{name}。それを無駄にするなよ。", 0xc90e9da6, 0x0892f9ee, 0x6a5a0197, nil, 0x0b0ec202, "...m." },
  [1508] = { "盲目のCazul", "OrgrimmarのZankajaと話して下さい。", "Gan'rulがお前を私のもとへ寄こしたのなら、お前はsuccubus――sayaad種族の女――を召喚しようとしていて、誘惑に使う品が要るということだろう。\n\nふむ……盲目の男に導かれるのを信じるなら、{name}、よく聞け。Orgrimmarの断崖、wind riderの塔の西に、Zankajaが住んでいる。彼女は伴侶の帰りを待っている。\n\n彼女のもとへ行け。", nil, "Dogranについての知らせを持ってきたのかしら? 彼は何日も前に戻ってくることになっていたのです。でも何の便りも無くて……。", 0x4b8d82bc, 0xab264922, 0xdc04a746, nil, 0xc30ee2c1, "...m." },
  [1509] = { "Dogranに関する情報", "CrossroadsのGazrogと話して下さい。", "私のつれあいのDogranが、最近Crossroadsでの任務に送られました。昇進だったので、彼はとても誇らしげでした。\n\nもちろん私は寂しかったけれど、それを彼には悟らせませんでした。それに心配でもあったのです。BarrensはOrgrimmarより危険な場所ですから、最悪の事態を恐れていました。\n\n戻ってくるはずの日からもう一週間も経つのに、彼からは何の便りもないのです……\n\nCrossroadsへ行って、何か知らせがないか確かめてもらえないでしょうか?彼はGazrogと一緒に働いていました。Gazrogなら今もあそこに駐屯しているはずです。", nil, "Zankaja? Dogranの連れ合いのことだな?\n\nああ、奴から便りはあった。だが、彼女の耳に入れるべき類いの報せじゃない……\n\nいや、死んじゃいない。だが怪我をして、quilboarの捕虜になっている。", 0x38116f43, 0x1552029b, 0x075a7321, nil, 0x0ed15c17, "...m." },
  [1510] = { "Dogranに関する情報", "Malaka'jinのKen'ziglaと話して下さい。", "彼は、我々がquilboarを一掃しようとしているCamp Taurajoに駐屯していた。何人かの兵卒を率いて奴らの野営地の一つへ向かい、そこでひどい傷を負ったのだ。ほかの者たちは戻ってきて、彼を救い出そうとした。彼の容体は悪く、傷は膿んでいた。だから、手当てをせずに動かすのを恐れたのだ。\n\n奴らはここへ伝令をよこし、Stonetalon MountainsのふもとにあるMalaka'jinのトロールに治療の薬を頼んでほしいと言ってきた。我々は薬を取りに人を送ったが、まだ戻ってきていない。", nil, "またオークか、え? もう一人の方のことで来たんじゃなきゃいいが。あいつは助からなかった。ゴブリンどもにすっかりやられちまったんだ。\n\nあいつは治療薬が必要だと言ってたが、ほかにはたいして何も要らないとさ。", 0x38116f43, 0x274e05fb, 0x8e29736f, nil, 0xc87ee0e8, "...m." },
  [1511] = { "Ken'zigla's Draught", "Ken'zigla's DraughtをCamp TaurajoのGrunt Logmarのところへ持って行く。", "また誰かが薬を取りに来るかもしれないと思ってたから、どっちみち用意しておいたよ。\n\nほら、{name}。いいか、彼には半分だけ飲ませるんだぞ！ そうすれば、血を流し尽くさずに動けるだけの力がつく。一晩待ってから、残りの半分を飲ませてやれ。\n\nとにかく、これをCamp TaurajoのLogmarのところへ持っていくといい。最初に来た奴の話じゃ、LogmarならそのDogranがどこにいるか見当がつくはずだ。", "ああ、何だ?", "まったく、ようやくか！Dogranはこれを待って、あっちで死にかけているんだ。\n\nすぐにこれを届けなければならんが、ここに駐屯している兵士のほとんどは食糧調達の任務に出払っている。", 0xa5e7e1b3, 0xf17fda61, 0x719c82c7, 0xb4a62c76, 0xb7888e5f, "....." },
  [1512] = { "愛の贈り物", "OrgrimmarのGan'rul BloodeyeにDirt-caked Pendantを渡して下さい。", "Zankajaは若くて美しい。体の不自由な者に縛りつけられるなど……そんな理不尽な苦しみを、あいつに味わわせるわけにはいかん。\n\n行ってくれ、{name}。そして、ありがとう。これで俺は、生ける屍としてではなく、栄光ある戦いの中で命を終えられるかもしれん。\n\nそれと、頼む。このことはつれあいには言わないでくれ……あいつの心に罪の意識を背負わせたくはないんだ。", "戻ってきたか。succubusと戦う覚悟はできたか？", "{name}、これで条件を満たすと言うのなら、信じよう。だが綺麗にさせてくれ……元通りぴかぴかに。succubusにはより魅力的かもしれんのでな。", 0xbe13511d, 0x30cfa262, 0x4113689c, 0xe4777579, 0xae4f2aa0, "....." },
  [1513] = { "拘束", "Dogran's Pendantを使ってsuccubusを召喚して征服し、Dogran's PendantをOrgrimmarのGan'rul Bloodeyeに返して下さい。", "これをNeeruのテントにある召喚の輪へ持っていけ、{name}。穢れたsuccubusを呼び出し、お前の支配の力を見せつけてやるのだ。私はお前の魔法の力を信じている。だが、いつものように用心は怠るな。多くの有望なウォーロックが、慢心と過信に呑まれてきたのだからな。\n\n倒したら、そのペンダントを私のところへ持って戻ってこい。Zankajaに知らせを届けられるようにな。", "succubusを目にすると、私の心は舞い上がり始める……だが同時に、魂が引き潮のように流れ去っていくのをほとんど感じ取れるのだ。\n\n用心しろ、友よ。", "成功か! 我が一番弟子に、それ以下のものは期待していなかったとも。\n\nお前は己の値打ちを証明した。屈服させたsuccubusを召喚する方法を、喜んで教えよう。行け、学ぶべきことはまだ多い。次に会うときには、succubusを完全に支配していることを期待する。\n\nDogranとZankajaの悲しみは、我ら年長の者に任せておけ。だがそれを忘れず、今日学んだ暗き力の誘惑に抗う守りとして胸に抱いておくのだ。", 0x5926988f, 0xa3846b0b, 0xcbb4f07d, 0x60f275cd, 0x5e6deefa, "....." },
  [1515] = { "囚われのDogran", "BarrensのDogranにKen'zigla's Draughtを渡して下さい。", "ここまで来たんだ。最後までやり遂げたいなら、俺は止めない。ただ、これ以上人手は割けない。お前一人でやることになる。\n\nDogranはここから北にあるquilboarの野営地に捕らえられている。小屋が2つ並んでいる場所を探せ。厳重に見張られているはずだ――奴らにまだ殺されていなければ、それに傷で力尽きていなければの話だがな。\n\n幸運を祈る。", "うううぐぐぐ……", "ひどい味の薬だ……\n\n今は体に力が戻ったのを感じる。よろよろとでも歩き去れるくらいには……だがこの脚は、一生失ったままだろう。腕もだ。", 0xb9c2abe8, 0xd92b478b, 0xd3ece112, 0xec7d2401, 0x5eda9561, "....." },
  [1516] = { "大地の呼び声", "Valley of TrialsのCanaga EarthcallerにFelstalker Hoovesを二つ持ってきましょう。", "時は来た、若き{class}よ。お前は強くなり、その魂は大地のように揺るぎない。シャーマンの道を歩むことは、己を証明する前から知恵を備えていることを示している。\n\n大地の元素がお前の運命を導き、お前に準備ができているならお前の一部となるだろう。だが、お前は大地そのものの前に立たねばならない。準備ができているなら、シャーマンだけが知るものを目にすることになるだろう。\n\n北にいるFelstalkerを探し出し、奴らの蹄を2つ奪ってくるのだ。それから私のもとへ戻ってこい。そのときお前の未来についてさらに語り合おう。", "忍耐こそ大地の最大の美徳です。大地は万物の循環を見届けます。山は砂漠となり、川は峡谷となる。大地はあらゆるエレメントの中で最も頑固で賢く、せっかちを許しません。\n\n争いの時が近づいているからこそ、今、大地があなたを呼んでいるのです。成し遂げて私のもとへ戻ったとき、あなたは完全な存在にそれだけ近づくでしょう。\n\n他の者はあなたの知恵を妬み、自らの無知ゆえにあなたを憎むでしょう。", "見事だ。そなたの成功は、準備が整っていることを示している。\n\nあらゆるエレメントの中で、大地は万物の礎を表す。それはそなたの力であり、持久力であり、忍耐である。大地はそなたを守るが、それはふさわしい敬意を示したときだけだ。他のエレメントと同じく、大地でさえ移ろいやすいことがある。大地は生命の基盤であり、その法則を守ることで、そなたはより大いなる知恵を得るであろう。大地がそなたに分け与える秘密を決して忘れるな。\n\n今からそなたのためにsaptaを作ろう。それを受け入れることで、そなたは自らの道を悟るであろう。", 0xe316c17f, 0x38769ca5, 0x569e02d2, 0x96dc0c6e, 0x2b537118, "....." },
  [1517] = { "大地の呼び声", "Spirit Rockを探し、Earth Saptaを飲んで下さい。", "saptaとは、我らの魂を精霊と結びつけるために作られる飲み物だ。魔法を込められたこの薬は、強い意志を持つ者に、ほかの誰にもできないやり方で精霊を見せてくれる。そなたの魂は、そのsaptaが作られた精霊と結びつくであろう。そしてその作り方を知るのは、選ばれたわずかなシャーマンだけだ。\n\nsaptaは必ず聖なる場所で飲むものであり、それ以外の場所では決して飲まぬ――覚えておくがよい。\n\nここから南西にあるSpirit Rockを訪ねよ――Hidden Pathの終わりにある。そこでsaptaを飲めば……まあ、わかるであろう。", nil, "おぉ……よく来た{name}よ。\n\n精神と肉体の結びつきについて、そなたは知るだろう。強さは山として、忍耐は平原として、そしてそなたの本質は世界そのものとして。\n\nこの儀式を通るには、謙虚な心でEarthの前に立つことだ。しかし、他の場合にはそうではないかもしれない。時に混沌と、時に凶暴に、それがelementsの性質だ。互いに反する性質を困難を持って学んでいかなくてはならない。", 0xe316c17f, 0xa13b2e9f, 0x3a9eb51f, nil, 0x63c94008, "...m." },
  [1518] = { "大地の呼び声", "Valley of TrialsのCanaga EarthcallerにRough Quartzを持っていく。", "このRough Quartzを受け取り、我らが会った証としてCanaga Earthcallerのもとへ持っていくがよい。彼がそなたのためにトーテムを作るであろう。そしてこの小石がその核となる。小さく見えようとも、大きさは問題ではなく、ごく小さなものでさえ多くのものより長く残りうることを、そなたはやがて知るであろう。\n\n辛抱強くあれ、{name}。強くあり続けよ。そして知恵を求めよ。それが大地がそなたに求めるものだ。最後には、そなたは大地と一つになるであろう――大地を敬え。大地がそなたを敬うように。", "運命へと永遠にあなたを導く4つの道のうち、最初の道へあなたを正式に迎える最初の者でありたいと思います。\n\n大地があなたに与えた石を持っているなら、大地が約束したトーテムを授けましょう。\n\n持っていないなら、自分の道を見つけるまで立ち去りなさい。", "見事だ！\n\n私がお前のために作るトーテムは、{class}の間でのお前の地位を示す印以上のものだ――それを超えた力を持っている。トーテムの使い道の一つは、呪文の焦点とすることだ。その呪文は大地と結びついており、お前がより大きな知恵を得るにつれて、大地の力をより多く使えるようになる。\n\nより深い知識を得る準備ができれば、トレーナーたちがそれを見極めてくれるだろう。\n\nだが今は、この大地のトーテムと、最初の能力を教える巻物を受け取るがよい。", 0xe316c17f, 0x54eec492, 0xaf707d12, 0x193d5207, 0x5ffb2e61, "....." },
  [1519] = { "大地の呼び声", "Ritual Salveの軟膏2つをCamp NaracheのSeer Ravenfeatherに渡して下さい。", "その時が来ました、若き{class}よ。あなたの体は年を重ねて強くなり、あなたの魂は大地のように揺るぎません。私にはあなたの中にそれが見えます――あなたにはすでに知恵があるのです。\n\n大地は私たちの民を導き、私たちに語りかけます。いずれはあなたにも語りかけるでしょう。ですが、あなたは試されねばなりません。準備ができているなら、私たちの種族しか知らないものを目にすることになるでしょう。\n\n東の谷にいるBristlebackのシャーマンたちを探し出し、彼らが儀式に使う軟膏を奪ってきてください。あなた自身の薬を作れるだけの量が集まったら、そのときに私のもとへ戻ってきてください。", "大地は忍耐強く、あなたの準備が整うまで待ってくれます。時が経てば万物は侵食され、生まれ変わることを知っているからです。それが万物の循環です。山は砂漠となり、川は峡谷となる。大地はあらゆるエレメントの中で最も頑固で賢いのです。\n\n何よりも忍耐と持久力を学ばねばなりません。大地があなたの準備ができたと感じているからこそ、今あなたを呼んでいるのです。成し遂げたなら、それをあなたの再生と考えなさい。その後は二度と無知に戻ることはできないでしょう。", "よろしい、{name}。ここへ戻ってきたということは、お前が次の段階への備えを本当に整えたということだ。\n\nあらゆる元素の中で、地はすべての物事の礎を表す。それはお前の力であり、耐久であり、忍耐だ。Earth Motherはお前を守ってくださるが、それはお前が正しい敬意を示したときだけだ。彼女は生命の基であり、その掟に従うことで、お前はより大きな知恵を得るだろう。彼女が分け与えてくれる秘密を、決して忘れるな。\n\nこれからお前のsaptaを作ろう。それを受け取ることで、新たな道がお前の前に開かれる。", 0xe316c17f, 0x78a5e6e9, 0xa9b6ebaa, 0x155e3f35, 0x1bb9c4df, "....." },
  [1520] = { "大地の呼び声", "Kodo Rockを見つけ、Earth Saptaを飲んで下さい。", "saptaとは、私たちの魂をエレメンタルに結びつけるために作られる飲み物です。魔法を込めたこの薬によって、心を開いた者は、これまで誰も見たことのないようにエレメンタルを見ることができるのです。あなたの魂は、そのsaptaが作られたエレメンタルと永遠に結びつきます。そして、その作り方の秘密を知っているのは、私たちの種族のうちでもごく一握りの者だけです。\n\nsaptaは必ず聖なる場所で飲むもので、ほかの場所で飲むことは決してありません。\n\nここから東にあるシャーマンの祠を探し、そこでsaptaを飲んでください。", nil, "ああ……{name}よ……大地はお前がここにいることを喜んでいる。\n\n体と魂で結ばれ、お前は山々が己の力、平原が己の忍耐、そして世界そのものが己の本質であると知って進んでいくだろう。\n\nこの儀式を通るためにお前に求められるのは、ただ大地の前に謙虚に立つことだけだ。だが他の元素はそれほど受け身ではない。混沌としており、しばしば荒々しくもあるが、それが元素というものの性質だ。相反する二つの性質――お前はそうしたことを細やかに学び取らねばならない。", 0xe316c17f, 0xedfdb7bf, 0x9ec79348, nil, 0x63c94008, "...m." },
  [1521] = { "大地の呼び声", "Camp NaracheのSeer RavenfeatherにRough Quartzを渡して下さい。", "このrough quartzを私から受け取り、私たちが会った証としてSeer Ravenfeatherのもとへ持っていきなさい。彼女があなたのためにトーテムを作ってくれます。この小石がその心臓になるのです。小さく見えるかもしれませんが、大きさは問題ではないこと、そしてどんなに小さなものでも山より長く残りうることが、いずれ分かるでしょう。\n\n辛抱強くありなさい、{name}。強くありなさい。そして知恵を求めなさい。それが、大地があなたに求めることです。最後には、あなたは大地と一つになるでしょう――大地があなたを敬うように、大地を敬いなさい。", "ごきげんよう、{name}。務めを果たしていなければ、あなたは私のもとへ戻ってこなかったでしょう。あなたの旅を永遠に司る4つの道のうち、最初の道へあなたを正式に迎える最初の者とならせてください。\n\n大地があなたに与えた石を持っているなら、大地が約束したトーテムを授けましょう。持っていないなら、あなたを哀れに思います。エレメントに身を捧げきったときには、大いに誇りを持てるのですから。", "見事だ。\n\nお前のために作るトーテムは、単なる象徴以上のものだ――それ以上の力を備えている。トーテムの用途の一つは、呪文の焦点となることだ。その呪文は大地と結びついており、お前がより大きな知恵を得るにつれ、大地の力もより多く使えるようになる。Kalimdor各地のトレーナーたちは、お前がさらなる知識にふさわしくなった時を知り、訪ねた際にそう教えてくれるだろう。\n\nだが今は、この大地のトーテムを受け取るがいい……", 0xe316c17f, 0x9f97d72d, 0x8bafa0d9, 0x86fa5bbc, 0x00323f04, "....." },
  [1522] = { "火の呼び声", "BarrensでKranal Fissを見つけて下さい。", "火の加護を、兄弟。お前、もう大地の道じゃ強いみたいだな。そろそろKranalと話す準備ができたと俺は思うぜ。\n\nKranalはBarrensのCrossroadsの北に住んでる。あいつは元素の道に強くて、火の道を教えてくれる……お前が準備できてると思うならな。\n\nあいつはすぐ見つかる。ただ、行きすぎるなよ――行きすぎたら、エルフどもの土地に入っちまうからな。", nil, "ふむ、Searnがそなたを我のもとへ寄こしたのか？\n\nならば、Searnは常に信頼できる者だ。つまりそなたは次のsapta、火のsaptaに加わる準備ができているということだな。\n\nそなたの目にはすでに見えておる。燃え盛るもの、渇望が。そなたは力を味わい、今やさらなる力を求めている。忍耐だ、{name}。大地が教えたことを思い出せ。力と破壊はたやすく訪れる。だが、それでもいつ手を止めるべきかを知らねばならぬ。", 0x53f3b76b, 0xb1158d84, 0xf2febdb9, nil, 0xe2471546, "...m." },
  [1523] = { "火の呼び声", "BarrensでKranal Fissを見つけて下さい。", "あなたが最後に試されてから、長い時が経ちました、{name}。あなたはこれまでの修行で辛抱強さを示してきましたが、さらに学ぶ時が来たのです。破壊……そして混沌について学ぶ時が来ました。火のエレメンタルはあなたのものです。その代償を払う覚悟があるなら、理解できるでしょう。\n\nBarrensのKranal Fissを探しなさい。Crossroadsの北にある小さな住まいに住んでいます。ですが気をつけて。ナイトエルフの土地まで来てしまったら、行き過ぎです。", nil, "ふむ、Narmがお前を寄越したのだな?\n\nならばよい。Narmはいつでも信頼できる男だ。つまりお前は、次のsapta――火のsaptaを受ける用意ができているということだ。\n\nお前の目にはもう見える。燃えるもの、渇望だ。お前は力を味わい、今やもっと欲している。焦るな、{name}。大地が教えてくれたことを忘れるな。力と破壊は容易く手に入るが、いつ手を止めるべきかも知らねばならん。", 0x53f3b76b, 0xb1158d84, 0x0f02e651, nil, 0xd20cd47c, "...m." },
  [1524] = { "火の呼び声", "DurotarのTelf JoolamにTorch of the Dormant Flameを渡して下さい。", "そなたは火のトーテムを扱えるほどの力を持っている。だが、それは備えができているということではない。\n\nDurotarのSouthfury River沿い、Great Seaの手前に、この地で最も高い峰の一つへと続く隠された小道がある。頂上まで登れば、Telf Joolamが見守る我らの聖なる祠の一つ――Shrine of the Dormant Flame――が見つかるであろう。\n\nこの松明を彼のもとへ持っていくがよい――そなたが火を御そうとしている証だ。祠の火鉢でこれに火を灯し、私のもとへ戻れば、火のトーテムを授けよう。", "よう、{name}。ここはShrine of the Dormant Flameだ。シャーマンの術に十分通じた者だけが、この場所の秘密とそこに宿る力を知ることができる。はるばるここまで来てもらったのに、今になって追い返すことになってすまない――何しろ、ここまでの道のりは決して安全ではないからな――だが、私はこの祠の守り手で、誰でも彼でもここをうろつかせるわけにはいかないんだ。", "ああ、私の間違いだ、{name}。許してくれ。そなたがTorchを持っているとは気づかなかった。お目にかかれて光栄だ。\n\n多くの冒険者が、失われた財宝や、倒すべき神秘の生き物を求めてここへたどり着く。だが見たところ空っぽの祠を前に、追い返されるだけだ。しかし我らは真実を知っている、そうだろう、{name}？\n\nこの祠は、Hordeの凡俗な者たちには知られぬ大いなる秘密を秘めている。我らにとって、ここは神聖な場所なのだ。", 0x53f3b76b, 0x754469c8, 0xb7ad9777, 0x2af3079b, 0x7705d50c, "....." },
  [1525] = { "火の呼び声", "Fire Tar一つとReagent Pouch一つをDurotarのTelf Joolamに届けましょう。", "でも、お前は歴史を学ぶためにここにきたわけではないのですね？　火のトーテムとEternal Flameのためにきた。\n\n第一歩は、saptaを作って、お前と炎をつなぎとめる。\n\nお前が、二つのアイテムを持ってきてくれれば、お前のために火のsaptaを作ろう。一つはfire tar。単純なアイテムだ。Barrensの東でRazormane spellcastersが持っている。\n\n二つ目は少し危険だが、Burning Bladeの信奉者のreagent pouch。Razor Hillの北東の山間の上部にある洞窟で見つかるはずだ。", "reagent pouchとfire tarを見つけてくれれば、火のsaptaを作るのに十分な材料が揃う。Burning Bladeの狂信者たちは、ほとんどの呪文に必要な材料をそのpouchesに入れて持ち歩いている。たいてい私が必要とする品も十分に入っているから、他のものを探してこれ以上遠くまで行く必要はないだろう。\n\nsaptasは必ず、それぞれのエレメントと密接に結びついた材料から作られる。ウォーロックたちは火と結びついているから、我々の仕事も楽になるというわけだ。", "これで申し分ない、{name}。\n\n火は混沌と破壊だけのものではない。それをよく覚えておくがよい。火は生命と創造でもあるのだ。万物はそのように結びついている。力は互いに対立するが、同時に、一方はもう一方なしには存在できぬ。両者は互いを消し合うが、互いに意味を与えもする。常にこのことを忘れるな。\n\n異なる種類の魔法を互いに組み合わせて使うことは、真の技量だけでなく、大いなる知恵をも示すであろう。", 0x53f3b76b, 0x560b3faf, 0x4dc721a7, 0x4211f69c, 0xeff16076, "....." },
  [1526] = { "火の呼び声", "Minor Manifestation of Fireを倒してShrine of Eternal Flameの頂にある火桶にGlowing Emberを置いて下さい。", "fire saptaは用意してある。炎の力と対峙する時が来たようだな。神殿でsaptaを使い、山の上に行って、顕在化した者に会うがいい。彼はお前の準備ができるまで攻撃しないだろう。お前に自分が見えていることに気づくはずだ。\n\n迅速に彼を倒すのだ。時間をかければかけるほど、彼はより強くなっていくぞ、{name} 。その者を倒したあと、彼の白熱の燃え残りを火鉢に置くといい。そして、松明を燃やすのだ。", "その火鉢はあなたの背丈の三分の一ほどの高さで、滑らかな金属の縁に沿って刻まれた碑文を除けば、ごく普通に見える。金属には風雨による劣化の跡がまったくなく、上に据えられた鉢は触れるとひんやりとしている。", "あなたが燃え残りを中に置くと、白熱した炎は器の中で燃え出した。 saptaが身体を勢いよくめぐる不思議な効果が感じられた。そして、炎があなたの前で生き生きと踊った。\n\nあなたが祭壇の中に松明の先端を置くと、すぐに火がついた。", 0x53f3b76b, 0x7d09c623, 0x8243a2ed, 0x0c0f61ac, 0xca816112, "....." },
  [1527] = { "火の呼び声", "BarrensのKranal FissにTorch of Eternal Flameをもっていきましょう。", "松明が、その手の中で燃えている。あなたは振り返りDurotarを見渡した。風が炎を暴れさせるように、気持ちが高ぶるのを感じる。\n\nKranal Fissを探して、Barrensへ戻る道を下り始めた。", "ああ、{name}？そこに持っているのは何だ？", "お前は、私が今まで見たどんな松明よりも輝いているよ、{name}。だから、誇りに思うべきだ。\n\nこの先に進むなら、自然の力はお前の命令に従い、我らの同胞は知恵と導きをお前に求めるだろう。これを受け取ってくれたまえ。お前の新しいトーテムを最初に祝わせてくれ。", 0x53f3b76b, 0xd47d8263, 0x581acd2a, 0xacd1e0ef, 0xf51aa128, "....." },
  [1528] = { "水の呼び声", "BarrensのIslen Waterseerを見つけて下さい。", "お前さんの未来には水が見えるぜ、兄弟。お前さん、もう火の道は強いみてえだな。Islenと話す準備はできてると思うぜ。\n\nIslenはBarrensの海岸沿いに住んでる。Southfury Riverに沿って南へ行きゃ、見逃しっこねえ――でっけえサメを探しな!あいつはエレメンタルの道に通じてて、水の道を教えてくれる……お前さんが準備できてると思うならな。\n\nあいつは簡単に見つかる。ただ、南へ行き過ぎんなよ――Ratchetのすぐ先にいるからな。", nil, "風は地平の彼方から足早にお前へ近づき、大地はお前の足元で揺るぎなくあり、そしてお前の魂はすでに火に温められている――ならば今こそ、水の清らかさについて学ぶ時だろう。\n\nお前の道はここまで導いてきた。そしてお前の魂は、さらに先へ進む力を与えてくれる。だが最初の一歩を踏み出すのは、お前自身だ。", 0x1f0e11aa, 0x52f30fbd, 0x40f9c41e, nil, 0xf9228c66, "...m." },
  [1529] = { "水の呼び声", "BarrensのIslen Waterseerを見つけて下さい。", "あなたが最後に試されてから、長い時が経ちました、{name}。あなたはこれまでの修行で辛抱強さを示してきましたが、さらに学ぶ時が来たのです。水の清らかさについて学ぶ時が来ました。\n\nBarrensのIslen Waterseerを探しなさい。Southfury RiverとRatchetの南、東の海岸沿いにいます。釣り小屋で見つかるでしょう。幸運を祈ります、{name}。", nil, "風は地平の彼方から足早にお前へ近づき、大地はお前の足元で揺るぎなくあり、そしてお前の魂はすでに火に温められている――ならば今こそ、水の清らかさについて学ぶ時だろう。\n\nお前の道はここまで導いてきた。そしてお前の魂は、さらに先へ進む力を与えてくれる。だが最初の一歩を踏み出すのは、お前自身だ。", 0x1f0e11aa, 0x52f30fbd, 0x7363625e, nil, 0xf9228c66, "...m." },
  [1530] = { "水の呼び声", "Southern BarrensにいるBrineを見つけて下さい。", "水について学ばねばならない教えが一つあるとすれば、それはこれです。水とは再生を意味するのです。\n\n水の力は流れ、削り、あらゆるものを清めます。水の癒し、満たす力は比類ないものだと分かるでしょう。ただし、それは水が清らかなときだけです。\n\n水が汚れれば、触れるものすべてを荒廃させうる。そのことを理解したとき、水がどれほど欠かせない資源なのか分かるでしょう。\n\n水のsaptaを望むなら、Southern Barrensの奥深くにいるBrineを探しなさい。Brineの住まいは、あそこのquilboarに絶えず荒らされているのです。", nil, "何か?\n\nふむ。あなたが何を尋ねようとしているか、見当はついています。なぜBarrensの最も奥深く、quilboarの脅威に囲まれ、何の守りもない場所に住んでいるのか、と。まあ、誰にでも自分の行いを正当化する理由はあるものです。本当の問いは、身の安全など明らかに気にかけていない女に話をするために、何が卑しい{race}をBarrensの奥深くまで連れてきたのか、ということでしょう。\n\nその答えは、二人とも承知しているはずです。", 0x1f0e11aa, 0xee4ba4c3, 0xfd15e1c1, nil, 0xfab4a730, "...m." },
  [1531] = { "大気の呼び声", "Thousand NeedlesのPrate Cloudseerを見つけて下さい。", "順調に進んでるな、兄弟。お前さんは風のトーテムにふさわしいと示す準備ができてる。だがまずは、Thousand NeedlesのPrate Cloudseerを見つけなきゃなんねえ。十分に敬意を払えば、風のトーテムの手に入れ方を教えてくれるぜ。\n\nBarrensを抜けて南へ行って、Thousand Needlesに着いたら東へ向かえ。恋人と一緒に穴の中に隠れてるのが見つかるぜ――ハハ、俺があいつの悪口言ってたなんて言うなよ――あいつ、きっといい顔しねえからな。", nil, "差し当たって、大気の精霊を呼び出し、呪文に集中するのに必要な物を差し上げましょう。このトーテムをお持ちなさい。そして、準備ができたら、私と一緒に少しばかり訓練しましょう。", 0x8f4acf86, 0x7a57cbe0, 0x94f082ac, nil, 0x451e9311, "...m." },
  [1532] = { "大気の呼び声", "Thousand NeedlesのPrate Cloudseerを見つけて下さい。", "Kalimdorの風があなたを迎えに吹き寄せ、あなたは私たちの最も力ある同胞の一人に数えられるでしょう。あなたがここまで来て、これほど有望な未来を持っていることを誇りに思います。\n\n風のエレメンタルは制御するのが難しいものですが、あなたの技なら、前に立ちはだかるどんな障害も乗り越えられると信じています。\n\nBarrensの一番南へ向かい、Thousand Needlesへ入りなさい。その遥か東でPrate Cloudseerに会えるでしょう。彼女がさらに教えてくれます。", nil, "差し当たって、大気の精霊を呼び出し、呪文に集中するのに必要な物を差し上げましょう。このトーテムをお持ちなさい。そして、準備ができたら、私と一緒に少しばかり訓練しましょう。", 0x8f4acf86, 0x7a57cbe0, 0xa1687f62, nil, 0x451e9311, "...m.", nil, nil, 0x6ef3855e, nil, nil },
  [1534] = { "水の呼び声", "AshenvaleのRuins of StardustでEmpty Blue Waterskinに水を汲み、BarrensのBrineに返して下さい。", "この水袋を持って、ナイトエルフがAshenvaleと呼ぶ緑豊かな森の奥深くへ向かいなさい。Barrensのはるか北にあります。\n\n森に入ったら、西へ進みなさい。StonetalonとAshenvaleを隔てる山々に沿って、Lake Mystralを越えた先に、聖なる場所があります。Ruins of Stardustです。湖の中央に、小さな泉があるでしょう。\n\nその泉の水を汲んできなさい。それが、あなたをIslenのもとへ送り返す前に必要な、最後の材料になります。", "{name}、水はもう手に入れましたか？言い伝えでは、あの遺跡は訪問者を好まない大きな自然の生き物に守られているそうです。ですが、それはナイトエルフの敵を追い払うための作り話かもしれません。\n\nいずれにせよ、気をつけてください。", "素晴らしい、{name}。3つの見本がすべて揃ったので、生きとし生けるものが見つけうる最も清らかな水の小瓶を、お前のために作れる。それはお前の通過儀礼の次の段階で使われるものだ。\n\nお前を我らの同胞に数えられることを嬉しく思う、{name}。お前は{class}すべての誇りだ。これからの活躍を聞くのを楽しみにしている。", 0x1f0e11aa, 0x6761c4a7, 0xc0b99b1d, 0x4add2c8a, 0x3f6d811e, "....." },
  [1535] = { "水の呼び声", "Brineの小屋の下にある水たまりでEmpty Brown Waterskinに水を汲み、彼女に返して下さい。", "理解を得て、私からsaptaを受け取るには、最も清らかな水だけを求めねばなりません。水を汲みに行く間、周りの様子をよく見ておきなさい。水に頼って生きる生き物、水を守る生き物に気を配りなさい。水が森や砂漠にどんな影響を与えるかを見なさい。命を支えるまさにその物が、生き物たちに命を奪わせることを、その目で確かめなさい。\n\n簡単な務めから始めましょう。私の小屋の下に、この貴重な液体の池があります。この水袋をそれで満たして、戻ってきなさい。", "もうすぐ他の務めにあなたを送り出す準備が整います。skinはもう満たしましたか？\n\nquilboarがどれほど縄張り意識が強いか、私は知っています。ほんの小さな水源でさえ、彼らにとっては莫大な富なのです。Barrensにわずかな雨が降るだけでも、彼らは盛大な宴を開きます。水はとても乏しいので、彼らにとっては神聖なものなのです。分かりますか？", "あの泉から水を汲もうとすれば、多少の流血は避けられまいと思っていた。quilboarたちが、生きとし生けるものはすべて繋がっているのだと気づかないのは惜しいことだ。彼らの強欲が、自らの民の痛みと苦しみを長引かせているだけだということも。違いを脇に置き、氏族が一つにまとまれば、どれほどのことを成せただろうか。\n\n重ねて惜しいことだが、Barrensの他の種族にとっては、おそらく恵みなのだろう。", 0x1f0e11aa, 0x3c4dd7b6, 0x425c8a0e, 0x96cf7b6b, 0xb02bcec2, "....." },
  [1536] = { "水の呼び声", "Tarren Millの井戸でEmpty Red Waterskinに水を汲み、BarrensのBrineに返して下さい。", "ずっと昔、私は仲間たちについてHillsbrad Foothillsへ行きました。あそこに住みついている手ごわい人間たちから身を守りながら進むうちに、Forsakenが乗っ取った小さな町にたどり着きました。Tarren Millです。\n\nそこで、とても不思議なものを見つけたのです。町の真ん中に、新鮮な湧き水の小さな井戸がありました。疫病に冒された町の住人たちがその価値に気づいているのかどうかは分かりません――穢れた海に浮かぶ、小さな聖なる名残なのです。\n\nこの水袋に、その水を汲んできてください。", "町の中で清らかなままの井戸を見ると、若い頃に聞かされた話を思い出す、{name}。大きな苦しみと悲しみの時にも、かすかな希望、人々が結束するための小さな象徴を見出すことはできる。オークの民にとってThrallとはそういう存在だ。彼は大きな逆境を生き延び、その強さと手本によって我らの民を導くために立ち上がったのだ。\n\n彼ほど苦しんだオークがいるかどうかは分からない。だが同時に、彼ほど強いオークがいるかどうかも分からない。", "よろしい、{name}。お前は目の前の務めに献身しており、必要なものを探し出す力も備えている。\n\nお前のsaptaに要る試薬を作るには、あと一つ見本が必要なだけだ。Islenも喜ぶだろう。", 0x1f0e11aa, 0xb7fce94c, 0x94c4b54f, 0x7fa68a20, 0x24c2788b, "....." },
  [1558] = { "Stonewrought Dam", "孤児をLoch ModanのStonewrought Damへ連れて行って下さい。巨大な滝を見渡せるよう、ダムの中央へ連れて行って下さい。", "Ironforgeはドワーフとノームがみんな住んでるところなんだ。その近くにLoch Modanっていう場所があって、ドワーフたちがそこにものすごく大きなダムを作ったんだって。今まで作られた中で一番大きなものの一つなんだってさ。すごいよね!\n\nLoch Modanに連れてって、ダムを見せてくれない?お願い!たしかStone……えっと……Stonewrench Dam?Stonewrought?とにかく大きいのは確かだよ。大きな滝を見下ろしてみたいんだ。あんまり身を乗り出したりしないって約束するから!", "まだ着かないの?", "わあ――ダムは思ってたよりずっとずっと大きかった! 水がすごい音で流れてて、自分の声もほとんど聞こえなかったよ! ねえ、あの水っていつかなくなっちゃうと思う? うわあ、もしあのダムが決壊したらどうなるんだろう! わあ、怖いだろうな!\n\nダムを見に連れていってくれてありがとう。とっても親切だったね。あんまり身を乗り出さないって言ったでしょ!", 0xa08162db, 0x0677c7f0, 0xa3e82d90, 0x63e6b64c, 0xfffb4fdb, "....." },
  [1559] = { "Flash Bombの作り方", nil, nil, nil, "では君は技術者なのか? よし、真珠を手に入れるのを手伝ってくれた礼に、これが閃光爆弾のレシピだ。\n\n幸運を祈る。自分の目を潰さないように気をつけろよ!", 0x7af82f5d, nil, nil, nil, 0x7a64992c, ".mmm." },
  [1560] = { "Toogaの冒険", "Toogaに妻Tortaのところへ戻る道を示して下さい。", "すっかり迷ってしまった!\n\n妻のTortaに夕飯を取ってこいと言われて出てきたんだが、どこかで道を間違えたらしい。\n\nすまないが、Tortaのところまで連れて帰ってくれないか?Steamwheedle Portのすぐ南で待っているんだ。", "Toogaはどこだ?", "つまり、あいつは自力で帰り道も見つけられなかったのか? やはりな。\n\nまあ、その手間の分くらいは受け取る資格があるだろう……", 0x64284271, 0xd4e97dbf, 0x5835d3d9, 0x7dfa6aa0, 0xc60ddd14, "....." },
  [1578] = { "前線への供給", "Copper Axe・Copper Chain Beltをそれぞれ6つずつ、Loch Modanの南防御塔にいるThorvaldに渡して下さい。", "Loch Modanの山の民はtroggsと戦っていて、大忙しなんだ! あのtroggsにいつも対処するなら、絶え間なく新しい防具と武器が必要になる。\n\n同僚のThorvaldがあそこにいるのは、山の民の装備を良い状態に維持しようとしてるというのが理由さ。だから、copper axesとcopper chain beltsをいくつかThorvaldに持って行ってやれば、感謝するだろうよ。鍛冶の知識だって分けてくれるかもしれない。\n\nThorvaldはLoch Modanの南防御塔にいるぞ。", "おしゃべりしている暇はない。私に用があるのか?", "おお、すまんな! 軍の補給に来てくれたのに気が付かなかった。あんたの作ってくれたものはすごく助かるよ!\n\nこれは防具の製法だよ。役立ててもらえると嬉しい。", 0xc30dcf6c, 0xcc5d9418, 0x30473b15, 0xec2e191f, 0xf823104b, "....." },
  [1579] = { "Gaffer Jacks", "AuberdineのWizbang CranktoggleにGaffer Jack 8個を渡して下さい。", "静かだからAuberdineに来たんだ。発明品は静かなところで発明したいんだよ。一晩飲んだあとは、Ironforgeの騒がしさが嫌でたまらないからね!\n\nそれで船でAuberdineへ来たんだけど、途中でちょっと飲み過ぎちゃってさ。gaffer jacksの箱を船から落としちゃったんだ!gaffer jacksがないと困るんだよ!\n\nどこで落としたのか正確には分からないけど、海で釣りをすれば運よく引っかかるかもしれないよ……", "gaffer jacksは見つかったかい、{name}? gaffer jacksがないと、stintle pegsを調整できないんだよ!", "見つけたなんて信じられない! 君はきっとKalimdorで一番ツイてる{race}だよ!", 0xfa9d081e, 0xb6cf36d8, 0xf09fa27e, 0x68a8175d, 0x9be37eba, "....." },
  [1580] = { "Electropeller", "AuberdineのWizbang CranktoggleにElectropeller 12個を渡して下さい。", "君が運のいいやつなのは知ってる。でも……どれくらい運がいいんだい、{name}?\n\nある晩、僕はDarkshoreの道をぶらついてたんだ。新作の自走式爆発アヒルおとりを試すのにいい川か湖を探しててね。たぶん少し酔ってたんだと思う……気を失って、何時間も経ってからAuberdineで目を覚ましたんだ。髪は焦げてるし、electropellersの袋はなくなってるし!きっと水の中に落としたんだ!\n\nあのelectropellersが要るんだよ!Darkshoreの湖か川で釣り上げられるかもしれない……", "electropellersは見つかったかい? カモのデコイの研究を続けるには、あれが必要なんだ……", "信じられない! 見つけてくれたのか! 君は私が今まで見た中で最高の釣り人だ!\n\nありがとう、{name}。それとこれを持っていってくれ。君ほど腕が良ければ必要ないだろうが、釣りの助けになるはずだ。", 0x667cc3c7, 0xdc46859a, 0x642310a5, 0xf9546f58, 0xc63f8173, "....." },
  [1581] = { "Bladeleafsに薬を", "Elixir of Lion's Strength 6本・Elixir of Minor Defense 2本をDolanaarのSyral Bladeleafに渡して下さい。", "私たちの薬草と錬金術のお店は大盛況ですが、夫はポーションを混ぜるのにあまりにも多く時間を費やしていて、夫婦の時間が取れないのです。\n\n手伝って下さいませんか?\n\nあらかじめ完成させた薬を持ってきて下さったら、喜んで交換しますよ。いくつか貴重な薬草を持っていますから、きっと役に立つと思います。", "こんにちは、{name}。交換するエリクサーは持ってきたかい?", "よく混ざっていますね。{name}、あなたは心を込めて仕事をしていますね。それは錬金術師にとって大切なことですよ。\n\nこれがあなたに差し上げる薬草です。最近採ってきました。上手く使って下さいますように。", 0x55e6a1a0, 0x4cd053d4, 0x114405e0, 0x486738da, 0xd85fcf4b, "....." },
  [1582] = { "Moonglow Vest", "Embossed Leather Glove 1つ・Embossed Leather Boots 5足・Embossed Leather Cloak 5つをDarnassusのLotheriasに渡して下さい。", "Darnassusにいる私たち、とりわけ職人は本当に忙しいのです。若い冒険者たちが荒野で己を試したがり、常に物資を必要としています。\n\n革製品の注文をさばくのを手伝ってくれたら、もっと進んだ皮加工技術を教えてあげられるかもしれません。", "ごきげんよう、{name}。", "ええ、良い品物ですね。あなたはいい腕を持った、細かいところまで目が行き届く方ですね。皮細工師として将来有望ですよ。\n\nさあ、{name}。Moonglow Vestを作る型紙を見せてさしあげましょう。", 0x13b76bcf, 0xd2ae52ab, 0x86455e3c, 0x1355ea4c, 0x60bb3c3a, "....." },
  [1598] = { "盗まれた書物", "Drusilla La SalleのPowers of the Voidを取り戻して下さい。", "そこのお前!{name}だな?\n\nウォーロックになることに迷いがないといいがな。自分の身を守れなければ、引きずり込まれるのがおちだぞ。\n\n私はお前を教えることになっているが、その前にお前が十分に強いか確かめねばならん。\n\nAbbeyで学んでいた新米が、逃げ出してDefias Brotherhoodに加わった。なぜ私が気にするのか?そいつが大事な本を何冊か盗んでいったからだ。\n\nその中の一冊が、たまたま私が欲しかった本、Powers of the Voidだ。それを盗んでこい。奴らはVineyardsのテントに隠している。", "私自身があの本を盗むのは目立ちすぎた。奴らのお人好しの一人が、私の代わりに汚れ仕事をしてくれるとは、なんと運のいいことだ。", "素晴らしい……私はこの書に手を出すことができなかった。図書館の立ち入りが制限された棟に置かれていて、私がその辺をうろついていては怪しまれただろうからな。\n\nまあ、よくこれを手に入れてくれた。お前なら自分のimpくらい扱えると確信した。だから召喚の仕方を教えてやらない理由はない。", 0x88b1dee6, 0x8e23bc14, 0x4748064a, 0xdb594d3a, 0x048d8e41, "....." },
  [1599] = { "始まり", "Feather Charm 3つをAnvilmarのAlamar Grimmに渡して下さい。", "お前が、皆が噂している新しいウォーロックだな。研究の時間を割いてお前の修行を始めてくれと私に頼むとは、よほど誰かに気に入られているらしい。\n\n心配するな、それでお前を恨んだりはしない。\n\nお前が学ぶ召喚の呪文の中で最も簡単なのは、impの召喚だ。だが、それを授ける前に、お前に必要な魔法の力と体の力があることを証明してもらわねばならん。\n\n南西の洞窟にいるfrostmane novicesから、feather charmsを3つ持ってこい。", "見習いどもが持っているあのfeather charmsには、何らかの魔力が宿っている。研究するのが楽しみだ。トロールからそんなものが出てくるとは思ってもみなかった。", "実によい、実によい! よくやった、{name}。お前に寄せられている関心も、結局は値するものなのかもしれん。\n\nそれを決めるのは他の者たちだがな――お前のimpがお前を圧倒して、その経歴を芽のうちに摘み取らなければの話だ。今のところ、{class}としての最初の数か月はおそらく生き延びるだろうと、私は満足している。\n\nimpについて一言だ、{name}。{race}なら承知しているだろうが、その大きさに騙されるな。あれの魔法は非常に危険になりうる。", 0xf98072ec, 0xf994bd58, 0xa842c92b, 0xeeb2dc13, 0xe52d5af0, "....." },
  [1618] = { "Redridgeの備え", "Tormus Deepforgeは、Runed Copper Belt・Heavy Copper Maulをそれぞれ4つずつRedridgeのVerner Osgoodに渡すよう求めています。", "戦っているのは俺たちドワーフだけじゃない。人間の同盟軍も手一杯なんだよ!\n\nRedridgeはblackrock族のオークから断続的に攻撃を受けていて、いつも装備の供給が足りてないんだ。あいつらを手伝ってやったら、常駐鍛冶師のVerner Osgoodがコツのひとつやふたつ教えてくれるだろうよ。", "Ironforgeから良い知らせを持ってきてくれたんだといいが。もうどうしていいか分からないんだ!", "ありがとう、{name}。大いに助かるよ。Blackrock族オークはStonewatch Keepから攻撃を仕掛けてくるし、Redridge gnollsは北の山麓に待ち伏せしている。俺はいつも我が軍のために鎧を修理して新しい武器を作ってるんだ。\n\nあんたの持ってきてくれた物資が束の間の平穏をもたらしてくれるだろう。何かを教えてあげる時間は充分ありそうだ……。", 0x2d039f79, 0xf39d4ff5, 0x66c6d741, 0x49945919, 0x462fb187, "....." },
  [1638] = { "ウォリアーの訓練", "StormwindのHarry Burlguardと話して下さい。", "君は有能なウォリアーであることを示した、{name}。だが、まだ若く、学ぶことはたくさんある。\n\nHarry Burlguardと話してみろ――たいていはStormwindのOld TownにあるPig and Whistleという酒場にいる。Harryは古参の兵で、良い教師だ。長生きできる技をいくつか教えてくれるだろう。", nil, "おお! 一杯やろうじゃないか、{name}。見た目は頑丈そうだが、Pig and Whistleで一番強いのを何杯か、その腹が受け止められるか見てみようぜ!!\n\nそれとも……稽古をつけてもらいに来たのか?", 0x93c881d5, 0x0aef52fa, 0x0ff82d16, nil, 0x11af52b0, "...m." },
  [1639] = { "Bartleby the Drunk", "Bartlebyと話して下さい。", "ああ、教えてやってもいい。だがまずは、お前がすでにどんな技を持ってるか見せてもらいたい。\n\nあそこのカウンターの端にいる酔っ払いが見えるか?Bartlebyだ。あいつのマグを手に入れてこい。\n\nハッ、Bartlebyを知ってるなら、あいつがすんなり渡すはずがないことも分かるだろう。", nil, "こんにちは、おしゃれさん! あんたみたいな身なりのいい奴がPig and Whistleで何してんだ? 気をつけろよ。でないと爪が欠けちまうぜ……。", 0x1785381a, 0x423c9e83, 0x1cf66148, nil, 0x99442b95, "...m.", nil, nil, nil, nil, 0x4102c003 },
  [1640] = { "Bartlebyを倒せ", "Bartlebyを倒してから彼に話しかけて下さい。", "何が欲しいって??頭がおかしいんじゃないか!\n\nこのマグを手に入れたいなら、俺の冷たくなった死体の指から引きはがすしかないぜ……", "このジョッキが欲しけりゃ、俺の冷たくなった死体の指からもぎ取るしかないぜ……", "見た目よかずっと強いんだな!", 0x26ecfd0d, 0x3f5bb9b0, 0xe0771850, 0xa0dfd961, 0xdc83d2d5, "....." },
  [1641] = { "Tome of Divinity", nil, nil, nil, "ここStormwindで、私はパラディンたちを、より大いなる美徳への道へと導く務めを担っている。彼らは光に身を捧げ、Scourgeやその他の脅威からAzerothを守るのだ。\n\n君が真に美徳ある者となるための第一歩を踏み出す時が来た。受け入れるなら、Book of Divinityを授けよう。それを学べば、光について、そして君に期待されていることについて、いくらか知ることになる。それを理解し、力があるならば、より大いなる力を得ることができるだろう。", 0xe91f21c0, nil, nil, nil, 0xde6e2d42, ".mmm." },
  [1642] = { "Tome of Divinity", "StormwindのDuthorian Rallに話しかけて下さい。", "何事においても、パラディンは我らの力を補う光を映し出さねばなりません。我らのような者にとって神聖であろうと努めることは、神になろうと努めることではありません――あらゆる行いにおいて善であろうと努めることなのです。\n\nこの厳しい時代に悪を討つよう求められてはいても、あなたを真にAzerothの民から際立たせるのは他者を助けることなのだと、常に覚えておかねばなりません。思いやり、忍耐、勇気――これらはパラディンにとって、戦いにおける力と同じだけの意味を持つのです。\n\nこのことをよく心に刻み、決して忘れないでください。", nil, "また会ったな、{name}。Tome of Divinityの学びはどうだ?\n\nならば、自らを試される用意ができているはずだ。この街や我らの地には、なすべき務めが常にある。慈悲と理解の行い、助けを必要とする人々、討つべき獣たち。\n\n他者を、とりわけ恵まれぬ者たちを助ける忍耐があると示すことで、お前は光に仕える者であり、健全な心の持ち主であることを証明するのだ。", 0xe91f21c0, 0x0f3ca705, 0x0d5218fa, nil, 0x075c2620, "...m." },
  [1643] = { "Tome of Divinity", "StormwindのTrade DistrictにいるStephanie Turnerを探して下さい。", "では、あなたの務めはこうです、{name}。ここStormwindで、助けを必要としている人を見つけなさい。心も動機も清らかな人を。もしかすると、他者を助けている人かもしれません。もしかすると、案内を必要としている人かもしれません。いずれにせよ、その人は気高い志を持ち、あなたの親切を頼りにしていなければなりません。\n\nこれを成し遂げたら、私のもとへ戻ってきなさい。そのときに、あなたの道について、そして光のパラディンであるとはどういうことかについて、さらに話し合いましょう。", nil, "あら、こんにちは、あなた。冒険はどう? まあ、順調だと聞けて嬉しいわ。\n\nあら、私? 聞いてくれてありがとう――いろいろあるけれど、元気にやっているわ。\n\n商人が増えたせいで、皆が手放してくれる革や布の量がめっきり減ってしまってね。孤児院の子どもたちの服を作るのが難しくなっているの。でも何とかするわ。「私たち」というのは、夫と私のこと。あの人はIronforgeで、あそこの市民に助けを求めているのよ。", 0xe91f21c0, 0xce0e1021, 0x63f1ddfe, nil, 0x3d88e066, "...m." },
  [1644] = { "Tome of Divinity", "Linen Cloth 10枚をStormwindのStephanie Turnerに渡して下さい。", "かわいそうに、あの子たちのほとんどは、この十年のScourgeの襲撃のせいで家族がいないのです。\n\n夫のJohnが子供たちのシャツやズボンを作るための材料を集めてくれるのですが、それを作る時間さえ取れていません。あの子たちのお皿に食べ物をのせ、頭の上に屋根を保つことで精一杯だったのです。\n\n何ですって?手伝ってくださるの?ああ、光に感謝します。そして、あなたにも感謝します、{name}。\n\n子供たちの服を縫えるように、linen clothを持ってきてもらえたら、本当に助かります。", "うちのJohnがIronforgeでうまくいっているといいのだけど。子供たちと私を置いていくことになるから、あの人はあそこへ行くのをとても嫌がるの。でも、行かなきゃならないことは分かっているのよ。本当に優しい人なの。\n\n楽な年もあればそうでない年もあったけれど、今年はずっと厳しいわ。まるで空気の中の何かが、大きな変化の兆しを告げているみたい。でも、誰にも分からないわよね?", "ありがとう、{name}、本当にありがとう!\n\n子どもたちも大喜びするわ。それに、おかげでずいぶん時間が助かった。これで子どもたちの他の入り用にも手をかけられるし、うちのJohnも思っていたより早く帰ってこられるかもしれないわ。\n\n重ねてありがとう、{name}。人の情けを頼りにできると分かっていたわ。光があなたとともにありますように。", 0xe91f21c0, 0xf1310977, 0xb01329b2, 0x903a4103, 0x6226b5ac, "....." },
  [1645] = { "Tome of Divinity", nil, nil, nil, "会えて嬉しいよ、{name}。私はパラディンたちを、より大いなる美徳への道へと導く務めを担っている。彼らは光に身を捧げ、Scourgeやその他の脅威からAzerothを守るのだ。\n\n君が真に美徳ある者となるための第一歩を踏み出す時が来た。受け入れるなら、Book of Divinityを授けよう。それを学べば、光について、そして君に期待されていることについて、いくらか知ることになる。それを理解し、力があるならば、より大いなる力を得ることができるだろう。", 0xe91f21c0, nil, nil, nil, 0xd28a44f8, ".mmm." },
  [1646] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "何事においても、パラディンは我らの力を補う光を映し出さねばなりません。我らのような者にとって神聖であろうと努めることは、神になろうと努めることではありません――あらゆる行いにおいて善であろうと努めることなのです。\n\nこの厳しい時代に悪を討つよう求められてはいても、あなたを真にAzerothの民から際立たせるのは他者を助けることなのだと、常に覚えておかねばなりません。思いやり、忍耐、勇気――これらはパラディンにとって、戦いにおける力と同じだけの意味を持つのです。\n\nこのことをよく心に刻み、決して忘れないでください。", nil, "おかえり、{name}。本を読む時間は取れたのだろうな?\n\nならば、自らを試される用意ができているはずだ。この街や我らの地には、なすべき務めが常にある。慈悲と理解の行い、助けを必要とする人々、討つべき獣たち。\n\n他者を、とりわけ恵まれぬ者たちを助ける忍耐があると示すことで、お前は光に仕える者であり、健全な心の持ち主であることを証明するのだ。", 0xe91f21c0, 0x04be03fc, 0x0d5218fa, nil, 0x8e061755, "...m." },
  [1647] = { "Tome of Divinity", "Ironforgeの外周円でJohn Turnerを探して下さい。", "では、{name}、あなたの務めは、ここIronforgeで助けを必要としている者を見つけることです。心も動機も清らかな者を。他者を助けている者かもしれません。導き手を必要としている者かもしれません。いずれにせよ、その者は高潔な志を持ち、あなたの優しさを頼りにしている者でなければなりません。\n\nこれを果たし、終わったら私のところへ戻ってきなさい。そのときに、あなたの道について、そして光のパラディンであるとはどういうことかについて、さらに話し合いましょう。私はあなたが戻るまでここの神殿にいます。他のパラディンたちも私の導きを必要としているのです。", nil, "こちらSTOR……の孤児院――ああ、失礼、怒鳴るつもりはなかったんです、お客さん。\n\n私の名はJohn Turnerといいます。ご機嫌いかがですか?\n\nよかった、よかった、順調だと聞けて何よりです。今日はもう長いこと働いていましてね、妻がひどく恋しいですよ。でも、食わせる口と着せる背中があるなら、それは払わねばならない代償です。", 0xe91f21c0, 0xa7a38a3f, 0x6e4cdf70, nil, 0xd326865b, "...m.", nil, nil, nil, nil, 0xc090c1d5 },
  [1648] = { "Tome of Divinity", "IronforgeのJohn TurnerにLinen Cloth 10枚を渡して下さい。", "妻と私はStormwindで孤児院を営んでいるんです。主に、この十年のScourgeの襲撃で親を失った子供たちのためのものです。私はひと月かそこらごとにIronforgeへ来て、ここの市民から物資をもっと集められないか当たり、さまざまな団体と話して、何か手助けしてもらえないか探っています。\n\n今回の旅はひどく時間がかかっていて、あまり成果も上がっていません。\n\n妻が服を作れるように、もう少しlinenが手に入りさえすれば、ようやく荷を故郷へ送れるのですが。", "ここやAzeroth中に商人が押し寄せているせいで、うちの孤児院の子供たちの服を作る材料が品薄になっているんだ。妻が子供たちの新しい服を作れるように、linen集めを手伝ってくれるなんて、とても立派なことだよ、{name}。ありがとう。\n\nもうすぐ妻の待つ家へ帰れるといいんだが。", "こんなことをしてくれるなんて、本当に素晴らしいわ、{name}。重ねてお礼を言います。\n\n私のためにこんなことをしてくれるなんて、あなたは気高い人ね。光の道を選んだのも当然だわ。あなたがしてくれたすべてに、何か報いる方法があればいいのに……え、何ですって? 当然のことをしたまで? ほらね? それが私の言っていることよ、{name}、最後まで気高いわ。\n\n道中お気をつけて。旅路に光の加護がありますように。", 0xe91f21c0, 0xfd1fbfec, 0xabd207ba, 0xfcf718e1, 0x929bdf7f, ".....", nil, nil, nil, nil, 0xc7eef468 },
  [1649] = { "Tome of Valor", "StormwindのDuthorian Rallに話しかけて下さい。", "勇気と、それに伴うあらゆる美徳は、希少な鉱物のようなものです。その価値ゆえに、見つけたときには大切にしなければなりません。けれども同時に、時間をかけて掘り出し……精錬しなければなりません。正しく混ぜ合わされたとき、強い合金が生まれ、ときには最も強力な打撃にさえ砕けないものとなるのです。\n\nこの強さ、あなたの信仰、あなたの勇気は、試されなければなりません。決して信仰を失わないことを学び、光の力があれば、他の多くの者にはできないことも乗り越えられるのだと悟らなければなりません。", nil, "ああ、武勇の試練を願い出に来たのだな。結構。\n\nこの街とその周辺の地には、大きな試練を伴う務めが数多くある。あなたのような技量の持ち主の力を必要としているのだ。\n\nこの試練を軽く見てはならない、{name}。我らの道にある多くのことと同じく、これも命を落としかねないものだ。Churchは常にその陣容を強くすることを望んでいるが、仕えるパラディンが真にふさわしくあるために必要な犠牲も理解している。\n\n覚悟はよいか?", 0xdaebf666, 0x0f3ca705, 0x19f0af5d, nil, 0x370b9c7b, "...m.", nil, nil, nil, nil, 0xeacd036c },
  [1650] = { "Tome of Valor", "WestfallにいるDaphne Stilwellを探して下さい。", "よろしい！ ためらわないのは、準備ができていて、自らを試すことに意欲的な確かな証です。では、そうしましょう。\n\nWestfallのLongshoreのいちばん端に、海を見下ろす小さな家があります。そこにはStilwellsという夫婦が住んでいます。Jordanは素晴らしい鍛冶師で、しばらくドワーフたちと会うためにIronforgeへ行っています。けれどもそのせいで、彼の妻Daphneは一人きりで、守る者もいないのです。\n\n報告によれば、Defiasがあの一帯をほとんど支配してしまったとのこと。Daphneには悪党どもからの護衛が必要かもしれません。そこへ行きなさい。", nil, "こんにちは、{name}。その鎧と武器から察するに、あなたは私の土地を奪いに来たか、Jordanが留守の間に私を守るためにChurchがようやく誰かを寄越したかのどちらかね。\n\nでは自己紹介させて。私はDaphne Stilwell。よろしくね。\n\nまだ遅くはないわ……日が昇ってからは、あのクズどもを半ダースほど殺しただけ。向こうの曲がり角を回ってくるのが少し遅れているけれど、たぶんあなたが来るのが見えたんでしょう。つまり、もうすぐここに現れるってことよ。", 0xdaebf666, 0xcafbffbb, 0x9e791513, nil, 0xd85dbe60, "...m." },
  [1651] = { "Tome of Valor", "Defiasの襲撃からDaphne Stilwellを守る。\n\n成功したいなら、あなたと彼女のどちらの魂も肉体から解き放たれてはならない。\n\n成功したら、もう一度Daphne Stilwellと話して下さい。", "さて、あいつらはきっとすぐにまたやって来るわ。だから準備をしておいて。\n\n家に銃があるの。それを取ってきて、あなたを手伝えるようにしておくわ。でも、ほとんどはあなた一人で戦うことになるわね。\n\nあいつらが何人よこすのかは分からないけど、さっきよこした数人より多いのは確かよ。\n\n光に祈って、授かれるだけの祝福を授かっておいて。だって……今の聞こえた？ 来たみたい。\n\n家のそばで迎え撃つわよ！", "この家で迎え撃つぞ!", "やったわ、{name}! 助けてくれてありがとう。あなたは本当に見事だった。パラディンがあんなに大勢の敵を一度に相手にできるなんて、思ってもみなかったわ。\n\n圧倒的な不利を前に、あなたは本当の勇敢さを見せてくれた。", 0xdaebf666, 0x891ebe27, 0xa90e2959, 0x52f37378, 0x0f46273c, "....." },
  [1652] = { "Tome of Valor", "StormwindのDuthorian Rallに話しかけて下さい。", "お願い、Duthorianのところへ戻って、私はひとまず無事だと伝えて。あなたとChurchのおかげだわ。\n\n彼がIronforgeへ知らせを送って、私のJordanに何も心配はいらないと伝えてくれるはずよ。\n\nああ、夫が恋しいわ。帰ってくるのが待ちきれない。", nil, "また会ったな、{name}。ずいぶん意気軒昂のようだ。\n\nStilwell家はもう一日安全でいられるだろう。そしてお前の話から、危険には事欠かなかったことがよく分かる。よくやった。\n\nDaphneとJordanはChurchに大きく貢献してくれた。彼らの財産を、そして命そのものをお前に守ってもらうことは、我々が彼らにしてやれる最低限のことだったのだ。\n\nその武勇に対し、報酬が与えられるだろう。", 0xdaebf666, 0x0f3ca705, 0xc192be15, nil, 0xccb181a9, "...m." },
  [1653] = { "正義の試練", "IronforgeのJordan Stilwellに話しかけて下さい。", "実のところ、Jordan本人もあなたに礼を言いたがるに違いありません。それに、彼の妻が無事だと知らせる使者が必要なので、あなたはうってつけだと思います。\n\nJordanは、父親の技に打ち込んで別の道へ進むまでは、光のパラディンになるはずでした。彼は私たちの生き方をよく知っていて、私たちの中でも最も信仰の厚い一人とされているのです。\n\nまだIronforgeにいるはずです。昼間は門の外で仕事をするのが好きなのです。山の涼しい空気がどうとか言っていました。", nil, "やあ、{name}。光は君と共にあるか?\n\n何だって? Duthorianに遣わされただと!? 妻は、妻はどうしている? 私が発てば面倒なことになると分かっていたのだ。頼む、彼女は……ああ、よかった。無事でいてくれて本当に嬉しい。Defiasはこの襲撃のずっと前から脅威だったが、今や王の顧問たちもそれを否定できまい。\n\nDuthorianは他に何か言っていたか?\n\n妻を守るために遣わされたのが君なのか? ならば改めて礼を言う、{name}。それ以上の勇気の試練など思いつかないよ。", 0xcdb318ba, 0x81a2ff9b, 0x9423b858, nil, 0xcf755a7e, "...m." },
  [1654] = { "正義の試練", "Jordan's Weapon Notesを読み、Whitestone Oak Lumber・Bailor's Refined Ore Shipment・Jordan's Smithing Hammer・Kor Gemを探して、IronforgeにいるJordan Stilwellのところへ持ち帰って下さい。", "よければ、君に礼をしたいんだが、受けてもらえるかな？ 誤解しないでくれ。俺の気前の良さは、君がどれだけ役に立てるかにかかっている。だが、この協力で俺たち二人とも大いに得をすると思うんだ。\n\n君が成し遂げたことにふさわしい武器を作ってやろう。パラディンであることと光の象徴だ。だが、それを作るのに必要な品は君が集めなければならない。品についてはもうメモを取り始めている。あとは、それを取り戻せるだけの勇気と腕のある者がいればいい。どうだい、{class}？", "君が探している品々を手に入れるのは難しいだろう。だが約束しよう、私が君のために作る武器は、その苦労に見合うものになる。\n\nそれはこれまでで最高の作品になるだろう。そして、君がしてくれた働きに対するささやかな礼にすぎないのだ。", "こいつはすごい! 全部揃えてくれたんだな。\n\nこれだけあれば、立派な武器を鍛えるのは造作もない。実を言うと、この設計図はずいぶん前から持っていたんだ。ただ、材料を集める機会がなかっただけでな。ありがとう、{name}。\n\n親父のハンマーがまた手元に戻ってくるのはいいものだ……それにKorの宝石もな。自分がこれを目にする日が来るとは思わなかった。", 0xcdb318ba, 0xc7646423, 0xfb00e058, 0x7e9cab3a, 0x803f6796, "....." },
  [1655] = { "Bailorの荷物", "Loch ModanのBailor StonehandにJordan's Ore Shipmentを渡して下さい。", "ああびっくりした! 考え事をしてたのが見えなかったのか?\n\nなんだそれ? Jordanの荷物……Ironforgeへの……。ああああ、うん、何のことか分かった。Mo'grosh ogreだよ……あいつらが荷物を盗ったんだ。Wetlandsからここへ向かってたキャラバンが襲撃されたんだ。辛うじて生き延びた護衛もほんの何日か前に亡くなった。医師が間に合わなかったんだ。\n\n荷物が必要なら、湖を越えて北東に行ってくれ。その辺りのどこかにあるはずだ。", "で、うまくいったか? ハハ、あのogresにまだやられちゃいないよな?", "うんうん、これだよ。ちぇっ! あんたが本当にあそこへ行ってogreと戦うって知ってたら、ひとつだけじゃなくて取り返す物リストを渡してたのに。でも、俺のために仕事をしに来たわけじゃないんだよな?\n\n約束は約束だ。Jordanは合金の荷物を求めてたんだ。これこそが彼の欲しがってたものだよ。\n\nあいつによろしく言っといてくれ。それと達者でな、{class}。", 0xa7b78c4d, 0x20c7415e, 0x9cf966dc, 0x0aa0afd3, 0xfa19665f, ".....", nil, nil, 0xc6e76059, nil, nil },
  [1656] = { "やりかけの仕事", "Bloodhoof VillageのInnkeeper KauthにBundle of Fursを持って行ってください。", "{name}、どうかお願いします。助けてくれませんか? Mesaでの仕事が終わらなくて……Rite of Strengthの真っ最中なんだけど……父がこの毛皮をBloodhoofの宿まで持って行ってくれないかって言うんです。\n\n父の頼みと儀式と両方をこなすには疲れてしまって。どうかお願いできませんでしょうか。\n\nその宿は快適で、あなたの長旅の疲れを癒すのには最適なところです。行ってみたらきっと、あなたもうなずけると思いますよ。", "何かな、若いの? Kauthに何ができるかね?\n\nMesaからここまでの旅は、ある者にはひどい重荷となり、またある者には喜ばしい光景となる。そなたにとってはどちらであろうな?", "ああ、思ってた通りの毛皮だ。どうもありがとう。\n\n意外と早く届いたなあ。この毛皮はね、誰もがここに泊まりたくなるような、上質の毛布になるんだ。\n\n遠慮無く好きなだけ泊まっていくといい。私の宿はいつも開いてて、全ての人を歓迎するよ。\n\nそれと、安眠をあなどっちゃいけない。旅に出てるあいだは、それが大きな違いになってくるからね。", 0xc958b12f, 0x96f2a5d5, 0xd339afba, 0xcd32ef45, 0xd1fe2ab2, "....." },
  [1657] = { "Southshoreに悪臭を放て", "Forsaken Stink Bomb 3個をHillsbradのSouthshoreの中心に投げ込み、Tirisfal GladeのWickerman FestivalにいるDarkcaller Yankaのところへ戻って下さい。", "Hallow's Endは派手に祝おう……Southshoreの敵どもに悲嘆をくれてやってな！\n\n特製の悪臭爆弾を一つ持っていけ。人間には、いや、それを言うなら意志の弱い獣ならどいつも、嗅ぐのに耐えられない強烈な悪臭が詰まっている。役目を果たさせるには、Southshoreのど真ん中に投げ込まなければならん。だから、Allianceとの戦いに備えておけ！\n\nこの任務……我らの解放へのこの捧げ物を果たしたら、俺のところへ戻ってこい！", "Southshoreの民に我らの「贈り物」は届けたか?\n\n<Darkcaller Yankaは邪悪に笑う。>", "ああ、よくやった! 我々がScourgeの隷属の軛に喉を詰まらせられたように、Allianceも我々が贈ってやったあの汚らわしい贈り物に喉を詰まらせればいい!\n\nお前はHallow's Endの精神を守り抜いた、{name}。そのことに敬意を表する。おまけとして、手持ちのHallow's Endの菓子を分けてやろう。なかなか楽しい気晴らしになると思うぞ。", 0x2e8981db, 0x9b71ae92, 0x2245cc22, 0x49b9ebdb, 0xd4d650e8, "....." },
  [1658] = { "Wickerman Festivalをぶち壊せ", "Tirisfal GladeでForsakenのWickerman Festivalを探して下さい。それを終えたら、SouthshoreのSergeant Hartmanのところへ戻って下さい。", "Tirisfal Gladeまで行って、Wickerman Festivalを探ってくれる勇敢な者が必要だ。嘘は言わない。あそこへ行くのは危険だ。祭りの衛兵はとりわけ凶暴だろう。それでも、今年の祭りがどれほどの規模なのか、そしてHallow's Endの間にForsakenがどれだけ厄介事を起こすつもりなのかを知る必要がある。\n\nやる気があるなら、Tirisfalへ行って祭りを偵察してこい。情報を持って戻ってくれば、たっぷり報酬を出すと約束しよう。", "Tirisfal Gladeまで行って様子を見てきたか? 祭りはたいていUndercityの近くで開かれるんだが……", "よくやった、{name}。忌まわしいForsakenどもがLordaeronの残骸に取り憑くのを許している限り、Wickerman Festivalは厄介事であり続けるだろう。かつて誇り高かったあの王国への手向けとしては、まったくふさわしくない……そう言わせてもらう。\n\n修理に必要なら、この金を使ってくれ。それと、この季節にちなんで気に入りそうな菓子も入れておいた。よいHallow's Endを。ここSouthshoreをできる限り安全に保とうじゃないか。", 0xea538ce9, 0xaea7886b, 0xb5ed7ed6, 0x1e87c181, 0x044aeaed, "....." },
  [1661] = { "Tome of Nobility", "StormwindのDuthorian Rallと話して下さい。", "再びそなたに挨拶しよう、{name}。そなたを同胞と呼べることを、今ほど誇らしく思ったことはない。そなたの献身は、我ら皆への賛辞だ。\n\nそなたに大いなる贈り物を授ける時が来た。だが、これだけは心得ておくがよい。今はこれを無償で与えるが、いずれ時が許せば、我が探求を引き受けようとするすべてのパラディンにとって、これははるかに大きな試練となるであろう。\n\n再び我に話しかけるがよい。そうすれば、大いなる恩恵を授けよう。", nil, "おめでとう。光が君を守らんことを。", 0x2923ea98, 0x0f3ca705, 0xb8e31e55, nil, 0x72ae1e80, "...m.", nil, nil, 0xe0eeab96, nil, nil },
  [1665] = { "Bartleby's Mug", "Bartleby's MugをBurlguardに渡して下さい。", "分かったよ。俺のジョッキだ。ちょっと待て! その前に残りを飲ませてくれ……ああいいぞ。", "Bartlebyとの戦い、見てたぞ。見事だった! 彼のmugは手に入れたか?", "それだ! あいつはよほど手放したくなかっただろうが、うまく説き伏せたな。よくやった。\n\nさて、お前の修行を始めるとしよう……", 0x02b31d24, 0x1a2aa8fa, 0xbe9a356b, 0xc1276dca, 0xd416acd3, "....." },
  [1666] = { "Marshal Haggard", "Marshal Haggardと話して下さい。", "いくつか技は覚えたが、まだまともな武器があったほうがいいな。Marshal Haggardと話せば、きっと力になってくれるだろう。\n\nMarshal HaggardはElwynn ForestのEastvale Lumber Campにある屋敷に住んでいる。今は引退しているが、現役の間に装備をたくさん集めていたんだ。\n\n俺の紹介だと伝えれば、運が良ければ予備の武器を譲ってくれるだろう。", nil, "誰だ?\n\nBurlguard、お前か?\n\nもう少し近くに寄ってくれんか。この目も昔ほど利かなくてな。\n\nそんなふうに歩いてこられたら、gnollかと思ったぞ!", 0x0f30a247, 0x28259910, 0x2a45bdb6, nil, 0x9c239c26, "...m." },
  [1667] = { "Dead-tooth Jack", "Dead-tooth JackのキャンプからHaggard's Badgeを取り戻し、Marshal Haggardに返して下さい。", "Burlguardの紹介で来たのか？ ああ、予備の武器ならこのあたりにある。だが、まずは君に頼みたいことがある……\n\n少し前、Defiasの悪党Dead-tooth Jackにだまされたんだ。暗かったし、奴はStormwindの陣羽織を着ていたので、Marshal Dughanだと思ってしまった。奴は私の古いStormwindの元帥のバッジが必要だと言い、私はそれを渡してしまった……すると奴は笑って、私が捕まえる前に逃げていったんだ！\n\n私のバッジを取り返してくれ！ Dead-tooth Jackはおそらく南にある自分のキャンプにしまい込んでいるはずだ。", "私のバッジは持っているか? Dead-tooth Jackがそれを使ってどんな悪さをするか、考えたくもない。", "素晴らしい、見つけてくれたか! 永久に失われ、DefiasがStormwindの役人になりすますのに使われるのではと恐れていた。だが君のおかげで、そうはならない。\n\nこれは私が元帥だった頃に使っていた武器だ。手入れは万全にしてある——好きなものを選んでくれ!", 0x3fd751ee, 0xe3968aa6, 0x35913d6c, 0x0dd5019b, 0xaa14a96f, "....." },
  [1678] = { "Vejrek", "Vejrek's HeadをIronforgeのMuren Stormpikeに渡して下さい。", "ウォリアーとして昇進したいなら、タフでなければならん。新しい技を教えてやることはできるが、その前に、本物の敵を相手に自分の身を守れることを証明してみせろ。\n\nVejrekはこのあたりで一番手強いトロールで、お前が倒すべき相手だ。奴はFrostmane Holdのすぐ南の丘陵地帯に小屋を構えている。\n\nVejrek's headを持ってこい。そうすれば、お前に根性があると認めてやる。", "Vejrekの小屋へは行ったか、{name}? お前から臭うのは{race}の悪臭か?", "Vejrekは実に醜い奴だっただろう? 見事だ、{name}! お前には素質がある。さあ、修行を始めよう……\n\n知らないかもしれんが、堅固な防御は{class}にとって非常に重要だ。他の者なら倒れるような敵を前にしても立ち続けられる。それこそ仲間が求めているものだ。", 0x79ac8618, 0x8eeb8a4d, 0x97c7fda5, 0xbfd8004a, 0x4056a577, "....." },
  [1679] = { "Muren Stormpike", "Muren Stormpikeと話して下さい。", "やあ、ウォリアー！ 君はなかなか見込みがあるが、まだ覚えるべき技がある。それを教えるのにうってつけのドワーフがMuren Stormpikeだ。\n\nMurenはIronforgeのMilitary WardにあるHall of Armsにいる。ウォリアーであるとはどういうことかを学ぶ準備ができたら、彼に話しかけるといい。", nil, "ああ、{name}か。Dun Moroghのウォリアーたちがお前さんの名をあちこちで噂しておったぞ。お前さんが醸造所でずっと時間を費やさないよう願うぞ!", 0xd9ddd0b2, 0xdec45bd4, 0x8fd9e632, nil, 0x01c660f9, "...m." },
  [1680] = { "Tormus Deepforge", "Tormus Deepforgeと話して下さい。", "技をいくつか覚えたところで、まともな武器を手に入れる頃合いだ。Tormus Deepforgeと話してこい。きっと気に入る武器を作ってくれるはずだ。\n\nTormusはここ、IronforgeのGreat Forgeにいる。", nil, "Murenに寄越されたのか。ああ、いい武器を作ってやれるとも……だがその前に、一つ頼みがある。\n\n心配するな。十分に危険で、死ぬかもしれん。まさに{class}が望むような仕事だ。", 0x9d447a97, 0xc2199bac, 0x02618112, nil, 0xf292e320, "...m." },
  [1681] = { "Ironband's Compound", "IronforgeのTormus DeepforgeにUmbral Oreを渡して下さい。", "私の師匠、Sturgy Ironbandは、Dun Morogh東部のHelm's Bed Lakeの南に屋敷を構えていた。そこで鍛冶を教えていて、誰よりも腕が良かったんだ。\n\nだがある日、弟子の一人が奇妙な鉱石を一山持ち込んできた。Master Ironbandはそれをumbral oreと呼び、それを扱うのを心待ちにしていたが、それが届いてすぐ……Dark Ironのドワーフの一団が屋敷を襲ったんだ。奴らは全員を殺した！\n\nIronbandの屋敷に踏み込んで、{name}、師匠の仇を討ってくれ。そして、その原因となったumbral oreの山を持ってきてくれ。", "Ironband's Compoundには入ったか? umbral oreは見つかったか?", "見つけたか! よくやった!\n\n探している間にDark Ironのドワーフを大勢殺してくれたなら何よりだ。Ironbandの施設が奴らを見る最後の場所にはならんだろうな。\n\nとにかくoreをありがとう、{name}。早く加工して、その性質を確かめたいものだ。", 0x2a3780d0, 0x4a772cf1, 0x9c8b9801, 0xb61614dd, 0xbd6d2250, "....." },
  [1682] = { "鉄灰色の武器", nil, nil, nil, "さあ武器だ。金床から出したての、君が持ってきてくれた新しいumbral oreで作ったものだぞ!\n\nさあ{name}、好きなものを選んでくれ!", 0x73849205, nil, nil, nil, 0x676432e2, ".mmm." },
  [1683] = { "Vorlus Vilehoof", "DarnassusのElanariaにHorn of Vorlusを渡して下さい。", "私があなたに教える前に、あなたの決意を見せてもらわなければなりません。\n\nsatyrのVorlus Vilehoofが、Ban'ethil Barrow Denの南東にある、私たちの人里離れた月の泉の一つを見つけました。今やその中で水を跳ね散らし、清らかな水を穢れで汚しているのです。\n\n月の泉でVorlusを見つけ、滅ぼしなさい。証として奴のhornを持ってくれば、ウォリアーとしての上級の訓練を始めましょう。\n\n月の泉への道はよく隠されています、{name}。けれども、気を抜かず注意を払っていれば、きっと見つけられるでしょう。", "hornは手に入れましたか、{name}? 私たちの月の泉は、悪鬼Vorlusから解放されましたか?", "よくやりました、{name}。Vorlusが倒され、我らの月の泉が清められたと知って安堵しています。そして、愛するTeldrassilを穢れから守ろうと意気込む若いウォリアーを見られるのも喜ばしいことです。\n\nさあ、あなたの訓練を始めましょう……", 0xd401ffda, 0x5adfba87, 0x8fb16149, 0x049695c0, 0x512c5bec, "....." },
  [1684] = { "Elanaria", "Elanariaと話して下さい。", "ごきげんよう、ウォリアー。あなたの腕は上がっていますが、あなたの職には、あなたが思っている以上のものがあります。さらに進むには、近いうちに師を見つけなければなりません。\n\nウォリアーのElanariaが、DarnassusのWarrior's Terraceにいます。彼女があなたを指導してくれるでしょう。", nil, "ご機嫌よう、{name}。あなたの名前はDarnassusで広く知れ渡っていますよ、将来の見込みがあるということで。ですが、{class}の道を歩む意志の力を持っているかどうか、すぐに調べなくてはなりません。", 0x521e2628, 0x1d103619, 0xe3640e54, nil, 0xee8cf141, "...m." },
  [1685] = { "Gakinの呼び出し", "StormwindのMage QuarterにいるGakin the Darkbinderの元へ出向いて下さい。", "いつもこうなるんだよな？ 一日中探しても見つからなかったのに、こっちが予期していないときに、向こうから真っすぐ歩いてくるんだから。\n\n君を探すのにもう十分時間を無駄にしたから、これ以上引き止めはしないよ。Master Gakinが追加の訓練のために君を呼んでいる。できるだけ早く会いに行ったほうがいいと思うね。\n\n彼はSlaughtered Lambという酒場の地下にいる。ところで、その場所のことは黙っておいたほうがいいかもしれない。噂が広まるのは困るからね。", nil, "ようやく来たか。もっとも、お前を探すのにRemenより有能な者を送るべきだったかもしれんな。\n\nまあいい。\n\n訓練を怠りすぎだ。訓練を受けていないウォーロックなど、長く首を繋げてはいられん。", 0xafbad200, 0xd830dab8, 0x7de17495, nil, 0x9da53ed7, "...m." },
  [1686] = { "Eluraの亡霊", "Elunite Ore 8個・Medallion of EluraをDarnassusのElanariaに渡して下さい。", "あなたは多くを学びました、{name}。今こそあなたのために武器を作りましょう。ウォリアーの武器を。\n\nそのためには、Darkshoreへ旅しなければなりません。\n\n昔、Auberdineの灯台の近くで船が岩に乗り上げ、たくさんのelunite oreの木箱が海底に散らばりました。\n\nまず、eluniteの守護者、Shade of Eluraを倒さなければなりません。彼女はかつてその船の船長で、自らに呪いをかけ、永遠に深みをさまよって積み荷を守っているのです。彼女を倒してメダルを手に入れ、失われたEluniteの木箱を集めなさい。", "Shade of Eluraを倒しましたか、{name}? そして、失われたelunite oreは持っていますか?", "勇敢な働きでした、{name}。\n\nあなたはShade of Eluraに、当然与えられるべき安らぎをもたらしました。集められたeluniteを使って、あなたのために見事な武器を作りましょう。", 0x8040e914, 0x47fcac4e, 0x0ae1f260, 0x77ddb931, 0xe02c3ab9, "....." },
  [1687] = { "不気味な灯台", "Westfallの海岸のはずれにある灯台へ孤児を連れて行って下さい。", "夜遅くになると、孤児院の寮母さんたちがときどき怖い話をしてくれるんだ。あれ、最高なんだよ！ Westfallの灯台に出る幽霊の話があってさ。その幽霊は、他の海賊に船を奪われた海賊の船長だったんだって。すごいよね！\n\nWestfallの灯台に連れていってくれない？ その船長の幽霊がいるか見てみたいんだ！ ちゃんとそばにいるって約束するよ。勝手に走っていったりしないから！", "まだ着かないの?", "わあ、本物の幽霊だったね! すごくかっこよかった——孤児院のみんなに早く話したいな。Captain Grayson……海賊みたいな見た目だったよ! 大きくなったらぼくも幽霊の海賊になりたい!\n\nWestfallに連れて行ってくれてありがとう、{name}。Westfallの荒野には怖いものがいるって知ってるし、あんまり迷惑をかけてなかったらいいな。きみは最高だよ!", 0x31cdf2d0, 0x06462a80, 0x21a7f6b6, 0x63e6b64c, 0x2a4e0c50, "....." },
  [1688] = { "Surena Caledon", "StormwindのGakin the Darkbinderのために、Surena's Chokerを取り戻して下さい。", "私にはSurena Caledonという弟子がいた。彼女は今お前が立っているところに立ち、ウォーロックの魔法を学ぶことに意欲を燃やし、少なからぬ才能を持っていた。それ以上に、若く、見目も良かった。あのとき気づいていれば、あの裏切り者のあばずれめ！\n\nあの盗人女はDefiasの一人、Erlan Drudgemoorと駆け落ちした。あの女を失ったこと自体はどうでもいいが、私はあの女にbloodstone chokerを贈っていて、それはどうしても取り戻さねばならん。\n\n今やあの女の命など私にはどうでもいい。Brackwell Pumpkin Patchにいるはずだ。私のものを取り戻してこい。", "年を重ねた賢い者でさえ、若さと美しさの手管には骨抜きにされるものだ、{name}。生涯覚えておくとよい忠告だぞ。", "Surenaには才能があったが、独力でウォーロックの魔法を極めるには足りなかった。才能が無駄になるのは惜しいが、時には必要なことだ。\n\nお前への投資は違う結果を生むことを期待している。", 0x9384a1d7, 0xbd6285ef, 0x7fe37381, 0x1aeacf64, 0x26838f1f, "....." },
  [1689] = { "拘束", "Bloodstone Chokerを使って召喚したvoidwalkerを倒し、StormwindのGakin the DarkbinderにBloodstone Chokerを返して下さい。", "私のchokerを取り戻し、Surenaを打ち負かしたことで、お前は少なくとも彼女と同じくらいの力があると証明した。\n\nとはいえ、お前がひどく訓練を必要としているのは分かる。魔法の流れを扱うことはできる、確かに。だが、ウォーロックであるとはそれ以上のことなのだ。\n\nvoidwalkerを従える方法を教えてやろう。だがその前に、召喚の円陣で一体を呼び出し、手持ちのあらゆる武器――物理的なものも魔法のものも――を使ってそれを屈服させねばならん。下にある召喚の円陣で、このchokerの魔法を使え。", "voidwalkerを屈服させるまでは、その操り方を教えることはできん。", "予想以上の働きだったな、{name}。期待どおりではあるが。さあ、服従させたvoidwalkerを操ることを学べる。これから必ず訪れる試練で、貴重な味方となるだろう。\n\n今のところ教えることはもうない。だが、お前との用が済んだわけでは到底ないぞ、{name}。", 0x5926988f, 0x4d76bd4b, 0xe97faec4, 0xe581a55d, 0xfecce601, "....." },
  [1690] = { "Wastewanderの裁き", "Gadgetzanの東でWastewander BanditとWastewander Thievesをそれぞれ10人ずつ倒し、Chief Engineer Bilgewhizzleに折り返し報告して下さい。", "おい、そこのあんた! Gadgetzan Water Companyの大きな助けになってもらう時が来たよ。\n\nTanarisの砂漠にいるWastewanderの遊牧民どもが、井戸をほとんど全部占領しちまったんだ! 井戸が使えなきゃ、うちの水の供給なんてあっという間に干上がっちまう。うちに気に入られたいなら、あの遊牧民どもに裁きを下す手伝いをしてもらうよ!\n\nここから東へ行って、Wastewander BanditsとThievesを十人倒して、大急ぎで報告しに戻ってきな。正義は誰のことも待っちゃくれない……人も……ゴブリンも……ええい、いいからさっさと取りかかりな!", "もう戻ったのかい? 頼んだとおり、あのWastewander BanditsとThievesにゴブリン流の正義を少しは下してきてくれたんだろうね!", "これぞ効率ってもんだ! おかげで遊牧民どもの数が十分に減って、あの水源を取り戻す算段を考え始められるようになったよ。\n\nGadgetzan Water Companyは君の助けに感謝するよ。だが、あの汚らしい遊牧民どもの始末はまだまだ終わっちゃいない。よく聞きな——次に必要なのはこれだ……", 0xfe646324, 0xc85f4c85, 0xa437315a, 0xc6dc6b8e, 0x1b088c54, "....." },
  [1691] = { "続・Wastewanderの裁き", "GadgetzanのChief Engineer Bilgewhizzleのために、Wastewander Shadow Mage 10人・Wastewander Rogue8人・Wastewander Assassin6人を倒して下さい。", "今度はWastewanderの遊牧民の中でも手強い連中を相手にしてもらいたい。ここまでよくやってくれたが、あの井戸を取り戻すなら、できるだけ少ない遊牧民を相手にするのが理にかなってるってもんだ！\n\n今回は、奴らのローグと暗殺者、それに影のメイジを倒してもらいたい。ここから東と南東にいるよ。\n\n嘘は言わない。ひどく厄介な連中だ。だが、これをやってくれれば、正当にうちらのものを取り戻す道が開けるってわけさ！", "で、頼んだとおりあの遊牧民どもを片付けてくれたか? Gadgetzan Water Companyは、ここでの君の成功をもとに計画を練ってるんだ! がっかりさせないでくれよ……", "一流の仕事だ、{name}……実に一流だ! 遊牧民の数を、こちらから討って出られるところまで減らしてくれたぞ!\n\nまだなら、ここにいるSpigot Operator Luglunketに話してみな。遊牧民どもを成敗している間に手に入れたWastewanderの水袋には、どれも報奨金を出してくれる!", 0x6f5f8f7d, 0x68f307f7, 0x189c64e9, 0xfd247196, 0xeae816bf, "....." },
  [1692] = { "Smith Mathiel", "Case of EluniteをSmith Mathielに渡して下さい。", "あなたが集めたeluniteをケースに収めました。これを鍛冶屋のMathielのところへ持っていけば、eluniteの武器を作ってくれるでしょう。\n\nMathielは南、この建物の反対側にいます。", "ごきげんよう、若き{class}よ。私の技でどのようにお役に立てるだろうか?", "ああ、elunite oreですね。女神Elune自らの祝福を受けた、扱うに値する見事な金属です。これで武器を作れるのは光栄なことです。\n\n作業の間、しばしお待ちください……", 0xfd66549a, 0x228e326e, 0x6be6ff55, 0x8c6ab610, 0xf4a34bbc, "....." },
  [1693] = { "Eluniteの武器", nil, nil, nil, "{name}、あなたが持ってきてくれたeluniteでこれらの武器を作りました。どうぞ、最も合うものをお取りください。\n\nそして礼を言わせてください。eluniteを扱うのは名誉であり、喜びでもあります。", 0x0ad2a7a8, nil, nil, nil, 0xf1481cc9, ".mmm." },
  [1698] = { "Yorus Barleybrew", "Yorus Barleybrewと話して下さい。", "Yorus BarleybrewがAllianceのウォリアー全員に挑戦を出したぞ。彼はRedridgeにあるLakeshire Innで待っている。試練に合格したもの全員に莫大な報酬を約束するとのことだ。", nil, "ハッ! 俺の挑戦の話を聞きつけたってわけか?\n\nなら座って聞け。一杯やって、じっくり味わうんだな……最後の一杯になるかもしれんからな。", 0xcd09cdbf, 0x341329a1, 0x3bd4b7dc, nil, 0xf107d207, "...m." },
  [1699] = { "Rethbanガントレット", "Rethban Cavernsに入り、最初の分かれ道まで行って、制限時間内にYorus Barleybrewのところへ戻って下さい。\n\n死んで魂を解放してはならない。", "俺の挑戦はRethban Gauntletって呼んでるんだ。試練に合格するには、Rethban Cavernsに入って最初の分かれ道まで行き、ここへ戻ってくるだけでいい。簡単だろ！ ただし、ちょっとした難点がいくつかあってな……\n\n一時間以内に戻ってこなきゃならない。\n\n途中にはRedridge Gnollsがうじゃうじゃいる。\n\n始める前に、うちの家族自慢の酒、Barleybrew Scalderをぐいっと一口飲まなきゃならない！\n\nで、どうだい？ Rethban CavernsはLakeshireの北の丘陵地帯にある。Rethban Gauntletに挑む準備はいいか？", "時間を無駄にしているぞ、{name}。私ならさっさと出発するがな……", "やったな! よくやったぞ! {name}万歳!", 0xd10a48fe, 0xa8194546, 0xfd08c428, 0x9b73f4f5, 0x9fe48580, "....." },
  [1700] = { "Grimand Elmore", "Furen's NotesをGrimand Elmoreに渡して下さい。", "あんたの鎧を作りながら身につけた技術について、俺のnotesの写しを作ったんだ。それをGrimand Elmoreに届けてほしい。彼はここ、Dwarven Districtの武器屋にいる。\n\nそれと、渡すときは身をかがめておけよ。あいつは自分の腕に猛烈な誇りを持っていて、俺から何かを学ぶなんて考えは気に入らないだろうからな……", "こんにちは、よく来てくれました。どのようなご用でしょう?", "Furenがこれを書いたのか? よくもまあ! こいつの知っていることは全部わしが教えたんだぞ! そのこいつがわしに何かを教えられるなどと、とんでもない話だ! とんでもない!\n\nふむ……だが、この覚え書きには試してみたいことが書いてあるな……", 0x32eacdf3, 0x7caa129c, 0x4e71336d, 0xe126afd2, 0x9f7c1433, "....." },
  [1701] = { "火で鍛えた鎧", "Furen Longbeardが要求した素材を集めて、Stormwindにいる彼に渡して下さい。", "いい盾をやったが、そこで終わりにする必要はない。俺はとびきり硬い鎖かたびらを作る秘訣を知ってるんだ。簡単じゃないし、非常に珍しい材料がいるが、あんたが足を使ってくれるなら、一着作ってやろう。\n\nどうだい、{name}？ 挑戦する気があるなら、何をどこで手に入れればいいかのリストを渡すよ。", "宝探しの調子はどうだ、{name}? 材料は持ってきたか?", "全部手に入れたのか? 大したものだ! あのchimaeraどもに食われてしまうのではと心配していたぞ!\n\nさて、その防具に取りかかるとしよう……", 0x63d079d1, 0x17005a3a, 0x3f524efb, 0x9d29594a, 0x8da07437, "....." },
  [1702] = { "盾職人", "Cask of ScalderをFuren Longbeardに渡して下さい。", "Rethban Gauntletを走り抜けて、あんたの実力をしっかり見せてもらったよ、{name}。俺は約束は守る男だ。約束した報酬を用意してやろう……\n\nただし、それはStormwindにあるんだ。\n\nStormwindのDwarven Districtにいる俺の友人、Furen Longbeardと話してくれ。あんたが会う中で最高の盾職人だし、あいつは俺に大きな借りがあるんだ。\n\nほら、このBarleybrew ScalderのcaskをFurenに持っていって、盾を頼んでくれ。いいやつをくれるはずだ。", "やあ! 乾いたご時世だと思わないかい?", "おお、Barleybrew Scalderか。いい酒だ! Yorusに会ってきたんだな?\n\n盾を用意してやれるとも! これより上等なものは見つからんぞ、嘘じゃない!", 0x798b8e48, 0xa9d5c007, 0x121a2fd8, 0x9fc39f0a, 0x9c18ee37, "....." },
  [1703] = { "Mathiel", "MathielにFuren's Notesを渡して下さい。", "メモの写しを作ったぞ。お前さんの鎧を作っている間に身に着けた技を書き留めたものだ。鍛冶屋のMathielに送ってやらないといかんな。Mathielは遙か遠いDarnassusに住んでいるけども、俺が学んだものを身につけるのをとても喜ぶはずだ。", "ごきげんよう、{class}。", "これは興味深い、実に興味深いですね。ドワーフの同僚Furenは、なんとも大きな発見をしたものです!\n\nありがとう、{name}。彼の新しい技術を私自身の作品に応用できるのは光栄なことです。", 0xa9224821, 0x7d69410a, 0x9cfdd510, 0xc0241fbe, 0xe16816d1, "....." },
  [1704] = { "Klockmort Spannerspan", "Klockmort SpannerspanにFuren's Notesを渡して下さい。", "お前さんの鎧を作ってる間に学んだ技術のメモを書き写したんだ。それで、誰かKlockmort Spannerspanに渡してくれる奴が必要だ。あいつはIronforgeにいるノームの鍛冶屋だよ。俺が学んだことをあいつが学んでたら……興奮のあまり自分のひげを引き千切るだろうよ。", "こんにちは、それともおはようかこんばんはかな。こんな地下深くじゃ分からなくてね。で、何か用かい?", "おやまあ! この覚え書きはすごい! おまけに……信じられないし、途方もないし、膝ががくがくしてくるよ!\n\nFurenは大発見をしたんだ! 本物の大発見を! 彼の新しい技術を早く試してみたくてたまらないよ!", 0xe7370e5c, 0x8704fda0, 0x6072da24, 0x40580185, 0xcf60d068, "....." },
  [1705] = { "Burning Blood", "Burning Blood 20本・Burning Rock 1個をStormwindのGrimand Elmoreに渡して下さい。", "認めたくはないが、Furenは本当に何かを見つけたのかもしれん。だが確かめるには、新しい鎧で奴の技術を試してみる必要がある。材料集めを手伝ってくれるなら、{name}、その鎧はお前のものだ。\n\nこの鎧を作るには、burning bloodの見本とburning rockが必要だ。\n\nそれが手に入る場所で俺が知っているのはDuskwoodだけだ。Roland's Doomの鉱山を根城にしているNightbane worgenがburning bloodを持っていて、奴らの頭のGutspillがrockを持っているはずだ。\n\n幸運がお前に速さを授けますように、{name}。", "{name}、burning bloodとrockは持ってきたか? 鎧を完成させるにはそれが必要なんだ。", "素晴らしい! それでは失礼して、自分の仕事に取りかからせてもらうよ……。", 0xf84ba6ef, 0x5a863d44, 0xd546c7a8, 0x78e76958, 0x46cd6b29, "....." },
  [1706] = { "Grimandの防具", nil, nil, nil, "ほとんど信じられないよ! Furenの技術は成功だ。この防具はとんでもない負荷にも耐えるはずだ。\n\nさあどうぞ、{name}。そしてありがとう。自分で試すのに必要な材料を君が集めてくれなければ、Furenの発見を信じることはなかっただろう。", 0x1b21ef14, nil, nil, nil, 0x8a3cf8c0, ".mmm." },
  [1707] = { "水袋の報酬", "GadgetzanのSpigot Operator LuglunketにWastewander Water Pouch 5個を渡して下さい。", "やあ、{name}。俺の名はLuglunket。やる気があるなら、あんたに大事な仕事があるんだ！ やったぜ！\n\n経験豊富な蛇口係の俺としちゃ、あんたが砂漠で見つけたWastewander water pouchesを引き取れるほど嬉しいことはない。どうせあれはうちらの水なんだ。遊牧民どもが盗んだってだけさ！ Gadgetzan Water Companyは、5個持ってきてくれるごとに公式の支援物資を一つ渡すよ。でも何より大事なのは、あんたがGadgetzanの自助を手伝ってるってことさ！", "必要な5個のWastewander water pouchesは手に入れたか? 持ってきたなら、Gadgetzan Water Company Care Package, Model 103-XBは君のものだ!", "素晴らしい……もっと水袋を調達できるということは、災厄をさらに遠ざけるということなんだ! このまま続けてくれ。水袋を5つ持ってくるごとに必ず報酬を渡すよ。", 0x18923060, 0x5e1bdf3d, 0xf821125b, 0xabf40a44, 0x62e25684, "....." },
  [1708] = { "鉄サンゴ", "Searing Coral 20個をIronforgeのKlockmort Spannerspanに渡して下さい。", "Furen Longbeardの新しい技術を、俺自身の鎧で試してみたいんだ。あんたはFurenを助けて、Furenは俺を助けてくれたんだから、鎧ができたらあんたにやるよ！\n\n仕上げるには特別な珊瑚、searing coralが必要なんだ。それが育つのはたった一か所、WetlandsのMenethil Harborの南の海岸沿いだけだ。\n\nsearing coralを十分に持ってきてくれれば、すぐに鎧に取りかかる。急いでくれよ、{name}。始めたくてうずうずして、足の指がよじれそうなんだ！", "やあやあ、{name}! searing coralは持ってきたかい? 早く仕事に取りかかりたくてたまらないよ!", "これだよ! よくやった! さあ、これを溶かして打って、Furenの技術を自分のものと合わせて使ってみよう。そうすればどうなるか分かる!\n\nおやおや! この防具はきっと、とてもとてもとても頑丈になるよ!", 0x95d46a3a, 0x3e28241a, 0x08ca6259, 0xa8ff5a9d, 0x51171b46, "....." },
  [1709] = { "Klockmortの作品", nil, nil, nil, "さあ、君の防具だ、{name}。Furenの工程は見事に成功したよ! 完璧だ! 本当に素晴らしい!\n\nこの防具は攻城兵器で轢いたって、すぐに元の形に戻るだろうね!", 0xe53f77d4, nil, nil, nil, 0xaafc1252, ".mmm." },
  [1710] = { "Sunscorched Shells", "Sunscorched Shell 20個をDarnassusのMathielに渡して下さい。", "私の同僚、Furen Longbeardがある発見をしたので、ぜひ試してみたいのです。私が研究している新しい鎧で試したいと思っています。Furenの技術なら、より優れた結果が得られると信じていますので。\n\n手伝っていただけますか？ 鎧を作るのに必要なものを集めてくだされば、あなたのためにもう一着作りましょう。\n\nThousand NeedlesのHighperchに棲むHighperch Wyvernsのsunscorched egg shellsが必要なのです。巣の下でshellsを探し、十分な量が集まったら私のところへ戻ってきてください。", "shellsは持ってきたか、{name}? あれはとても頑丈で、加工すれば、新しい鎖帷子の輪を覆う塗料にできるんだ。", "ああ、ありがとう。これなら申し分なく使えるよ!\n\nすぐに防具の制作に取りかかろう……", 0xd80ce525, 0x5c836a66, 0x41c7b49e, 0x76aded81, 0x8386f94f, "....." },
  [1711] = { "Mathielの鎧", nil, nil, nil, "あなたの防具が仕上がりました。実に満足のいく出来です。Furenの新しい技術は私自身のものと完璧に噛み合いました。この防具はきっと相当な頑強さを見せてくれるでしょう。\n\nありがとう、{name}。これが今後の戦いであなたの役に立ちますように。", 0xf31b6b88, nil, nil, nil, 0x39be4aab, ".mmm." },
  [1712] = { "Cyclonian", "Bath'rah's Parchmentに書かれている品物をAlteracのBath'rah the Windwatcherに渡して下さい。", "我は長きにわたりこの地を見張ってきた。いつの日か偉大なるCyclonianが倒れるのを見届けるため、見張っておるのだ。だが、あの風の王を倒す勇者は、いまだ見つかっておらぬ。\n\nおそらく、そなたこそがその勇者であろう。\n\nそれを我に証明してみせよ。Cyclonianを呼び出すのに必要な品を集めれば、そなたが偉大なるウォリアーであると認めよう。そうすれば、そなたは奴を倒し、奴のwhirlwind heartを手に入れられるかもしれぬ。\n\nもしそうなれば、我はそのheartの力を武器に注ぎ込み、その武器をそなたに授けよう。\n\nこれが、我の必要とする品を記したparchmentだ。", "品々は持ってきたか、{name}? それらを集めることこそ、そなたにCyclonianと対峙する力がある証となるのだ。", "我が呪文のための品を集め、その力と知略を示してみせたな。だが、我らのクエストの次の段階はさらに危険だ。\n\nお前の力が揺らがぬことを願うとしよう。", 0x3f98ea1b, 0x1225d934, 0xb7e52410, 0xf41610df, 0x5f294daf, "....." },
  [1713] = { "召喚", "Bath'rah WindwatcherにWhirlwind Heartを渡して下さい。", "Cyclonianを呼び出す儀式を行う準備ができた。奴が呼び出されたら、そなたは奴を倒し、そのwhirlwind heartを奪わねばならぬ。我はそれを用いて、武器にCyclonianの力を宿すのだ。\n\n{name}よ、風の王と対峙する覚悟はできておるか？", "{name}、whirlwind heartがどうしても必要なのだ!", "やったな! Cyclonianを倒してWhirlwind Heartを手に入れたんだ!", 0x7256d21c, 0x03db61b0, 0x1c7ae6a8, 0xaae28055, 0xba56a949, "....." },
  [1715] = { "Slaughtered Lamb", "StormwindのMage QuarterにいるGakin the Darkbinderのところへ出向いて下さい。", "ふん。昔は、Khaz Modanのウォーロックはみな、Gnomereganの師たちの庇護のもとで訓練を受けたものだ。だが、今や我々はみなIronforgeのこのネズミの穴に移住させられ、Magniは我々を注意深く見張ると決めた。おかげで、見習いをStormwindへ訓練に送らなきゃならなくなった。\n\n幸い、Gakinはなかなかの腕利きだから、必要なことはちゃんと学べる。だが、腹が立ってしょうがない！\n\nとにかく、GakinはStormwindのSlaughtered Lambの地下にいる。", nil, "Blackwrenchが君を送り出したんだね? Ironforgeのウォーロックは物事をてきぱき処理しなきゃならんな。Stormwindにあるのは限られた空間と限られた数の師匠だけだ。人通りが増えたことから考えると、遅かれ早かれ気が付かれるに違いない。", 0x0d4e536f, 0xd830dab8, 0x5dec5e50, nil, 0x6dd03c2b, "...m." },
  [1716] = { "魂をむさぼる者", "BarrensのTakar the Seerと話して下さい。", "sayaadとは魂を貪る者であり、意志を支配する者であり、心を誘惑する者。邪悪以外を知らぬのだ。\n\n淫らな物語では、この悪魔は通称で呼ばれている。女ならsuccubus、男ならincubusだ。\n\nこの生き物を呼び寄せるには刺激が要る。愛の象徴を餌にすれば、必ずやお前の呼びかけに応えるだろう。そいつを打ち負かし、お前の道具とするのだ。\n\nだが、そのような性質の物を見つけるのは難しいだろう。Takar the Seerと話すがよい。KalimdorのBarrens、Camp Taurajoの近くにいるはずだ。", nil, "{name}、航海は大変だったろう? 私と話すためにはるばるやって来てくれたのだな。だが心配はいらない。何故Gakinが君を寄越したのかは分かっているし、ここへ寄越したのは賢明な判断だったよ。私なら君の求めるものを手伝えるからな。", 0xc90e9da6, 0x5802ee48, 0xc237a24d, nil, 0xcb33ee38, "...m." },
  [1717] = { "Gakinの召喚", "StormwindのMage QuarterにいるGakin the Darkbinderの元へ出向いて下さい。", "{name}！ こんなところで会うとは思わなかったが、君を見かけたら気をつけておくよう言われていたんだ。\n\nもっと訓練を受けてもいい頃をとうに過ぎている。今度Stormwindに行ったら、Gakinのところに顔を出すといい。君を待っているはずだ。", nil, "誰かがお前と連絡を取れてよかった、{name}。最悪の事態を恐れ始めていたところだ。これだけ時間を注ぎ込んだ後でお前を失うのは惜しいからな。\n\nだが話は後でいい。今はお前の訓練だけが重要だ。", 0xafbad200, 0xd830dab8, 0x596c7292, nil, 0x2d466a24, "...m." },
  [1718] = { "島の者", "Klannoc Macleodと話して下さい。", "ウォリアーとしてのそなたの名声は高まっている、{name}。今こそ同輩たちと競い合い、己の立ち位置を知る時だ。\n\nBarrensの沖、Ratchetの南に島がある。Fray Islandと呼ばれ、ウォリアーたちが集う場所だ。\n\n集い、そして戦う。\n\nFray Islandの筆頭ウォリアー、Klannoc Macleodと話せ。そなたがふさわしいと認めれば、Klannocがウォリアーの道のさらに先へとそなたを導いてくれよう。\n\nFray Islandへ行くには、Merchant Coast沿いの砂州の浅瀬を探すがよい。", nil, "やあ、ウォリアー。Fray Islandへ来ることのできた奴と会えて嬉しい。君の気に入るものが見つかるといいね……", 0xc6cccc89, 0x59e047a6, 0xb37036cb, nil, 0x08e60fb9, "...m." },
  [1719] = { "乱闘", "Big Willを殺し、Fray IslandのKlannoc Macleodに話しかけて下さい。", "俺から学びたいなら、まずThe Affrayを突破しなきゃならない。Fray Islandの俺たちが、自分はタフだと思っている新進のウォリアーに挑ませる試練だ。この試験に合格できれば、お前がタフだと認めてやる。\n\n始めるには、あそこの人だかりの真ん中へ歩いていって、格子を踏め。それでTwiggy Flatheadにお前の準備ができたと伝わり、奴が挑戦者どもを差し向ける。\n\n挑戦者を全員倒せば、奴がBig Willを呼び出す。Big Willを倒し、決められた時間内に俺のところへ戻ってこい。", "試練は終えたか?", "よくやった、{name}。The Affrayを乗り越えたな!\n\nお前は立派なウォリアーだ。教えを授けられるのは光栄なことだ……", 0x71a4d209, 0x1003a249, 0x7ffe012e, 0x518944b1, 0xbf82ca14, "....." },
  [1738] = { "Heartswood", "AshenvaleでHeartswoodを入手し、StormwindのMage QuarterにいるGakin the Darkbinderに渡して下さい。", "お前が来るのに備えて、私は遠見の力で世界を見渡し、時の霧の向こうを覗いた。お前の探し求めるものを見つけたぞ。\n\nWar of the Ancientsで、二人の恋人が共に戦いに倒れた。二人が最期の息を引き取ったその場所に、heartswoodとして知られる木が育った。二人の不滅の愛の象徴だ。\n\nそれならばsuccubusを誘うには十分だろう。Ashenvaleの森の北西部、Ordil'Aranの廃墟で見つかるはずだ。", "探し物は見つかったか、{name}?", "うむ、これなら申し分ないと分かる。少しばかり手を加えさせてくれ……\n\nTakarは頼りになる男だろう? 文明のあるところへ戻るよう説得できればいいのだがな。", 0x3723b35c, 0x83326afc, 0x89350d42, 0xe8536f8f, 0x78395298, "....." },
  [1739] = { "拘束", "Heartswood Coreを使って召喚したsuccubusを倒し、Slaughtered LambにいるGakin the DarkbinderにHeartswood Coreを返して下さい。", "heartswood coreを使えば、下の地下墓所にある召喚の円陣で呪文を唱え、succubusが通り抜ける門を開くことができる。\n\n気をつけろ、{name}。succubiは、どれほど強い精神の持ち主でさえ支配してきたのだ。\n\n奴を打ち負かして虚空へ送り返したら、私のところへ戻ってこい。奴を呼び出し、従える方法を教えてやろう。", "Surenaは変装したsuccubusで、私の心を歪めねじ曲げるために送り込まれたのではないかと思うことがある……ハッ! 買いかぶりすぎだな。", "よくやった、実によくやった、{name}。お前を鍛えると決めたのは正しかったようだ。その働きは確かに期待を裏切らん。\n\n新たに縛り付けたsuccubusを操る術を示すのに、ためらいはない。よく見ておけ。", 0x5926988f, 0xc70dfe93, 0x0b92f947, 0x111f48b5, 0xc7d74427, "....." },
  [1740] = { "Orb of Soran'ruk", "Soran'ruk Fragment 3つとLarge Soran'ruk Fragment 1つを見つけ、BarrensのDoan Karhanに渡して下さい。", "Legionの悪魔が寵を失うと、その魂は宝珠の中に封じられ、彼らのメイジやウォーロックに分け与えられる。\n\nその多くは、Azerothにいる彼らの僕たちが持ち運んだ。砕けていてもなお、それらは中に囚われた悪魔の力を宿している。\n\nSoran'rukの宝珠は2つに割られた。一つはさらに砕かれ、Blackfathom DeepsにいるTwilight's Hammerの侍祭たちに使われている。もう一つ、大きい方の破片は、Shadowfang Keepにいる魔術師が持っていた。それらを見つけてくれば、私が元の形に戻してやろう。", "Zargainのオーブの欠片を集めるには長い年月がかかったが、あれは私によく尽くしてくれた。Soran'rukのオーブもきっと君によく尽くしてくれるだろう。", "そうだ……オーブはさほど細かく砕けてはおらず、欠片もほぼ全て揃っている。これらを作り直し、Soran'rukを再び完全なものにするのは造作もない。\n\n私はBurning Legionのオーブとその再生の研究に生涯を捧げてきた。研究用にこの欠片を集めてくれたのは有り難い。完全に組み直したうえで、お前の望む形にして返してやろう。", 0x331f56fd, 0xad372c46, 0x452768a2, 0x04ccd818, 0xafeadf79, "....." },
  [1758] = { "Tome of the Cabal", "IronforgeのKrom Stoutarmと話して下さい。", "お前が挑むfelhunterを呼び出すには、単純な召喚の円陣だけでは足りない。\n\n私と3人の侍祭が、魔法陣を作る手助けをしよう。お前にはTome of the Cabalの写本が必要だ。あれはしばらく前から我々の手を離れて失われている。何の助けも借りずにfelhunterを召喚した最初のウォーロックの一団が書いたものだ。\n\nKrom Stoutarmならこの件で力になれるかもしれん。近頃は流れ者のウォーロックで、古い書物を溜め込み、Ironforgeの図書館をこそこそうろついて日々を過ごしている。", nil, "Tome of the Cabal? ふむ……聞き覚えがある。だが、ここで見たことは一度もない——信じてくれ、読んだ本は全て覚えているのだ。\n\nふむ……\n\nああ、そうだ! 図書目録の本の中で、それへの言及を見たことがある。", 0x03d040dc, 0x6185a67d, 0x0a3411a2, nil, 0xeb681de0, "...m." },
  [1778] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "これから国へ帰る計画を手配しますよ。Stephanieの奴、Stormwindでうまくやってるといいんですけどね。妻にまた会うのが待ちきれないですよ。それではまた次にお会いする時まで。{class}さん。", nil, "ずいぶん早く戻ってきたな。それで、ここを離れている間に何を成し遂げたのか聞かせてもらおうか。\n\n気高い大義のために働けたか? 慈悲の価値を、あるいはAzerothの民に対する自らの務めをいくらか学んだかもしれんな。話してくれ、誰をどのように助けたのか……。見事だ、{name}。それはまさしく光に従う者の行いだ。\n\nそうした犠牲はいずれ必ず報われる。", 0xe91f21c0, 0x04be03fc, 0x7d700dcc, nil, 0x26c0f0e8, "...m." },
  [1779] = { "Tome of Divinity", "IronforgeにいるMuiredon BattleforgeのところへSymbol of Lifeを持って行って下さい。", "これを受け取ってほしいのです、{name}。Symbol of Lifeと呼ばれるものです。\n\nあなたは慈悲深く忍耐強いことを証明しました。今度は、戦いと力の両面で、あなたがどれほど熟達したかを証明してほしいのです。\n\n夫のMuiredonが、Dark Ironのドワーフたちと出くわして最近戻ってきたのですが、命からがら逃げてきたのです。今、あちらで私たちのプリーストの一人に傷を癒してもらっています。\n\nSymbolを持って、彼と話してください。彼を助けられたら、近いうちにまた話しましょう。光があなたを照らしますように。", nil, "*ゴホッ*\n\nこんにちは、{class}。わしの傷は気にせんでくれ、そこの腕のいいプリーストがそのうち老いぼれMuiredonの面倒を見てくれる。あんたの持っているそのSymbol of Lifeの力は、まだ要らんよ。\n\nそれで、女房があんたをわしのところへ話しに寄越したんだな? いいだろう。時間を取って話してやる——Muiredonと、その親友でありあんたと同じパラディンだったNarmに何が起きたのか、そっくり話してやろう。", 0xe91f21c0, 0x2d923b1f, 0xa605745e, nil, 0x1dd454cc, "...m." },
  [1780] = { "Tome of Divinity", "StormwindにいるDuthorian Rallに話しかけて下さい。", "今日にでもこれを子供たちのところへ届けましょう。どうか気をつけて、善き{class}よ。あなたのような人柄の方々が街に顔を見せることはそう多くありません。けれども、ここStormwindのパラディンたちは、困っている者に決して背を向けないと、あなたが証明してくれました。\n\nさようなら。", nil, "ずいぶん早く戻ってきたな、{name}。それで、Cathedralを離れている間に何を成し遂げた?\n\n気高い大義のために働いたか? 慈悲の価値を、あるいはAzerothの民に対する自らの務めをいくらか学んだかもしれんな。話してくれ、誰をどのように助けたのか……。うむ、感心したぞ、{name}。それはまさしく光に従い、他者を自らより重んじる者の行いだ。\n\nそうした犠牲はいずれ必ず報われる。", 0xe91f21c0, 0x0f3ca705, 0xa762da4f, nil, 0xe78d8da6, "...m.", nil, nil, 0xc898f87d, nil, nil },
  [1781] = { "Tome of Divinity", "StormwindにいるGazin TenormのところへSymbol of Lifeを持って行って下さい。", "これを受け取ってください、{name}。Symbol of Lifeと呼ばれるものです。\n\nあなたは慈悲深く忍耐強いことを証明しました。今こそ、光の最も偉大な賜物の一つを集中させるだけの力があなたにあるか、確かめる時です。\n\n私の友Gazinが、ElwynnのHeroes' Vigilの近くでDefiasと出くわして最近戻ってきたのですが、命からがら逃げてきたのです。今は祭壇のそばで、私たちのプリーストたちに傷を癒してもらっています。\n\nSymbolを持って、彼と話してください。彼を助けられたら、近いうちにまた話しましょう。あなたが光の栄光に浴しますように。", nil, "*ゴホッ*\n\n会えて嬉しいよ、{class}。私の傷は気にしないでくれ、今回はここの腕のいいプリーストが老いぼれGazinの面倒を見てくれる。君が持っているそのSymbol of Lifeの力は必要ない……今のところはな。\n\nそれで、Duthorianが私と話すよう君を寄越したんだな? いいだろう。私と友のHenzeに何が起きたのか、そっくり話そう。運と君の腕次第では、まだ我々全員を救えるかもしれん。", 0xe91f21c0, 0xdb6e8f90, 0x25218c29, nil, 0x4ea87484, "...m." },
  [1782] = { "Furenの鎧", nil, nil, nil, "ほら、君の鎧だ、{name}。どんなに強烈な攻撃にも耐えるぞ。でなけりゃ俺はFuren Longbeardの名を返上するさ！\n\nそれに、礼を言わなきゃな。君が持ってきてくれた材料を\n\n扱っているうちに、たくさんのことを学んだよ。いつかまた大発見ができそうだ！\n\n学んだことを、Allianceの他の\n\n鍛冶屋たちにも送るつもりだ。\n\n君が大いに助けになってくれたと伝えておくよ。向こうも恩返ししたいと思うかもしれんな。", 0xe60f030a, nil, nil, nil, 0x2efb420d, ".mmm." },
  [1783] = { "Tome of Divinity", "Symbol of Lifeを使ってDun MoroghにいるNarm Faulkを蘇生して下さい。", "わしらはHelm's Bed Lakeの南に立てこもっとるDark Ironのドワーフどもを偵察しとったんじゃ。ろくでもねえことを企んどるのは分かっとったから、Narmとわしでもっと近くで見てみようと思ってな。奴らの頭が手下どもに命令を出しとるのが見えたんじゃ。\n\nNarmとわしはその隙に何人か仕留めたんじゃが、奴らは思ったより手強くて、もっと大勢に不意を突かれちまった。Narmがわしに、走って援軍を呼んでこいと言うもんで、こうしてここにおるんじゃ。\n\nNarmには助けが要る。あいつが助けを得るまで、わしは休まんぞ。\n\n手を貸してくれんか、{name}？", nil, "感謝してもしきれない、同胞よ。\n\nSymbol of Lifeを携えているということは、TizaとMuiredonが私を助けるためにあなたを寄越したのだろう。\n\nそのとおり、私はscriptの一つを手に入れようとしてDark Ironに倒された。Muiredonを逃がすだけの間は持ちこたえたが、あなたが来たときには光にほとんど完全に抱かれかけていた。あなたがSymbolを使えるほどの力を持っていたという事実は、あなたにとって大きな意味を持つ。だが、その話をするのは後でいい。", 0xe91f21c0, 0x0f3fb381, 0x604e878c, nil, 0xb325f61b, "...m.", nil, nil, nil, nil, 0xccfa623a },
  [1784] = { "Tome of Divinity", "Helm's Bed湖付近にいるDark Iron族ドワーフからDark Iron Scriptを手に入れ、IronforgeにいるMuiredon Battleforgeのところへ持ち帰って下さい。", "私が戦いに倒れる前、Muiredonと私は、あの小さな家の近くでDark Ironの密偵の一人をもう少しで倒すところでした。彼らの隊長が彼らに命令書を渡しているのを目撃して、隊長を倒してその命令書を奪おうとしたのです。\n\nIronforgeの評議会の中には、Dun MoroghにDark Ironのドワーフがいることをまだ信じていない者もいます。あのscriptを一つ手に入れれば、彼らの動きの証拠になるだけでなく、彼らが何を企んでいるのかも分かるかもしれません。\n\nscriptを一つ手に入れて、Muiredonのところへ持っていってください、{name}。", "戻ったか! 会えて嬉しいぞ、{name}。傷も治ったし、女房に大丈夫だと納得させられ次第、Helm's Bed lakeに戻る準備はほぼできとる。", "ハハ! やってくれたな! Narmを救い、女房が評議会へ持っていくのに必要な証拠も見つけてくれた。あんたはまさしく光の恵みだ……もちろん女房は別としてな。\n\n重ねて礼を言うぞ、{name}。", 0xe91f21c0, 0x552cfc26, 0x107e3082, 0x1db426a0, 0x9d225682, "....." },
  [1785] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "あっちで、うちのかみさんがもう誇らしげに顔を輝かせとるのが見えるわい。さっさとあっちへ尻を向けて行ったほうがええぞ。お前さんに何か話があるんじゃろうて。\n\n光がお前さんと共にあらんことを、強き{class}よ。その時が来たら、ScourgeやあのDark Ironsとの戦場で、お前さんを探すとしよう。", nil, "今日あなたはIronforge全体に大きな貢献をしてくれたわ、{name}。あなたを仲間に数えられることを誇りに思う。もし準備ができていると感じるなら、この巻物で祝福を授けたいの。Symbol of Lifeは、光の最も偉大な祝福の一つ——死者を生き返らせる力——を受ける準備が整ったパラディンが使ったときにしか働かなかったはずよ。\n\n仲間を蘇生させる力を教えましょう。賢く使ってね、{name}。そして私自身と夫、そしてIronforgeを代表して、ありがとう。", 0xe91f21c0, 0x04be03fc, 0xa2b7f13a, nil, 0xf9eb3df3, "...m." },
  [1786] = { "Tome of Divinity", "Symbol of Lifeを使ってElwynnにいるHenze Faulkを蘇生して下さい。", "HenzeとわたしはHeroes' Vigilまでたどり着きました。Elwynn北東部のStone Cairn Lakeの真ん中にある島です。Defiasがわたしたちの領内に潜入したと聞いて、王の顧問たちに届ける証拠を手に入れたかったのです。\n\nあの悪党どもの何人かが書類を調べているのを見つけて、わたしたちは襲いかかりました。けれども残念ながら、さらに多くのメイジたちにたちまち圧倒されてしまいました。\n\nわたしが逃げる間、Henzeが奴らを食い止めてくれたのです……あの愚か者、勇敢なまねをして。\n\n彼は今もあそこにいるんです、Henzeは。わたしたちを助けてもらえませんか、{name}？", nil, "ありがとう、同胞よ。\n\nSymbol of Lifeを手にしているところを見ると、DuthorianかGazinがあなたを寄越したと考えていいのだろうか?\n\n私はGazinと共に奴らの計画を奪おうとして、Defiasの呪文使いに倒された。Gazinを逃がすだけの間は持ちこたえたが、最後には奴らの魔法に圧倒されてしまった。\n\nだが、あなたは私を連れ戻してくれた。Symbolを使う力は誰にでも備わるものではない、{name}。自らの信仰でそれに力を与えられたことは、あなたにとって良い兆しだ。", 0xe91f21c0, 0x4eb84a7e, 0xddf00bb3, nil, 0xd0b687e0, "...m.", nil, nil, nil, nil, 0xe3b33add },
  [1787] = { "Tome of Divinity", "ElwynnのDefias Rogue WizardsからDefias Scriptを取り戻し、StormwindのGazin Tenormのところへ戻って下さい。", "Symbolについては、後でまた話す時間があるでしょう。今大事なのは、Defiasが調べていたあの書類を手に入れることです。あれを手に入れられれば、DefiasがElwynnに潜入したことを証明でき、うまくいけば彼らの計画についても何か分かるでしょう。\n\n私は今、戦える状態ではありません、{name}。この島にいるDefiasからあの書類を奪えるだけの力が、あなたにあると思いますか？\n\n手に入れられたら、Gazinのところへ持っていって、私は大丈夫だと伝えてください。", "Henzeは無事ですか、{name}? うまくいきましたか?\n\nあなたの武器の腕と光の力があれば、Heroes' VigilはDefiasのどんな脅威からも安全だと思いますが、それを判断するのは王とその顧問たちです。", "素晴らしい! やって下さいましたね。Henzeも救って下さった。確かに「光」はあなたと共にありますぞ、{name}!", 0xe91f21c0, 0x09e322c6, 0xb07e8693, 0x78c1898e, 0x3eda4356, "....." },
  [1788] = { "Tome of Divinity", "StormwindにいるDuthorian Rallに話しかけて下さい。", "Duthorianが目を通したら、このscriptは王の顧問たちのところへ持っていきます。でもその間に、あなたは今すぐDuthorianと話しに行くべきです。きっとあなたの肩を叩いてねぎらいたがっていますよ！\n\n改めてありがとう、{name}。また会えることを願っています。あなたは間違いなく、友と呼ぶのを誇りに思える味方です。", nil, "今日はよくやった、{name}。成し遂げたことに誇りを持つといい。\n\nそれ以上に、自分の力を誇りに思うべきだ。Symbol of Lifeの力は誰もが使えるわけではない。光に呼びかけて死者を蘇らせるということは、パラディンにとって最大の栄誉の1つ、蘇生の力を授かる準備ができているということだ。\n\nHenzeにしたように、倒れた仲間を蘇らせる力が君のものとなる。\n\n達者でな、{name}。光は君を照らしている。心から受け入れるといい。", 0xe91f21c0, 0x0f3ca705, 0xd2692364, nil, 0xaecaeccf, "...m." },
  [1789] = { "Symbol of Life", nil, nil, nil, "急いでください、{name}。あなたが失敗すれば、一つだけではない命が危うくなるのです。\n\nもし何らかの理由でMuiredonとNarmを助けられなかったなら、私のところへ戻ってきてください。旅のために、もう一つSymbol of Lifeを差し上げましょう。\n\n私の援助をただの施しと勘違いしないでください。あなたも他の{class}と同じように、自らがふさわしいことを証明しなければなりません。失敗を重ねれば、いずれあなた自身に跳ね返ってくるかもしれません。", 0x69ed2c55, nil, nil, nil, 0xf2e6ba1d, ".mmm." },
  [1790] = { "Symbol of Life", nil, nil, nil, "急いでくれ、{name}。君が失敗すると、何人もの命が生きるか死ぬかの危機にさらされる。\n\n何かの事情でGazinとHenzeを助けるのに失敗したら、私のところへ戻ってきてくれ。また新しいSymbol of Lifeを渡そう。\n\n私の支援を単なる慈善行為と勘違いしないでほしい。君は他の{class}たちのように自分が相応しいと示さねばならないのだ。それから、失敗し続けると、後になってそれが跳ね返ってくることがあるのだぞ。", 0x69ed2c55, nil, nil, nil, 0x3f42f7b3, ".mmm." },
  [1791] = { "風見る者", "Bath'rah the Windwatcherと話して下さい。", "狂戦士の構えを覚えたからには、それと一緒に使える良い武器が欲しいだろう。\n\nBath'rah the Windwatcherと話してこい。Alterac MountainsとWestern Plaguelandsの間に住む、トロールの隠者だ。腕のいい武器職人で、強力なシャーマンでもある。\n\nBath'rahを見つけるには、Tarren Millの東側を流れる川へ行け。それを北へたどるんだ。Bath'rahは川の東岸に残る廃墟の近くで野営している。", nil, "遠くから旅してきたな、若きウォリアーよ。その目には炎が見える。強大な力を持つ武器を求めているのだろう?\n\nお前のクエストには力を貸せる。そして、お前も私のクエストに力を貸せるはずだ。", 0xb6038666, 0x3cac39b3, 0xea9f0083, nil, 0xbb0930b4, "...m." },
  [1792] = { "嵐の武器", nil, nil, nil, "旋風の心臓は手に入れた。お前が選んだ器にそれを収める用意はできている。\n\n武器を選べ、{name}。その力はCyclonianの力なのだと知るがいい。", 0x2c74e831, nil, nil, nil, 0x0ae24e1b, ".mmm." },
  [1793] = { "Tome of Valor", nil, nil, nil, "光があなたと共にあることは証明されました、{name}。しかし時代が危険さを増すにつれ、肉体の下にどれほどの強さが宿っているかを知ることが重要になります。悪魔やドラゴン、あるいはその他の邪悪があなたの地に足を踏み入れたとき、あなたの気概は試されるでしょう。それに耐えるだけの強さがありますか?\n\n状況がどうであれ、勇気は光や防具や武器と同じくらいパラディンとしての在り方の一部です。弱き者を守ること、そして信仰を失わないこと。これがCathedral of Lightで学ぶ間に修めるべき、さらに2つの教えです。", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1794] = { "Tome of Valor", nil, nil, nil, "光が君と共にあることは証明された、{name}。だが時代が危険さを増すにつれ、肉体の下にどんな強さが秘められているかを知ることが重要になる。悪魔や竜、その他いかなる悪が君の地に足を踏み入れたとき、君の気概が試されるだろう。君は十分に強くあれるだろうか？\n\nどんな状況でも揺るがぬ勇気は、光や鎧や武器と同じくらい、パラディンたる者の一部だ。弱き者を守ること、そして信仰を失わないこと。この2つも、Cathedral of Lightで学ぶ間に君が身につけねばならない教えだ。", 0xdaebf666, nil, nil, nil, 0x66a0b620, ".mmm." },
  [1795] = { "拘束", "Tome of the Cabalを使い、felhunterを召喚して征服し、RatchetのStrahad FarsanにTome of the Cabalを返して下さい。", "十分に準備ができているなら、始めよう。手順を説明してやる。\n\nまず私が基本の召喚の円陣を作る。それが終わったら、私の侍祭たちが集中の杖を使って大きな円陣を作る。\n\nそれが済んだら、Tome of the Cabalから呪文を読み上げろ。そうすればfelhunterが引きずり出される。気をつけろ、{name}。felhunterは強敵だ。お前の首が肩の上に乗ったままでいてほしいものだな。", "ウォーロックたる者、felhunterを従えているべきだ。手なずけるのは難しいが、それが主人にもたらす力は、その代償をはるかに上回る。", "感動したと言わざるを得ないよ、{name}。私がfelhunterと対峙した時は、命からがら逃げ出したんだ。君には当代一のウォーロックになれる可能性があるよ。", 0x5926988f, 0x90eb7a27, 0x5d293135, 0x6582b8e7, 0x2ff39446, "....." },
  [1796] = { "Enchanted Gold Bloodrobeの材料", "BarrensのMenara VoidrenderにRobes of the Arcanaを渡して下さい。", "私が作るのを手伝う最初の品はローブです。あなたが私のために品を集め、私たちでそれを組み合わせます。その後、うまくいけば、あなたは自らを強くし、戦いの助けとなる数多くの品の最初の一つを手にすることになるでしょう。\n\nまず、作製されたRobes of Arcanaが必要です。仕立て屋に作ってもらうこともできますし、誰かから買うこともできるでしょう。あなた自身が作れたなら大いに感心しますが、いずれにせよ、そのローブを持ってきてください。そこから始めましょう。", "ローブ探しの具合はどうだ、{name}? 自分で作ったのか? そうした自らの手による工夫があると、魔力を込めるのが一層味わい深くなるものだ。より大きな達成感が得られる。だが、手っ取り早い道を選んで他人に作らせるのも分かる――そういう……野心にも一理あるからな。", "これで申し分ありません、{name}。\n\n魔法の品はすべて、質の高い品から始めなければなりません。品に注がれた労力と技量が大きいほど、宿せる魔力も大きくなります。希少で高価な材料ほど、魔力をよく保ちます。このローブを、後ほど私たちが作るものへ仕立て直したことを後悔はさせません。", 0x7fee9266, 0x691cf117, 0x8dcf592c, 0x9a22f6e6, 0x7badf4fc, "....." },
  [1798] = { "Strahadを捜して", "BarrensのStrahad Farsanと話して下さい。", "felhunterの召喚を学ぶ時が来たぞ、{name}。ここには君に教えるのに必要な試薬や品物がないので、別の者を訪ねてもらわねばならん。我々の側近の一人、Strahad Farsanだ。\n\n彼はゴブリンの港町Ratchetに住んでいる。君が向かうことは、先に知らせを送って伝えておこう。", nil, "{name}? ああ、なるほど。我らが最新の神童か。実物は伝説には及ばないものだな、残念ながら。\n\nまあいい。お前がここへ来たのは学ぶためで、私の独り言の冗談を聞くためではあるまい。", 0x884bfbbe, 0xe2b6e98e, 0xd43a3b1f, nil, 0x5156dbd9, "...m." },
  [1799] = { "Orb of Orahilの破片", "Ratchetの上にある塔の中でMenaraの侍祭たちと話し、彼らの道のうち一つを選ぶ。\n\nその後、Infernal OrbをDustwallow MarshのTabethaのところへ持って行って下さい。", "よし、では始めよう。\n\nまず、中にいる私の侍祭たちと話さねばならん。その中から従う道を一つ選べ。詳しくは彼らが説明する。\n\n次に、Desolaceへ行き、Mannoroc Covenのウォーロックの一人からInfernal Orbを手に入れねばならん。そのorbを、Dustwallow Marshの南の奥にいるTabethaというメイジの助けを借りて浄化するのだ。私と彼女との因縁があるから、彼女は力を貸してくれるだろう。\n\nもう一度言う。私が頼んだ両方のことを果たすまで、戻ってくるな。", "それに、どう見てもメイジではないお前を、そもそも信用できるものかどうか。お前からは秘術の力の匂いがするが、お前の同類に進んでつきまとう堕落の悪臭からは逃れているようだ。\n\nそうか、{class}か……{class}が私の助けを求めに来たというわけだ。\n\nさて、私に何をしてほしいのだ、{name}?", "あら、Menaraが寄越してきたのね。いいでしょう……当分の間、お客として滞在してもいいわ。でも、急ぎの仕事のようね……失われた力を探してここへ来たのでしょう? 私の勘違いかもしれないけれど、堕落はまったく遠ざかってはいないと思うわ。", 0x2e1f0446, 0x3a7840aa, 0x122ee87b, 0x4ac12eff, 0x5dae030e, "....." },
  [1800] = { "Lordaeronの玉座の間", "孤児をかつてのLordaeronの玉座の間へ連れて行って下さい。玉座の間はUndercityへ降りていくすぐ手前にあります。", "ぼくたちがいい子にして手伝いをすると、ぼくの家の孤児院の寮母さんたちが、夜に戦いや伝承のすごいお話をしてくれるんだ。その中に、Lordaeronがどうやって滅びたか、悪いArthasが王になるために自分のお父さんの命を奪ったっていうお話があったんだ。\n\nあいつには名誉なんてなかったんだよ、{name}！ ぼくは大きくなって強いHordeのウォリアーになったら、ぼくの剣は名誉に導かれるんだ。悪になんて絶対にならない！\n\n玉座の間を見に連れていってくれない？ お願い。Undercityに下りていくところのすぐ手前にあるんだ。", "まだ着かないの?", "あの玉座の間は怖かったよ、{name}! 誰もいなかったのに、そこですごく悪いことが起きたって感じがした。腹が立ったけど……悲しくもなったんだ。保母さんたちがどうしてあんな話をするのか分かったよ。ぼくは絶対にあんなふうに同胞を裏切ったりしない!\n\n玉座の間に連れて行ってくれてありがとう、{name}。たくさん学べたよ。", 0xbe01571a, 0x847c5209, 0x27f3662b, 0x63e6b64c, 0xfd690453, "....." },
  [1801] = { "Tome of the Cabal", "UndercityのJorah Annisonと話して下さい。", "お前が挑むfelhunterを呼び出すには、単純な召喚の円陣だけでは足りない。\n\n私と3人の侍祭が、魔法陣を作る手助けをしよう。お前にはTome of the Cabalの写本が必要だ。あれはしばらく前から我々の手を離れて失われている。何の助けも借りずにfelhunterを召喚した最初のウォーロックの一団が書いたものだ。\n\nJorah Annisonならこの件で力になれるかもしれん。近頃はUndercityで地図製作者として雇われているが、古い書物については私の知る誰よりも詳しい。", nil, "地図作り! 絵だの、現実の当て推量だの。そんなものに用はない。\n\n本の中にこそ、物語と描写にこそ! 真実はそこにある。この店の地図をすべて差し出してでも、死霊術の台頭について書かれた本を1冊、あるいはDark Ladyの勝利の物語を手に入れたいものだ。", 0x03d040dc, 0x9994065e, 0x3090f470, nil, 0x8e93fa06, "...m." },
  [1802] = { "Tome of the Cabal", "Moldy TomeとTattered Manuscriptを手に入れ、IronforgeのKrom Stoutarmに渡して下さい。", "失われてしまったが、どこで見つかるかについては見当がついている。\n\n写本は一冊しか作られなかったんだが、ある時に荒らされて、大部分が綴じ目から破り取られてしまった。噂では、それがどういうわけかThousand Needlesのcentaurの手に渡ったらしい。\n\n残りは、Southshoreの西の沖で失われた。船でMenethil Harborへ運ばれる予定だったんだが、結局届かなかったんだ。\n\nこの知識と引き換えに、一つだけ頼みがある。見つけたら、私に見せに持ってきてくれ。", "噂は本当だったか、{name}?", "素晴らしい! これでその中身を覗いた数少ない者の列に加われる。\n\nこの書物をさらに読み込むのが待ちきれん。今日は素晴らしい日だ、{name}! 発つ前に一目見せてくれさえすればいい。Strahadならきっと写しを送ってくれるだろう。", 0x03d040dc, 0x10b05201, 0x03736d31, 0xe389e673, 0x24a83959, "....." },
  [1803] = { "Tome of the Cabal", "Moldy TomeとTattered Manuscriptを取り戻し、UndercityのJorah Annisonに渡して下さい。", "ああ！ あなたは私と似た趣味をお持ちのウォーロックのようですね。確かに、Tome of the Cabalを手に入れるのは立派な志です。かつてそれがLordaeronの城壁の中に保管されていたのをご存じでしたか？ けれども荒らされて、ページのほぼ半分が取り去られてしまったのです。誰がそんな極悪な行為をするというのでしょう？\n\nその半分は失われましたが、噂ではThousand Needlesのcentaurの手に落ちたそうです。\n\n残りの文書はIronforgeへ移される予定でしたが、Southshoreの西の沿岸で輸送中に失われてしまいました。", "君はおとぎ話を追いかけているのかもしれない、{name}。だが、どれほど突飛な噂でも、その中心には真実が見つかるものだ。", "おやおやおや! これは何かな?\n\n見事だ、{name}。可能だとは思っていなかったが、こうしてこの手の中にある。完全なTome of the Cabalが。\n\nまた発つ前に、少しだけページをめくらせてくれ。", 0x03d040dc, 0x7c0192c1, 0x75503650, 0x7b7b1d9c, 0x47a791b4, "....." },
  [1804] = { "Tome of the Cabal", "Reconstructed TomeとRod of Channeling 3本をRatchetのStrahad Farsanに渡して下さい。", "いやあ、その、手放すのはつらいね。でも見つけたのは君だし、君にはもっと大事な使い道があるんだから、もちろんだ。ただ、どうか、私が写しを欲しがっていたとStrahadに必ず伝えておいてくれ。\n\n君が出かけている間に、彼から君宛てに伝言があった。彼の侍祭たちが召喚を手伝うには、君が集中の杖を3本手に入れなければならないと伝えてほしいそうだ。\n\n彼はどこで見つかるか知らないかもしれないが、私は知っているよ！ 最後に使っていたのは、WetlandsのDragonmaw氏族のオークたちだ。私なら奴らの呪文使いを調べるね！", "しばらくこのあたりで見かけなかったな。tomeとロッドは見つかったか?", "よくやった! Tome of the Cabalと、3本の完璧な——少々傷はついているようだが——チャネリングの杖だ。\n\nこれは面白くなる。若いウォーロックがfelhunterを自らのものにしようと挑むのは、久しぶりのことだ。", 0x03d040dc, 0x9ef106aa, 0x55a37205, 0x5476cf47, 0x6c5768db, "....." },
  [1805] = { "Tome of the Cabal", "Reconstructed TomeとRod of Channeling 3本をRatchetのStrahad Farsanに渡して下さい。", "これは、この数年で私が目を通した中でも最も興味深い文書の一つです。ここの蔵書は乏しく、ほとんどが地理の本で、もう全部読んでしまいました。Strahadが機会を見てこの書の写しを送ってくれるといいのですが。\n\n彼といえば、あなたが留守の間に私に知らせをよこしました。あなたの務めのために、集中の杖を3本手に入れなければならないそうです。\n\nこの文書を見せてくれたお礼に、秘密を一つ教えましょう。その杖は、WetlandsにいるDragonmaw Clanのオークたちが持っています。", "はい、{name}? 何のご用でしょう?", "よくやった! Tome of the Cabalと、3本の完璧な——少々傷はついているようだが——チャネリングの杖だ。\n\nこれは面白くなる。若いウォーロックがfelhunterを自らのものにしようと挑むのは、久しぶりのことだ。", 0x03d040dc, 0x9ef106aa, 0x30425814, 0x88bc1a02, 0x6c5768db, "....." },
  [1806] = { "正義の試練", "Jordan Stilwellが武器を完成させるまで待って下さい。", "鍛冶場へ行って、これに取りかかろうじゃないか。君が来るのに備えてしばらく前から準備してきたから、ちっとも時間はかからないはずだ。\n\n終わる頃には、君はこれまでよりずっと光を守る備えができているだろう。それだけは誓うよ。\n\n少し正直に言うとね、{name}、君の功績の成果を見ると、ちょっとうらやましくなるんだ。でも、自分なりの大事なやり方で君の冒険に貢献できると分かっているのは、やっぱり嬉しいものだよ。", nil, "さあ、これだ、{name}。あなたのような光の勇者にふさわしい武器だ。私の友人だった偉大なドワーフのパラディンにちなんで名付けた。彼の名はVerigan……Bosch Veriganといった。\n\n私と妻を代表して、どうか受け取ってくれ。あなたには大きな恩がある。あなたほどの腕を持つ者がこの地を旅してくれるなら、世界はより安全な場所になるだろう。", 0xcdb318ba, 0xe85d14f5, 0x581863b3, nil, 0x3f6f787f, "...m." },
  [1818] = { "Dillingerとの対話", "BrillのDeathguard Dillingerと話して下さい。", "Deathguard Dillingerがお前のような者に仕事があると聞いた。Dark Ladyの軍勢に自分の価値を示す気があるなら、すぐにDillingerのところへ出頭しろ。\n\nDeathguard Dillingerの持ち場は、Brillの西の端、墓地の近くだ。", nil, "任務を受けに来たのか? よかろう。大事な任務がひとつある。戦闘技術……そしてForsakenの防衛における決意を試すものだ。", 0xf02ed521, 0x1be1f22e, 0x6a039674, nil, 0x7aa141fe, "...m." },
  [1819] = { "Ulag the Cleaver", "Ulag the Cleaverを殺し、Deathguard Dillingerと話して下さい。", "ScourgeがTirisfal Gladesを席巻したとき、我々は研究のために一体を捕らえた。そいつは自由な精神を持ち、Ulag the Cleaverと名乗った。だが、その意志は自由であっても、なおLich Kingに支配されていた。\n\n我々はUlagに対する王の支配を断ち切る方法を見つけたいと願ったが、失敗した。今、ついに奴を解き放つ時が来た。\n\n奴を解き放ち、そして殺せ。\n\n北の霊廟の近くにある髑髏の石の仕掛けを起動しろ。そうすれば、奴を縛る魔法の封印が解かれる。\n\nそれから……覚悟しておけ、{name}。", "任務はまだ終わっておらんぞ、{name}。ウォリアーが恐れを見せるのは賢明ではない……", "よくやったぞ、{name}。UlagはScourgeの下等兵ではないぞ。お前はDeathguardsひいてはDark Ladyに対し、腕前と決意を兼ね備えたウォリアーでありさらなる指導に値することを示して見せたのだ。", 0xbc5fb5c0, 0x50a8ff39, 0x7f95b19b, 0xf733d594, 0x10babf8b, "....." },
  [1820] = { "Colemanとの対話", "Coleman Farthingと話して下さい。", "お前はDark Ladyに自らの価値を証明した。今度は彼女の臣下の一人に、自分を証明できるかもしれん。\n\nColeman Farthingは、Forsakenの敵に対する復讐の道具となる気のあるウォリアーを待っている。\n\n彼はBrill東部のGallow's End Tavernにいる。", nil, "ああ、本当さ。君の戦闘技術が必要なんだ。俺は貧乏だが、この仕事は俺とForsakenの目的との両方に役立つ。これをこなせば、報酬も二倍になるぞ。", 0xdc3a5265, 0xb6fc3d41, 0xfe952d6f, nil, 0x8ccd524f, "...m." },
  [1821] = { "Agamand家の家宝", "Agamand Family Axe・Agamand Family Sword・Agamand Family Mace・Agamand Family DaggerをColeman Farthingに渡して下さい。", "Agamand家は、私が生きていた頃の雇い主で、私の死の原因でもある！ Agamandsが今やLich Kingの心なき手先になっているのは、ふさわしい報いだ。\n\n今度は、奴らに残った名誉の最後のかけらをいただくとしよう。奴らの一族の地下墓所に入り、家宝を奪ってこい。sword、axe、短剣、そしてmaceだ。それを私のところへ持ってこい！\n\nAgamand家の地下墓所はAgamand millsの北の端にあり、潜むscourgeと死んだAgamandsに守られている。", "家宝は持ってきたか、{name}?", "ああ! 取ってきたのか! これで微かに残った最後の栄光と記憶は、呪われたAgamandの土地から剥ぎ取られたんだな。あの一族は本当に何もなくなったんだ!", 0xc2d69d26, 0x0089ab46, 0x20fc1b75, 0x5bb4ceec, 0x9190acbd, "....." },
  [1822] = { "家宝の武器", nil, nil, nil, "返してもらった武器のうち3つは、私の痛みと喪失の形見として手元に置いておこう。だが頼む、{name}、その家宝の中から気に入ったものを選び、自分のものにしてくれ。\n\n呪われた元の持ち主たちに仕えた以上に、それがあなたの役に立ちますように。", 0x4b8a763f, nil, nil, nil, 0x46f59d1b, ".mmm." },
  [1823] = { "Rugaとの対話", "Ruga Ragetotemと話して下さい。", "お前は腕が立ち、名声も高まっているウォリアーだ。Ruga Ragetotemの試練に挑む準備ができているかもしれんな。そうなら、BarrensのCamp TaurajoでRugaを探せ。\n\n彼は、呼びかけに応えるウォリアーたちを待っている。", nil, "{name}、私の試練を受けにきたのかな?", 0x0d81c230, 0xfe1dd616, 0x7cd5b742, nil, 0x565a3dc1, "...m." },
  [1824] = { "Field of Giantsでの試練", "Twitching Antenna 5本をCamp TaurajoのRuga Ragetotemに渡して下さい。", "この試練に合格するには、南のField of Giantsへ行かねばならない。そこには這い回る虫の生き物が大勢いる。奴らはBarrensに現れたばかりで、奴らが何の前触れなのか、私は気に入らない。\n\nまだぴくぴく動いている奴らの触角を持ってこい。時間を無駄にするなよ、{name}。刈り取った触角は長くは動かないからな。決められた時間内に触角を持ってくれば、試練に合格だ。", "触角は持ってきたか? あるなら早くよこせ。ぴくぴく動く触角も、いつまでも動いているわけではないからな……", "見事だ、{name}！Field of Giantsでの試練を乗り越え、君は{class}の道をさらに1歩進んだ。", 0x0163ae6e, 0x4e25533d, 0xd15e450b, 0x257de42a, 0x90078856, "....." },
  [1825] = { "Thun'grimとの対話", "BarrensのThun'grim Firegazeと話して下さい。", "名高いオークの鍛冶屋、Thun'grim Firegazeが、Hordeのために勇気ある行いを重ねるお前の噂を聞いた。お前のために鎧を一揃い作りたいそうで、すぐに話しに来るよう言っている。\n\nThun'grimはBarrensのCrossroadsの東で野営している。", nil, "うん、やって来たね。良いことだ。君と私とでたくさん話し合うことがあるからね。", 0x33f6853a, 0xb0a44244, 0xd434d1d8, nil, 0xe81873e0, "...m." },
  [1838] = { "Brutal Armor", "Smoky Iron Ingot 15本・Powdered Azurite 10個・Iron Bar 10本・Vial of PhlogistonをThun'grim Firegazeに渡して下さい。", "お前の強さと勇気の話は聞いている。お前のために鎧を一揃い作ってやりたい。お前の偉業の話が広まるにつれて、お前を助ける相棒となる鎧だ。\n\nだが、この鎧を作ること自体が一つのクエストになるだろう、{name}。お前の助けと、Hordeの他の鍛冶師たちの助けが必要になる。\n\nほら、この巻物を持っていけ。ほとんど見えない目で苦労しながら、幾晩もかけて、鎧に必要なものを書き記した。この巻物に書いた品を持ってくれば、鎧の最初の一部を作ってやろう。", "巻物に書いた品々は持ってきたか、{name}?", "頼んだ物を全部持ってきたね。さあ、私は自分の仕事にとりかかるとしようか……", 0xe5b472c9, 0x27dfd441, 0xb954c562, 0xe662a37f, 0xd8db3e5a, "....." },
  [1839] = { "Ula'elekとBrutal Gauntlets", "DurotarのUla'elekと話して下さい。", "トロールの鍛冶屋Ula'elekがBrutal Gauntletsを作ってくれるだろう。彼はDurotarのSen'jin VillageにDarkspear族の同胞と一緒に住んでいる。君が来るのを待っているぞ。", nil, "よく来た、{name}。年老いたThun'grimがお前の来訪を知らせてきたが、あれが黙っていたとしても、お前がここにいることに驚きはしなかっただろう。\n\n精霊たちはお前の歩みを見守っている、若き{class}よ。そして、多くの敵がお前の前に倒れたと語っている。", 0xa8ffb2ac, 0x75ae49c1, 0x7397cc32, nil, 0xd519cab7, "...m." },
  [1840] = { "Orm StonehoofとBrutal Helm", "Thunder BluffのOrm Stonehoofと話して下さい。", "Orm Stonehoofは、その腕前で大いに尊敬されている。彼がお前のために猛々しい兜を作ってくれるだろう。\n\nThunder Bluffで、街の中央にある大きなトーテムのそばの池の近くを探すといい。", nil, "御機嫌よう、{class}。私はOrm。兜を作ってほしいとThun'grimから聞いたが?", 0x370291ee, 0x52dd8f49, 0xc87c3f2d, nil, 0xd0a23079, "...m." },
  [1841] = { "Velora NitelyとBrutal Legguards", "UndercityのVelora Nitelyと話して下さい。", "Velora Nitelyは、死ぬ前はLordaeronでも指折りの鎧職人だったと言われている。死んでも、その才能は衰えていないようだ。Veloraと話せ。彼女がお前の猛々しい脚甲を作ってくれる。\n\nVeloraはLordaeronのUndercityの交易区で商売をしている。", nil, "脚の防具が目当てか? 結構だ!\n\nええと……防具を作るのは私がお前のためにか、それともお前が私のためにか?\n\n今のは冗談だ。面白かったか? 私には分からん……ユーモアの感覚は嗅覚と同じ時に失った。それはちょうど息をしなくなった頃だ。", 0x5920766a, 0x9b67f952, 0x1f3d9dcd, nil, 0x8b154887, "...m." },
  [1842] = { "Satyrの蹄", "DurotarのSen'jin VillageにいるUla'elekに、Uncloven Satyr Hooves 7つを渡して下さい。", "猛々しい籠手を一組作ってやれるし、それには大きな魔力が宿るだろう。だがまず、お前がその魔力を集めて私のところへ持ってこなければならない。\n\nsatyrsは、森の力を求めてAshenvaleの北東部に棲んでいる。奴らはその清らかさを糧にし、吸い取り、腐らせているのだ。どのsatyrsがAshenvaleの魔力を最も多く吸い取ったかは、腫れ上がった、割れていない蹄で見分けられる。\n\nその蹄には大きな力が宿っている。お前の籠手を作るのに、それが必要なのだ。", "蹄は持ってきましたか、{name}? その中に宿る魔力は強いのです。", "やあ、手に入れたのか! さてと、SatyrどもがAshenvaleの力を吸い取ったみたいに、蹄から力を吸い取って作品に込めてやるぞ……", 0x2ffc2005, 0xb9892d83, 0x2118fb87, 0x16fa27c8, 0x78102431, "....." },
  [1843] = { "Brutal Gauntlets", nil, nil, nil, "ありがとう、{name}。この小手は最高の作品だよ。持ってってくれ。これを着けてくれることが、オレと祖先の誇りになるんだ。", 0x7fe2d3c0, nil, nil, nil, 0x0724c79b, ".mmm." },
  [1844] = { "Chimaeric Horn", "Thunder BluffのOrm StonehoofにGalvanized Hornを渡して下さい。", "兜は作ってやろう。だが、お前がそれにふさわしいことを示してもらわねばならん。\n\nStonetalon Mountainsの北西の奥に、Charred Valeがひっそりと広がっている。かつては緑豊かな地だったが、今は穢され灰に覆われ、そこに残る生き物たちは苦痛と絶望で狂っている。\n\nそこへお前を送り出す、{name}。\n\nCharred Valeへ行き、chimaeraの女族長を見つけろ。そいつを殺し、その苦しみから解き放ってやれ。証としてそいつのgalvanized hornを持ってくれば、兜を作ってやろう。", "hornは持ってきましたか? 群れの母はもう痛みから解放されましたか?", "{name}、君は仕事をきっちりこなして、己の価値と決意を示してくれた。兜は君のものとなろう……", 0xb8512596, 0x6968948f, 0xc8418ace, 0xc0be4480, 0xb6d733e6, "....." },
  [1845] = { "Brutal Helm", nil, nil, nil, "この兜をお前に与えよう。\n\n偉大な行いがお前を我のもとへ導いた、{name}。そしてEarthmotherの御心のままに……さらに偉大な行いがお前の前に待っている。", 0x21f20070, nil, nil, nil, 0x85a88fa6, ".mmm." },
  [1846] = { "Dragonmaw族の脛骨", "UndercityのVelora NitelyにSturdy Dragonmaw Shinbone 8本を渡して下さい。", "猛々しい脚甲を作るには、sturdy shinbonesが一対必要だ。WetlandsのDragonmawのオークどもは、いい太いすね骨をしている。奴らのが要る。\n\nだが、頑丈でなければならん。集めるときに、必ずshinbonesを試せ。素手で折れるようなら、細工に使えるほど頑丈じゃない。", "shinbonesを待ってるぞ、{name}。お前のレッグガードのいい骨組みになるからな。", "よくやった! どれも丈夫そうだ。十分に使えるだろう。あのオークどもは脛を取られてどう思ったかな、{name}? ずいぶん文句を言ったか?\n\n今のもまた冗談だ。笑っていないな。\n\n近ごろの私はあまり面白くないらしい……", 0x4a563a64, 0x6f4838f8, 0xd449bda0, 0xa935bc7e, 0xfd8b7f21, "....." },
  [1847] = { "Brutal Legguards", nil, nil, nil, "これがお前のレッグガードだ、{name}。サイズが合うか、手直しが要るか教えてくれ。客を満足させるのが信条だ！少なくとも昔はそうだった。\n\n近頃は自分の腕にもあまり興味がない。だが、Scourgeの心なき手下でいるよりはましだ！\n\nたぶんな。", 0x46ca525e, nil, nil, nil, 0xef27dfd1, ".mmm." },
  [1848] = { "Brutal Hauberk", nil, nil, nil, "我が頼み事では多くの苦難に耐え、多くの血を流したことだろう、{name}。これが労苦の成果だ。\n\nよく身に着けてくれ。そしていつの日か、それがどう役立ったかの話を携えてここへ戻ってきてほしい。", 0x152a43f9, nil, nil, nil, 0xf852a004, ".mmm." },
  [1858] = { "Shattered Hand", "Tazanの鍵を盗み、その鍵を使って鞄を開け、中身をOrgrimmarのCleft of ShadowにいるTherzokに届けて下さい。", "Tazanの鞄を開けて、中身を持って戻ってくるのは君に任せよう。錠の仕組みが複雑だから、鍵を手に入れるのがおそらく一番簡単だろう。\n\nTazanの死体から見つからなかったのなら、奴は鍵を誰か別の者に預けたとしか思えない……ああ、そうだ、その通り。奴にはGamonという助手がいた。飲んだくれだから、たぶん酒場で見つかるだろう。こっそり鍵を頂戴できるかもしれないな。", "望むものが手の届くところにあるのに、それに近づく術がないとは、腹立たしいことではないか?", "ふーむ。これは面白いな。己の真価のみに留まらぬものをお前は示したのだ、{name}。実に感動した。お前はShattered Handの新人だと思え。それとこれを持って行け。後々、大いに役立つだろう。", 0xaa823b93, 0x4790c9c0, 0xad0f9af3, 0xfafd7288, 0x38c43aa8, "....." },
  [1859] = { "Therzok", "OrgrimmarのCleft of ShadowにいるTherzokと話して下さい。", "声を落とせ、{name}。ああ、お前の名前は知ってる。お前の人相に合うオークに目を光らせておけと言われてたんでな。\n\n聞いた話じゃ、お前は戦いで自分の身を守れるし、時にはちょっとしたこそこそ仕事も嫌がらないそうだな。\n\n違うか？\n\nとにかく、OrgrimmarのTherzokに会いに行け。お前に聞かせたい話があるそうだ。", nil, "結構だ。Kaplakがお前と連絡を取れてよかった。\n\n話すべきことがいくつかある。中でも重要なのは、Handでのお前の将来だ。", 0x74b10f51, 0x1b7efc2d, 0x5ee00801, nil, 0xacd1469f, "...m." },
  [1860] = { "Jenneaとの対話", "StormwindのJennea Cannonと話す。", "我々メイジには、果たすべき任務がある。StormwindとElwynnの森の安全に欠かせない任務だ。\n\n詳しいことはJennea Cannonが知っている。彼女はStormwindのメイジ地区にある魔法使いの聖域で研究をしている。急いで彼女のもとへ向かってくれ。", nil, "我が務めを助けるために遣わされたのか、{name}？よろしい。若いメイジたちが我らの大義のために進んで力を貸そうとするのは心強いものだ……\n\n何の大義か、と？いずれ分かる、若き者よ。そなたにも分かる……時が来ればな。", 0x7b586e0a, 0x17610de7, 0x833e5a0d, nil, 0x5a63396f, "...m." },
  [1861] = { "Mirror Lake", "Mirror Lakeのサンプルを、StormwindのJennea Cannonのところへ持って行く。", "この世界は大規模な神秘の戦いの犠牲となり、魔力の流れがかつての安定した経路から引き剥がされてしまった。我々はこうした変化がもたらした影響を突き止めようと苦心しているが、中には最悪の事態を恐れている者もいる！\n\nだが、そのことについては後で詳しく明かそう。今は、君に情報を集めてもらいたい。\n\nさあ、このフラスコを持っていけ。Stormwindの門の南西にあるMirror Lakeの滝のふもとへ行き、そこの水のサンプルを採ってきてくれ。魔法による汚れがないか調べられるよう、私のところへ持ち帰るのだ。", "サンプルは持ってきたか、{name}? StormwindとElwynnの魔力の流れが変わってしまった。それが水に染み込んでいるかどうか、確かめねばならんのだ。", "ありがとう、{name}。この水に魔法の性質があるか調べてみます。何も含まれていないことを祈りましょう。さもなければ、Mirror Lakeの水を長く飲んできた者たちに悪影響が出るかもしれません。\n\nさあ、{name}。務めの証として、このオーブか杖を受け取ってください。あなたの役に立ちますように。", 0x8c5d3612, 0x299fa3ef, 0x14519806, 0x40ceafc2, 0x6ddff8d3, "....." },
  [1879] = { "Binkとの対話", "IronforgeのBinkと話す。", "{name}！ Ironforgeにいる私のノームの同僚Binkから知らせが来たよ。彼女にはやってほしい仕事があって、メイジ以外には任せたくないそうだ！ 君がそのメイジかい、{name}？\n\nそうなら、Binkと話してくれ。彼女はIronforgeのMystic WardにあるHall of Mysteriesで過ごしているよ。", nil, "おお、君には見込みがあるね、そうとも！でも、良いメイジになるには見込みだけじゃ足りない。良いメイジでなければ、悪いメイジだ。そして悪いメイジは問題の一部なんだ、そうとも！\n\nおっと、先走りすぎた。最初から始めよう！", 0x0b59c7b3, 0x88f317f6, 0x9decdd73, nil, 0x88e0f9f8, "...m." },
  [1880] = { "Mage-tastic Gizmonitor", "Mage-tastic GizmonitorをBinkのところへ持って行く。", "私たちメイジは、ただ指をひらひらさせてきれいな火花を出すだけじゃないのよ！ 私たちは魔法を、この世界の根源をなす織物を操っているの！ それには細心の注意と決意が必要なの。それに知識も……たくさんの知識がね！\n\n私の装置の一つ、mage-tastic gizmonitorは、その知識を大量に集めて蓄えられるの！ でもそれをなくしちゃったのよ！ 故郷のGnomereganから逃げ出した時、街の外にある小屋の一つの箱に置いてきちゃって、今じゃあそこはleper gnomeだらけなの！\n\nお願い、{name}、私のgizmonitorを取り戻して！", "gizmonitorは見つかったか? エネルギーが切れる前に手に入れなきゃならないんだ!", "ああ、なんて素晴らしい日だ！gizmonitorを作ったときは、こんなに頼りきりになるなんて思いもしなかったよ。これでまた研究を始められる！\n\nありがとう、{name}！それからほら……これは私がメイジとして初めて使った道具なんだ。ちょっと傷がついてるけど、実績は十分だよ。好きなほうを選んでくれ……どちらもきっと役に立つはずだ。", 0x7e1133b0, 0x694f2e68, 0x57d62cf0, 0x0ab359eb, 0x9bceb030, "....." },
  [1881] = { "Anastasiaとの語らい", "Anastasia Hartwellと話して下さい。", "{name}、Anastasia Hartwellはお前の能力に関する仕事を持つ人だ。UndercityのMagic Quarterにいる彼女と話して、Forsakenのメイジたちのための初仕事に備えてくれ。", nil, "ご機嫌よう、{name}。呼び出しに応えるのは賢いわ。これから私が言うことを聞くのなら、もっと賢いわね……。", 0xc4711561, 0x6490e08e, 0x892f7df9, nil, 0x8b45b1c1, "...m." },
  [1882] = { "Balnir Farmstead", "UndercityのMage QuarterにいるAnastasia Hartwellに、Balnir Snapdragonsを渡して下さい。", "東のPlaguelandsは異常な存在だ。Lich Kingが作り出したもので、その魔力を土に染み込ませ、生きとし生けるものを腐らせ、殺している。疫病の破壊の力にはある種の魅力もあるが、我々Forsakenのメイジは、それが手に負えないものであり、抑え込まねばならないと考えている。\n\nだがまずは、それがTirisfalにどこまで広がったかを測らねばならない。Tirisfal東部のBalnir Farmsteadへ行け。庭に花が咲いている。snapdragonsだ。それを集めて戻ってこい。", "snapdragonsは持ってきたか? あの種類の花は魔力にとても敏感でな、Plaguelandsのすぐ近くでsnapdragonsを調べれば、疫病がTirisfal Gladesに入り込んでいるかどうかが分かるのだ。", "ああ、これは見事な標本だ。我らの薬剤師たちに送って調べさせ、Plaguelandの穢れがどこまで及んでいるかを見極めよう。\n\nよくやった、{name}。その働きに対し、選択肢を与えよう。オーブか杖かだ。どちらを選んでも、大いに役立つはずだ。", 0x8e22f419, 0xc51d5d3b, 0x91501431, 0x79fac00f, 0x8fa46f65, "....." },
  [1883] = { "Un'thuwaとの語らい", "Un'thuwaと話して下さい。", "Sen'jin Villageの部族のメイジ、Un'thuwaが、Durotarの魔力の流れに乱れを感じ取り、助けを求めている。Un'thuwaと話し、できる限り彼を助けてやれ。\n\nこれを果たせば、いずれさらなる秘密がお前に明かされるだろう。", nil, "よお、{name}。褒めてやるぞ。支援の呼びかけに答えてもらったからな。お前が任務に耐えられることを願うぞ……。", 0x9f1fb4f6, 0x6d399ba5, 0x6b38ce29, nil, 0x5b11fa4b, "...m." },
  [1884] = { "Ju-Ju Heaps", "Ju-Ju Heap 4つを壊し、Sen'jin VillageのUn'thuwaのところへ戻って下さい。", "Echo Islesのウォーロック、ZalazaneがDurotarの本来の魔力の流れを乱している。奴は穢れた呪物、ju-ju heapsを使ってそれを行っている。それを本島のEcho Isleにある自分の小屋のあちこちに置いているのだ。\n\nそのheapsは我々の野生の生き物を腐らせ、この地の暗がりに潜むウォーロックや地獄の生き物に力を与えている。\n\n魔力の流れが永遠に変わってしまう前に、ju-ju heapsを破壊しなければならない、{name}。", "急げ、{name}。ju-juの山を壊すのだ!", "Zalazaneのju-juの山が破壊されたのを感じる。時と運が味方すれば、Durotarの魔力の流れも正常に戻るだろう。\n\nお前は同胞のために偉大な行いを成した、{name}。そして我々Hordeのメイジたちに、その価値を示してみせた。", 0x565e7ac5, 0x966d5c6b, 0xbc0c0b65, 0xaae3b630, 0xcb8fa40d, "....." },
  [1885] = { "Mennet Carkad", "UndercityのRogues' QuarterにいるMennet Carkadと話して下さい。", "{name}か？ Carkad本人がお前に目をかけているにしちゃ、思ってたのとはちょっと違うな。まあ、見かけは当てにならないってことか？\n\nどっちにしろ、できるだけ早く彼に会いに行ったほうがいい。彼の呼び出しを無視した最近の何人かがどうなったかは、知りたくもないだろうよ。", nil, "ふむ。俺の呼び出しの話を聞いて、真っ先にここへ向かったということで間違いないな? 当然だ。まさしく見込みのあるDeathstalkerに期待しているぞ。", 0xe1e85fb2, 0x9601ae12, 0x2bbbbe4a, nil, 0xbfdff15c, "...m." },
  [1886] = { "Deathstalkers", "Astor's Letter of Introductionを手に入れ、Rogues' QuarterのMennet Carkadに返して下さい。", "Lord Varimathrasの精鋭護衛、Deathstalkersに加わりたいのなら、自らの価値を証明しなければならない。\n\n嘘は言わない、{name}。この任務はお前の死を意味するかもしれん。\n\n片付けねばならないことがいくつかある。SilverpineとUndercityの間を行き来する使者、Astor Hadrenの私物が必要だ。手に入れる方法はお前の裁量に任せよう。\n\nこの仕事の性質について知ることは少ないほうが、お前のためだ。成功すれば、もっと話してやろう。", "報告できる成果はあるか?", "よくやった、{name}。最初の試験に通ったのだぞ。お前の行動の気配をAndronが察知していないと良いが。というのも、奴にお前のことを信じ込ませようとしているのだ。つまり、奴が期待しているメッセンジャーとしてな。", 0x188cbd51, 0xbbe5324e, 0x2203cce3, 0xfd970964, 0x00fc1721, "....." },
  [1898] = { "Deathstalkers", "UndercityのAndron Gantと話して下さい。", "その紹介状があれば、お前こそ彼が待っていた使者だとAndronを納得させられるはずだ。以前Andronに会ったことがあるが、奴はそれほど疑り深くなれるだけの頭を持ち合わせていない。\n\nLord Varimathrasは、Andronが別の何らかの一派に手を貸しているのではないかと疑っておられる。それがどんな組織なのかを知りたいとお望みで、その証拠を求めておられるのだ。\n\nAndronと話し、この情報を手に入れてこい。奴はApothecariumの近くにある自分の店にいる。", "やあ。何か用かい?", "ああ、そうだ、お前を待っていた。我々の共通の知人たちは、これまで私が提供した情報に満足しているのだろうな?\n\nお前に尋ねても意味はあるまい。奴らがこの知識をお前に背負わせるとも思えん。使者にそこまでの信を置く理由があるか?", 0x188cbd51, 0xa89dca7e, 0x46557e99, 0xb58298f8, 0x918a8f91, "....." },
  [1899] = { "Deathstalkers", "Astor's LedgerをUndercityのRogues' QuarterにいるMennet Carkadに渡して下さい。", "お前の雇い主がお探しの例の情報を記した帳簿は、後ろの本棚にある。これを届けてよろしくお伝えしてくれ。それと、こうお伝えするのだ。もしあなた方の続けたがっているこの手配に充分な価値を見出していて、このメッセンジャーを寄越すのであれば、それを受け入れましょう、とな。", "うまくいったか、{name}?", "なるほど、Andronから引き出せると予想していたものよりずっと多くの情報だ。次の任務を任せる前に、詳しく調べる時間をくれ。", 0x188cbd51, 0x4d912e62, 0xed39f886, 0x8d80cd20, 0xf297cc15, "....." },
  [1918] = { "穢された精霊", "AshenvaleのSplintertree PostにいるMastok Wrilehissに、Befouled Water Globeを渡して下さい。", "殺された精霊は、猛烈に輝く水の玉を生み出した。玉の内容物は、非常に気味の悪いものだった。Mystral湖の水を穢した何かが、恐らくこの水の玉の中に存在していると推測するのが無難だろう。\n\nこのような発見に対して興味を持つのが誰か、正確には分からなかった。だが、Splintertree PostのMastok Wrilehissならば何か考えがあるだろう。", "ああ、何の用だ?", "汚い水の玉を見つけて、俺のところへ持ってくることにしたのか? 俺をEarthen Ringか何かかと思ったのか?\n\n実を言うと、そのおかげで、ある考えが浮かんだ……恐らく、それにはEarthen Ringが必要になるだろう。つまり、この水の玉が湖で起きている事態を解明するのに役立つなら、大賛成だ。\n\n{name}、Earthen Ringが何者か知ってるか?", 0x21873bc1, 0x3bae8df7, 0x322816ba, 0x25eef297, 0x74f9b004, "....." },
  [1919] = { "Jenneaへの報告", "StormwindにいるJennea Cannonと話して下さい。", "あなたの技の知識は深まっています、若き{name}よ。いよいよ本当の教えを始める準備はできましたか？ 私たちが繰り広げる秘密の戦いに加わる準備はできていますか？\n\nもしそうなら、Stormwindのメイジ地区にある魔術師の聖域で、Jennea Cannonと話しなさい。彼女には、見えざる世界への最初の窓を開く務めがあなたのために用意されています。", nil, "{name}、ここにはあなたの任務があります。よく聞くのですよ。無駄にする時間などないのですから。", 0xc2dfd63b, 0x17610de7, 0xfe7e6834, nil, 0x5ae736c8, "...m." },
  [1920] = { "Blue Reclusの調査", "Jennea Cannonの後ろからCantation of Manifestation・Chest of Containment coffersを手に入れ、Filled Containment Coffer 3箱を彼女に渡して下さい。", "Mage QuarterのBlue Recluseという酒場で異変が報告されました。見えない奇妙な生き物が今や酒場をうろついていて、そこにマナの裂け目ができたのではないかと私は心配しています。\n\n酒場を調べて、その生き物たちを捕らえてきてほしいのです。酒場でcantation of manifestationを使って生き物たちを見えるようにし、弱らせてから、containment cofferを使って捕らえなさい。十分に集まったら、中身の入ったcoffersと空のcoffers、そしてcantationを持って私のところへ戻ってきなさい。", "その生き物たちは捕まえたか、{name}? 奴らが現れた理由を突き止めるには、研究しなければならんのだ。", "実によくやった! これらの生き物を研究し、勤勉さと運があれば、どうやって我々の世界へ紛れ込んだのかを突き止めよう。\n\nメイジの社会におけるお前の価値は高まっているぞ、{name}。", 0x99ff705d, 0x444df4da, 0x4b931a51, 0x411e2ef3, 0x4083ef42, "....." },
  [1921] = { "素材集め", "Linen Cloth 10枚・Charged Rift Gem 6つをStormwindのWynne Larsonに渡して下さい。", "あなたは仲間のメイジたちによく尽くしました。今こそ魔術師のローブをまとう時です。Wynne Larsonがあなたのローブを作ってくれますが、必要な材料を彼女のところへ持っていかなければなりません。\n\nローブはリネンで作られ、それは簡単に見つかります。けれども、charged rift gemsも手に入れなければなりません。gemsのある場所として知られているのはLoch ModanのSilver Stream Mineだけで、ドワーフの鉱夫組合が木箱に入れて残していったのです。\n\nリネンとgemsを集めて、Mage DistrictのLarson ClothiersにいるWynne Larsonのところへ持っていきなさい。", "こんにちは、{name}。Jenneaからあなたが来ると聞いていました。何か私に渡すものがありますか?", "ええ、素晴らしい麻布ですね。これで良いローブが作れますよ。それから織り上げた後、rift gemsをこれにつけるのです。魔法使いにぴったりの服を作りますよ!", 0x2c5cc185, 0xcd459eaf, 0x8bb64794, 0xf3259f6b, 0xbad1677b, "....." },
  [1938] = { "Ur's Treatise on Shadow Magic", "Ur's Treatise on Shadow MagicをStormwindのHigh Sorcerer Andromathに渡して下さい。", "昔、3人のメイジがこの塔で学んでいたが、やがて一人が闇の術に堕ちた。その邪悪な魔法から離れるよう説かれたが、彼は抗えなかった。そして追放されたのだ。\n\n堕ちたメイジの新たな領地はRedridgeにあるIlgalarの塔で、彼は強力な書物を持ち去った。Ur's Treatise on Shadow Magicだ。\n\n我々Stormwindのメイジは、その書物を取り戻したい。Ilgalarの塔に入り、彼の書庫でその書を見つけて、私のところへ持ってきてくれ。", "本は持ってきたか、{name}? その秘密は未熟な者のためのものではない。その深みを探れば、破滅と没落を招きかねんのだ。", "Morganthがその本をどこか別の場所に隠したか、あるいは開いて中身を読む方法を見つけたのではないかと恐れていた。\n\nそうではなく、我々がUr's Treatise on Shadow Magicに施した封印がまだ保たれていると分かって何よりだ。", 0x3eab5ca9, 0x5da24331, 0x84778b51, 0xc0beaebd, 0x6a7c0b88, "....." },
  [1939] = { "High Sorcerer Andromath", "High Sorcerer Andromathと話して下さい。", "High Sorcerer Andromathがあなたと話したがっています、{name}。彼はStormwindのメイジ地区にある魔術師の聖域の最上階にいます。\n\n彼と話すのが賢明でしょう。AndromathはDalaranに閉じ込められていないメイジの中でも屈指の力を持つ一人なのですから。彼の助言は、まさしく最高の助言です。", nil, "ご機嫌よう、{name}。会えて嬉しい。この老人の話を聞く時間があるといいのだが……。", 0xade0a64e, 0xc9d25e42, 0xb1ce8c24, nil, 0x10407ead, "...m." },
  [1940] = { "Pristine Spider Silk", "StormwindのWynne LarsonにPristine Spider Silk 8つを渡して下さい。", "あなたの奉仕は揺るぎないものでした、{name}。そろそろ、熟達したメイジという立場にもっとふさわしい、上等な衣をまとってもよい頃でしょう。必要な材料を集めてくれれば、ローブを作る手配をしましょう。\n\nDuskwoodに入り、carrion recluse spidersを狩りなさい。そのsilkを取り出すのですが、最上の、最も汚れのないsilkでなければなりません。十分に集まったら、このメイジ地区のLarson ClothiersにいるWynne Larsonのところへ持っていきなさい。彼女があなたのローブを仕立ててくれます。", "ああ、そうだった。Wizard's Sanctumのメイジたちから、君が話しに来ると聞いていたよ。必要なsilkは持ってきたかい?", "いい素材ですね、これ。早速仕事にとりかかりましょう!", 0x0ae2c7a3, 0x2674cfe7, 0x31b76a02, 0x5407cd18, 0x48d28ffb, "....." },
  [1941] = { "Manaweave Robe", nil, nil, nil, "さあ、これがあなたのローブですよ。今までで一番の出来です! 誇りを持ってこれを着て下さいな。そして、人に聞かれたら……「Larson洋服店で作ってもらった」と教えてあげて下さいね!", 0xc492652c, nil, nil, nil, 0xf4dc234a, ".mmm." },
  [1942] = { "Astral Knot Garment", nil, nil, nil, "衣装ができあがったよ! それにあんたが集めてきた絹はとても上等でね……自分の分を少し残しておきたくて、ちょっと短めに作ったんだが、構わないだろう?\n\n冗談だよ。ぴったり合うし、冒険にも正餐にも申し分ない。楽しんでくれ!", 0xd423e365, nil, nil, nil, 0x7bdf4eeb, ".mmm." },
  [1943] = { "Deinoとの語らい", "Deinoと話して下さい。", "トロルの魔法使いDeinoがあなたの支援を必要としているの、{name}。彼女はOrgrimmarのDarkbriar Lodgeに住んでいるわよ。", nil, "よし、来たわね。仕事は容易なものではないけれど、魔法使いの社会には不可欠なの。手伝ってくれれば、必ずやりがいを感じると思う。", 0xf18219b3, 0x9593292e, 0x3f3b729c, nil, 0x7f8e7e01, "...m." },
  [1944] = { "Xavianの水", "OrgrimmarのDeinoにXavian Water Sampleを渡して下さい。", "伝説の都Xavianは、Ashenvale東部の奥深くにひっそりとたたずんでおり、その古の知識の話は学識ある者の間でよく知られています。Xavianの水には膨大な魔力が宿っていると言われているのです。\n\nその水の見本を、源から汲んだものが欲しいのです。\n\nこのフラスコを持ってXavianへ行きなさい。一番高い滝の滝壺から水を汲んで、私のところへ戻ってきなさい。そして、あの古の都を進むときは気をつけなさい。今やsatyrsがその廃墟を支配していて、メイジが自分たちのことを詮索するのを好まないのです。", "無事な姿で戻ってきてくれて嬉しいぞ、{name}。water sampleは持ってきたか? その性質を早く調べたいのだ。", "ああ、結構です。Xavianのsatyrたちはさほど手こずらせなかったでしょうね?\n\nありがとう、{name}。このXavianの水の標本をすぐに調べます。", 0x25a8fb6b, 0x69a196d3, 0x453fec0e, 0xc1429ad4, 0x925c63b7, "....." },
  [1945] = { "Laughing Sisters", "CrossroadsのKil'halaにLaughing Sister's Hair 12個を渡して下さい。", "あなたの働きに報いるため、新しいローブを作る手配をしました。必要な材料を集められればの話ですが……\n\nこのローブのためには、もう一度Ashenvaleへ行って、laughing sistersのhairの房を手に入れなければなりません。Raynewood Retreatの近くに集まるdryadsです。\n\n彼女たちのhairを手に入れたら、BarrensのCrossroadsにいるトロールの仕立て屋、Kil'halaのところへ持っていきなさい。彼はあなたを待っていて、ローブを仕立ててくれるでしょう。", "ごきげんよう、{name}。Deinoから、あなたが来て、laughing sisters' hairを持ってきてくれると聞いています。お持ちですか?", "ああ、この髪は見事なローブに織り上がりますよ、{name}。laughing sisterたちがこれを手放すのに死なねばならなかったのは惜しいことです。とはいえ、彼女たちが進んで差し出すとも思えませんが。\n\n惜しいことです。ですが、ほんの少しだけ。", 0x483fd0b4, 0x404d3b5c, 0x16557f4c, 0x2b62536e, 0x76d06fc5, "....." },
  [1946] = { "Nether-laceの衣", nil, nil, nil, "これがあなたのnether-laceです、{name}。着心地が良く丈夫で、laughing sistersの髪の魔力が宿っています。\n\nどうぞお楽しみください。もし気に入ったら、Deinoにそう伝えてください。彼女は、私が機嫌を損ねたくないメイジなのです……", 0x47a79219, nil, nil, nil, 0xb7ac8288, ".mmm." },
  [1947] = { "沼地への旅", "Tabethaと話して下さい。", "今こそ、メイジのワンドを手に入れる時です。このクエストを始めるには、Dustwallow Marshにいる人間の隠者Tabethaと話しなさい。彼女の小屋は沼地の奥深く、Theramoreの西にあります。\n\n彼女と話しなさい。彼女の知識は膨大です。Tabethaの小屋はTheramoreの西、Stonemaul Ruinsのすぐ北にあります。", nil, "静かに! 今は微妙なところなんだ、邪魔をされては困る!\n\n少し待ってくれ……", 0x00cab63e, 0xec630cd9, 0xd84d1f56, nil, 0xd662f796, "...m." },
  [1948] = { "力の品", "JadeとBolt Charged Brambleをそれぞれ1つずつ、Dustwallow MarshのTabethaに渡して下さい。", "メイジのワンドを作るのは簡単じゃないよ。珍しい素材が必要だし、大量の魔力を蓄えられる器を作らなきゃならない。それらを集めて、私のところへ持ってきておくれ。\n\n必要なものと、その手に入れ方をこの羊皮紙に書いておいたよ。このリストにあるものをきっちり持ってきて、書いた指示に一字一句従うこと。そうしないと、ワンドを作るときに……まずいことになるかもしれないからね。", "こんにちは、{name}。私が必要とする品々は持ってきましたか?", "おお! jadeを手に入れて、brambleも作ったんだな! よくやった!\n\n耳から煙が出ているように見えるが? 雷がトーテムの棒に落ちたとき、近づきすぎたのかもしれんな。だが心配ない。雷に打たれるのは幸運の印だ!", 0x9fca506c, 0xffee0377, 0x293cf3b1, 0x2727c796, 0xe2d3e5c2, "....." },
  [1949] = { "隠れた秘密", "Shimmering FlatsのMagus Tirthと話して下さい。", "あなたのワンドを作るには、ある本の重要な一節を読まなければなりません。その本はRituals of Powerといい、Magus Tirthが書いたものです。\n\n私はその本を持っていませんし、世界のどの大図書館にも所蔵されていません。ですから、あなたがTirthと話して、彼から手に入れてこなければならないのです。\n\n幸運を祈ります。Tirthはかつて偉大なメイジであり学者でしたが、今ではShimmering Flatsで開かれるノームとゴブリンのレースで、酒と賭け事に明け暮れています。", nil, "何だって? もっと大きな声で! この老いた耳は昔ほど利かなくてな。\n\nさて、冷えたエールの一杯か、次のレースの耳寄りな情報を持ってきたのならいいんだが! そうでないなら、そのまま歩き続けるんだな……お前の名前を書いたpolymorphのワンドがあるんだからな!", 0x1135011b, 0x6e5fa5c1, 0xf9fa4f5c, nil, 0x4d107d35, "...m." },
  [1950] = { "情報を手に入れろ", "Tirthの金庫の合い言葉を見つけ、Tirthのところへ戻って下さい。", "本のことなら手を貸してやれるが、まずはわしを手伝ってもらわにゃならん！\n\nお前さんの探しとる書は、魔法で鍵をかけたわしの金庫の中にある。開けるには特別な言葉を唱えにゃならんのだが、その言葉が思い出せんのだ！ いつもならわしの助手がこういうことを思い出させてくれるんだが、どこにも見当たらん。\n\nわしの本が欲しいなら、わしの弟子を見つけてくれ！ レース場のあたりで聞いて回るといい。運が良ければ、誰かが見かけとるだろう。引きずって連れ戻すか、せめてあいつからわしの魔法の言葉を聞き出してきてくれ。そうすりゃ箱を開けられる！", "何をぐずぐずしてるんだ? 魔法の呪文が必要なんだよ!", "ああ、思い出したぞ……\n\nJohnsonにかけたあのちょっとした呪いのことをすっかり忘れていた。なぜそうしたのかは思い出せんが、あの恩知らずには当然の報いだったに違いない!", 0x5a6e9070, 0xff721e76, 0x81aae872, 0xe0b09124, 0xf89c07ae, "....." },
  [1951] = { "Rituals of Power", "Dustwallow MarshのTabethaに「Rituals of Power」を渡して下さい。", "うーむ……今考えてみると、わしは本を持っとらん！ 実はな、賭けの借金があって、それを払うためにRituals of Powerの最後の一冊を聖職者の一人に売ってしまったんだ……\n\nScarlet Brotherhoodの一員だ。奴はきっとTirisfal GladesのScarlet Monasteryにある連中の書庫へ持っていったに違いない！\n\nその本が欲しいなら、修道院へ行って見つけるしかないな。面倒ばかりかけてすまん。近頃のわしはどうもわしらしくないんだ……", "ごきげんよう、{name}。あの本、Rituals of Powerは見つかりましたか?", "これです! これこそが、杖を作るのに用意する物なんです! 見つけるには大変な苦労をなさったことでしょうね……", 0xe24e2540, 0xc397e91a, 0xf290baf5, 0xaa5d76af, 0x2100a453, "....." },
  [1952] = { "メイジの杖", "儀式の後、Tabethaと話して下さい。", "これから杖を作りますね。", nil, "杖が完成しました。お好きな物を選んで下さい!", 0x0eb25641, 0x5fb8da99, 0x60427f51, nil, 0xc2bb3341, "...m." },
  [1953] = { "沼地へ", "Tabethaと話して下さい。", "時が来ました、{name}。Tabetha……Dustwallow Marshの隠者と話しなさい。彼女が、強力なメイジの道具の作り方を教えてくれるでしょう。\n\nTabethaの小屋はDustwallow Marshの奥深く、Theramoreの西にあります。", nil, "ああ、そうだ。オーブか杖が目当てで来たんだな、{name}? よろしい。その制作に手を貸そう。\n\nだが忠告しておく——この工程は危険で、お前の死を意味するかもしれん。\n\nあるいは私の死をな。確実に誰かは死ぬ……\n\nまあ、死ぬのが他の誰かであることを願おうじゃないか?", 0x388ca425, 0xec630cd9, 0x5724d720, nil, 0x1489288b, "...m." },
  [1954] = { "Infernal Orb", "Dustwallow MarshのTabethaにInfernal Orbを渡して下さい。", "最初の手順は、力を持ったorbを手に入れることだよ。Burning Bladeのウォーロックどもは上等で質のいいorbを持ってる……悪魔を封じ込めちまってるのが残念だけどね！ でも、それは直せる。ああ、直せるとも。\n\nDesolaceへ行って、Burning Bladeの召喚師からinfernal orbをひったくってきな。召喚師たちはMannoroc Covenにいるよ。\n\norbを手に入れたら、私のところへ戻ってきな。", "infernal orbは持っているか、{name}?", "おお、これはいい代物だ! いや、暑い日の冷たいジュースがいいという意味の「いい」ではないぞ。\n\nむしろ、考えてみればまったくよくない。ジュースのことではない。オーブのことだ!\n\n集中しろ、{name}! この仕事を終わらせるつもりなら、お前に集中してもらわねばならん!", 0x06f7d3bf, 0x7e679ffe, 0x17cf4db6, 0x3a45602f, 0x54ab9363, "....." },
  [1955] = { "悪魔払い", "Demon of the Orbを殺し、Tabethaと話して下さい。", "召喚師のorbが手に入ったから、今度は中の悪魔を追い出さなきゃならない。それは私ができる。そっちは簡単なほうさ。\n\n大変な仕事をするのはあんただよ。出てきた悪魔を倒さなきゃならないのはあんたなんだから。\n\nしかも素早くやらなきゃならない。もたもたしてたら、奴はorbの中に跳ね戻って、最初からやり直しになっちまう！\n\nだから準備を整えておきな。一番強い呪文を用意して、薬を手元に置いて、友がいるなら連れてきな。きれいな仕事にはならないからね。", "オーブからその穢れを取り除くには、あの悪魔を倒さねばならんぞ、{name}。", "見事だ、{name}! あの悪魔に、そう簡単には忘れられない教訓を与えてやったな。\n\n奴は自分を打ち負かした愚かな定命の者を探しに、その醜い頭をこの世界へ突き出す前に二度は考えるだろう。今度は仲間連れかもしれんがな。大きくて鱗に覆われた仲間、お前を小さな{race}の切れ端に引き裂くことしか望まないような奴らだ。\n\n怖がらせてはいないだろうな……{name}?", 0x8c023e9b, 0x0c09dbd7, 0x7bc8e6ee, 0x5a957568, 0xc565119e, "....." },
  [1956] = { "Uldamanの力", "Obsidian Power Sourceを取り戻し、Dustwallow MarshのTabethaに渡して下さい。", "悪魔を取り除いたから、今度は動力源を手に入れなきゃならない。残念ながら、一番いい動力源はたいてい一番古くて、一番手に入れにくいんだ。運命ってのは時々がぶりと噛みついてくるのが好きなもんだね、面白いだろ？\n\nだから、Uldamanへ行って、そこにいるobsidian sentinelを倒してもらう必要がある。でかくて、タフで、奴のpower sourceはすごい威力なんだ！\n\n幸運を祈るよ、{name}。もし運がなかったら、まあ……知り合えてよかったよ。", "Uldamanへは行ったか、{name}? obsidian sentinelは倒したか?", "やったの? 見事だわ!\n\n同僚たちと話していてあなたの名前が出たとき、彼らはこう言ったのよ。「あの{name}はプレッシャーの中でもよく働くよな!」ってね。\n\nでも、obsidian sentinelと戦わせるためにあなたをUldamanへ送ったと言ったら、私は正気じゃないと言われたわ! 「Tabetha、あんた正気じゃないわよ! {name}があのsentinelに挑めるはずがない!」ってね。\n\nそれで私は「まあ見ていて」と言い、彼らは「ああ、見ていよう……」と言ったの。\n\nまあ、見事に見せつけてやったわね!", 0x8540f2cc, 0x609de4c9, 0x337bdace, 0x97e3557d, 0x68911b1b, "....." },
  [1957] = { "Mana Surge", "制限時間内にMana Surgeを12体殺して下さい。", "もうすぐ完成だけど、この最後の手順が一番危ないんだ、{name}。\n\n空になった召喚師のorbがここにあって、力を込める準備はできてる。マナの裂け目のエネルギーを利用してそれをやるんだ。私が呪文を唱えて一時的に裂け目を開くと、そこから生き物、mana surgesがあふれ出てくる。あんたがmana surgesを倒せば、その力が解き放たれるから、それを私が集めるって寸法さ。\n\n裂け目が閉じる前にmana surgesを十分倒してくれれば、集めたエネルギーを全部あんたのorbに込めてやるよ。", "必要な数のmana surgesをまだ倒していないぞ、{name}。", "やったわね! 一瞬たりとも疑ったことはなかったわ! いえ、ほんの一瞬、あるいは2秒くらいは疑ったかも……でも基本的にはほとんど疑っていなかったの。\n\n本当よ。", 0x80c697f8, 0x215059ed, 0x71ba4f8d, 0xee6b77cf, 0x78536f4a, "....." },
  [1958] = { "神聖な力", nil, nil, nil, "よくやった、{name}。君が相手にした化け物たちに、これまで多くのメイジが倒れてきたんだ。\n\nCelestial Orbの準備はできている。望むなら杖の先に取り付けることもできる。君次第だ。私ならオーブのままにするが、私がとやかく言うことでもないな。", 0xe22e458c, nil, nil, nil, 0xd2e8f38d, ".mmm." },
  [1959] = { "Anastasiaへの報告", "Anastasia Hartwellと話して下さい。", "Undercityのメイジたちが街の中で魔力の乱れに気づき、Hordeのメイジに調査するよう知らせを送ってきた。\n\nAnastasia Hartwellが詳しく教えてくれるだろう。UndercityのMagic Quarterで彼女と話せ。", nil, "本当だ。我らの都市で魔法の乱れが検知された。その源も、悪意あるものか無害なものかも、まだ分かっていない。まずはより多くの情報を集めねばならん……\n\nそしてそれが、{name}、お前の任務につながる。", 0xa475d463, 0x6490e08e, 0x63fa5d80, nil, 0x27c6603d, "...m." },
  [1960] = { "錬金術店の調査", "Anastasia Hartwellの後ろからCantation of ManifestationとChest of Containment Cofferを入手して下さい。UndercityのAnastasiaにFilled Containment Coffer 3箱・Chest of Containment Coffers・Cantation of Manifestationを渡して下さい。", "ApothecariumにあるAlgernonの錬金術の店が、奇妙な乱れの中心になっている。魔力だけでできた見えない生き物が店をうろついているのだ。何か理由があるはずだ。それを突き止めねばならん！\n\n乱れを調べて、その生き物たちを捕らえてこい。私の後ろからcoffersの箱と巻物を一つ持っていけ。店で巻物を使って生き物たちを見えるようにし、呪文で弱らせてから、cofferを投げつけて捕らえるのだ。中身の入ったcoffersと空のcoffers、そしてcantationを持って戻ってこい。", "異変は調べたか、{name}? 生き物たちは捕まえたか?", "結構だ、{name}。このcontainment cofferの中の生き物は我らの最も優れた頭脳によって研究され、Undercityに現れた理由が突き止められるだろう。\n\n奴らの出現が魔力の自然な流れの裂け目によるものなら、その裂け目が偶然のものだったかを見極めねばならない。偶然ではなく、何らかの魔法の力による攻撃だったなら、今後さらに深刻な乱れに備えねばならない。", 0x3d00ed2a, 0x782743e8, 0x8a0f9c02, 0xf5165c0b, 0x2724ebaf, "....." },
  [1961] = { "素材集め", "Linen 10枚・Dalaran Mana Gem 6個をJosef Gregorianに渡して下さい。", "最初のメイジのローブをまとう時だ、{name}。それはお前の地位の証であり、お前の価値の証でもある。\n\nローブを手に入れるには、SilverpineのDalaranのメイジたちからmana gemsを集めてこなければならない。奴らの信条は我々のものと似ているから、殺すのはいささか気が進まないが、我々に抗う力がないのなら、奴らに生きる資格はない。\n\ngemsとリネンを一揃い、Magic Quarterの仕立て屋にいるJosef Gregorianのところへ持っていけ。", "Anastasiaから君が来ると聞いていた。ローブを仕立てる用意はできている。gemsとリネンは持ってきたか?", "これはとても良い素材だ。自分にはこの宝石の質を見極める才能が無いけれども、spellfire robesを作るのに必要な力を備えているかどうかはすぐに分かるよ。", 0x2c5cc185, 0x01f81e3a, 0x31421ea5, 0xf26b5dc2, 0x7b0078e9, "....." },
  [1962] = { "Spellfireのローブ", nil, nil, nil, "これがあなたのローブです、{name}。大切に着てください。", 0xd0e883d2, nil, nil, nil, 0x1484d0c1, ".mmm." },
  [1963] = { "Shattered Hand", "Tazanを殺し、彼のSatchelをOrgrimmarのCleft of ShadowにいるTherzokに渡して下さい。", "大族長のやり方は慎重すぎる。Hordeの力を解き放つことにためらっておられる。かつて我々はもっと強かった。皆が強大な征服者だったのだ。その誇りを取り戻さねばならん。そしてShattered Handがそれを成し遂げる。\n\n我々は影から力を蓄え、隙を見せた者を討ち、ひそかに敵を倒していく。お前の価値を証明するために、私のために果たすべき任務がある。\n\nトロールのTazanが、Ratchetの近くで海賊と取引をしている。奴は私がどうしても欲しい情報を持っている。奴を殺し、奴の鞄を持ってこい。", "斧を抜いての突撃のほうが闇に潜む短剣より危険だと思うのは、愚か者だけだ。", "ふむ、Tazanがもういないと聞けて嬉しいが、鍵のかかった鞄では何の役にも立たん。必要なのは中に収められた情報だ。\n\nこれはShattered Handに加わろうとする者にとって、二つ目の試練としてふさわしいはずだ。", 0xaa823b93, 0x5a2a4bc5, 0x000efca9, 0x8d47ba3b, 0xddd506ad, "....." },
  [1978] = { "Deathstalkers", "Andron's LedgerをUndercityのHall of the Dark LadyにいるVarimathrasのところへ届ける。", "Syndicateだと？ 思いもよらなかった。Alteracの貴族どもは、あの裏切り以来の年月でずいぶんと落ちぶれたようだな。\n\nLord Varimathrasはこれを知ってお喜びになるだろう。この発見にお前は大いに貢献したのだから、お前自身がこれを閣下に届けるのがふさわしい。\n\nああ、それと、忘れるところだった。\n\nDeathstalkersへようこそ。", "何か？", "ふむ、これは興味深い。Deathstalkerたちはこれを探り出すという務めを見事に果たした。\n\n聞くところでは、お前の働きも称賛に値するそうだな。これがお前にとって日常となることを願っているぞ、{name}。私のDeathstalkerたちには、常に優秀な者が必要なのだ。", 0x188cbd51, 0xe84bf2aa, 0x06c42722, 0x0c07a888, 0x6f0b3033, ".....", nil, nil, nil, nil, 0x9dd8ce85 },
  [1998] = { "Fenwick Thatros", "Fenwick Thatrosを殺し、彼の首をUndercityのRogues' QuarterにいるMennet Carkadに渡して下さい。", "Lord Varimathrasから、ただちに排除せねばならないForsakenへの脅威について書状が届いたところだ。その名はFenwick Thatros。Lord Varimathrasは、Silverpine Forestに根を張ったアンデッドの首領の一人だと考えておられる。\n\nすぐにお前の名が頭に浮かんだぞ、{name}。お前ならこの任務を完璧にやり遂げると信じられるだけの力がある。\n\nSilverpineのDeathstalkersからの最新の報告によれば、ThatrosはLordamereの朽ちた桟橋の近くにいるらしい。", "Lord Varimathrasのためにこの務めを果たしてくれると、私はお前に全幅の信頼を置いている。", "よくやった、{name}。お前はDeathstalkerのためによく働き、己の価値を示しているのだということに気が付いたよ。影の技の訓練を促す時が来たかもしれんな。", 0x781cfb68, 0x4baac6d9, 0xb8ed3a72, 0xab7b0537, 0xdd812daf, "....." },
  [1999] = { "商売道具", "Dalaran Status Reportを見つけ、UndercityのRogues' QuarterにいるMennet Carkadに返して下さい。", "AmbermillにいるKirin Torの魔術師どもが、Dalaranの現状に関する重要な文書をしまい込んでいる。これは我々の捕虜の一人の自白から分かったことだ。Lord Varimathrasは、それを取り戻す任をDeathstalkersの手に委ねられた。\n\nこの任務はお前に任せる、{name}。ただし、いくらか道具と、錠前破りの知識が必要になる。出発する前に、我々の装備係のEstelle Gendryと話し、道具一式をもらっておけ。", "書類は見つかったか、{name}?", "実に結構だ、{name}! 鍵開けという見事な技をよく身につけた。しかも私が予想し得たよりずっと速くな。\n\nお前を信じたのは正しかったようだ。信じてくれ、若いの、この道でお前は大成すると見ているぞ。", 0x47f8e1ca, 0xcb3a5841, 0x4a4717c8, 0xf5e3d303, 0x5e1c7f0b, ".....", nil, nil, nil, nil, 0xce9cbc9b },
})
